'use strict';

const {
  ArrayIsArray,
  ArrayPrototypeJoin,
  ArrayPrototypePush,
  ArrayPrototypeReverse,
  ArrayPrototypeSlice,
  ArrayPrototypeSort,
  JSONStringify,
  MathFloor,
  MathMax,
  MathMin,
  MathRound,
  MathSqrt,
  Number,
  NumberIsFinite,
  NumberMAX_SAFE_INTEGER,
  ObjectFreeze,
  ObjectKeys,
  PromiseWithResolvers,
  SafeSet,
  StringPrototypeToLowerCase,
} = primordials;
const { AsyncResource } = require('async_hooks');
const {
  codes: {
    ERR_INVALID_ARG_TYPE,
    ERR_INVALID_ARG_VALUE,
    ERR_INVALID_STATE,
    ERR_OUT_OF_RANGE,
  },
} = require('internal/errors');
const { createHistogram } = require('internal/histogram');
const { TIMEOUT_MAX } = require('internal/timers');
const { kEmptyObject } = require('internal/util');
const {
  validateAbortSignal,
  validateFunction,
  validateInteger,
  validateNumber,
  validateObject,
  validateString,
  validateUint32,
} = require('internal/validators');
const { structuredClone } = require('internal/worker/js_transferable');

const { bigint: hrtime } = process.hrtime;
const kDefaultSamples = 30;
const kDefaultWarmup = 10;
const kEmptyDiagnosticChannels = ObjectFreeze([]);
const kEmptyNamePath = ObjectFreeze([]);
const kEmptyParams = ObjectFreeze({ __proto__: null });
const kEmptyTags = ObjectFreeze([]);

function validateSkip(skip) {
  if (skip !== undefined && typeof skip !== 'boolean' &&
      typeof skip !== 'string') {
    throw new ERR_INVALID_ARG_TYPE('options.skip', ['boolean', 'string'], skip);
  }
}

function canonicalizeTags(tags, parentTags = kEmptyTags) {
  if (tags === undefined) return parentTags;
  if (!ArrayIsArray(tags)) {
    throw new ERR_INVALID_ARG_TYPE('options.tags', 'Array', tags);
  }

  const result = ArrayPrototypeSlice(parentTags);
  const seen = new SafeSet(parentTags);
  for (let i = 0; i < tags.length; i++) {
    validateString(tags[i], `options.tags[${i}]`);
    if (tags[i].length === 0) {
      throw new ERR_INVALID_ARG_VALUE(
        `options.tags[${i}]`, tags[i], 'must not be empty');
    }
    const tag = StringPrototypeToLowerCase(tags[i]);
    if (!seen.has(tag)) {
      seen.add(tag);
      ArrayPrototypePush(result, tag);
    }
  }
  return ObjectFreeze(result);
}

function canonicalizeDiagnosticChannels(
  diagnosticChannels,
  parentDiagnosticChannels = kEmptyDiagnosticChannels,
) {
  if (diagnosticChannels === undefined) return parentDiagnosticChannels;
  if (!ArrayIsArray(diagnosticChannels)) {
    throw new ERR_INVALID_ARG_TYPE(
      'options.diagnosticChannels', 'Array', diagnosticChannels);
  }

  const result = ArrayPrototypeSlice(parentDiagnosticChannels);
  const seen = new SafeSet(parentDiagnosticChannels);
  for (let i = 0; i < diagnosticChannels.length; i++) {
    const name = diagnosticChannels[i];
    if (typeof name === 'symbol') continue;
    if (typeof name !== 'string') {
      throw new ERR_INVALID_ARG_TYPE(
        `options.diagnosticChannels[${i}]`, ['string', 'symbol'], name);
    }
    if (!seen.has(name)) {
      seen.add(name);
      ArrayPrototypePush(result, name);
    }
  }
  return ObjectFreeze(result);
}

function canonicalizeParams(params) {
  if (params === undefined) return kEmptyParams;
  validateObject(params, 'options.params');

  const result = { __proto__: null };
  const keys = ObjectKeys(params);
  ArrayPrototypeSort(keys);
  for (let i = 0; i < keys.length; i++) {
    const key = keys[i];
    const value = params[key];
    if (typeof value !== 'string' && typeof value !== 'boolean' &&
        (typeof value !== 'number' || !NumberIsFinite(value))) {
      if (typeof value === 'number') {
        throw new ERR_OUT_OF_RANGE(
          `options.params.${key}`, 'a finite number', value);
      }
      throw new ERR_INVALID_ARG_TYPE(
        `options.params.${key}`, ['string', 'number', 'boolean'], value);
    }
    result[key] = value;
  }
  return ObjectFreeze(result);
}

function validateNodeOptions(options, parentTags, parentDiagnosticChannels) {
  validateObject(options, 'options');
  const { diagnosticChannels, only = false, skip, tags } = options;
  if (typeof only !== 'boolean') {
    throw new ERR_INVALID_ARG_TYPE('options.only', 'boolean', only);
  }
  validateSkip(skip);
  return {
    __proto__: null,
    diagnosticChannels: canonicalizeDiagnosticChannels(
      diagnosticChannels, parentDiagnosticChannels),
    only,
    skip,
    tags: canonicalizeTags(tags, parentTags),
  };
}

function createLocation(loc, fallbackFile) {
  return {
    __proto__: null,
    file: loc?.[2] ?? fallbackFile,
    line: loc?.[0],
    column: loc?.[1],
  };
}

function getNamePath(parent, name) {
  const path = [];
  for (let current = parent; current?.parent !== null; current = current.parent) {
    ArrayPrototypePush(path, current.name);
  }
  ArrayPrototypeReverse(path);
  ArrayPrototypePush(path, name);
  return path;
}

function cloneSample(sample) {
  const result = {
    __proto__: null,
    operations: sample.operations,
    duration_ns: sample.duration_ns,
    rate: sample.rate,
  };
  if (sample.detail !== undefined) {
    result.detail = structuredClone(sample.detail);
  }
  return result;
}

class Suite extends AsyncResource {
  constructor(harness, parent, name, options, fn, loc, isRoot = false) {
    super('BenchSuite');
    const validated = validateNodeOptions(
      options,
      parent?.tags ?? kEmptyTags,
      parent?.diagnosticChannels ?? kEmptyDiagnosticChannels,
    );

    this.harness = harness;
    this.parent = parent;
    this.name = name;
    this.fn = fn;
    this.loc = createLocation(loc, harness.entryFile);
    this.isRoot = isRoot;
    this.fileScope = isRoot ? null :
      (parent.isRoot ? harness.getFileScope() : parent.fileScope);
    this.namePath = isRoot ? kEmptyNamePath :
      ObjectFreeze(getNamePath(parent, name));
    this.suiteId = isRoot ? null : JSONStringify([
      this.loc.file,
      this.namePath,
    ]);
    this.parentId = isRoot || parent.isRoot ? null : parent.suiteId;
    this.diagnosticChannels = validated.diagnosticChannels;
    this.only = validated.only;
    this.skip = validated.skip;
    this.tags = validated.tags;
    this.children = [];
    this.hooks = {
      __proto__: null,
      after: [],
      afterEach: [],
      before: [],
      beforeEach: [],
    };
    this.buildError = null;
    this.buildPromise = null;
    this.finished = false;
    this.completion = PromiseWithResolvers();
  }
}

class Bench extends AsyncResource {
  constructor(harness, parent, name, options, fn, loc) {
    super('Benchmark');
    const validated = validateNodeOptions(
      options, parent.tags, parent.diagnosticChannels);
    const {
      params,
      samples = kDefaultSamples,
      signal,
      timeout = Infinity,
      warmup = kDefaultWarmup,
    } = options;

    validateUint32(samples, 'options.samples', true);
    validateUint32(warmup, 'options.warmup');
    validateAbortSignal(signal, 'options.signal');
    if (timeout !== Infinity) {
      validateNumber(timeout, 'options.timeout', 0, TIMEOUT_MAX);
    }

    this.harness = harness;
    this.parent = parent;
    this.name = name;
    this.fn = fn;
    this.loc = createLocation(loc, harness.entryFile);
    this.diagnosticChannels = validated.diagnosticChannels;
    this.only = validated.only;
    this.skip = validated.skip;
    this.tags = validated.tags;
    this.params = canonicalizeParams(params);
    this.samples = samples;
    this.warmup = warmup;
    this.timeout = timeout;
    this.outerSignal = signal;
    this.fileScope = parent.isRoot ? harness.getFileScope() : parent.fileScope;
    this.namePath = ObjectFreeze(getNamePath(parent, name));
    this.fullName = ArrayPrototypeJoin(this.namePath, ' ');
    this.benchId = JSONStringify([
      this.loc.file,
      this.namePath,
      this.params,
    ]);
    this.parentId = parent.suiteId;
    this.finished = false;
    this.result = null;
    this.completion = PromiseWithResolvers();
  }
}

class BenchContext {
  #closed = false;
  #done = false;
  #endCalled = false;
  #index;
  #invalid = false;
  #onDiagnostic;
  #phase;
  #recordCalled = false;
  #sample = null;
  #startCalled = false;
  #startTime;

  constructor(bench, signal, phase, index, onDiagnostic) {
    this.name = bench.name;
    this.params = bench.params;
    this.signal = signal;
    this.#phase = phase;
    this.#index = index;
    this.#onDiagnostic = onDiagnostic;
  }

  get index() {
    return this.#index;
  }

  get phase() {
    return this.#phase;
  }

  diagnostic(message, options = kEmptyObject) {
    if (this.#closed) {
      this.#invalid = true;
      throw new ERR_INVALID_STATE('benchmark sample is no longer active');
    }
    try {
      const clonedMessage = structuredClone(message);
      validateObject(options, 'options');
      const { detail, level = 'info' } = options;
      validateString(level, 'options.level');
      if (level !== 'info' && level !== 'warning') {
        throw new ERR_INVALID_ARG_VALUE(
          'options.level', level, "must be 'info' or 'warning'");
      }
      const diagnostic = { __proto__: null, level, message: clonedMessage };
      if (detail !== undefined) diagnostic.detail = structuredClone(detail);
      this.#onDiagnostic(diagnostic);
    } catch (error) {
      this.#invalid = true;
      throw error;
    }
  }

  start() {
    if (this.#closed) {
      this.#invalid = true;
      throw new ERR_INVALID_STATE('benchmark sample is no longer active');
    }
    if (this.#recordCalled) {
      this.#invalid = true;
      throw new ERR_INVALID_STATE(
        'start() cannot be combined with record()');
    }
    if (this.#startCalled) {
      this.#invalid = true;
      throw new ERR_INVALID_STATE(
        'start() must be called exactly once per benchmark sample');
    }
    this.#startCalled = true;
    this.#startTime = hrtime();
  }

  end(operations, options = kEmptyObject) {
    const endTime = hrtime();
    if (this.#closed) {
      this.#invalid = true;
      throw new ERR_INVALID_STATE('benchmark sample is no longer active');
    }
    if (this.#recordCalled) {
      this.#invalid = true;
      throw new ERR_INVALID_STATE(
        'end() cannot be combined with record()');
    }
    if (this.#endCalled) {
      this.#invalid = true;
      throw new ERR_INVALID_STATE(
        'end() must be called exactly once per benchmark sample');
    }
    this.#endCalled = true;
    if (!this.#startCalled) {
      this.#invalid = true;
      throw new ERR_INVALID_STATE('end() cannot be called before start()');
    }

    try {
      validateObject(options, 'options');
      const { detail } = options;
      validateInteger(operations, 'operations', 1, NumberMAX_SAFE_INTEGER);
      const duration = endTime - this.#startTime;
      if (duration === 0n) {
        throw new ERR_INVALID_STATE(
          'insufficient clock precision for benchmark sample');
      }
      this.#sample = {
        __proto__: null,
        operations,
        duration_ns: duration,
        rate: operations / (Number(duration) / 1e9),
      };
      if (detail !== undefined) {
        this.#sample.detail = structuredClone(detail);
      }
    } catch (error) {
      this.#invalid = true;
      throw error;
    }
    return cloneSample(this.#sample);
  }

  record(sample) {
    if (this.#closed) {
      this.#invalid = true;
      throw new ERR_INVALID_STATE('benchmark sample is no longer active');
    }
    if (this.#recordCalled) {
      this.#invalid = true;
      throw new ERR_INVALID_STATE(
        'record() must be called exactly once per benchmark sample');
    }
    if (this.#startCalled || this.#endCalled) {
      this.#invalid = true;
      throw new ERR_INVALID_STATE(
        'record() cannot be combined with start() or end()');
    }
    this.#recordCalled = true;

    try {
      validateObject(sample, 'sample');
      const { detail, duration_ns, operations } = sample;
      validateInteger(
        operations, 'sample.operations', 1, NumberMAX_SAFE_INTEGER);
      if (typeof duration_ns !== 'bigint') {
        throw new ERR_INVALID_ARG_TYPE(
          'sample.duration_ns', 'bigint', duration_ns);
      }
      if (duration_ns <= 0n) {
        throw new ERR_OUT_OF_RANGE(
          'sample.duration_ns', 'a positive bigint', duration_ns);
      }
      if (duration_ns > 9_007_199_254_740_991n) {
        throw new ERR_OUT_OF_RANGE(
          'sample.duration_ns',
          'less than or equal to Number.MAX_SAFE_INTEGER',
          duration_ns);
      }
      this.#sample = {
        __proto__: null,
        operations,
        duration_ns,
        rate: operations / (Number(duration_ns) / 1e9),
      };
      if (detail !== undefined) {
        this.#sample.detail = structuredClone(detail);
      }
    } catch (error) {
      this.#invalid = true;
      throw error;
    }
    return cloneSample(this.#sample);
  }

  done() {
    if (this.#closed) {
      this.#invalid = true;
      throw new ERR_INVALID_STATE('benchmark sample is no longer active');
    }
    if (this.#phase !== 'measurement') {
      this.#invalid = true;
      throw new ERR_INVALID_STATE(
        'done() can only be called during a measured sample');
    }
    this.#done = true;
  }

  finish() {
    this.#closed = true;
    if (this.#invalid) {
      throw new ERR_INVALID_STATE(
        'benchmark sample violated the context method contract');
    }
    if (!this.#recordCalled && !this.#startCalled) {
      throw new ERR_INVALID_STATE(
        'benchmark callback did not call start() or record()');
    }
    if (!this.#recordCalled && (!this.#endCalled || this.#sample === null)) {
      throw new ERR_INVALID_STATE(
        'benchmark callback did not call end()');
    }
    return {
      __proto__: null,
      done: this.#done,
      sample: this.#sample,
    };
  }

  close() {
    this.#closed = true;
  }
}

function arithmeticMean(values) {
  let sum = 0;
  let compensation = 0;
  for (let i = 0; i < values.length; i++) {
    const adjusted = values[i] - compensation;
    const next = sum + adjusted;
    compensation = (next - sum) - adjusted;
    sum = next;
  }
  return sum / values.length;
}

function summarizeSamples(samples) {
  const rates = [];
  let min = Infinity;
  let max = -Infinity;
  for (let i = 0; i < samples.length; i++) {
    const rate = samples[i].rate;
    ArrayPrototypePush(rates, rate);
    min = MathMin(min, rate);
    max = MathMax(max, rate);
  }

  const mean = arithmeticMean(rates);
  let variance = 0;
  for (let i = 0; i < rates.length; i++) {
    const difference = rates[i] - mean;
    variance += difference * difference;
  }
  variance /= rates.length;
  const stddev = MathSqrt(variance);

  const sorted = ArrayPrototypeSlice(rates);
  ArrayPrototypeSort(sorted, (a, b) => a - b);
  const middle = MathFloor(sorted.length / 2);
  const median = sorted.length % 2 === 0 ?
    (sorted[middle - 1] + sorted[middle]) / 2 : sorted[middle];

  const scale = MathMin(1_000_000, NumberMAX_SAFE_INTEGER / max);
  const histogram = createHistogram({ __proto__: null, figures: 5 });
  for (let i = 0; i < rates.length; i++) {
    const value = MathMin(NumberMAX_SAFE_INTEGER, MathRound(rates[i] * scale));
    histogram.record(value);
  }

  const meanCI = histogram.meanCI();
  const histogramMean = meanCI.mean / scale;
  const medianCI = histogram.percentileCI(50);

  return {
    __proto__: null,
    mean,
    median,
    min,
    max,
    stddev,
    coefficientOfVariation: stddev / mean,
    confidenceInterval: {
      __proto__: null,
      lower: mean + meanCI.lower / scale - histogramMean,
      upper: mean + meanCI.upper / scale - histogramMean,
    },
    medianConfidenceInterval: {
      __proto__: null,
      lower: medianCI.lower / scale,
      upper: medianCI.upper / scale,
    },
    skewness: histogram.skewness,
  };
}

function normalizeArgs(type, name, options, fn) {
  if (typeof name === 'function') {
    fn = name;
    name = fn.name || '<anonymous>';
    options = kEmptyObject;
  } else if (name !== null && typeof name === 'object') {
    fn = options;
    options = name;
    name = fn?.name || '<anonymous>';
  } else if (typeof options === 'function') {
    fn = options;
    options = kEmptyObject;
  }

  validateFunction(fn, `${type} function`);
  validateString(name, `${type} name`);
  if (name.length === 0) {
    throw new ERR_INVALID_ARG_VALUE(`${type} name`, name, 'must not be empty');
  }
  validateObject(options, 'options');
  return { __proto__: null, fn, name, options };
}

module.exports = {
  Bench,
  BenchContext,
  Suite,
  normalizeArgs,
  summarizeSamples,
};

sources.internal/bench_runner/benchmarks_stream:
'use strict';

const {
  ArrayFrom,
  ArrayIsArray,
  ArrayPrototypePush,
  MapPrototypeClear,
  MapPrototypeEntries,
  MapPrototypeSet,
  ObjectDefineProperty,
  ObjectGetOwnPropertyDescriptor,
  ObjectGetOwnPropertyNames,
  ObjectGetPrototypeOf,
  ObjectKeys,
  ObjectPrototype,
  ObjectPrototypeHasOwnProperty,
  ObjectSetPrototypeOf,
  PromiseReject,
  PromiseResolve,
  PromiseWithResolvers,
  SafeMap,
  SetPrototypeAdd,
  SetPrototypeClear,
  SetPrototypeValues,
  Symbol,
} = primordials;
const { Readable } = require('stream');
const { deserializeError, serializeError } = require('internal/error_serdes');
const {
  codes: {
    ERR_INVALID_STATE,
  },
} = require('internal/errors');
const { isError } = require('internal/util');
const { isMap, isSet } = require('internal/util/types');
const { structuredClone } = require('internal/worker/js_transferable');

const kEmitMessage = Symbol('kEmitMessage');

function repairError(source, clone, seen) {
  const serialized = deserializeError(serializeError(source));
  let sourceName;
  try {
    sourceName = source.name;
  } catch {
    // The serialized form already omits properties whose getters throw.
  }
  let repaired = clone;
  if (!isError(repaired) ||
      (sourceName !== undefined && repaired.name !== sourceName)) {
    repaired = serialized;
  }
  if (repaired === null || typeof repaired !== 'object') return repaired;
  seen.set(source, repaired);

  if (serialized !== null && typeof serialized === 'object') {
    const serializedKeys = ObjectGetOwnPropertyNames(serialized);
    for (let i = 0; i < serializedKeys.length; i++) {
      const key = serializedKeys[i];
      if (ObjectPrototypeHasOwnProperty(repaired, key)) continue;
      const descriptor = ObjectGetOwnPropertyDescriptor(serialized, key);
      ObjectSetPrototypeOf(descriptor, null);
      ObjectDefineProperty(repaired, key, descriptor);
    }
  }

  const keys = ObjectGetOwnPropertyNames(source);
  for (let i = 0; i < keys.length; i++) {
    const key = keys[i];
    const descriptor = ObjectGetOwnPropertyDescriptor(source, key);
    if (!ObjectPrototypeHasOwnProperty(descriptor, 'value') ||
        typeof descriptor.value === 'function' ||
        typeof descriptor.value === 'symbol') {
      continue;
    }
    const existing = ObjectGetOwnPropertyDescriptor(repaired, key);
    const value = descriptor.value !== null &&
      typeof descriptor.value === 'object' ?
      repairClone(descriptor.value, existing?.value, seen) : descriptor.value;
    if ((existing !== undefined && existing.value === value) ||
        existing?.configurable === false) {
      continue;
    }
    ObjectDefineProperty(repaired, key, {
      __proto__: null,
      configurable: descriptor.configurable,
      enumerable: descriptor.enumerable,
      value,
      writable: descriptor.writable,
    });
  }
  return repaired;
}

function repairClone(source, clone, seen) {
  if (source === null || (typeof source !== 'object' &&
                          typeof source !== 'function')) {
    return clone === undefined ? source : clone;
  }
  if (typeof source === 'function') return clone;
  if (seen.has(source)) return seen.get(source);
  if (isError(source)) return repairError(source, clone, seen);
  if (clone === null || typeof clone !== 'object') {
    try {
      clone = structuredClone(source);
    } catch {
      const prototype = ObjectGetPrototypeOf(source);
      if (!ArrayIsArray(source) && prototype !== null &&
          prototype !== ObjectPrototype) {
        return clone;
      }
      clone = ArrayIsArray(source) ? [] : { __proto__: prototype };
    }
  }
  seen.set(source, clone);
  if (isMap(source) && isMap(clone)) {
    const sourceEntries = ArrayFrom(MapPrototypeEntries(source));
    const cloneEntries = ArrayFrom(MapPrototypeEntries(clone));
    const repairedEntries = [];
    for (let i = 0; i < sourceEntries.length; i++) {
      ArrayPrototypePush(repairedEntries, [
        repairClone(sourceEntries[i][0], cloneEntries[i][0], seen),
        repairClone(sourceEntries[i][1], cloneEntries[i][1], seen),
      ]);
    }
    MapPrototypeClear(clone);
    for (let i = 0; i < repairedEntries.length; i++) {
      MapPrototypeSet(clone, repairedEntries[i][0], repairedEntries[i][1]);
    }
    return clone;
  }
  if (isSet(source) && isSet(clone)) {
    const sourceValues = ArrayFrom(SetPrototypeValues(source));
    const cloneValues = ArrayFrom(SetPrototypeValues(clone));
    const repairedValues = [];
    for (let i = 0; i < sourceValues.length; i++) {
      ArrayPrototypePush(
        repairedValues, repairClone(sourceValues[i], cloneValues[i], seen));
    }
    SetPrototypeClear(clone);
    for (let i = 0; i < repairedValues.length; i++) {
      SetPrototypeAdd(clone, repairedValues[i]);
    }
    return clone;
  }
  const prototype = ObjectGetPrototypeOf(source);
  if (prototype === null) ObjectSetPrototypeOf(clone, null);
  if (prototype !== null && prototype !== ObjectPrototype &&
      !ArrayIsArray(source)) {
    return clone;
  }
  const keys = ObjectKeys(source);
  for (let i = 0; i < keys.length; i++) {
    const key = keys[i];
    const descriptor = ObjectGetOwnPropertyDescriptor(source, key);
    if (!ObjectPrototypeHasOwnProperty(descriptor, 'value')) continue;
    const existing = ObjectGetOwnPropertyDescriptor(clone, key);
    const value = repairClone(descriptor.value, existing?.value, seen);
    if ((existing !== undefined && existing.value === value) ||
        existing?.configurable === false) {
      continue;
    }
    ObjectDefineProperty(clone, key, {
      __proto__: null,
      configurable: descriptor.configurable,
      enumerable: descriptor.enumerable,
      value,
      writable: descriptor.writable,
    });
  }
  if (ArrayIsArray(source)) {
    const descriptor = ObjectGetOwnPropertyDescriptor(source, 'length');
    ObjectSetPrototypeOf(descriptor, null);
    ObjectDefineProperty(clone, 'length', descriptor);
  }
  return clone;
}

function cloneRecordData(data) {
  let clone;
  try {
    clone = structuredClone(data);
  } catch (error) {
    if (data.error === undefined) throw error;
    clone = structuredClone({ __proto__: null, ...data, error: undefined });
    clone.error = deserializeError(serializeError(data.error));
  }
  try {
    return repairClone(data, clone, new SafeMap());
  } catch {
    return clone;
  }
}

class BenchmarksStream extends Readable {
  #blocked = false;
  #drainWaiters = [];
  #hasReader = false;

  constructor() {
    super({
      __proto__: null,
      objectMode: true,
    });
  }

  _read() {
    if (this.#blocked) {
      this.#blocked = false;
      const waiters = this.#drainWaiters;
      this.#drainWaiters = [];
      for (let i = 0; i < waiters.length; i++) waiters[i].resolve();
    }
  }

  read(size) {
    if (size !== 0) this.#hasReader = true;
    return super.read(size);
  }

  _destroy(error, callback) {
    const failure = error ??
      new ERR_INVALID_STATE('benchmark stream is closed');
    const waiters = this.#drainWaiters;
    this.#drainWaiters = [];
    for (let i = 0; i < waiters.length; i++) waiters[i].reject(failure);
    callback(error);
  }

  waitForDrain() {
    if (this.destroyed) {
      return PromiseReject(this.errored ??
        new ERR_INVALID_STATE('benchmark stream is closed'));
    }
    if (!this.#blocked) return PromiseResolve();
    const waiter = PromiseWithResolvers();
    ArrayPrototypePush(this.#drainWaiters, waiter);
    return waiter.promise;
  }

  plan(data) {
    return this[kEmitMessage]('bench:plan', data);
  }

  start(data) {
    return this[kEmitMessage]('bench:start', data);
  }

  sample(data) {
    return this[kEmitMessage]('bench:sample', data);
  }

  complete(data) {
    return this[kEmitMessage]('bench:complete', data);
  }

  diagnostic(data) {
    return this[kEmitMessage]('bench:diagnostic', data);
  }

  summary(data) {
    return this[kEmitMessage]('bench:summary', data);
  }

  end() {
    return this.#tryPush(null);
  }

  [kEmitMessage](type, data) {
    const recordData = cloneRecordData(data);
    const record = { __proto__: null, type, data: recordData };
    if (this.listenerCount(type) > 0) {
      this.emit(type, cloneRecordData(recordData));
    }
    return this.#tryPush(record);
  }

  #tryPush(record) {
    if (this.destroyed) return false;
    const canPush = this.push(record);
    if (record !== null && !canPush && this.#hasReader) {
      this.#blocked = true;
      return false;
    }
    return true;
  }
}

module.exports = {
  BenchmarksStream,
};

sources.internal/bench_runner/cli:
'use strict';

const {
  ArrayFrom,
  ArrayIsArray,
  ArrayPrototypeFilter,
  ArrayPrototypeIncludes,
  ArrayPrototypeJoin,
  ArrayPrototypePush,
  ArrayPrototypePushApply,
  ArrayPrototypeSlice,
  ArrayPrototypeSome,
  ArrayPrototypeSort,
  MathMax,
  NumberIsFinite,
  NumberIsSafeInteger,
  ObjectGetOwnPropertyDescriptor,
  ObjectGetPrototypeOf,
  ObjectKeys,
  ObjectPrototype,
  ObjectPrototypeHasOwnProperty,
  ObjectValues,
  Promise,
  PromisePrototypeThen,
  PromiseReject,
  PromiseResolve,
  PromiseWithResolvers,
  RegExp,
  SafeMap,
  SafePromiseAllReturnVoid,
  SafeSet,
  String,
  StringPrototypeIndexOf,
  StringPrototypeReplaceAll,
  StringPrototypeSlice,
  StringPrototypeStartsWith,
  StringPrototypeToUpperCase,
  SymbolDispose,
  uncurryThis,
} = primordials;
const { Buffer } = require('buffer');
const BufferToString = uncurryThis(Buffer.prototype.toString);
const { spawn } = require('child_process');
const { createWriteStream, statSync } = require('fs');
const { Glob } = require('internal/fs/glob');
const { getValidatedPath } = require('internal/fs/utils');
const {
  BenchmarksStream,
} = require('internal/bench_runner/benchmarks_stream');
const {
  configureRunScope,
  createRunId,
  runInFileScope,
  runBenchmarks,
} = require('internal/bench_runner/harness');
const { deserializeError, serializeError } = require('internal/error_serdes');
const {
  AbortError,
  codes: {
    ERR_ACCESS_DENIED,
    ERR_INVALID_ARG_TYPE,
    ERR_INVALID_ARG_VALUE,
    ERR_INVALID_STATE,
  },
} = require('internal/errors');
const { addAbortListener } = require('internal/events/abort_listener');
const {
  getCLIOptionsInfo,
  getOptionValue,
  getOptionsAsFlagsFromBinding,
} = require('internal/options');
const permission = require('internal/process/permission');
const { TIMEOUT_MAX } = require('internal/timers');
const { kEmptyObject } = require('internal/util');
const {
  validateAbortSignal,
  validateArray,
  validateObject,
  validateStringWithoutNullBytes,
  validateUint32,
} = require('internal/validators');
const { pathToFileURL } = require('internal/url');
const { pipeline } = require('stream/promises');
const { resolve, sep } = require('path');
const { clearTimeout, setTimeout } = require('timers');

const console = require('internal/console/global');
const esmLoader = require('internal/modules/esm/loader');
const { bigint: hrtime } = process.hrtime;

const kBuiltinDestinations = new SafeMap([
  ['stdout', process.stdout],
  ['stderr', process.stderr],
]);
const kBuiltinReporters = new SafeMap([
  ['json', 'internal/bench_runner/reporter/json'],
  ['spec', 'internal/bench_runner/reporter/spec'],
]);
const kChildAckMessageType = 'node:bench:ack';
const kChildMessageType = 'node:bench:record';
const kEventTypes = new SafeSet([
  'bench:plan',
  'bench:start',
  'bench:sample',
  'bench:complete',
  'bench:diagnostic',
  'bench:summary',
]);
const kFilterArgs = [
  '--bench',
  '--experimental-bench',
  '--experimental-default-config-file',
];
const kFilterArgValues = [
  '--bench-isolation',
  '--bench-name-pattern',
  '--bench-reporter',
  '--bench-reporter-destination',
  '--bench-samples',
  '--bench-warmup',
  '--config-file',
  '--experimental-config-file',
];
const kIncompatibleExecArgv = new SafeSet([
  '--build-sea',
  '--build-snapshot',
  '--build-snapshot-config',
  '--check',
  '--completion-bash',
  '--eval',
  '--experimental-sea-config',
  '--help',
  '--help-all',
  '--input-type',
  '--interactive',
  '--print',
  '--prof-process',
  '--run',
  '--test',
  '--version',
  '--v8-options',
  '--watch',
  '--watch-path',
  '-c',
  '-e',
  '-h',
  '-i',
  '-p',
  '-v',
]);
const kExecArgvWithValue = new SafeSet([
  '--eval',
  '--input-type',
  '--print',
  '--run',
  '--watch-path',
  '-e',
  '-p',
]);
const kIPCEnvironmentVariables = new SafeSet([
  'NODE_CHANNEL_FD',
  'NODE_CHANNEL_SERIALIZATION_MODE',
  'NODE_BENCH_CONTEXT',
  'NODE_BENCH_FILE_RUN_ID',
  'NODE_BENCH_RUN_ID',
  'NODE_OPTIONS',
]);
const kForceKillDelay = 1_000;

function createBenchmarkFileList(patterns, cwd) {
  if (patterns.length === 0) {
    console.error('--bench requires at least one file or glob pattern');
    return null;
  }

  const glob = new Glob(patterns, { __proto__: null, cwd });
  const files = ArrayPrototypeFilter(glob.globSync(), (path) => {
    try {
      return statSync(resolve(cwd, path)).isFile();
    } catch {
      return false;
    }
  });
  if (files.length === 0) {
    console.error(`Could not find '${ArrayPrototypeJoin(patterns, ', ')}'`);
    return null;
  }
  return ArrayPrototypeSort(files);
}

function createChildFileList(patterns, cwd) {
  if (patterns.length !== 1) {
    console.error('benchmark child process requires exactly one file');
    return null;
  }
  const path = resolve(cwd, patterns[0]);
  try {
    if (statSync(path).isFile()) return [path];
  } catch {
    // Fall through to the standard not-found diagnostic.
  }
  console.error(`Could not find '${patterns[0]}'`);
  return null;
}

function createFileScopes(files, options) {
  const scopes = [];
  for (let i = 0; i < files.length; i++) {
    ArrayPrototypePush(scopes, {
      __proto__: null,
      entryFile: resolve(options.cwd, files[i]),
      fileRunId: options.isChild && i === 0 &&
        options.fileRunId !== undefined ? options.fileRunId : createRunId(),
    });
  }
  return scopes;
}

function parseNamePattern(value) {
  if (value.length === 0) return undefined;
  try {
    return new RegExp(value);
  } catch (error) {
    throw new ERR_INVALID_ARG_VALUE(
      '--bench-name-pattern', value,
      `is an invalid regular expression. ${error.message}`);
  }
}

function parseCommandLine() {
  const reporters = getOptionValue('--bench-reporter');
  const destinations = getOptionValue('--bench-reporter-destination');
  const isChild = process.env.NODE_BENCH_CONTEXT === 'child' &&
    typeof process.send === 'function';

  if (!isChild) {
    if (reporters.length === 0 && destinations.length === 0) {
      ArrayPrototypePush(reporters, 'spec');
    }
    if (reporters.length === 1 && destinations.length === 0) {
      ArrayPrototypePush(destinations, 'stdout');
    }
    if (reporters.length !== destinations.length) {
      throw new ERR_INVALID_ARG_VALUE(
        '--bench-reporter', reporters,
        'must match the number of specified ' +
        "'--bench-reporter-destination'");
    }
  }

  const samples = getOptionValue('[has_bench_samples]') ?
    getOptionValue('--bench-samples') : undefined;
  const warmup = getOptionValue('[has_bench_warmup]') ?
    getOptionValue('--bench-warmup') : undefined;
  if (samples !== undefined) {
    validateUint32(samples, '--bench-samples', true);
  }
  if (warmup !== undefined) {
    validateUint32(warmup, '--bench-warmup');
  }

  return {
    __proto__: null,
    cwd: process.cwd(),
    destinations,
    fileRunId: isChild && process.env.NODE_BENCH_FILE_RUN_ID ?
      process.env.NODE_BENCH_FILE_RUN_ID : undefined,
    isChild,
    isolation: getOptionValue('--bench-isolation'),
    namePattern: parseNamePattern(getOptionValue('--bench-name-pattern')),
    namePatternSource: getOptionValue('--bench-name-pattern'),
    reporters,
    runId: isChild && process.env.NODE_BENCH_RUN_ID ?
      process.env.NODE_BENCH_RUN_ID : undefined,
    samples,
    warmup,
  };
}

async function loadReporter(name) {
  const builtin = kBuiltinReporters.get(name);
  let reporter;
  if (builtin !== undefined) {
    reporter = require(builtin);
  } else {
    let parentURL;
    try {
      parentURL = pathToFileURL(`${process.cwd()}${sep}`).href;
    } catch {
      parentURL = 'file:///';
    }
    const loader = esmLoader.getOrInitializeCascadedLoader();
    reporter = await loader.import(name, parentURL, kEmptyObject);
  }

  reporter = reporter?.default ?? reporter;
  if (reporter?.prototype &&
      ObjectGetOwnPropertyDescriptor(reporter.prototype, 'constructor')) {
    reporter = new reporter();
  }
  if (!reporter) {
    throw new ERR_INVALID_ARG_VALUE(
      '--bench-reporter', name, 'is not a valid reporter');
  }
  return reporter;
}

async function setupReporters(stream, reporters, destinations) {
  const state = { __proto__: null, error: undefined, pending: [] };
  try {
    for (let i = 0; i < reporters.length; i++) {
      const reporter = await loadReporter(reporters[i]);
      const builtinDestination = kBuiltinDestinations.get(destinations[i]);
      const destination = builtinDestination ??
        createWriteStream(destinations[i], { __proto__: null, flush: true });
      const pending = PromisePrototypeThen(pipeline(
        stream,
        reporter,
        destination,
        { __proto__: null, end: builtinDestination === undefined },
      ), undefined, (error) => {
        state.error ??= error;
      });
      ArrayPrototypePush(state.pending, pending);
    }
  } catch (error) {
    stream.destroy();
    await SafePromiseAllReturnVoid(state.pending);
    throw error;
  }
  return state;
}

async function finishReporters(state) {
  await SafePromiseAllReturnVoid(state.pending);
  if (state.error !== undefined) throw state.error;
}

function emitRecord(stream, record) {
  switch (record.type) {
    case 'bench:plan':
      return stream.plan(record.data);
    case 'bench:start':
      return stream.start(record.data);
    case 'bench:sample':
      return stream.sample(record.data);
    case 'bench:complete':
      return stream.complete(record.data);
    case 'bench:diagnostic':
      return stream.diagnostic(record.data);
    case 'bench:summary':
      return stream.summary(record.data);
    default:
      throw new ERR_INVALID_ARG_VALUE(
        'benchmark event type', record.type, 'is not recognized');
  }
}

function emitRecordAndWait(stream, record) {
  if (stream.destroyed) {
    return PromiseReject(stream.errored ??
      new ERR_INVALID_STATE('benchmark output stream is closed'));
  }
  if (emitRecord(stream, record)) return undefined;
  if (stream.destroyed) {
    return PromiseReject(stream.errored ??
      new ERR_INVALID_STATE('benchmark output stream is closed'));
  }
  return stream.waitForDrain();
}

function serializeRecord(record) {
  if (record.data.error === undefined) return record;
  return {
    __proto__: null,
    type: record.type,
    data: {
      __proto__: null,
      ...record.data,
      error: serializeError(record.data.error),
    },
  };
}

function deserializeRecord(record) {
  if (record.data.error === undefined) return record;
  return {
    __proto__: null,
    type: record.type,
    data: {
      __proto__: null,
      ...record.data,
      error: deserializeError(record.data.error),
    },
  };
}

function isStringArray(value) {
  if (!ArrayIsArray(value)) return false;
  for (let i = 0; i < value.length; i++) {
    if (typeof value[i] !== 'string') return false;
  }
  return true;
}

function isContextDiagnostic(record) {
  return record.type === 'bench:diagnostic' &&
    (record.data.benchId !== undefined ||
     record.data.phase !== undefined ||
     record.data.index !== undefined ||
     record.data.detail !== undefined);
}

function validateRecord(record) {
  if (record === null || typeof record !== 'object' ||
      !kEventTypes.has(record.type) || record.data === null ||
      typeof record.data !== 'object' ||
      typeof record.data.runId !== 'string' ||
      (record.data.fileRunId !== null &&
       typeof record.data.fileRunId !== 'string') ||
      (record.data.entryFile !== null &&
       typeof record.data.entryFile !== 'string')) {
    throw new ERR_INVALID_ARG_VALUE(
      'benchmark child message', record, 'is not a valid benchmark record');
  }
  const contextDiagnostic = isContextDiagnostic(record);
  if ((record.type === 'bench:plan' || record.type === 'bench:start' ||
       record.type === 'bench:sample' || record.type === 'bench:complete' ||
       contextDiagnostic) &&
      (typeof record.data.fileRunId !== 'string' ||
       typeof record.data.benchId !== 'string' ||
       (record.data.parentId !== null &&
         typeof record.data.parentId !== 'string') ||
        typeof record.data.name !== 'string' ||
        !isStringArray(record.data.namePath))) {
    throw new ERR_INVALID_ARG_VALUE(
      'benchmark child message', record, 'is not a valid benchmark record');
  }
  if (record.type === 'bench:plan') {
    const {
      samples,
      selected,
      skip,
      timeout,
      warmup,
      yieldBetweenSamples,
    } = record.data;
    if (!isStringArray(record.data.diagnosticChannels) ||
        typeof record.data.file !== 'string' ||
        !NumberIsSafeInteger(record.data.line) || record.data.line < 0 ||
        !NumberIsSafeInteger(record.data.column) || record.data.column < 0 ||
        !isStringArray(record.data.tags) ||
        record.data.params === null ||
        typeof record.data.params !== 'object' ||
        ArrayIsArray(record.data.params) ||
        (ObjectGetPrototypeOf(record.data.params) !== null &&
         ObjectGetPrototypeOf(record.data.params) !== ObjectPrototype) ||
        ArrayPrototypeSome(ObjectValues(record.data.params), (value) =>
          typeof value !== 'string' && typeof value !== 'boolean' &&
          (typeof value !== 'number' || !NumberIsFinite(value))) ||
        !NumberIsSafeInteger(samples) || samples <= 0 ||
        samples > 0xFFFFFFFF ||
        !NumberIsSafeInteger(warmup) || warmup < 0 || warmup > 0xFFFFFFFF ||
        (timeout !== null &&
         (!NumberIsFinite(timeout) || timeout < 0 || timeout > TIMEOUT_MAX)) ||
        typeof yieldBetweenSamples !== 'boolean' ||
        typeof selected !== 'boolean' ||
        (selected && skip !== undefined) ||
        (!selected && skip !== true && typeof skip !== 'string')) {
      throw new ERR_INVALID_ARG_VALUE(
        'benchmark child plan', record.data,
        'is not a valid benchmark plan');
    }
  }
  if (contextDiagnostic &&
      ((record.data.phase !== 'warmup' &&
        record.data.phase !== 'measurement') ||
       !NumberIsSafeInteger(record.data.index) || record.data.index < 0 ||
       record.data.index > 0xFFFFFFFF ||
       !ObjectPrototypeHasOwnProperty(record.data, 'message') ||
       (record.data.level !== 'info' && record.data.level !== 'warning') ||
       typeof record.data.file !== 'string' ||
       !NumberIsSafeInteger(record.data.line) || record.data.line < 0 ||
       !NumberIsSafeInteger(record.data.column) || record.data.column < 0 ||
       record.data.error !== undefined)) {
    throw new ERR_INVALID_ARG_VALUE(
      'benchmark child diagnostic', record.data,
      'is not a valid benchmark diagnostic');
  }
  if (record.type === 'bench:summary') {
    const { counts, duration_ns, success } = record.data;
    if (typeof success !== 'boolean' || typeof duration_ns !== 'bigint' ||
        counts === null || typeof counts !== 'object' ||
        !NumberIsSafeInteger(counts.completed) || counts.completed < 0 ||
        !NumberIsSafeInteger(counts.failed) || counts.failed < 0 ||
        !NumberIsSafeInteger(counts.skipped) || counts.skipped < 0 ||
        !NumberIsSafeInteger(counts.total) || counts.total < 0) {
      throw new ERR_INVALID_ARG_VALUE(
        'benchmark child summary', record.data,
        'is not a valid benchmark summary');
    }
  }
  return record;
}

let nextChildRecordId = 0;
let listeningForAcks = false;
const pendingChildRecordAcks = new SafeMap();

function listenForAcks() {
  if (listeningForAcks) return;
  listeningForAcks = true;
  process.on('message', (message) => {
    if (message?.type !== kChildAckMessageType) return;
    const pending = pendingChildRecordAcks.get(message.id);
    if (pending === undefined) return;
    pendingChildRecordAcks.delete(message.id);
    pending.resolve();
  });
  process.once('disconnect', () => {
    const error = new ERR_INVALID_STATE(
      'benchmark IPC channel closed before acknowledging records');
    for (const pending of pendingChildRecordAcks.values()) {
      pending.reject(error);
    }
    pendingChildRecordAcks.clear();
  });
}

function sendRecord(record) {
  listenForAcks();
  const id = nextChildRecordId++;
  const acknowledged = PromiseWithResolvers();
  pendingChildRecordAcks.set(id, acknowledged);
  try {
    process.send({
      __proto__: null,
      id,
      type: kChildMessageType,
      record: serializeRecord(record),
    }, undefined, undefined, (error) => {
      if (error) {
        pendingChildRecordAcks.delete(id);
        acknowledged.reject(error);
      }
    });
  } catch (error) {
    pendingChildRecordAcks.delete(id);
    acknowledged.reject(error);
  }
  return acknowledged.promise;
}

function sendAck(child, id) {
  return new Promise((resolve, reject) => {
    if (!child.connected) {
      reject(new ERR_INVALID_STATE(
        'benchmark child disconnected before acknowledgement'));
      return;
    }
    child.send({ __proto__: null, id, type: kChildAckMessageType },
               undefined, undefined, (error) => {
                 if (error) reject(error);
                 else resolve();
               });
  });
}

async function loadUserImports(options) {
  const parentURL = pathToFileURL(`${options.cwd}${sep}`).href;
  const loader = esmLoader.getOrInitializeCascadedLoader();
  const userImports = getOptionValue('--import');
  for (let i = 0; i < userImports.length; i++) {
    await loader.import(userImports[i], parentURL, kEmptyObject);
  }
  return { __proto__: null, loader, parentURL };
}

async function loadBenchmarkFiles(files, options, modules, onRecord) {
  const { loader, parentURL } = modules;
  let loadFailed = false;
  for (let i = 0; i < files.length; i++) {
    const file = resolve(options.cwd, files[i]);
    try {
      await runInFileScope(options.fileScopes[i], () =>
        loader.import(pathToFileURL(file), parentURL, kEmptyObject));
    } catch (error) {
      loadFailed = true;
      await onRecord({
        __proto__: null,
        type: 'bench:diagnostic',
        data: {
          __proto__: null,
          runId: options.runId,
          ...options.fileScopes[i],
          message: error?.message ?? String(error),
          error,
          level: 'error',
          file,
        },
      });
    }
  }

  const stream = runBenchmarks({
    __proto__: null,
    namePattern: options.namePattern,
    samples: options.samples,
    warmup: options.warmup,
  }, true);
  let summary;
  for await (const record of stream) {
    if (record.type === 'bench:summary' && (process.exitCode ?? 0) !== 0) {
      const scope = files.length === 1 ? options.fileScopes[0] : {
        __proto__: null,
        entryFile: null,
        fileRunId: null,
      };
      await onRecord({
        __proto__: null,
        type: 'bench:diagnostic',
        data: {
          __proto__: null,
          runId: options.runId,
          ...scope,
          message: `Benchmark process set exit code ${process.exitCode}`,
          level: 'error',
          file: files.length === 1 ?
            resolve(options.cwd, files[0]) : null,
        },
      });
    }
    if (record.type === 'bench:summary' &&
        (loadFailed || (process.exitCode ?? 0) !== 0)) {
      record.data.success = false;
    }
    if (record.type === 'bench:summary') {
      record.data.file = files.length === 1 ?
        resolve(options.cwd, files[0]) : null;
      record.data.fileRunId = files.length === 1 ?
        options.fileScopes[0].fileRunId : null;
      record.data.entryFile = files.length === 1 ?
        options.fileScopes[0].entryFile : null;
      summary = record.data;
    }
    await onRecord(record);
  }
  return summary;
}

function filterExecArgv(arg, index, args) {
  const name = getOptionName(arg);
  return !ArrayPrototypeIncludes(kFilterArgs, name) &&
    !ArrayPrototypeSome(kFilterArgValues, (option) => {
      return name === option ||
        (option !== '--config-file' &&
         option !== '--experimental-config-file' &&
         index > 0 &&
         StringPrototypeIndexOf(args[index - 1], '=') === -1 &&
         getOptionName(args[index - 1]) === option);
    });
}

function getOptionName(arg) {
  const equals = StringPrototypeIndexOf(arg, '=');
  const name = equals === -1 ? arg : StringPrototypeSlice(arg, 0, equals);
  return StringPrototypeReplaceAll(name, '_', '-');
}

function getRunFileOptionName(arg) {
  if (StringPrototypeStartsWith(arg, '-') &&
      !StringPrototypeStartsWith(arg, '--') && arg.length > 2) {
    const shortName = StringPrototypeSlice(arg, 0, 2);
    if (kIncompatibleExecArgv.has(shortName)) return shortName;
  }
  return getOptionName(arg);
}

function filterRunFileExecArgv(arg, index, args) {
  if (!filterExecArgv(arg, index, args)) return false;
  if (!StringPrototypeStartsWith(arg, '-') || arg === '-' || arg === '--') {
    return false;
  }
  const name = getRunFileOptionName(arg);
  if (kIncompatibleExecArgv.has(name)) return false;
  if (index > 0) {
    const previous = getRunFileOptionName(args[index - 1]);
    if (kExecArgvWithValue.has(previous) &&
        StringPrototypeIndexOf(args[index - 1], '=') === -1) {
      return false;
    }
  }
  return true;
}

function runFileOptionRequiresValue(arg) {
  const equals = StringPrototypeIndexOf(arg, '=');
  let name = getRunFileOptionName(arg);
  const { aliases, options } = getCLIOptionsInfo();
  let info = options.get(name);
  if (info === undefined) {
    const alias = aliases.get(name);
    if (alias !== undefined) info = options.get(alias[0]);
  }
  if (info === undefined && StringPrototypeStartsWith(name, '--no-')) {
    name = `--${StringPrototypeSlice(name, 5)}`;
    info = options.get(name);
  }
  return info !== undefined && info.type >= 3 &&
    (equals === -1 || equals === arg.length - 1);
}

const kOptionAliases = new SafeMap([
  ['--loader', '--experimental-loader'],
  ['-C', '--conditions'],
  ['-r', '--require'],
]);

function getInheritedChildArgs() {
  const nodeOptions = getOptionsAsFlagsFromBinding();
  const args = ArrayPrototypeFilter(nodeOptions, filterExecArgv);
  const nodeOptionNames = new SafeSet();
  for (let i = 0; i < nodeOptions.length; i++) {
    nodeOptionNames.add(getOptionName(nodeOptions[i]));
  }
  const unknownExecArgv = ArrayPrototypeFilter(
    process.execArgv,
    (arg, index, values) => {
      if (!filterExecArgv(arg, index, values)) return false;
      const optionName = getOptionName(arg);
      const name = kOptionAliases.get(optionName) ?? optionName;
      if (nodeOptionNames.has(name)) return false;
      if (!StringPrototypeStartsWith(arg, '-') && index > 0) {
        const previousName = getOptionName(values[index - 1]);
        const previous = kOptionAliases.get(previousName) ?? previousName;
        if (nodeOptionNames.has(previous)) return false;
      }
      return true;
    },
  );
  ArrayPrototypePushApply(args, unknownExecArgv);
  // Option serialization omits port 0, which would otherwise become 9229.
  if (process.debugPort === 0) ArrayPrototypePush(args, '--inspect-port=0');
  return args;
}

function getChildArgs(path, options) {
  const args = options.execArgv === undefined ?
    getInheritedChildArgs() : ArrayPrototypeSlice(options.execArgv);
  ArrayPrototypePush(
    args, '--experimental-bench', '--bench', '--bench-isolation=none');
  if (options.namePatternSource.length > 0) {
    ArrayPrototypePush(
      args, `--bench-name-pattern=${options.namePatternSource}`);
  }
  if (options.samples !== undefined) {
    ArrayPrototypePush(args, `--bench-samples=${options.samples}`);
  }
  if (options.warmup !== undefined) {
    ArrayPrototypePush(args, `--bench-warmup=${options.warmup}`);
  }
  ArrayPrototypePush(args, '--', resolve(options.cwd, path));
  return args;
}

async function runChild(path, options, scope, onRecord) {
  if (options.signal?.aborted) {
    return {
      __proto__: null,
      aborted: true,
      error: new AbortError(undefined, {
        __proto__: null,
        cause: options.signal.reason,
      }),
    };
  }
  const resource = resolve(options.cwd, path);
  if (permission.isEnabled() &&
      !permission.has('fs.read', resource) &&
      !permission.isAuditMode()) {
    throw new ERR_ACCESS_DENIED(
      'Access to this API has been restricted. Use --allow-fs-read to manage permissions.',
      'FileSystemRead',
      resource,
    );
  }
  const child = spawn(
    options.execPath ?? process.execPath,
    getChildArgs(path, options),
    {
      __proto__: null,
      cwd: options.cwd,
      env: {
        __proto__: null,
        ...(options.env ?? process.env),
        NODE_BENCH_CONTEXT: 'child',
        NODE_BENCH_FILE_RUN_ID: scope.fileRunId,
        NODE_BENCH_RUN_ID: options.runId,
      },
      serialization: 'advanced',
      stdio: ['inherit', 'pipe', 'pipe', 'ipc'],
    },
  );
  let childClosed = false;
  let forceKillTimer;
  const terminateChild = () => {
    if (childClosed) return;
    child.kill();
    forceKillTimer ??= setTimeout(() => {
      child.kill('SIGKILL');
    }, kForceKillDelay);
  };
  const closed = PromiseWithResolvers();
  let closeTracked = false;
  let spawnError;
  try {
    child.once('close', (...status) => closed.resolve(status));
    closeTracked = true;
    child.once('error', (error) => {
      spawnError ??= error;
      terminateChild();
    });
  } catch (error) {
    terminateChild();
    if (closeTracked) {
      try {
        await closed.promise;
      } catch {
        // Preserve the setup error.
      }
    }
    throw error;
  }
  let protocolError;
  let abortError;
  let aborted = false;
  let activeBenchId;
  let plansComplete = false;
  let recordPending = false;
  let summaryReceived = false;
  let abortListener;
  const closeListener = () => {
    terminateChild();
  };
  try {
    if (options.signal !== undefined) {
      abortListener = addAbortListener(options.signal, () => {
        aborted = true;
        abortError = new AbortError(undefined, {
          __proto__: null,
          cause: options.signal.reason,
        });
        terminateChild();
      });
    }
    options.output?.once('close', closeListener);
    if (options.output?.destroyed) closeListener();
  } catch (error) {
    terminateChild();
    try {
      await closed.promise;
    } catch {
      // Preserve the setup error.
    }
    childClosed = true;
    if (forceKillTimer !== undefined) clearTimeout(forceKillTimer);
    abortListener?.[SymbolDispose]();
    options.output?.removeListener('close', closeListener);
    throw error;
  }
  const pendingRecords = new SafeSet();
  const handleRecord = (record) => {
    if (protocolError !== undefined) return;
    try {
      return onRecord(record);
    } catch (error) {
      protocolError = error;
      terminateChild();
    }
  };
  const trackPending = (pending, source) => {
    if (pending === undefined) return;
    source?.pause();
    const tracked = PromisePrototypeThen(PromiseResolve(pending), () => {
      pendingRecords.delete(tracked);
      source?.resume();
    }, (error) => {
      pendingRecords.delete(tracked);
      if (!aborted) protocolError ??= error;
      terminateChild();
    });
    pendingRecords.add(tracked);
  };
  const reportOutput = (source, stream, message) => {
    const pending = handleRecord({
      __proto__: null,
      type: 'bench:diagnostic',
      data: {
        __proto__: null,
        runId: options.runId,
        ...scope,
        message,
        level: 'info',
        file: path,
        stream,
      },
    });
    trackPending(pending, source);
  };
  try {
    child.stdout.setEncoding('utf8');
    child.stderr.setEncoding('utf8');
    child.stdout.on('data', (data) => {
      reportOutput(child.stdout, 'stdout', data);
    });
    child.stderr.on('data', (data) => {
      reportOutput(child.stderr, 'stderr', data);
    });
    child.on('message', (message) => {
      if (message?.type !== kChildMessageType) return;
      try {
        if (!NumberIsSafeInteger(message.id) || message.id < 0 || recordPending) {
          throw new ERR_INVALID_ARG_VALUE(
            'benchmark child message', message,
            'does not have a valid record sequence');
        }
        recordPending = true;
        const record = deserializeRecord(validateRecord(message.record));
        const contextDiagnostic = isContextDiagnostic(record);
        if (summaryReceived || (record.type === 'bench:plan' && plansComplete) ||
            (record.type === 'bench:start' && activeBenchId !== undefined) ||
            ((record.type === 'bench:sample' || contextDiagnostic) &&
             activeBenchId !== record.data.benchId) ||
            (record.type === 'bench:complete' && activeBenchId !== undefined &&
             activeBenchId !== record.data.benchId) ||
            (record.type === 'bench:summary' && activeBenchId !== undefined)) {
          throw new ERR_INVALID_ARG_VALUE(
            'benchmark child message', message,
            'does not have a valid lifecycle sequence');
        }
        if (record.type !== 'bench:plan' &&
            record.type !== 'bench:diagnostic') {
          plansComplete = true;
        }
        if (record.type === 'bench:start') {
          activeBenchId = record.data.benchId;
        } else if (record.type === 'bench:complete' &&
                   activeBenchId === record.data.benchId) {
          activeBenchId = undefined;
        }
        if (record.type === 'bench:summary') summaryReceived = true;
        record.data.runId = options.runId;
        record.data.fileRunId = scope.fileRunId;
        if (record.data.entryFile !== null) {
          record.data.entryFile = scope.entryFile;
        }
        const pending = handleRecord(record);
        if (protocolError === undefined) {
          trackPending(PromisePrototypeThen(PromiseResolve(pending), () => {
            // The child can receive the acknowledgement and send its next
            // record before the send callback runs.
            recordPending = false;
            return sendAck(child, message.id);
          }));
        }
      } catch (error) {
        if (!aborted) protocolError ??= error;
        terminateChild();
      }
    });
  } catch (error) {
    terminateChild();
    try {
      await closed.promise;
    } catch {
      // Preserve the setup error.
    }
    childClosed = true;
    if (forceKillTimer !== undefined) clearTimeout(forceKillTimer);
    abortListener?.[SymbolDispose]();
    options.output?.removeListener('close', closeListener);
    throw error;
  }
  let status;
  try {
    status = await closed.promise;
  } finally {
    childClosed = true;
    if (forceKillTimer !== undefined) clearTimeout(forceKillTimer);
    abortListener?.[SymbolDispose]();
    options.output?.removeListener('close', closeListener);
  }
  const { 0: code, 1: signal } = status;
  await SafePromiseAllReturnVoid(ArrayFrom(pendingRecords));
  if (!aborted && spawnError !== undefined) throw spawnError;
  if (!aborted && protocolError !== undefined) throw protocolError;
  return {
    __proto__: null,
    aborted,
    code,
    error: abortError,
    signal,
  };
}

async function runIsolated(files, options, output) {
  const counts = {
    __proto__: null,
    completed: 0,
    failed: 0,
    skipped: 0,
    total: 0,
  };
  const start = hrtime();
  let success = true;

  for (let i = 0; i < files.length; i++) {
    const path = files[i];
    const scope = options.fileScopes[i];
    const observedCounts = {
      __proto__: null,
      completed: 0,
      failed: 0,
      skipped: 0,
      total: 0,
    };
    let childSummary;
    let result;
    try {
      result = await runChild(path, options, scope, (record) => {
        if (record.type === 'bench:summary') {
          childSummary = record.data;
          return;
        }
        if (record.type === 'bench:plan') observedCounts.total++;
        if (record.type === 'bench:complete') {
          if (ObjectPrototypeHasOwnProperty(record.data, 'error')) {
            observedCounts.failed++;
          } else if (ObjectPrototypeHasOwnProperty(record.data, 'skip')) {
            observedCounts.skipped++;
          } else {
            observedCounts.completed++;
          }
        }
        return emitRecordAndWait(output, record);
      });
    } catch (error) {
      success = false;
      await emitRecordAndWait(output, {
        __proto__: null,
        type: 'bench:diagnostic',
        data: {
          __proto__: null,
          runId: options.runId,
          ...scope,
          message: error.message,
          error,
          level: 'error',
          file: path,
        },
      });
      counts.completed += observedCounts.completed;
      counts.failed += observedCounts.failed;
      counts.skipped += observedCounts.skipped;
      counts.total += MathMax(
        observedCounts.total,
        observedCounts.completed + observedCounts.failed +
          observedCounts.skipped);
      continue;
    }

    if (result.aborted) {
      success = false;
      await emitRecordAndWait(output, {
        __proto__: null,
        type: 'bench:diagnostic',
        data: {
          __proto__: null,
          runId: options.runId,
          ...scope,
          message: result.error.message,
          error: result.error,
          level: 'error',
          file: path,
        },
      });
    }
    if (childSummary !== undefined) {
      success &&= childSummary.success;
      counts.completed += childSummary.counts.completed;
      counts.failed += childSummary.counts.failed;
      counts.skipped += childSummary.counts.skipped;
      counts.total += childSummary.counts.total;
    } else {
      counts.completed += observedCounts.completed;
      counts.failed += observedCounts.failed;
      counts.skipped += observedCounts.skipped;
      counts.total += MathMax(
        observedCounts.total,
        observedCounts.completed + observedCounts.failed +
          observedCounts.skipped);
    }
    if (!result.aborted && (childSummary === undefined || result.code !== 0 ||
        result.signal !== null)) {
      success = false;
      if (childSummary === undefined || childSummary.success) {
        const status = result.signal === null ?
          `exit code ${result.code}` : `signal ${result.signal}`;
        await emitRecordAndWait(output, {
          __proto__: null,
          type: 'bench:diagnostic',
          data: {
            __proto__: null,
            runId: options.runId,
            ...scope,
            message: `Benchmark file '${path}' failed with ${status}`,
            level: 'error',
            file: path,
          },
        });
      }
    }
  }

  const scope = files.length === 1 ? options.fileScopes[0] : null;
  const summary = {
    __proto__: null,
    runId: options.runId,
    fileRunId: scope?.fileRunId ?? null,
    entryFile: scope?.entryFile ?? null,
    success: success && (options.useProcessExitCode === false ||
      (process.exitCode ?? 0) === 0),
    counts,
    duration_ns: hrtime() - start,
    file: files.length === 1 ? resolve(options.cwd, files[0]) : null,
  };
  await emitRecordAndWait(output, {
    __proto__: null,
    type: 'bench:summary',
    data: summary,
  });
  return summary;
}

function runFile(path, options = kEmptyObject) {
  path = getValidatedPath(path);
  if (typeof path !== 'string') path = BufferToString(path);
  const file = resolve(path);
  validateObject(options, 'options');
  const {
    env = process.env,
    execArgv,
    signal,
  } = options;
  let childExecArgv;
  if (execArgv !== undefined) {
    validateArray(execArgv, 'options.execArgv');
    childExecArgv = [];
    const length = execArgv.length;
    for (let i = 0; i < length; i++) {
      const arg = execArgv[i];
      validateStringWithoutNullBytes(arg, `options.execArgv[${i}]`);
      if (!StringPrototypeStartsWith(arg, '-') || arg === '-' || arg === '--') {
        throw new ERR_INVALID_ARG_VALUE(
          `options.execArgv[${i}]`, arg,
          'must be a Node.js command-line option');
      }
      if (kIncompatibleExecArgv.has(getRunFileOptionName(arg))) {
        throw new ERR_INVALID_ARG_VALUE(
          `options.execArgv[${i}]`, arg,
          'is not compatible with benchmark execution');
      }
      if (runFileOptionRequiresValue(arg)) {
        const equals = StringPrototypeIndexOf(arg, '=');
        if (equals !== -1) {
          throw new ERR_INVALID_ARG_VALUE(
            `options.execArgv[${i}]`, arg,
            'must include a non-empty value');
        }
        if (i + 1 >= length) {
          throw new ERR_INVALID_ARG_VALUE(
            `options.execArgv[${i}]`, arg,
            'must be followed by a value');
        }
        ArrayPrototypePush(childExecArgv, arg);
        i++;
        const value = execArgv[i];
        validateStringWithoutNullBytes(value, `options.execArgv[${i}]`);
        if (value.length === 0) {
          throw new ERR_INVALID_ARG_VALUE(
            `options.execArgv[${i}]`, value,
            'must not be empty');
        }
        ArrayPrototypePush(childExecArgv, value);
        continue;
      }
      if (!StringPrototypeStartsWith(arg, '--') &&
          StringPrototypeIndexOf(arg, '=') !== -1) {
        throw new ERR_INVALID_ARG_VALUE(
          `options.execArgv[${i}]`, arg,
          'must not use = with a short option');
      }
      ArrayPrototypePush(childExecArgv, arg);
    }
    if (ArrayPrototypeFilter(childExecArgv, filterExecArgv).length !==
        childExecArgv.length) {
      throw new ERR_INVALID_ARG_VALUE(
        'options.execArgv', childExecArgv,
        'must not contain benchmark runner options');
    }
  } else {
    childExecArgv = ArrayPrototypeFilter(
      getInheritedChildArgs(), filterRunFileExecArgv);
  }
  validateObject(env, 'options.env');
  const childEnv = { __proto__: null };
  const envKeys = ObjectKeys(env);
  for (let i = 0; i < envKeys.length; i++) {
    const key = envKeys[i];
    validateStringWithoutNullBytes(key, 'options.env key');
    const value = env[key];
    if (value === undefined) continue;
    validateStringWithoutNullBytes(value, `options.env.${key}`);
    if (kIPCEnvironmentVariables.has(StringPrototypeToUpperCase(key))) continue;
    childEnv[key] = value;
  }
  validateAbortSignal(signal, 'options.signal');
  if (signal !== undefined &&
      (typeof signal.addEventListener !== 'function' ||
       typeof signal.removeEventListener !== 'function')) {
    throw new ERR_INVALID_ARG_TYPE('options.signal', 'AbortSignal', signal);
  }

  const runId = createRunId();
  const scope = {
    __proto__: null,
    entryFile: file,
    fileRunId: createRunId(),
  };
  const output = new BenchmarksStream();
  const runOptions = {
    __proto__: null,
    cwd: process.cwd(),
    env: childEnv,
    execPath: process.execPath,
    execArgv: childExecArgv,
    fileScopes: [scope],
    namePatternSource: '',
    output,
    runId,
    signal,
    useProcessExitCode: false,
  };
  const execution = PromisePrototypeThen(PromiseResolve(), () =>
    (output.destroyed ? undefined : runIsolated([file], runOptions, output)));
  PromisePrototypeThen(execution, () => output.end(),
                       (error) => output.destroy(error));
  return output;
}

async function run(patterns) {
  const options = parseCommandLine();
  const files = options.isChild ?
    createChildFileList(patterns, options.cwd) :
    createBenchmarkFileList(patterns, options.cwd);
  if (files === null) return { __proto__: null, success: false };

  options.runId ??= createRunId();
  options.fileScopes = createFileScopes(files, options);
  const scope = files.length === 1 ? options.fileScopes[0] : {
    __proto__: null,
    entryFile: null,
    fileRunId: options.runId,
  };
  configureRunScope({
    __proto__: null,
    runId: options.runId,
    ...scope,
  });

  if (options.isChild) {
    try {
      const modules = await loadUserImports(options);
      return await loadBenchmarkFiles(
        files, options, modules, sendRecord);
    } finally {
      if (process.connected) process.disconnect();
    }
  }

  const output = new BenchmarksStream();
  let executionError;
  let reporterState;
  let summary;
  try {
    options.modules = await loadUserImports(options);
    reporterState = await setupReporters(
      output, options.reporters, options.destinations);
    if (options.isolation === 'process') {
      summary = await runIsolated(files, options, output);
    } else {
      summary = await loadBenchmarkFiles(
        files,
        options,
        options.modules,
        (record) => emitRecordAndWait(output, record),
      );
    }
  } catch (error) {
    executionError = error;
  } finally {
    output.end();
  }
  if (reporterState !== undefined) await finishReporters(reporterState);
  if (executionError !== undefined) throw executionError;
  return summary;
}

module.exports = { run, runFile };

sources.internal/bench_runner/harness:
'use strict';

const {
  ArrayPrototypePush,
  ArrayPrototypeReverse,
  ArrayPrototypeSlice,
  BigInt,
  FunctionPrototypeCall,
  JSONStringify,
  MathCeil,
  Number,
  Promise,
  PromisePrototypeThen,
  PromiseResolve,
  PromiseWithResolvers,
  ReflectApply,
  RegExp,
  RegExpPrototypeExec,
  SafeMap,
  SafePromiseRace,
  String,
  SymbolDispose,
} = primordials;
const { getCallerLocation } = internalBinding('util');
const { exitCodes: { kGenericUserError } } = internalBinding('errors');
const { AsyncLocalStorage } = require('async_hooks');
const {
  subscribe: subscribeToChannel,
  unsubscribe: unsubscribeFromChannel,
} = require('diagnostics_channel');
const { AbortController } = require('internal/abort_controller');
const {
  AbortError,
  codes: {
    ERR_INVALID_ARG_TYPE,
    ERR_INVALID_STATE,
    ERR_OPERATION_FAILED,
  },
} = require('internal/errors');
const { addAbortListener } = require('internal/events/abort_listener');
const {
  kEmptyObject,
} = require('internal/util');
const { isRegExp } = require('internal/util/types');
const {
  validateAbortSignal,
  validateBoolean,
  validateFunction,
  validateObject,
  validateUint32,
} = require('internal/validators');
const { queueMicrotask } = require('internal/process/task_queues');
const { getOptionValue } = require('internal/options');
const { clearTimeout, setImmediate, setTimeout } = require('timers');
const {
  Bench,
  BenchContext,
  Suite,
  normalizeArgs,
  summarizeSamples,
} = require('internal/bench_runner/benchmark');
const {
  BenchmarksStream,
} = require('internal/bench_runner/benchmarks_stream');

const { bigint: hrtime } = process.hrtime;
const kCancellationGracePeriod = 100;
const kHookNames = ['after', 'afterEach', 'before', 'beforeEach'];
const kIsCliRunner = getOptionValue('--bench');
let nextRunId = 0;

function createRunId() {
  return `${process.pid}:${String(hrtime())}:${nextRunId++}`;
}

function eventLoopTurn() {
  return new Promise((resolve) => setImmediate(resolve));
}

async function settlesPromptly(work) {
  const timeout = PromiseWithResolvers();
  const timer = setTimeout(
    () => timeout.resolve(false), kCancellationGracePeriod);
  try {
    return await SafePromiseRace([
      PromisePrototypeThen(work, () => true, () => true),
      timeout.promise,
    ]);
  } finally {
    clearTimeout(timer);
  }
}

function createAbortError(signal) {
  return new AbortError(undefined, { __proto__: null, cause: signal.reason });
}

function createTimeoutError(benchmark) {
  return new ERR_OPERATION_FAILED(
    `Benchmark timed out after ${benchmark.timeout}ms`);
}

class Harness {
  #abortReason = null;
  #autoRun;
  #buildPromises = [];
  #cliRun = false;
  #duplicateErrors = new SafeMap();
  #explicitRun = false;
  #fileScopeStorage = new AsyncLocalStorage();
  #hasOnly = false;
  #runPromise = null;
  #scheduled = false;
  #starting = false;
  #storage = new AsyncLocalStorage();
  #yieldBetweenSamples;

  constructor(options = kEmptyObject) {
    validateObject(options, 'options');
    const {
      autoRun = true,
      yieldBetweenSamples = true,
    } = options;
    validateBoolean(autoRun, 'options.autoRun');
    validateBoolean(
      yieldBetweenSamples, 'options.yieldBetweenSamples');
    this.#autoRun = autoRun;
    this.#yieldBetweenSamples = yieldBetweenSamples;
    this.runId = createRunId();
    this.fileRunId = this.runId;
    this.entryFile = process.argv?.[1] ?? null;
    this.stream = new BenchmarksStream();
    this.state = 'collecting';
    this.namePattern = null;
    this.outerSignal = undefined;
    this.samples = undefined;
    this.success = true;
    this.warmup = undefined;
    this.counts = {
      __proto__: null,
      completed: 0,
      failed: 0,
      skipped: 0,
      total: 0,
    };
    this.root = new Suite(
      this,
      null,
      '<root>',
      kEmptyObject,
      undefined,
      undefined,
      true,
    );
  }

  getFileScope() {
    return this.#fileScopeStorage.getStore() ?? null;
  }

  runInFileScope(scope, fn) {
    return this.#fileScopeStorage.run(scope, fn);
  }

  setRunScope({ entryFile, fileRunId, runId }) {
    if (this.state !== 'collecting') {
      throw new ERR_INVALID_STATE(
        'benchmark execution scope cannot change after execution has started');
    }
    this.entryFile = entryFile;
    this.fileRunId = fileRunId;
    this.runId = runId;
  }

  #ensureCollecting() {
    if (this.state === 'building' &&
        this.#storage.getStore() instanceof Suite) return;
    if (!this.#explicitRun && !this.#starting &&
        this.state === 'collecting') return;
    throw new ERR_INVALID_STATE(
      'benchmarks cannot be declared after execution has started');
  }

  #getParent() {
    const current = this.#storage.getStore();
    return current instanceof Suite ? current : this.root;
  }

  createBench(name, options, fn, overrides = kEmptyObject) {
    this.#ensureCollecting();
    const normalized = normalizeArgs('benchmark', name, options, fn);
    const parent = this.#getParent();
    const benchmark = new Bench(
      this,
      parent,
      normalized.name,
      { __proto__: null, ...normalized.options, ...overrides },
      normalized.fn,
      overrides.loc,
    );
    ArrayPrototypePush(parent.children, benchmark);
    this.#schedule();
    return parent.isRoot ? benchmark.completion.promise : PromiseResolve();
  }

  createSuite(name, options, fn, overrides = kEmptyObject) {
    this.#ensureCollecting();
    const normalized = normalizeArgs('suite', name, options, fn);
    const parent = this.#getParent();
    const suite = new Suite(
      this,
      parent,
      normalized.name,
      { __proto__: null, ...normalized.options, ...overrides },
      normalized.fn,
      overrides.loc,
    );
    ArrayPrototypePush(parent.children, suite);
    this.#buildSuite(suite);
    this.#schedule();
    return parent.isRoot ? suite.completion.promise : PromiseResolve();
  }

  createHook(name, fn, options = kEmptyObject) {
    this.#ensureCollecting();
    validateFunction(fn, 'hook function');
    validateObject(options, 'options');
    const parent = this.#getParent();
    ArrayPrototypePush(parent.hooks[name], {
      __proto__: null,
      fileScope: parent.isRoot ? this.getFileScope() : parent.fileScope,
      fn,
      loc: getCallerLocation(),
    });
    this.#schedule();
  }

  #buildSuite(suite) {
    let result;
    try {
      result = suite.runInAsyncScope(() => this.#storage.run(
        suite,
        () => FunctionPrototypeCall(suite.fn),
      ));
    } catch (error) {
      suite.buildError = error;
      result = undefined;
    }

    suite.buildPromise = PromisePrototypeThen(
      PromiseResolve(result),
      undefined,
      (error) => {
        suite.buildError = error;
      },
    );
    ArrayPrototypePush(this.#buildPromises, suite.buildPromise);
  }

  configure(options = kEmptyObject) {
    validateObject(options, 'options');

    const {
      namePattern,
      samples,
      signal,
      warmup,
      yieldBetweenSamples,
    } = options;
    let nextNamePattern = this.namePattern;
    let nextSamples = this.samples;
    let nextWarmup = this.warmup;
    let nextYieldBetweenSamples = this.#yieldBetweenSamples;
    if (namePattern !== undefined) {
      if (typeof namePattern === 'string') {
        nextNamePattern = new RegExp(namePattern);
      } else if (isRegExp(namePattern)) {
        nextNamePattern = new RegExp(namePattern);
      } else {
        throw new ERR_INVALID_ARG_TYPE(
          'options.namePattern', ['string', 'RegExp'], namePattern);
      }
    }
    if (samples !== undefined) {
      validateUint32(samples, 'options.samples', true);
      nextSamples = samples;
    }
    validateAbortSignal(signal, 'options.signal');
    if (warmup !== undefined) {
      validateUint32(warmup, 'options.warmup');
      nextWarmup = warmup;
    }
    if (yieldBetweenSamples !== undefined) {
      validateBoolean(
        yieldBetweenSamples, 'options.yieldBetweenSamples');
      nextYieldBetweenSamples = yieldBetweenSamples;
    }

    this.namePattern = nextNamePattern;
    this.samples = nextSamples;
    this.outerSignal = signal;
    this.warmup = nextWarmup;
    this.#yieldBetweenSamples = nextYieldBetweenSamples;
  }

  #ensureCanRun() {
    if (this.#explicitRun || this.#starting || this.state !== 'collecting') {
      throw new ERR_INVALID_STATE('benchmark execution has already started');
    }
  }

  run(options = kEmptyObject, force = false) {
    if (kIsCliRunner && !force) {
      throw new ERR_INVALID_STATE(
        'run() cannot be called from a file run with --bench');
    }
    this.#ensureCanRun();
    this.#starting = true;
    try {
      this.configure(options);
      this.#explicitRun = true;
      this.#cliRun = force;
    } finally {
      this.#starting = false;
    }
    this.#schedule(force, true);
    return this.stream;
  }

  #schedule(force = false, explicit = false) {
    if (!force && kIsCliRunner) return;
    if (!explicit && !this.#autoRun) return;
    if (this.#scheduled) return;
    this.#scheduled = true;
    queueMicrotask(() => {
      if (this.#runPromise === null) {
        if (!this.#explicitRun) this.stream.resume();
        this.#runPromise = PromisePrototypeThen(
          this.#execute(), undefined, (error) => this.#recover(error));
      }
    });
  }

  async #recover(error) {
    this.#settleSubtree(this.root, error);
    if (this.state !== 'finished') {
      try {
        await this.#diagnostic(error, undefined, 'error');
      } catch {
        // The stream can fail while reporting the original error.
      }
    }
    try {
      await this.#finish();
    } catch {
      // Stream failure has already been reported to its consumer.
    }
  }

  #settleSubtree(node, error) {
    for (let i = 0; i < node.children.length; i++) {
      const child = node.children[i];
      if (child.finished) continue;
      if (child instanceof Suite) {
        this.#settleSubtree(child, error);
        child.finished = true;
        child.completion.resolve();
      } else {
        this.success = false;
        this.counts.failed++;
        const result = this.#createResult(
          child, [], { __proto__: null, error });
        child.finished = true;
        child.result = result;
        child.completion.resolve(result);
      }
      child.emitDestroy();
    }
  }

  async #waitForBuild() {
    for (let i = 0; i < this.#buildPromises.length; i++) {
      await this.#buildPromises[i];
    }
  }

  #walk(node, callback) {
    for (let i = 0; i < node.children.length; i++) {
      const child = node.children[i];
      callback(child);
      if (child instanceof Suite) this.#walk(child, callback);
    }
  }

  #prepare() {
    const identities = new SafeMap();
    this.#walk(this.root, (node) => {
      if (node.only) this.#hasOnly = true;
      if (!(node instanceof Bench)) return;

      this.counts.total++;
      const identity = JSONStringify([
        this.#getRecordScope(node).fileRunId,
        node.benchId,
      ]);
      const existing = identities.get(identity);
      if (existing === undefined) {
        identities.set(identity, node);
      } else {
        this.#duplicateErrors.set(node, new ERR_INVALID_STATE(
          `duplicate benchmark identity for "${node.fullName}"`));
      }
    });
  }

  async #emitPlans() {
    const benchmarks = [];
    this.#walk(this.root, (node) => {
      if (node instanceof Bench) ArrayPrototypePush(benchmarks, node);
    });
    for (let i = 0; i < benchmarks.length; i++) {
      const benchmark = benchmarks[i];
      const skip = this.#getSkip(benchmark);
      const data = {
        __proto__: null,
        ...this.#getRecordScope(benchmark),
        benchId: benchmark.benchId,
        parentId: benchmark.parentId,
        name: benchmark.name,
        namePath: ArrayPrototypeSlice(benchmark.namePath),
        diagnosticChannels: ArrayPrototypeSlice(benchmark.diagnosticChannels),
        file: benchmark.loc.file,
        line: benchmark.loc.line,
        column: benchmark.loc.column,
        tags: ArrayPrototypeSlice(benchmark.tags),
        params: benchmark.params,
        samples: this.samples ?? benchmark.samples,
        warmup: this.warmup ?? benchmark.warmup,
        timeout: benchmark.timeout === Infinity ? null : benchmark.timeout,
        yieldBetweenSamples: this.#yieldBetweenSamples,
        selected: skip === null,
      };
      if (skip !== null) data.skip = skip;
      await this.#waitForStream(this.stream.plan(data));
    }
  }

  #hasSelectedAncestor(benchmark) {
    for (let current = benchmark; current !== null; current = current.parent) {
      if (current.only) return true;
    }
    return false;
  }

  #getSkip(benchmark) {
    for (let current = benchmark; current !== null; current = current.parent) {
      if (current.skip !== undefined && current.skip !== false) {
        return current.skip;
      }
    }
    if (this.#hasOnly && !this.#hasSelectedAncestor(benchmark)) return 'only';
    if (this.namePattern !== null) {
      this.namePattern.lastIndex = 0;
      if (RegExpPrototypeExec(this.namePattern, benchmark.fullName) === null) {
        return 'name pattern';
      }
    }
    return null;
  }

  #suiteHasActiveBench(suite) {
    for (let i = 0; i < suite.children.length; i++) {
      const child = suite.children[i];
      if (child instanceof Suite) {
        if (this.#suiteHasActiveBench(child)) return true;
      } else if (this.#getSkip(child) === null) {
        return true;
      }
    }
    return false;
  }

  async #invoke(resource, store, fn, args) {
    const result = resource.runInAsyncScope(() => this.#storage.run(
      store,
      () => ReflectApply(fn, undefined, args),
    ));
    return PromiseResolve(result);
  }

  async #runHooks(suite, name, resource, store, context) {
    const hooks = suite.hooks[name];
    for (let i = 0; i < hooks.length; i++) {
      await this.#invoke(resource, store, hooks[i].fn, [context]);
    }
  }

  async #runSuiteHooks(suite, name) {
    const context = {
      __proto__: null,
      name: suite.name,
      signal: this.outerSignal,
    };
    const hooks = suite.hooks[name];
    for (let i = 0; i < hooks.length; i++) {
      try {
        await this.#invoke(suite, suite, hooks[i].fn, [context]);
      } catch (error) {
        return { __proto__: null, error, hook: hooks[i] };
      }
    }
    return null;
  }

  #getRecordScope(node = undefined) {
    const scope = node?.fileScope;
    if (scope !== null && scope !== undefined) {
      return {
        __proto__: null,
        runId: this.runId,
        fileRunId: scope.fileRunId,
        entryFile: scope.entryFile,
      };
    }
    if (node !== undefined && kIsCliRunner) {
      return {
        __proto__: null,
        runId: this.runId,
        fileRunId: this.fileRunId,
        entryFile: null,
      };
    }
    return {
      __proto__: null,
      runId: this.runId,
      fileRunId: this.fileRunId,
      entryFile: this.entryFile,
    };
  }

  async #waitForStream(canContinue) {
    if (canContinue) return;
    try {
      await this.stream.waitForDrain();
    } catch (error) {
      if (!this.stream.destroyed) throw error;
    }
  }

  async #diagnostic(error, loc, level = 'info', node = undefined) {
    this.success = false;
    await this.#waitForStream(this.stream.diagnostic({
      __proto__: null,
      ...this.#getRecordScope(node),
      message: error?.message ?? `${error}`,
      error,
      level,
      file: loc?.file ?? loc?.[2],
      line: loc?.line ?? loc?.[0],
      column: loc?.column ?? loc?.[1],
    }));
  }

  async #emitSampleDiagnostics(benchmark, phase, index, diagnostics) {
    for (let i = 0; i < diagnostics.length; i++) {
      const diagnostic = diagnostics[i];
      const data = {
        __proto__: null,
        ...this.#getRecordScope(benchmark),
        benchId: benchmark.benchId,
        parentId: benchmark.parentId,
        name: benchmark.name,
        namePath: ArrayPrototypeSlice(benchmark.namePath),
        phase,
        index,
        message: diagnostic.message,
        level: diagnostic.level,
        file: benchmark.loc.file,
        line: benchmark.loc.line,
        column: benchmark.loc.column,
      };
      if (diagnostic.detail !== undefined) data.detail = diagnostic.detail;
      await this.#waitForStream(this.stream.diagnostic(data));
    }
  }

  async #completeSubtree(node, error) {
    for (let i = 0; i < node.children.length; i++) {
      const child = node.children[i];
      if (child instanceof Suite) {
        await this.#completeSubtree(child, error);
        child.finished = true;
        child.completion.resolve();
        child.emitDestroy();
      } else {
        await this.#executeBench(child, error);
      }
    }
  }

  async #executeSuite(suite) {
    if (this.#abortReason !== null) {
      await this.#completeSubtree(suite, this.#abortReason);
      suite.finished = true;
      suite.completion.resolve();
      if (!suite.isRoot) suite.emitDestroy();
      return;
    }

    if (suite.buildError !== null) {
      await this.#diagnostic(suite.buildError, suite.loc, 'error', suite);
      await this.#completeSubtree(suite, suite.buildError);
      suite.finished = true;
      suite.completion.resolve();
      suite.emitDestroy();
      return;
    }

    const active = this.#suiteHasActiveBench(suite);
    let beforeError;
    if (active) {
      const failure = await this.#runSuiteHooks(suite, 'before');
      if (failure !== null) {
        beforeError = failure.error;
        await this.#diagnostic(
          failure.error, failure.hook.loc, 'error', failure.hook);
      }
    }

    if (beforeError !== undefined) {
      await this.#completeSubtree(suite, beforeError);
    } else {
      for (let i = 0; i < suite.children.length; i++) {
        const child = suite.children[i];
        if (child instanceof Suite) {
          await this.#executeSuite(child);
        } else {
          await this.#executeBench(child);
        }
      }
    }

    if (active && this.#abortReason === null) {
      const failure = await this.#runSuiteHooks(suite, 'after');
      if (failure !== null) {
        await this.#diagnostic(
          failure.error, failure.hook.loc, 'error', failure.hook);
      }
    }
    suite.finished = true;
    suite.completion.resolve();
    if (!suite.isRoot) suite.emitDestroy();
  }

  #getHookSuites(benchmark) {
    const suites = [];
    for (let current = benchmark.parent; current !== null; current = current.parent) {
      ArrayPrototypePush(suites, current);
    }
    ArrayPrototypeReverse(suites);
    return suites;
  }

  async #runBenchHooks(benchmark, name, context) {
    const suites = this.#getHookSuites(benchmark);
    if (name === 'afterEach') ArrayPrototypeReverse(suites);
    for (let i = 0; i < suites.length; i++) {
      await this.#runHooks(
        suites[i], name, benchmark, benchmark, context);
    }
  }

  async #runWithStop(benchmark, controller, callback, deadline) {
    const signals = [];
    if (this.outerSignal !== undefined) {
      ArrayPrototypePush(signals, this.outerSignal);
    }
    if (benchmark.outerSignal !== undefined &&
        benchmark.outerSignal !== this.outerSignal) {
      ArrayPrototypePush(signals, benchmark.outerSignal);
    }

    for (let i = 0; i < signals.length; i++) {
      if (signals[i].aborted) {
        const error = createAbortError(signals[i]);
        controller.abort(error);
        throw error;
      }
    }

    const stop = PromiseWithResolvers();
    const listeners = [];
    let pausedWork;
    let timer;
    for (let i = 0; i < signals.length; i++) {
      const signal = signals[i];
      ArrayPrototypePush(listeners, addAbortListener(signal, () => {
        const error = createAbortError(signal);
        controller.abort(error);
        stop.reject(error);
      }));
    }
    const armTimer = () => {
      let remaining = deadline.value - hrtime();
      if (remaining < 0n) remaining = 0n;
      timer = setTimeout(() => {
        const error = createTimeoutError(benchmark);
        controller.abort(error);
        stop.reject(error);
      }, Number(remaining) / 1e6);
    };
    if (deadline !== null) armTimer();

    const pause = (work) => {
      pausedWork = (async () => {
        if (deadline === null) return work();
        clearTimeout(timer);
        timer = undefined;
        const start = hrtime();
        try {
          return await work();
        } finally {
          deadline.value += hrtime() - start;
          if (!controller.signal.aborted) armTimer();
        }
      })();
      return pausedWork;
    };

    const work = callback(pause);
    try {
      if (signals.length === 0 && timer === undefined) return await work;
      return await SafePromiseRace([work, stop.promise]);
    } catch (error) {
      try {
        await pausedWork;
      } catch {
        // Preserve the error that stopped benchmark execution.
      }
      if (!await settlesPromptly(work) && this.#abortReason === null) {
        this.#abortReason = new AbortError(
          'The benchmark run was aborted because asynchronous work did not ' +
          'settle after cancellation',
          { __proto__: null, cause: error },
        );
      }
      throw error;
    } finally {
      if (timer !== undefined) clearTimeout(timer);
      for (let i = 0; i < listeners.length; i++) {
        listeners[i][SymbolDispose]();
      }
    }
  }

  async #runSample(benchmark, signal, phase, index) {
    const diagnostics = [];
    const context = new BenchContext(
      benchmark, signal, phase, index,
      (diagnostic) => ArrayPrototypePush(diagnostics, diagnostic));
    const channels = benchmark.diagnosticChannels;
    let abortSubscription;
    let diagnosticError;
    let diagnosticFailed = false;
    let subscribed = 0;
    const onMessage = (message, name) => {
      if (signal.aborted || diagnosticFailed) return;
      try {
        context.diagnostic({ __proto__: null, name, message });
      } catch (error) {
        diagnosticError = error;
        diagnosticFailed = true;
      }
    };
    const unsubscribe = () => {
      while (subscribed > 0) {
        subscribed--;
        unsubscribeFromChannel(channels[subscribed], onMessage);
      }
    };
    try {
      for (let i = 0; i < channels.length; i++) {
        subscribeToChannel(channels[i], onMessage);
        subscribed++;
      }
      if (subscribed > 0) {
        abortSubscription = addAbortListener(signal, unsubscribe);
      }
      await this.#invoke(
        benchmark, benchmark, benchmark.fn, [context]);
      if (diagnosticFailed) throw diagnosticError;
      const { done, sample } = context.finish();
      return {
        __proto__: null,
        diagnostics,
        done,
        failed: false,
        sample,
      };
    } catch (error) {
      context.close();
      return {
        __proto__: null,
        diagnostics,
        error,
        failed: true,
      };
    } finally {
      abortSubscription?.[SymbolDispose]();
      unsubscribe();
    }
  }

  #createResult(benchmark, samples, extra = kEmptyObject) {
    return {
      __proto__: null,
      ...this.#getRecordScope(benchmark),
      benchId: benchmark.benchId,
      parentId: benchmark.parentId,
      name: benchmark.name,
      namePath: ArrayPrototypeSlice(benchmark.namePath),
      file: benchmark.loc.file,
      line: benchmark.loc.line,
      column: benchmark.loc.column,
      tags: ArrayPrototypeSlice(benchmark.tags),
      params: benchmark.params,
      samples,
      ...extra,
    };
  }

  async #recordResult(benchmark, result) {
    benchmark.finished = true;
    benchmark.result = result;
    let canContinue;
    try {
      canContinue = this.stream.complete(result);
    } finally {
      benchmark.completion.resolve(result);
      benchmark.emitDestroy();
    }
    await this.#waitForStream(canContinue);
  }

  async #executeBench(benchmark, forcedError = undefined) {
    const duplicateError = this.#duplicateErrors.get(benchmark);
    if (duplicateError !== undefined) {
      this.success = false;
      this.counts.failed++;
      await this.#recordResult(benchmark, this.#createResult(
        benchmark,
        [],
        { __proto__: null, error: duplicateError },
      ));
      return;
    }

    const skip = this.#getSkip(benchmark);
    if (skip !== null) {
      this.counts.skipped++;
      await this.#recordResult(benchmark, this.#createResult(
        benchmark,
        [],
        { __proto__: null, skip },
      ));
      return;
    }

    if (this.#abortReason !== null) forcedError = this.#abortReason;
    if (forcedError !== undefined) {
      this.success = false;
      this.counts.failed++;
      await this.#recordResult(benchmark, this.#createResult(
        benchmark,
        [],
        { __proto__: null, error: forcedError },
      ));
      return;
    }

    await this.#waitForStream(this.stream.start({
      __proto__: null,
      ...this.#getRecordScope(benchmark),
      benchId: benchmark.benchId,
      parentId: benchmark.parentId,
      name: benchmark.name,
      namePath: ArrayPrototypeSlice(benchmark.namePath),
      file: benchmark.loc.file,
      line: benchmark.loc.line,
      column: benchmark.loc.column,
      tags: ArrayPrototypeSlice(benchmark.tags),
      params: benchmark.params,
    }));

    const controller = new AbortController();
    const deadline = benchmark.timeout === Infinity ? null : {
      __proto__: null,
      value: hrtime() + BigInt(MathCeil(benchmark.timeout * 1e6)),
    };
    const checkDeadline = () => {
      if (deadline !== null && hrtime() >= deadline.value) {
        const timeoutError = createTimeoutError(benchmark);
        controller.abort(timeoutError);
        throw timeoutError;
      }
    };
    const samples = [];
    const hookContext = {
      __proto__: null,
      name: benchmark.name,
      params: benchmark.params,
      signal: controller.signal,
    };
    let error;
    let failed = false;
    const runAfterEach = async () => {
      await this.#runBenchHooks(
        benchmark, 'afterEach', hookContext);
      checkDeadline();
    };

    try {
      await this.#runWithStop(benchmark, controller, async (pause) => {
        try {
          await this.#runBenchHooks(
            benchmark, 'beforeEach', hookContext);
          checkDeadline();
          const warmup = this.warmup ?? benchmark.warmup;
          const total = warmup + (this.samples ?? benchmark.samples);
          for (let i = 0; i < total; i++) {
            if (controller.signal.aborted) {
              throw controller.signal.reason;
            }
            const phase = i < warmup ? 'warmup' : 'measurement';
            const index = phase === 'warmup' ? i : i - warmup;
            const outcome = await this.#runSample(
              benchmark, controller.signal, phase, index);
            if (!outcome.failed) {
              checkDeadline();
              if (controller.signal.aborted) {
                throw controller.signal.reason;
              }
              if (i >= warmup) {
                ArrayPrototypePush(samples, outcome.sample);
              }
            }

            let diagnosticError;
            let diagnosticFailed = false;
            if (outcome.diagnostics.length > 0 &&
                !controller.signal.aborted) {
              try {
                await pause(() => this.#emitSampleDiagnostics(
                  benchmark, phase, index, outcome.diagnostics));
              } catch (cause) {
                diagnosticFailed = true;
                diagnosticError = cause;
              }
            }
            if (outcome.failed) throw outcome.error;
            if (diagnosticFailed) throw diagnosticError;
            if (controller.signal.aborted) {
              throw controller.signal.reason;
            }
            if (i >= warmup) {
              await pause(() => this.#waitForStream(this.stream.sample({
                __proto__: null,
                ...this.#getRecordScope(benchmark),
                benchId: benchmark.benchId,
                parentId: benchmark.parentId,
                name: benchmark.name,
                namePath: ArrayPrototypeSlice(benchmark.namePath),
                index: i - warmup,
                ...outcome.sample,
              })));
              if (controller.signal.aborted) {
                throw controller.signal.reason;
              }
            }
            if (outcome.done) break;
            if (i + 1 < total && this.#yieldBetweenSamples) {
              await eventLoopTurn();
            }
          }
        } finally {
          await runAfterEach();
        }
      }, deadline);
    } catch (cause) {
      failed = true;
      error = cause;
    } finally {
      controller.abort();
    }

    if (failed) {
      this.success = false;
      this.counts.failed++;
      await this.#recordResult(benchmark, this.#createResult(
        benchmark,
        samples,
        { __proto__: null, error },
      ));
      return;
    }

    this.counts.completed++;
    await this.#recordResult(benchmark, this.#createResult(
      benchmark,
      samples,
      { __proto__: null, summary: summarizeSamples(samples) },
    ));
  }

  async #finish(startTime) {
    if (this.state === 'finished') return;
    this.state = 'finished';
    const duration = startTime === undefined ? 0n : hrtime() - startTime;
    try {
      await this.#waitForStream(this.stream.summary({
        __proto__: null,
        ...this.#getRecordScope(),
        success: this.success,
        counts: this.counts,
        duration_ns: duration,
        file: this.entryFile,
      }));
    } catch (error) {
      try {
        await this.#diagnostic(error, undefined, 'error');
      } catch {
        // The stream can fail while reporting the summary listener error.
      }
    } finally {
      this.stream.end();
      this.root.finished = true;
      this.root.completion.resolve();
      this.root.emitDestroy();
      this.#storage.disable();
      // Runners created with createRunner() leave the exit code to their
      // caller, and the CLI runner derives it from the aggregated summary.
      if (this.#autoRun && !this.#cliRun && !this.success) {
        process.exitCode ??= kGenericUserError;
      }
    }
  }

  async #execute() {
    this.state = 'building';
    const startTime = hrtime();
    await this.#waitForBuild();
    this.#fileScopeStorage.disable();
    this.#prepare();
    this.state = 'running';
    await this.#emitPlans();
    await this.#executeSuite(this.root);
    await this.#finish(startTime);
  }
}

let globalHarness;

function lazyHarness() {
  globalHarness ??= new Harness();
  return globalHarness;
}

function createDeclaration(type, getHarness) {
  const declare = (name, options, fn, overrides = kEmptyObject) => {
    const harness = getHarness();
    const loc = getCallerLocation();
    const declarationOptions = { __proto__: null, ...overrides, loc };
    return type === 'benchmark' ?
      harness.createBench(name, options, fn, declarationOptions) :
      harness.createSuite(name, options, fn, declarationOptions);
  };

  if (type === 'benchmark') {
    declare.skip = (name, options, fn) => declare(
      name, options, fn, { __proto__: null, skip: true });
    declare.only = (name, options, fn) => declare(
      name, options, fn, { __proto__: null, only: true });
  }
  return declare;
}

function createHook(name, getHarness) {
  return (fn, options) => getHarness().createHook(name, fn, options);
}

const bench = createDeclaration('benchmark', lazyHarness);
const suite = createDeclaration('suite', lazyHarness);

function createRunner(options = kEmptyObject) {
  validateObject(options, 'options');
  const harness = new Harness({
    __proto__: null,
    autoRun: false,
    yieldBetweenSamples: options.yieldBetweenSamples === undefined ?
      true : options.yieldBetweenSamples,
  });
  const getHarness = () => harness;
  const runnerBench = createDeclaration('benchmark', getHarness);
  const runnerSuite = createDeclaration('suite', getHarness);
  return {
    __proto__: null,
    after: createHook(kHookNames[0], getHarness),
    afterEach: createHook(kHookNames[1], getHarness),
    before: createHook(kHookNames[2], getHarness),
    beforeEach: createHook(kHookNames[3], getHarness),
    bench: runnerBench,
    describe: runnerSuite,
    run: (runOptions = kEmptyObject) => harness.run(runOptions),
    suite: runnerSuite,
  };
}

function configureRunScope(scope) {
  lazyHarness().setRunScope(scope);
}

function runInFileScope(scope, fn) {
  return lazyHarness().runInFileScope(scope, fn);
}

function runBenchmarks(options, force) {
  return lazyHarness().run(options, force);
}

module.exports = {
  Harness,
  after: createHook(kHookNames[0], lazyHarness),
  afterEach: createHook(kHookNames[1], lazyHarness),
  before: createHook(kHookNames[2], lazyHarness),
  beforeEach: createHook(kHookNames[3], lazyHarness),
  bench,
  configureRunScope,
  createRunId,
  createRunner,
  runInFileScope,
  runBenchmarks,
  suite,
};

