}

function createCipherBase(cipher, credential, options, isEncrypt, iv) {
  let authTagLength = -1;
  let ctsMode;
  let xtsStandard;
  if (options != null) {
    authTagLength = getUIntOption(options, 'authTagLength');
    ctsMode = getStringOption(options, 'ctsMode') ?? undefined;
    xtsStandard = getStringOption(options, 'xtsStandard') ?? undefined;
    if (ctsMode !== undefined)
      validateOneOf(ctsMode, 'options.ctsMode', kCtsModes);
    if (xtsStandard !== undefined)
      validateOneOf(xtsStandard, 'options.xtsStandard', kXtsStandards);
  }

  if (ctsMode === undefined && xtsStandard === undefined) {
    this[kHandle] = new CipherBase(
      isEncrypt, cipher, credential, iv, authTagLength);
  } else {
    this[kHandle] = new CipherBase(
      isEncrypt,
      cipher,
      credential,
      iv,
      authTagLength,
      ctsMode,
      xtsStandard);
  }
  this._decoder = null;

  FunctionPrototypeCall(LazyTransform, this, options);
}

function createCipherWithIV(cipher, key, options, isEncrypt, iv) {
  validateString(cipher, 'cipher');
  const encoding = getStringOption(options, 'encoding');
  key = prepareSecretKey(key, encoding);
  iv = iv === null ? null : getArrayBufferOrView(iv, 'iv');
  FunctionPrototypeCall(createCipherBase, this, cipher, key, options, isEncrypt, iv);
}

// The Cipher class is part of the legacy Node.js crypto API. It exposes
// a stream-based encryption/decryption model. For backwards compatibility
// the Cipher class is defined using the legacy function syntax rather than
// ES6 classes.

function _transform(chunk, encoding, callback) {
  this.push(this[kHandle].update(chunk, encoding));
  callback();
};

function _flush(callback) {
  try {
    this.push(this[kHandle].final());
  } catch (e) {
    callback(e);
    return;
  }
  callback();
};

function update(data, inputEncoding, outputEncoding) {
  if (typeof data === 'string') {
    validateEncoding(data, inputEncoding);
  } else if (!isArrayBufferView(data)) {
    throw new ERR_INVALID_ARG_TYPE(
      'data', ['string', 'Buffer', 'TypedArray', 'DataView'], data);
  }

  const ret = this[kHandle].update(data, inputEncoding);

  if (outputEncoding && outputEncoding !== 'buffer') {
    this._decoder = getDecoder(this._decoder, outputEncoding);
    return this._decoder.write(ret);
  }

  return ret;
};

function final(outputEncoding) {
  const ret = this[kHandle].final();

  if (outputEncoding && outputEncoding !== 'buffer') {
    this._decoder = getDecoder(this._decoder, outputEncoding);
    return this._decoder.end(ret);
  }

  return ret;
};

function setAutoPadding(ap) {
  if (!this[kHandle].setAutoPadding(!!ap))
    throw new ERR_CRYPTO_INVALID_STATE('setAutoPadding');
  return this;
};

function getAuthTag() {
  const ret = this[kHandle].getAuthTag();
  if (ret === undefined)
    throw new ERR_CRYPTO_INVALID_STATE('getAuthTag');
  return ret;
};

function setAuthTag(tagbuf, encoding) {
  tagbuf = getArrayBufferOrView(tagbuf, 'buffer', encoding);
  if (!this[kHandle].setAuthTag(tagbuf))
    throw new ERR_CRYPTO_INVALID_STATE('setAuthTag');
  return this;
}

function setAAD(aadbuf, options) {
  const encoding = getStringOption(options, 'encoding');
  const plaintextLength = getUIntOption(options, 'plaintextLength');
  aadbuf = getArrayBufferOrView(aadbuf, 'aadbuf', encoding);
  if (!this[kHandle].setAAD(aadbuf, plaintextLength))
    throw new ERR_CRYPTO_INVALID_STATE('setAAD');
  return this;
};

// The Cipheriv class is part of the legacy Node.js crypto API. It exposes
// a stream-based encryption/decryption model. For backwards compatibility
// the Cipheriv class is defined using the legacy function syntax rather than
// ES6 classes.

function Cipheriv(cipher, key, iv, options) {
  if (!(this instanceof Cipheriv))
    return new Cipheriv(cipher, key, iv, options);

  FunctionPrototypeCall(createCipherWithIV, this, cipher, key, options, true, iv);
}

function addCipherPrototypeFunctions(constructor) {
  constructor.prototype._transform = _transform;
  constructor.prototype._flush = _flush;
  constructor.prototype.update = update;
  constructor.prototype.final = final;
  constructor.prototype.setAutoPadding = setAutoPadding;
  if (constructor === Cipheriv) {
    constructor.prototype.getAuthTag = getAuthTag;
  } else {
    constructor.prototype.setAuthTag = setAuthTag;
  }
  constructor.prototype.setAAD = setAAD;
}

ObjectSetPrototypeOf(Cipheriv.prototype, LazyTransform.prototype);
ObjectSetPrototypeOf(Cipheriv, LazyTransform);
addCipherPrototypeFunctions(Cipheriv);

// The Decipheriv class is part of the legacy Node.js crypto API. It exposes
// a stream-based encryption/decryption model. For backwards compatibility
// the Decipheriv class is defined using the legacy function syntax rather than
// ES6 classes.
function Decipheriv(cipher, key, iv, options) {
  if (!(this instanceof Decipheriv))
    return new Decipheriv(cipher, key, iv, options);

  FunctionPrototypeCall(createCipherWithIV, this, cipher, key, options, false, iv);
}

ObjectSetPrototypeOf(Decipheriv.prototype, LazyTransform.prototype);
ObjectSetPrototypeOf(Decipheriv, LazyTransform);
addCipherPrototypeFunctions(Decipheriv);

const kMinNid = 1;
const kMaxNid = 2_147_483_647;
function getCipherInfo(nameOrNid, options = kEmptyObject) {
  validateObject(options, 'options');
  let { keyLength, ivLength } = options;
  if (keyLength !== undefined) {
    validateUint32(keyLength, 'options.keyLength');
    // Coerce -0 to +0.
    keyLength += 0;
  }
  if (ivLength !== undefined) {
    validateUint32(ivLength, 'options.ivLength');
    // Coerce -0 to +0.
    ivLength += 0;
  }

  const type = typeof nameOrNid;

  if (type === 'string') {
    if (nameOrNid.length === 0) return undefined;
    return _getCipherInfo(nameOrNid, keyLength, ivLength);
  } else if (type === 'number') {
    if (!NumberIsInteger(nameOrNid) || nameOrNid < kMinNid || nameOrNid > kMaxNid) {
      return undefined;
    }
    return _getCipherInfo(nameOrNid, keyLength, ivLength);
  }

  throw new ERR_INVALID_ARG_TYPE(
    'nameOrNid',
    ['string', 'number'],
    nameOrNid);
}

module.exports = {
  Cipheriv,
  Decipheriv,
  privateDecrypt,
  privateEncrypt,
  publicDecrypt,
  publicEncrypt,
  getCipherInfo,
};

sources.internal/crypto/diffiehellman:
'use strict';

const {
  ArrayBufferPrototypeGetByteLength,
  FunctionPrototypeCall,
  ObjectDefineProperty,
  SafeSet,
  TypedArrayPrototypeGetBuffer,
} = primordials;

const { Buffer } = require('buffer');

const {
  DHBitsJob,
  DiffieHellman: _DiffieHellman,
  DiffieHellmanGroup: _DiffieHellmanGroup,
  ECDH: _ECDH,
  ECDHConvertKey: _ECDHConvertKey,
  kCryptoJobAsync,
  kCryptoJobSync,
  kCryptoJobWebCrypto,
} = internalBinding('crypto');

const {
  codes: {
    ERR_CRYPTO_ECDH_INVALID_FORMAT,
    ERR_CRYPTO_ECDH_INVALID_PUBLIC_KEY,
    ERR_CRYPTO_INCOMPATIBLE_KEY,
    ERR_CRYPTO_INVALID_KEY_OBJECT_TYPE,
    ERR_INVALID_ARG_TYPE,
    ERR_INVALID_ARG_VALUE,
  },
} = require('internal/errors');

const {
  validateFunction,
  validateInt32,
  validateObject,
  validateString,
} = require('internal/validators');

const {
  isArrayBufferView,
  isAnyArrayBuffer,
} = require('internal/util/types');

const {
  deprecate,
  lazyDOMException,
} = require('internal/util');

const {
  isKeyObject,
  getCryptoKeyAlgorithm,
  getCryptoKeyHandle,
  getCryptoKeyType,
  getKeyObjectAsymmetricKeyType,
  getKeyObjectType,
  preparePrivateKey,
  preparePublicOrPrivateKey,
} = require('internal/crypto/keys');

const {
  getArrayBufferOrView,
  jobPromise,
  jobPromiseThen,
  numBitsToBytes,
  toBuf,
  truncateToBitLength,
  validateAlgorithm,
  kHandle,
} = require('internal/crypto/util');

const {
  crypto: {
    POINT_CONVERSION_COMPRESSED,
    POINT_CONVERSION_HYBRID,
    POINT_CONVERSION_UNCOMPRESSED,
  },
} = internalBinding('constants');

const DH_GENERATOR = 2;

function DiffieHellman(sizeOrKey, keyEncoding, generator, genEncoding) {
  if (!(this instanceof DiffieHellman))
    return new DiffieHellman(sizeOrKey, keyEncoding, generator, genEncoding);

  if (typeof sizeOrKey !== 'number' &&
      typeof sizeOrKey !== 'string' &&
      !isArrayBufferView(sizeOrKey) &&
      !isAnyArrayBuffer(sizeOrKey)) {
    throw new ERR_INVALID_ARG_TYPE(
      'sizeOrKey',
      ['number', 'string', 'ArrayBuffer', 'Buffer', 'TypedArray', 'DataView'],
      sizeOrKey,
    );
  }

  // Sizes < 0 don't make sense but they _are_ accepted (and subsequently
  // rejected with ERR_OSSL_BN_BITS_TOO_SMALL) by OpenSSL. The glue code
  // in node_crypto.cc accepts values that are IsInt32() for that reason
  // and that's why we do that here too.
  if (typeof sizeOrKey === 'number') {
    validateInt32(sizeOrKey, 'sizeOrKey');
    // Coerce -0 to +0.
    sizeOrKey += 0;
  }

  if (keyEncoding && !Buffer.isEncoding(keyEncoding) &&
      keyEncoding !== 'buffer') {
    genEncoding = generator;
    generator = keyEncoding;
    keyEncoding = false;
  }

  if (typeof sizeOrKey !== 'number')
    sizeOrKey = toBuf(sizeOrKey, keyEncoding);

  if (!generator) {
    generator = DH_GENERATOR;
  } else if (typeof generator === 'number') {
    validateInt32(generator, 'generator');
  } else if (typeof generator === 'string') {
    generator = toBuf(generator, genEncoding);
  } else if (!isArrayBufferView(generator) && !isAnyArrayBuffer(generator)) {
    throw new ERR_INVALID_ARG_TYPE(
      'generator',
      ['number', 'string', 'ArrayBuffer', 'Buffer', 'TypedArray', 'DataView'],
      generator,
    );
  }


  this[kHandle] = new _DiffieHellman(sizeOrKey, generator);
  ObjectDefineProperty(this, 'verifyError', {
    __proto__: null,
    enumerable: true,
    value: this[kHandle].verifyError,
    writable: false,
  });
}


function DiffieHellmanGroup(name) {
  if (!(this instanceof DiffieHellmanGroup))
    return new DiffieHellmanGroup(name);
  this[kHandle] = new _DiffieHellmanGroup(name);
  ObjectDefineProperty(this, 'verifyError', {
    __proto__: null,
    enumerable: true,
    value: this[kHandle].verifyError,
    writable: false,
  });
}


DiffieHellmanGroup.prototype.generateKeys =
    DiffieHellman.prototype.generateKeys =
    dhGenerateKeys;

function dhGenerateKeys(encoding) {
  const keys = this[kHandle].generateKeys();
  return encode(keys, encoding);
}


DiffieHellmanGroup.prototype.computeSecret =
    DiffieHellman.prototype.computeSecret =
    dhComputeSecret;

function dhComputeSecret(key, inEnc, outEnc) {
  key = getArrayBufferOrView(key, 'key', inEnc);
  const ret = this[kHandle].computeSecret(key);
  if (typeof ret === 'string')
    throw new ERR_CRYPTO_ECDH_INVALID_PUBLIC_KEY();
  return encode(ret, outEnc);
}


DiffieHellmanGroup.prototype.getPrime =
    DiffieHellman.prototype.getPrime =
    dhGetPrime;

function dhGetPrime(encoding) {
  const prime = this[kHandle].getPrime();
  return encode(prime, encoding);
}


DiffieHellmanGroup.prototype.getGenerator =
    DiffieHellman.prototype.getGenerator =
    dhGetGenerator;

function dhGetGenerator(encoding) {
  const generator = this[kHandle].getGenerator();
  return encode(generator, encoding);
}


DiffieHellmanGroup.prototype.getPublicKey =
    DiffieHellman.prototype.getPublicKey =
    dhGetPublicKey;

function dhGetPublicKey(encoding) {
  const key = this[kHandle].getPublicKey();
  return encode(key, encoding);
}


DiffieHellmanGroup.prototype.getPrivateKey =
    DiffieHellman.prototype.getPrivateKey =
    dhGetPrivateKey;

function dhGetPrivateKey(encoding) {
  const key = this[kHandle].getPrivateKey();
  return encode(key, encoding);
}


DiffieHellman.prototype.setPublicKey = function setPublicKey(key, encoding) {
  key = getArrayBufferOrView(key, 'key', encoding);
  this[kHandle].setPublicKey(key);
  return this;
};


DiffieHellman.prototype.setPrivateKey = function setPrivateKey(key, encoding) {
  key = getArrayBufferOrView(key, 'key', encoding);
  this[kHandle].setPrivateKey(key);
  return this;
};


function ECDH(curve) {
  if (!(this instanceof ECDH))
    return new ECDH(curve);

  validateString(curve, 'curve');
  this[kHandle] = new _ECDH(curve);
}

ECDH.prototype.computeSecret = DiffieHellman.prototype.computeSecret;
ECDH.prototype.setPrivateKey = DiffieHellman.prototype.setPrivateKey;
ECDH.prototype.setPublicKey = deprecate(DiffieHellman.prototype.setPublicKey,
                                        'ecdh.setPublicKey() is deprecated.',
                                        'DEP0031');
ECDH.prototype.getPrivateKey = DiffieHellman.prototype.getPrivateKey;

ECDH.prototype.generateKeys = function generateKeys(encoding, format) {
  this[kHandle].generateKeys();

  return this.getPublicKey(encoding, format);
};

ECDH.prototype.getPublicKey = function getPublicKey(encoding, format) {
  const f = getFormat(format);
  const key = this[kHandle].getPublicKey(f);
  return encode(key, encoding);
};

ECDH.convertKey = function convertKey(key, curve, inEnc, outEnc, format) {
  validateString(curve, 'curve');
  key = getArrayBufferOrView(key, 'key', inEnc);
  const f = getFormat(format);
  const convertedKey = _ECDHConvertKey(key, curve, f);
  return encode(convertedKey, outEnc);
};

function encode(buffer, encoding) {
  if (encoding && encoding !== 'buffer')
    buffer = buffer.toString(encoding);
  return buffer;
}

function getFormat(format) {
  if (format) {
    if (format === 'compressed')
      return POINT_CONVERSION_COMPRESSED;
    if (format === 'hybrid')
      return POINT_CONVERSION_HYBRID;
    if (format !== 'uncompressed')
      throw new ERR_CRYPTO_ECDH_INVALID_FORMAT(format);
  }
  return POINT_CONVERSION_UNCOMPRESSED;
}

const dhEnabledKeyTypes = new SafeSet(['dh', 'ec', 'x448', 'x25519']);

function diffieHellman(options, callback) {
  validateObject(options, 'options');

  if (callback !== undefined)
    validateFunction(callback, 'callback');

  const { privateKey, publicKey } = options;

  // TODO(@panva): remove these non-semver-major error code preserving measures
  // in a semver-major followup, the final state is just preparePublicOrPrivateKey
  // and preparePrivateKey
  if (privateKey == null)
    throw new ERR_INVALID_ARG_VALUE('options.privateKey', privateKey);

  if (publicKey == null)
    throw new ERR_INVALID_ARG_VALUE('options.publicKey', publicKey);

  if (isKeyObject(privateKey)) {
    const type = getKeyObjectType(privateKey);
    if (type !== 'private')
      throw new ERR_CRYPTO_INVALID_KEY_OBJECT_TYPE(type, 'private');
  }

  if (isKeyObject(publicKey)) {
    const type = getKeyObjectType(publicKey);
    if (type !== 'public' && type !== 'private') {
      throw new ERR_CRYPTO_INVALID_KEY_OBJECT_TYPE(type,
                                                   'private or public');
    }
  }

  if (isKeyObject(privateKey) && isKeyObject(publicKey)) {
    const privateType = getKeyObjectAsymmetricKeyType(privateKey);
    const publicType = getKeyObjectAsymmetricKeyType(publicKey);
    if (privateType !== publicType || !dhEnabledKeyTypes.has(privateType)) {
      throw new ERR_CRYPTO_INCOMPATIBLE_KEY('key types for Diffie-Hellman',
                                            `${privateType} and ${publicType}`);
    }
  }

  const {
    data: pubData,
    format: pubFormat,
    type: pubType,
    passphrase: pubPassphrase,
    namedCurve: pubNamedCurve,
  } = preparePublicOrPrivateKey(publicKey, 'options.publicKey');

  const {
    data: privData,
    format: privFormat,
    type: privType,
    passphrase: privPassphrase,
    namedCurve: privNamedCurve,
  } = preparePrivateKey(privateKey, 'options.privateKey');

  const job = new DHBitsJob(
    callback ? kCryptoJobAsync : kCryptoJobSync,
    pubData,
    pubFormat,
    pubType,
    pubPassphrase,
    pubNamedCurve,
    privData,
    privFormat,
    privType,
    privPassphrase,
    privNamedCurve);

  if (!callback) {
    const { 0: err, 1: secret } = job.run();
    if (err !== undefined)
      throw err;

    return Buffer.from(secret);
  }

  job.ondone = (error, secret) => {
    if (error) return FunctionPrototypeCall(callback, job, error);
    FunctionPrototypeCall(callback, job, null, Buffer.from(secret));
  };
  job.run();
}

// The ecdhDeriveBits function is part of the Web Crypto API and serves both
// deriveKeys and deriveBits functions.
function ecdhDeriveBits(algorithm, baseKey, length) {
  validateAlgorithm(algorithm, 'deriveBits');
  const { 'public': key } = algorithm;

  if (getCryptoKeyType(baseKey) !== 'private') {
    throw lazyDOMException(
      'baseKey must be a private key', 'InvalidAccessError');
  }

  const keyAlgorithm = getCryptoKeyAlgorithm(key);
  const baseKeyAlgorithm = getCryptoKeyAlgorithm(baseKey);
  if (keyAlgorithm.name !== baseKeyAlgorithm.name) {
    throw lazyDOMException(
      'The public and private keys must be of the same type',
      'InvalidAccessError');
  }

  if (
    keyAlgorithm.name === 'ECDH' &&
    keyAlgorithm.namedCurve !== baseKeyAlgorithm.namedCurve
  ) {
    throw lazyDOMException('Named curve mismatch', 'InvalidAccessError');
  }

  const bits = jobPromise(() => new DHBitsJob(
    kCryptoJobWebCrypto,
    getCryptoKeyHandle(key),
    undefined,
    undefined,
    undefined,
    undefined,
    getCryptoKeyHandle(baseKey),
    undefined,
    undefined,
    undefined,
    undefined));

  // If a length is not specified, return the full derived secret
  if (length === null)
    return bits;

  return jobPromiseThen(bits, (bits) => {
    const sliceLength = numBitsToBytes(length);

    const byteLength = ArrayBufferPrototypeGetByteLength(bits);
    // If the length is larger than the derived secret, throw.
    if (byteLength < sliceLength)
      throw lazyDOMException('derived bit length is too small', 'OperationError');

    if (length % 8 === 0 && byteLength === sliceLength)
      return bits;

    return TypedArrayPrototypeGetBuffer(truncateToBitLength(length, bits));
  });
}

module.exports = {
  DiffieHellman,
  DiffieHellmanGroup,
  ECDH,
  diffieHellman,
  ecdhDeriveBits,
};

sources.internal/crypto/ec:
'use strict';

const {
  TypedArrayPrototypeGetBuffer,
  TypedArrayPrototypeGetByteLength,
} = primordials;

const {
  EcKeyPairGenJob,
  KeyObjectHandle,
  SignJob,
  kCryptoJobWebCrypto,
  kKeyFormatDER,
  kKeyFormatRawPublic,
  kKeyTypePublic,
  kSignJobModeSign,
  kSignJobModeVerify,
  kSigEncP1363,
  kWebCryptoKeyFormatPKCS8,
  kWebCryptoKeyFormatRaw,
  kWebCryptoKeyFormatSPKI,
} = internalBinding('crypto');

const {
  crypto: {
    POINT_CONVERSION_UNCOMPRESSED,
  },
} = internalBinding('constants');

const {
  getUsagesMask,
  jobPromise,
  normalizeHashName,
  validateAlgorithm,
  kNamedCurveAliases,
  toUsagesSet,
} = require('internal/crypto/util');

const {
  lazyDOMException,
} = require('internal/util');

const {
  InternalCryptoKey,
  getCryptoKeyAlgorithm,
  getCryptoKeyHandle,
  getCryptoKeyType,
} = require('internal/crypto/keys');

const {
  createKeyUsages,
  getKeyPairUsages,
  importDerKey,
  importJwkKey,
  importRawKey,
  validateJwk,
  validateKeyUsages,
  validateUsagesNotEmpty,
  verifyAcceptableKeyUse,
} = require('internal/crypto/webcrypto_util');

const kDeriveUsages = createKeyUsages([], ['deriveKey', 'deriveBits']);

const kSignVerifyUsages = createKeyUsages(['verify'], ['sign']);

const kUsages = {
  '__proto__': null,
  'ECDH': kDeriveUsages,
  'ECDSA': kSignVerifyUsages,
};

function ecGenerateKey(algorithm, extractable, usages) {
  const { name, namedCurve } = algorithm;
  const allowedUsages = kUsages[name];
  const usagesSet = validateKeyUsages(usages, allowedUsages.keygen, name);
  validateAlgorithm(algorithm, 'generateKey');

  const keyAlgorithm = { name, namedCurve };
  const keyUsages = getKeyPairUsages(usagesSet, allowedUsages);
  validateUsagesNotEmpty(keyUsages.private);

  return jobPromise(() => new EcKeyPairGenJob(
    kCryptoJobWebCrypto,
    namedCurve,
    undefined,
    keyAlgorithm,
    getUsagesMask(keyUsages.public),
    getUsagesMask(keyUsages.private),
    extractable));
}

function ecExportKey(key, format) {
  try {
    const handle = getCryptoKeyHandle(key);
    switch (format) {
      case kWebCryptoKeyFormatRaw: {
        return TypedArrayPrototypeGetBuffer(
          handle.exportECPublicRaw(POINT_CONVERSION_UNCOMPRESSED));
      }
      case kWebCryptoKeyFormatSPKI: {
        let spki = handle.export(kKeyFormatDER, kWebCryptoKeyFormatSPKI);
        // WebCrypto requires uncompressed point format for SPKI exports.
        // This is a very rare edge case dependent on the imported key
        // using compressed point format.
        // Expected SPKI DER byte lengths with uncompressed points:
        // P-256: 91 = 26 bytes of SPKI ASN.1 + 65-byte uncompressed point.
        // P-384: 120 = 23 bytes of SPKI ASN.1 + 97-byte uncompressed point.
        // P-521: 158 = 25 bytes of SPKI ASN.1 + 133-byte uncompressed point.
        // Difference in initial SPKI ASN.1 is caused by OIDs and length encoding.
        const { namedCurve } = getCryptoKeyAlgorithm(key);
        if (TypedArrayPrototypeGetByteLength(spki) !== {
          '__proto__': null, 'P-256': 91, 'P-384': 120, 'P-521': 158,
        }[namedCurve]) {
          const raw = handle.exportECPublicRaw(POINT_CONVERSION_UNCOMPRESSED);
          const tmp = new KeyObjectHandle();
          tmp.init(kKeyTypePublic, raw, kKeyFormatRawPublic,
                   'ec', null, namedCurve);
          spki = tmp.export(kKeyFormatDER, kWebCryptoKeyFormatSPKI);
        }
        return TypedArrayPrototypeGetBuffer(spki);
      }
      case kWebCryptoKeyFormatPKCS8: {
        return TypedArrayPrototypeGetBuffer(
          handle.exportECPrivatePkcs8());
      }
      default:
        return undefined;
    }
  } catch (err) {
    throw lazyDOMException(
      'The operation failed for an operation-specific reason',
      { name: 'OperationError', cause: err });
  }
}

function ecImportKey(
  format,
  keyData,
  algorithm,
  extractable,
  usages,
) {
  const { name, namedCurve } = algorithm;
  validateAlgorithm(algorithm, 'importKey');

  let handle;
  const allowedUsages = kUsages[name];
  const usagesSet = toUsagesSet(usages);
  switch (format) {
    case 'KeyObjectHandle':
      verifyAcceptableKeyUse(
        name,
        usagesSet,
        keyData.getKeyType() === kKeyTypePublic ?
          allowedUsages.public :
          allowedUsages.private);
      handle = keyData;
      break;
    case 'spki': {
      verifyAcceptableKeyUse(name, usagesSet, allowedUsages.public);
      handle = importDerKey(keyData, true);
      break;
    }
    case 'pkcs8': {
      verifyAcceptableKeyUse(name, usagesSet, allowedUsages.private);
      handle = importDerKey(keyData, false);
      break;
    }
    case 'jwk': {
      const isPublic = keyData.d === undefined;
      verifyAcceptableKeyUse(
        name,
        usagesSet,
        isPublic ? allowedUsages.public : allowedUsages.private);

      const expectedUse = name === 'ECDH' ? 'enc' : 'sig';
      validateJwk(keyData, 'EC', extractable, usagesSet, expectedUse);

      if (keyData.crv !== namedCurve)
        throw lazyDOMException(
          'JWK "crv" does not match the requested algorithm',
          'DataError');

      if (algorithm.name === 'ECDSA' && keyData.alg !== undefined) {
        let algNamedCurve;
        switch (keyData.alg) {
          case 'ES256': algNamedCurve = 'P-256'; break;
          case 'ES384': algNamedCurve = 'P-384'; break;
          case 'ES512': algNamedCurve = 'P-521'; break;
        }
        if (algNamedCurve !== namedCurve)
          throw lazyDOMException(
            'JWK "alg" does not match the requested algorithm',
            'DataError');
      }

      handle = importJwkKey(isPublic, keyData);
      break;
    }
    case 'raw': {
      verifyAcceptableKeyUse(name, usagesSet, allowedUsages.public);
      handle = importRawKey(true, keyData, kKeyFormatRawPublic, 'ec', namedCurve);
      break;
    }
    default:
      return undefined;
  }

  switch (algorithm.name) {
    case 'ECDSA':
      // Fall through
    case 'ECDH':
      if (handle.getAsymmetricKeyType() !== 'ec')
        throw lazyDOMException('Invalid key type', 'DataError');
      break;
  }

  if (!handle.checkEcKeyData()) {
    throw lazyDOMException('Invalid keyData', 'DataError');
  }

  if (kNamedCurveAliases[namedCurve] !==
      handle.keyDetail({ __proto__: null }).namedCurve)
    throw lazyDOMException('Named curve mismatch', 'DataError');

  return new InternalCryptoKey(
    handle,
    { name, namedCurve },
    getUsagesMask(usagesSet),
    extractable);
}

function ecdsaSignVerify(key, data, { name, hash }, signature) {
  const mode = signature === undefined ? kSignJobModeSign : kSignJobModeVerify;
  const type = mode === kSignJobModeSign ? 'private' : 'public';

  if (getCryptoKeyType(key) !== type)
    throw lazyDOMException(`Key must be a ${type} key`, 'InvalidAccessError');

  return jobPromise(() => new SignJob(
    kCryptoJobWebCrypto,
    mode,
    getCryptoKeyHandle(key),
    undefined,
    undefined,
    undefined,
    undefined,
    data,
    normalizeHashName(hash.name),
    undefined,  // Salt length, not used with ECDSA
    undefined,  // PSS Padding, not used with ECDSA
    kSigEncP1363,
    undefined,
    signature));
}

module.exports = {
  ecExportKey,
  ecImportKey,
  ecGenerateKey,
  ecdsaSignVerify,
};

sources.internal/crypto/hash:
'use strict';

const {
  FunctionPrototypeCall,
  ObjectSetPrototypeOf,
  StringPrototypeReplace,
  StringPrototypeToLowerCase,
  Symbol,
  TypedArrayPrototypeIncludes,
} = primordials;

const {
  Hash: _Hash,
  HashJob,
  Hmac: _Hmac,
  kCryptoJobWebCrypto,
  oneShotDigest,
  TurboShakeJob,
  KangarooTwelveJob,
} = internalBinding('crypto');

const {
  getStringOption,
  jobPromise,
  normalizeHashName,
  validateAlgorithm,
  validateMaxBufferLength,
  kHandle,
  getCachedHashId,
  getHashCache,
  getArrayBufferOrView,
  getBufferSourceBytes,
  getOptionalByteLength,
} = require('internal/crypto/util');

const {
  prepareSecretKey,
} = require('internal/crypto/keys');

const {
  normalizeEncoding,
  encodingsMap,
  getDeprecationWarningEmitter,
} = require('internal/util');

const {
  Buffer,
} = require('buffer');

const {
  codes: {
    ERR_CRYPTO_HASH_FINALIZED,
    ERR_CRYPTO_HASH_UPDATE_FAILED,
    ERR_INVALID_ARG_TYPE,
    ERR_INVALID_ARG_VALUE,
  },
} = require('internal/errors');

const {
  validateEncoding,
  validateString,
  validateObject,
  validateUint32,
} = require('internal/validators');

const {
  isArrayBufferView,
} = require('internal/util/types');

const LazyTransform = require('internal/streams/lazy_transform');

const kState = Symbol('kState');
const kFinalized = Symbol('kFinalized');

/**
 * @param {string} name
 * @returns {string}
 */
function normalizeAlgorithm(name) {
  return StringPrototypeReplace(StringPrototypeToLowerCase(name), '-', '');
}

const maybeEmitDeprecationWarning = getDeprecationWarningEmitter(
  'DEP0198',
  'Creating SHAKE128/256 digests without an explicit options.outputLength is deprecated.',
  undefined,
  false,
  (algorithm) => {
    const normalized = normalizeAlgorithm(algorithm);
    return normalized === 'shake128' || normalized === 'shake256';
  },
);

function normalizeCShakeParameter(value, name) {
  if (value === undefined) return undefined;

  value = getArrayBufferOrView(value, name);
  if (TypedArrayPrototypeIncludes(getBufferSourceBytes(value), 0)) {
    throw new ERR_INVALID_ARG_VALUE(
      name, value, 'must not contain NUL bytes');
  }
  return value;
}

function Hash(algorithm, options) {
  if (!new.target)
    return new Hash(algorithm, options);
  const isCopy = algorithm instanceof _Hash;
  if (!isCopy)
    validateString(algorithm, 'algorithm');
  let xofLen = typeof options === 'object' && options !== null ?
    options.outputLength : undefined;
  if (xofLen !== undefined) {
    validateUint32(xofLen, 'options.outputLength');
    // Coerce -0 to +0.
    xofLen += 0;
  }
  let functionName;
  let customization;
  if (!isCopy && options !== undefined && options !== null) {
    const functionNameOption = options.functionName;
    if (functionNameOption !== undefined) {
      functionName = normalizeCShakeParameter(
        functionNameOption, 'options.functionName');
    }
    const customizationOption = options.customization;
    if (customizationOption !== undefined) {
      customization = normalizeCShakeParameter(
        customizationOption, 'options.customization');
    }
  }
  // Lookup the cached ID from JS land because it's faster than decoding
  // the string in C++ land.
  const algorithmId = isCopy ? -1 : getCachedHashId(algorithm);
  if (functionName === undefined && customization === undefined) {
    this[kHandle] = new _Hash(
      algorithm, xofLen, algorithmId, getHashCache());
  } else {
    this[kHandle] = new _Hash(
      algorithm,
      xofLen,
      algorithmId,
      getHashCache(),
      functionName,
      customization,
    );
  }
  this[kState] = {
    [kFinalized]: false,
  };
  if (!isCopy && xofLen === undefined) {
    maybeEmitDeprecationWarning(algorithm);
  }
  FunctionPrototypeCall(LazyTransform, this, options);
}

ObjectSetPrototypeOf(Hash.prototype, LazyTransform.prototype);
ObjectSetPrototypeOf(Hash, LazyTransform);

Hash.prototype.copy = function copy(options) {
  const state = this[kState];
  if (state[kFinalized])
    throw new ERR_CRYPTO_HASH_FINALIZED();

  return new Hash(this[kHandle], options);
};

Hash.prototype._transform = function _transform(chunk, encoding, callback) {
  if (!this[kHandle].update(chunk, encoding))
    return callback(new ERR_CRYPTO_HASH_UPDATE_FAILED());
  callback();
};

Hash.prototype._flush = function _flush(callback) {
  this.push(this[kHandle].digest());
  callback();
};

Hash.prototype.update = function update(data, encoding) {
  const state = this[kState];
  if (state[kFinalized])
    throw new ERR_CRYPTO_HASH_FINALIZED();

  if (typeof data === 'string') {
    validateEncoding(data, encoding);
  } else if (!isArrayBufferView(data)) {
    throw new ERR_INVALID_ARG_TYPE(
      'data', ['string', 'Buffer', 'TypedArray', 'DataView'], data);
  }

  if (!this[kHandle].update(data, encoding))
    throw new ERR_CRYPTO_HASH_UPDATE_FAILED();
  return this;
};


Hash.prototype.digest = function digest(outputEncoding) {
  const state = this[kState];
  if (state[kFinalized])
    throw new ERR_CRYPTO_HASH_FINALIZED();

  // Explicit conversion of truthy values for backward compatibility.
  const ret = this[kHandle].digest(outputEncoding && `${outputEncoding}`);
  state[kFinalized] = true;
  return ret;
};

function Hmac(hmac, key, options) {
  if (!(this instanceof Hmac))
    return new Hmac(hmac, key, options);
  validateString(hmac, 'hmac');
  const encoding = getStringOption(options, 'encoding');
  key = prepareSecretKey(key, encoding);
  this[kHandle] = new _Hmac();
  this[kHandle].init(hmac, key);
  this[kState] = {
    [kFinalized]: false,
  };
  FunctionPrototypeCall(LazyTransform, this, options);
}

ObjectSetPrototypeOf(Hmac.prototype, LazyTransform.prototype);
ObjectSetPrototypeOf(Hmac, LazyTransform);

Hmac.prototype.update = Hash.prototype.update;

Hmac.prototype.digest = function digest(outputEncoding) {
  const state = this[kState];

  if (state[kFinalized]) {
    const buf = Buffer.from('');
    if (outputEncoding && outputEncoding !== 'buffer')
      return buf.toString(outputEncoding);
    return buf;
  }

  // Explicit conversion of truthy values for backward compatibility.
  const ret = this[kHandle].digest(outputEncoding && `${outputEncoding}`);
  state[kFinalized] = true;
  return ret;
};

Hmac.prototype._flush = function _flush(callback) {
  this.push(this[kHandle].digest());
  this[kState][kFinalized] = true; // This diverges from Hash.prototype._flush:
  // Hash instances are still usable after a flush, Hmac are not, see DEP0206.
  callback();
};
Hmac.prototype._transform = Hash.prototype._transform;

// Implementation for WebCrypto subtle.digest()

function asyncDigest(algorithm, data) {
  validateMaxBufferLength(data, 'data');
  validateAlgorithm(algorithm, 'digest');

  switch (algorithm.name) {
    case 'SHA-1':
      // Fall through
    case 'SHA-256':
      // Fall through
    case 'SHA-384':
      // Fall through
    case 'SHA-512':
      // Fall through
    case 'SHA3-256':
      // Fall through
    case 'SHA3-384':
      // Fall through
    case 'SHA3-512':
      return jobPromise(() => new HashJob(
        kCryptoJobWebCrypto,
        normalizeHashName(algorithm.name),
        data));
    case 'cSHAKE128':
      // Fall through
    case 'cSHAKE256': {
      const outputLength = algorithm.outputLength;
      if (getOptionalByteLength(algorithm.functionName) ||
          getOptionalByteLength(algorithm.customization)) {
        return jobPromise(() => new HashJob(
          kCryptoJobWebCrypto,
          StringPrototypeToLowerCase(algorithm.name),
          data,
          outputLength,
          algorithm.functionName,
          algorithm.customization));
      }

      return jobPromise(() => new HashJob(
        kCryptoJobWebCrypto,
        normalizeHashName(algorithm.name),
        data,
        outputLength));
    }
    case 'TurboSHAKE128':
      // Fall through
    case 'TurboSHAKE256':
      return jobPromise(() => new TurboShakeJob(
        kCryptoJobWebCrypto,
        algorithm.name,
        algorithm.domainSeparation ?? 0x1f,
        algorithm.outputLength / 8,
        data));
    case 'KT128':
      // Fall through
    case 'KT256':
      return jobPromise(() => new KangarooTwelveJob(
        kCryptoJobWebCrypto,
        algorithm.name,
        algorithm.customization,
        algorithm.outputLength / 8,
        data));
    /* c8 ignore start */
    default: {
      const assert = require('internal/assert');
      assert.fail('Unreachable code');
    }
    /* c8 ignore stop */
  }
}

function hash(algorithm, input, options) {
  validateString(algorithm, 'algorithm');
  if (typeof input !== 'string' && !isArrayBufferView(input)) {
    throw new ERR_INVALID_ARG_TYPE('input', ['Buffer', 'TypedArray', 'DataView', 'string'], input);
  }
  if (options === undefined) {
    maybeEmitDeprecationWarning(algorithm);
    return oneShotDigest(algorithm, getCachedHashId(algorithm), getHashCache(),
                         input, 'hex', encodingsMap.hex, undefined);
  }
  let outputEncoding;
  let outputLength;
  let functionName;
  let customization;

  if (typeof options === 'string') {
    outputEncoding = options;
  } else if (options !== undefined) {
    validateObject(options, 'options');
    outputLength = options.outputLength;
    outputEncoding = options.outputEncoding;
    const functionNameOption = options.functionName;
    if (functionNameOption !== undefined) {
      functionName = normalizeCShakeParameter(
        functionNameOption, 'options.functionName');
    }
    const customizationOption = options.customization;
    if (customizationOption !== undefined) {
      customization = normalizeCShakeParameter(
        customizationOption, 'options.customization');
    }
  }

  outputEncoding ??= 'hex';

  let normalized = outputEncoding;
  // Fast case: if it's 'hex', we don't need to validate it further.
  if (normalized !== 'hex') {
    validateString(outputEncoding, 'outputEncoding');
    normalized = normalizeEncoding(outputEncoding);
    // If the encoding is invalid, normalizeEncoding() returns undefined.
    if (normalized === undefined) {
      // normalizeEncoding() doesn't handle 'buffer'.
      if (StringPrototypeToLowerCase(outputEncoding) === 'buffer') {
        normalized = 'buffer';
      } else {
        throw new ERR_INVALID_ARG_VALUE('outputEncoding', outputEncoding);
      }
    }
  }

  if (outputLength !== undefined) {
    validateUint32(outputLength, 'outputLength');
    // Coerce -0 to +0.
    outputLength += 0;
  }

  if (outputLength === undefined) {
    maybeEmitDeprecationWarning(algorithm);
  }

  if (functionName === undefined && customization === undefined) {
    return oneShotDigest(algorithm, getCachedHashId(algorithm), getHashCache(),
                         input, normalized, encodingsMap[normalized], outputLength);
  }
  return oneShotDigest(algorithm, getCachedHashId(algorithm), getHashCache(),
                       input, normalized, encodingsMap[normalized], outputLength,
                       functionName, customization);
}

module.exports = {
  Hash,
  Hmac,
  asyncDigest,
  hash,
};

sources.internal/crypto/hashnames:
'use strict';

const {
  ObjectKeys,
  ObjectSetPrototypeOf,
} = primordials;

const kHashContextNode = 1;
const kHashContextWebCrypto = 2;
const kHashContextJwkRsa = 3;
const kHashContextJwkRsaPss = 4;
const kHashContextJwkRsaOaep = 5;
const kHashContextJwkHmac = 6;

// WebCrypto and JWK use a bunch of different names for the
// standard set of SHA-* digest algorithms... which is ... fun.
// Here we provide a utility for mapping between them in order
// make it easier in the code.

const kHashNames = {
  'sha1': {
    [kHashContextNode]: 'sha1',
    [kHashContextWebCrypto]: 'SHA-1',
    [kHashContextJwkRsa]: 'RS1',
    [kHashContextJwkRsaPss]: 'PS1',
    [kHashContextJwkRsaOaep]: 'RSA-OAEP',
    [kHashContextJwkHmac]: 'HS1',
  },
  'sha256': {
    [kHashContextNode]: 'sha256',
    [kHashContextWebCrypto]: 'SHA-256',
    [kHashContextJwkRsa]: 'RS256',
    [kHashContextJwkRsaPss]: 'PS256',
    [kHashContextJwkRsaOaep]: 'RSA-OAEP-256',
    [kHashContextJwkHmac]: 'HS256',
  },
  'sha384': {
    [kHashContextNode]: 'sha384',
    [kHashContextWebCrypto]: 'SHA-384',
    [kHashContextJwkRsa]: 'RS384',
    [kHashContextJwkRsaPss]: 'PS384',
    [kHashContextJwkRsaOaep]: 'RSA-OAEP-384',
    [kHashContextJwkHmac]: 'HS384',
  },
  'sha512': {
    [kHashContextNode]: 'sha512',
    [kHashContextWebCrypto]: 'SHA-512',
    [kHashContextJwkRsa]: 'RS512',
    [kHashContextJwkRsaPss]: 'PS512',
    [kHashContextJwkRsaOaep]: 'RSA-OAEP-512',
    [kHashContextJwkHmac]: 'HS512',
  },
  'shake128': {
    [kHashContextNode]: 'shake128',
    [kHashContextWebCrypto]: 'cSHAKE128',
  },
  'shake256': {
    [kHashContextNode]: 'shake256',
    [kHashContextWebCrypto]: 'cSHAKE256',
  },
  'sha3-256': {
    [kHashContextNode]: 'sha3-256',
    [kHashContextWebCrypto]: 'SHA3-256',
  },
  'sha3-384': {
    [kHashContextNode]: 'sha3-384',
    [kHashContextWebCrypto]: 'SHA3-384',
  },
  'sha3-512': {
    [kHashContextNode]: 'sha3-512',
    [kHashContextWebCrypto]: 'SHA3-512',
  },
};

// Both tables are indexed with computed keys, so a polluted %Object.prototype%
// key must not answer a miss. Detached here rather than declared
// `__proto__: null`: V8 puts that literal form in dictionary mode.
ObjectSetPrototypeOf(kHashNames, null);

{
  // Index the aliases
  const keys = ObjectKeys(kHashNames);
  for (let n = 0; n < keys.length; n++) {
    const entry = kHashNames[keys[n]];
    ObjectSetPrototypeOf(entry, null);
    const contexts = ObjectKeys(entry);
    for (let i = 0; i < contexts.length; i++) {
      const alias = entry[contexts[i]];
      if (kHashNames[alias] === undefined)
        kHashNames[alias] = entry;
    }
  }
}

function normalizeHashName(name, context = kHashContextNode) {
  return kHashNames[name]?.[context];
}


normalizeHashName.kContextNode = kHashContextNode;
normalizeHashName.kContextWebCrypto = kHashContextWebCrypto;
normalizeHashName.kContextJwkRsa = kHashContextJwkRsa;
normalizeHashName.kContextJwkRsaPss = kHashContextJwkRsaPss;
normalizeHashName.kContextJwkRsaOaep = kHashContextJwkRsaOaep;
normalizeHashName.kContextJwkHmac = kHashContextJwkHmac;

module.exports = normalizeHashName;

sources.internal/crypto/hkdf:
'use strict';

const {
  ArrayBuffer,
  FunctionPrototypeCall,
  PromiseResolve,
  TypedArrayPrototypeGetByteLength,
  Uint8Array,
} = primordials;

const {
  HKDFJob,
  kCryptoJobAsync,
  kCryptoJobSync,
  kCryptoJobWebCrypto,
} = internalBinding('crypto');

const {
  validateFunction,
  validateInteger,
  validateString,
} = require('internal/validators');

const { kMaxLength } = require('buffer');

const {
  getBufferSourceByteLength,
  jobPromise,
  normalizeHashName,
  toBuf,
  validateByteSource,
  validateAlgorithm,
} = require('internal/crypto/util');

const {
  getCryptoKeyHandle,
  isKeyObject,
  prepareSecretKey,
} = require('internal/crypto/keys');

const {
  lazyDOMException,
} = require('internal/util');

const {
  isAnyArrayBuffer,
  isArrayBufferView,
  isSharedArrayBuffer,
} = require('internal/util/types');

const {
  codes: {
    ERR_INVALID_ARG_TYPE,
    ERR_OUT_OF_RANGE,
  },
  hideStackFrames,
} = require('internal/errors');

function getByteSourceByteLength(source) {
  if (isSharedArrayBuffer(source)) {
    return TypedArrayPrototypeGetByteLength(new Uint8Array(source));
  }
  return getBufferSourceByteLength(source);
}

const validateParameters = hideStackFrames((hash, key, salt, info, length) => {
  validateString.withoutStackTrace(hash, 'digest');
  key = prepareKey(key);
  salt = validateByteSource.withoutStackTrace(salt, 'salt');
  info = validateByteSource.withoutStackTrace(info, 'info');

  validateInteger.withoutStackTrace(length, 'length', 0, kMaxLength);
  // Coerce -0 to +0.
  length += 0;

  const infoByteLength = getByteSourceByteLength(info);
  if (infoByteLength > 1024) {
    throw new ERR_OUT_OF_RANGE.HideStackFramesError(
      'info',
      'must not contain more than 1024 bytes',
      infoByteLength);
  }

  return {
    hash,
    key,
    salt,
    info,
    length,
  };
});

function prepareKey(key) {
  if (isKeyObject(key))
    return prepareSecretKey(key);

  if (isAnyArrayBuffer(key))
    return key;

  key = toBuf(key);

  if (!isArrayBufferView(key)) {
    throw new ERR_INVALID_ARG_TYPE(
      'ikm',
      [
        'string',
        'SecretKeyObject',
        'ArrayBuffer',
        'TypedArray',
        'DataView',
        'Buffer',
      ],
      key);
  }

  return key;
}

function createHkdfJob(mode, params) {
  return new HKDFJob(
    mode,
    params.hash,
    params.key,
    params.salt,
    params.info,
    params.length);
}

function hkdf(hash, key, salt, info, length, callback) {
  const params = validateParameters(hash, key, salt, info, length);
  validateFunction(callback, 'callback');
  const job = createHkdfJob(kCryptoJobAsync, params);

  job.ondone = (error, bits) => {
    if (error) return FunctionPrototypeCall(callback, job, error);
    FunctionPrototypeCall(callback, job, null, bits);
  };

  job.run();
}

function hkdfSync(hash, key, salt, info, length) {
  const params = validateParameters(hash, key, salt, info, length);
  const job = createHkdfJob(kCryptoJobSync, params);
  const { 0: err, 1: bits } = job.run();
  if (err !== undefined)
    throw err;

  return bits;
}

function getDigestSizeInBytes(name) {
  switch (name) {
    case 'SHA-1':
      return 20;
    case 'SHA-256': // Fall through
    case 'SHA3-256':
      return 32;
    case 'SHA-384': // Fall through
    case 'SHA3-384':
      return 48;
    case 'SHA-512': // Fall through
    case 'SHA3-512':
      return 64;
  }
}

function validateHkdfDeriveBitsLength(length, hash) {
  if (length === null)
    throw lazyDOMException('length cannot be null', 'OperationError');
  if (length % 8) {
    throw lazyDOMException(
      'length must be a multiple of 8',
      'OperationError');
  }
  if (length > 255 * getDigestSizeInBytes(hash.name) * 8) {
    throw lazyDOMException(
      'length exceeds the maximum derived bit length',
      'OperationError');
  }
}

function hkdfDeriveBits(algorithm, baseKey, length) {
  const { hash, salt, info } = algorithm;
  validateHkdfDeriveBitsLength(length, hash);
  validateAlgorithm(algorithm, 'deriveBits');

  if (length === 0)
    return PromiseResolve(new ArrayBuffer(0));

  return jobPromise(() => new HKDFJob(
    kCryptoJobWebCrypto,
    normalizeHashName(hash.name),
    getCryptoKeyHandle(baseKey),
    salt,
    info,
    length / 8));
}

module.exports = {
  hkdf,
  hkdfSync,
  hkdfDeriveBits,
  validateHkdfDeriveBitsLength,
};

sources.internal/crypto/kem:
'use strict';

const {
  FunctionPrototypeCall,
} = primordials;

const {
  codes: {
    ERR_CRYPTO_KEM_NOT_SUPPORTED,
  },
} = require('internal/errors');

const {
  validateFunction,
} = require('internal/validators');

const {
  kCryptoJobAsync,
  kCryptoJobSync,
  KEMDecapsulateJob,
  KEMEncapsulateJob,
} = internalBinding('crypto');

const {
  preparePrivateKey,
  preparePublicOrPrivateKey,
} = require('internal/crypto/keys');

const {
  getArrayBufferOrView,
} = require('internal/crypto/util');

function encapsulate(key, callback) {
  if (!KEMEncapsulateJob)
    throw new ERR_CRYPTO_KEM_NOT_SUPPORTED();

  if (callback !== undefined)
    validateFunction(callback, 'callback');

  const {
    data: keyData,
    format: keyFormat,
    type: keyType,
    passphrase: keyPassphrase,
    namedCurve: keyNamedCurve,
  } = preparePublicOrPrivateKey(key);

  const job = new KEMEncapsulateJob(
    callback ? kCryptoJobAsync : kCryptoJobSync,
    keyData,
    keyFormat,
    keyType,
    keyPassphrase,
    keyNamedCurve);

  if (!callback) {
    const { 0: err, 1: result } = job.run();
    if (err !== undefined)
      throw err;
    const { 0: sharedKey, 1: ciphertext } = result;
    return { sharedKey, ciphertext };
  }

  job.ondone = (error, result) => {
    if (error) return FunctionPrototypeCall(callback, job, error);
    const { 0: sharedKey, 1: ciphertext } = result;
    FunctionPrototypeCall(callback, job, null, { sharedKey, ciphertext });
  };
  job.run();
}

function decapsulate(key, ciphertext, callback) {
  if (!KEMDecapsulateJob)
    throw new ERR_CRYPTO_KEM_NOT_SUPPORTED();

  if (callback !== undefined)
    validateFunction(callback, 'callback');

  const {
    data: keyData,
    format: keyFormat,
    type: keyType,
    passphrase: keyPassphrase,
    namedCurve: keyNamedCurve,
  } = preparePrivateKey(key);

  ciphertext = getArrayBufferOrView(ciphertext, 'ciphertext');

  const job = new KEMDecapsulateJob(
    callback ? kCryptoJobAsync : kCryptoJobSync,
    keyData,
    keyFormat,
    keyType,
    keyPassphrase,
    keyNamedCurve,
    ciphertext);

  if (!callback) {
    const { 0: err, 1: result } = job.run();
    if (err !== undefined)
      throw err;

    return result;
  }

  job.ondone = (error, result) => {
    if (error) return FunctionPrototypeCall(callback, job, error);
    FunctionPrototypeCall(callback, job, null, result);
  };
  job.run();
}

module.exports = {
  encapsulate,
  decapsulate,
};

sources.internal/crypto/kem_hybrids:
'use strict';

const {
  BigInt,
  PromiseWithResolvers,
  SafeSet,
  StringPrototypeToLowerCase,
  TypedArrayOf,
  TypedArrayPrototypeGetBuffer,
  TypedArrayPrototypeGetByteLength,
  TypedArrayPrototypeGetByteOffset,
  TypedArrayPrototypeGetLength,
  TypedArrayPrototypeSet,
  Uint8Array,
} = primordials;

const { Buffer } = require('buffer');

const {
  getCryptoKeyExtractable,
  getCryptoKeyAlgorithm,
  getCryptoKeyHandle,
  getCryptoKeySeedData,
  getCryptoKeySecondaryHandle,
  getCryptoKeyType,
  getCryptoKeyUsagesMask,
  InternalCryptoKey,
} = require('internal/crypto/keys');

const {
  DHBitsJob,
  KEMDecapsulateJob,
  KEMEncapsulateJob,
  KeyObjectHandle,
  kCryptoJobWebCrypto,
  kKeyFormatRawPrivate,
  kKeyFormatRawPublic,
  kKeyFormatRawSeed,
  kKeyTypePrivate,
  kKeyTypePublic,
  timingSafeEqual,
} = internalBinding('crypto');

const {
  crypto: {
    POINT_CONVERSION_UNCOMPRESSED,
  },
} = internalBinding('constants');

const {
  getBufferSourceBytes,
  getUsagesMask,
  getUsagesFromMask,
  jobPromise,
  jobPromiseThen,
  resolveWebCryptoResult,
} = require('internal/crypto/util');

const {
  lazyDOMException,
  setOwnProperty,
} = require('internal/util');

const {
  hash,
} = require('internal/crypto/hash');

const {
  randomBytes,
} = require('internal/crypto/random');

const {
  createKeyUsages,
  getKeyPairUsages,
  validateJwk,
  validateKeyUsages,
  validateUsagesNotEmpty,
  verifyAcceptableKeyUse,
} = require('internal/crypto/webcrypto_util');

// Concrete PQ/T Hybrid KEM instances:
// https://www.ietf.org/archive/id/draft-irtf-cfrg-concrete-hybrid-kems-04.html#section-4
// CG framework used by those instances:
// https://www.ietf.org/archive/id/draft-irtf-cfrg-hybrid-kems-12.html#section-5.5

const kKemPqSeedLength = 64;
const kSeedLength = 32;
const kX25519KeyLength = 32;
const kP256KeyLength = 32;
const kP384KeyLength = 48;
const kEcPointPrefixLength = 1;
const kEcUncompressedPointPrefix = 0x04;
const kKemPq768EncapsulationKeyLength = 1184;
const kKemPq768CiphertextLength = 1088;
const kKemPq1024EncapsulationKeyLength = 1568;
const kKemPq1024CiphertextLength = 1568;
const kKemPq768KeyType = 'ml-kem-768';
const kKemPq1024KeyType = 'ml-kem-1024';
const kX25519Name = 'X25519';
const kEcdhName = 'ECDH';
const kEcKeyType = 'ec';
const kP256Name = 'P-256';
const kP384Name = 'P-384';
// P-256 and P-384 group order constants are used by RandomScalar.
// https://www.ietf.org/archive/id/draft-irtf-cfrg-concrete-hybrid-kems-04.html#section-3.1.1
// https://www.rfc-editor.org/rfc/rfc8017#section-4.2
const kP256Order = 0xffffffff00000000ffffffffffffffffbce6faada7179e84f3b9cac2fc632551n;
const kP384Order = 0xffffffffffffffffffffffffffffffffffffffffffffffffc7634d81f4372ddf581a0db248b0a77aecec196accc52973n;

const kEncapsulationUsages = ['encapsulateKey', 'encapsulateBits'];
const kDecapsulationUsages = ['decapsulateKey', 'decapsulateBits'];
const kUsages = createKeyUsages(kEncapsulationUsages, kDecapsulationUsages);

function getByteView(data, start, end = TypedArrayPrototypeGetByteLength(data)) {
  return new Uint8Array(TypedArrayPrototypeGetBuffer(data),
                        TypedArrayPrototypeGetByteOffset(data) + start,
                        end - start);
}

/**
 * Adds lengths that are the concatenation of the PQ KEM component and the
 * traditional group component.
 * @param {object} config
 * @returns {object}
 */
function withHybridLengths(config) {
  return {
    __proto__: null,
    ...config,
    encapsulationKeyLength:
      config.kemPqEncapsulationKeyLength + config.groupElementLength,
    ciphertextLength:
      config.kemPqCiphertextLength + config.groupElementLength,
  };
}

const kAlgorithms = {
  '__proto__': null,
  'MLKEM768-P256': withHybridLengths({
    name: 'MLKEM768-P256',
    kemPqKeyType: kKemPq768KeyType,
    kemPqEncapsulationKeyLength: kKemPq768EncapsulationKeyLength,
    kemPqCiphertextLength: kKemPq768CiphertextLength,
    groupName: kEcdhName,
    groupKeyType: kEcKeyType,
    namedCurve: kP256Name,
    groupElementLength: kEcPointPrefixLength + 2 * kP256KeyLength,
    groupScalarLength: kP256KeyLength,
    groupSeedLength: 4 * kP256KeyLength,
    groupOrder: kP256Order,
    label: TypedArrayOf(
      Uint8Array,
      0x4d, 0x4c, 0x4b, 0x45, 0x4d, 0x37, 0x36,
      0x38, 0x2d, 0x50, 0x32, 0x35, 0x36, // "MLKEM768-P256"
    ),
  }),
  'MLKEM768-X25519': withHybridLengths({
    name: 'MLKEM768-X25519',
    kemPqKeyType: kKemPq768KeyType,
    kemPqEncapsulationKeyLength: kKemPq768EncapsulationKeyLength,
    kemPqCiphertextLength: kKemPq768CiphertextLength,
    groupName: kX25519Name,
    groupKeyType: StringPrototypeToLowerCase(kX25519Name),
    // Curve25519 RandomScalar is identity and Exp is X25519.
    // https://www.rfc-editor.org/rfc/rfc7748#section-5
    groupElementLength: kX25519KeyLength,
    groupScalarLength: kX25519KeyLength,
    groupSeedLength: kX25519KeyLength,
    label: TypedArrayOf(
      Uint8Array,
      0x5c, 0x2e, 0x2f, 0x2f, 0x5e, 0x5c, // "\\.//^\\"
    ),
  }),
  'MLKEM1024-P384': withHybridLengths({
    name: 'MLKEM1024-P384',
    kemPqKeyType: kKemPq1024KeyType,
    kemPqEncapsulationKeyLength: kKemPq1024EncapsulationKeyLength,
    kemPqCiphertextLength: kKemPq1024CiphertextLength,
    groupName: kEcdhName,
    groupKeyType: kEcKeyType,
    namedCurve: kP384Name,
    groupElementLength: kEcPointPrefixLength + 2 * kP384KeyLength,
    groupScalarLength: kP384KeyLength,
    groupSeedLength: kP384KeyLength,
    groupOrder: kP384Order,
    label: TypedArrayOf(
      Uint8Array,
      0x4d, 0x4c, 0x4b, 0x45, 0x4d, 0x31, 0x30,
      0x32, 0x34, 0x2d, 0x50, 0x33, 0x38, 0x34, // "MLKEM1024-P384"
    ),
  }),
};

/**
 * Wraps native or lower-level failures as WebCrypto OperationError failures.
 * @param {unknown} [cause]
 * @returns {DOMException}
 */
function operationFailure(cause) {
  return lazyDOMException(
    'The operation failed for an operation-specific reason',
    { name: 'OperationError', cause });
}

/**
 * Wraps native or lower-level failures as WebCrypto DataError failures.
 * @param {unknown} [cause]
 * @returns {DOMException}
 */
function dataFailure(cause) {
  return lazyDOMException('Invalid keyData', { name: 'DataError', cause });
}

/**
 * Copies supported BufferSource-like data into a new Uint8Array.
 * @param {ArrayBuffer | ArrayBufferView} data
 * @returns {Uint8Array}
 */
function copyBytes(data) {
  return new Uint8Array(getBufferSourceBytes(data));
}

/**
 * Concatenates byte arrays into a new Uint8Array of the expected length.
 * @param {Uint8Array[]} chunks
 * @param {number} length
 * @returns {Uint8Array}
 */
function concatBytes(chunks, length) {
  const output = new Uint8Array(length);
  let offset = 0;
  for (let n = 0; n < chunks.length; n++) {
    const chunk = chunks[n];
    TypedArrayPrototypeSet(output, chunk, offset);
    offset += TypedArrayPrototypeGetByteLength(chunk);
  }
  return output;
}

/**
 * Compares byte arrays by value.
 * @param {Uint8Array} a
 * @param {Uint8Array} b
 * @returns {boolean}
 */
function bytesEqual(a, b) {
  return TypedArrayPrototypeGetByteLength(a) === TypedArrayPrototypeGetByteLength(b) &&
    timingSafeEqual(a, b);
}

/**
 * Decodes a JWK base64url member.
 * @param {string} input
 * @returns {Uint8Array}
 */
function decodeJwkBase64Url(input) {
  return Buffer.from(input, 'base64url');
}

/**
 * Encodes JWK key material as unpadded base64url.
 * @param {Uint8Array} input
 * @returns {string}
 */
function base64urlEncode(input) {
  return Buffer.from(input).toString('base64url');
}

/**
 * Copies a Uint8Array's represented bytes into an ArrayBuffer result.
 * @param {Uint8Array} data
 * @returns {ArrayBuffer}
 */
function toArrayBuffer(data) {
  return TypedArrayPrototypeGetBuffer(copyBytes(data));
}

/**
 * Validates fixed-size key material.
 * @param {Uint8Array} data
 * @param {number} length
 */
function validateLength(data, length) {
  if (TypedArrayPrototypeGetByteLength(data) !== length) {
    throw lazyDOMException('Invalid keyData', 'DataError');
  }
}

/**
 * Splits bytes into the PQ KEM and traditional group portions.
 * @param {Uint8Array} data
 * @param {number} offset
 * @returns {{ head: Uint8Array, tail: Uint8Array }}
 */
function splitAt(data, offset) {
  return {
    __proto__: null,
    head: getByteView(data, 0, offset),
    tail: getByteView(data, offset),
  };
}

/**
 * Splits a Hybrid KEM raw-public key into its PQ and group public-key parts.
 * @param {Uint8Array} rawEncapsulationKey
 * @param {object} config
 * @returns {{ kemPq: Uint8Array, group: Uint8Array }}
 */
function splitEncapsulationKey(rawEncapsulationKey, config) {
  validateLength(rawEncapsulationKey, config.encapsulationKeyLength);
  const { head, tail } = splitAt(
    rawEncapsulationKey,
    config.kemPqEncapsulationKeyLength);
  return { __proto__: null, kemPq: head, group: tail };
}

/**
 * Copies and splits a Hybrid KEM ciphertext into its PQ and group parts.
 * @param {ArrayBuffer | ArrayBufferView} ciphertext
 * @param {object} config
 * @returns {{ kemPq: Uint8Array, group: Uint8Array }}
 */
function splitCiphertext(ciphertext, config) {
  const ciphertextBuffer = copyBytes(ciphertext);
  if (TypedArrayPrototypeGetByteLength(ciphertextBuffer) !==
      config.ciphertextLength) {
    throw operationFailure();
  }
  const { head, tail } = splitAt(
    ciphertextBuffer,
    config.kemPqCiphertextLength);
  return { __proto__: null, kemPq: head, group: copyBytes(tail) };
}

/**
 * Converts an octet string to a non-negative integer.
 * @param {Uint8Array} data
 * @returns {bigint}
 */
function os2ip(data) {
  let value = 0n;
  for (let n = 0; n < TypedArrayPrototypeGetLength(data); n++)
    value = (value << 8n) | BigInt(data[n]);
  return value;
}

/**
 * Derives a valid traditional group scalar from expanded seed bytes.
 * @param {Uint8Array} seed
 * @param {object} config
 * @returns {Uint8Array}
 */
function randomScalar(seed, config) {
  if (config.groupOrder === undefined)
    return copyBytes(seed);

  const { groupOrder, groupScalarLength } = config;
  for (let offset = 0;
    offset + groupScalarLength <= TypedArrayPrototypeGetLength(seed);
    offset += groupScalarLength) {
    const scalar = copyBytes(
      getByteView(seed, offset, offset + groupScalarLength));
    const value = os2ip(scalar);
    if (value !== 0n && value < groupOrder)
      return scalar;
  }

  throw operationFailure();
}

/**
 * Imports raw key material into a native KeyObjectHandle.
 * @param {number} keyType
 * @param {Uint8Array} keyData
 * @param {number} format
 * @param {string} asymmetricKeyType
 * @param {string} [namedCurve]
 * @returns {KeyObjectHandle}
 */
function importRawKeyHandle(
  keyType,
  keyData,
  format,
  asymmetricKeyType,
  namedCurve) {
  const handle = new KeyObjectHandle();
  handle.init(
    keyType,
    keyData,
    format,
    asymmetricKeyType,
    null,
    namedCurve ?? null);
  if (asymmetricKeyType === kEcKeyType && !handle.checkEcKeyData())
    throw lazyDOMException('Invalid keyData', 'DataError');
  return handle;
}

/**
 * Imports the PQ KEM decapsulation seed.
 * @param {Uint8Array} seed
 * @param {object} config
 * @returns {KeyObjectHandle}
 */
function importKemPqDecapsulationHandle(seed, config) {
  return importRawKeyHandle(
    kKeyTypePrivate,
    seed,
    kKeyFormatRawSeed,
    config.kemPqKeyType);
}

/**
 * Imports the PQ KEM encapsulation key.
 * @param {Uint8Array} rawEncapsulationKey
 * @param {object} config
 * @returns {KeyObjectHandle}
 */
function importKemPqEncapsulationHandle(rawEncapsulationKey, config) {
  return importRawKeyHandle(
    kKeyTypePublic,
    rawEncapsulationKey,
    kKeyFormatRawPublic,
    config.kemPqKeyType);
}

/**
 * Imports the traditional group private scalar.
 * @param {Uint8Array} seed
 * @param {object} config
 * @returns {KeyObjectHandle}
 */
function importGroupPrivateHandle(seed, config) {
  return importRawKeyHandle(
    kKeyTypePrivate,
    seed,
    kKeyFormatRawPrivate,
    config.groupKeyType,
    config.namedCurve);
}

/**
 * Imports the traditional group public element.
 * @param {Uint8Array} groupElement
 * @param {object} config
 * @returns {KeyObjectHandle}
 */
function importGroupElementHandle(groupElement, config) {
  if (config.groupKeyType === kEcKeyType &&
      groupElement[0] !== kEcUncompressedPointPrefix) {
    throw lazyDOMException('Invalid keyData', 'DataError');
  }
  return importRawKeyHandle(
    kKeyTypePublic,
    groupElement,
    kKeyFormatRawPublic,
    config.groupKeyType,
    config.namedCurve);
}

/**
 * Exports the raw public key bytes from the PQ KEM handle.
 * @param {KeyObjectHandle} handle
 * @returns {Uint8Array}
 */
function rawKemPqEncapsulationKey(handle) {
  return copyBytes(handle.rawPublicKey());
}

/**
 * Exports the raw public element from the traditional group handle.
 * @param {KeyObjectHandle} handle
 * @param {object} config
 * @returns {Uint8Array}
 */
function rawGroupElement(handle, config) {
  if (config.groupKeyType === kEcKeyType) {
    return copyBytes(
      handle.exportECPublicRaw(POINT_CONVERSION_UNCOMPRESSED));
  }
  return copyBytes(handle.rawPublicKey());
}

/**
 * Builds the Hybrid KEM raw-public key from component public handles.
 * @param {KeyObjectHandle} kemPqHandle
 * @param {KeyObjectHandle} groupHandle
 * @param {object} config
 * @returns {Uint8Array}
 */
function rawEncapsulationKeyFromHandles(kemPqHandle, groupHandle, config) {
  return concatBytes([
    rawKemPqEncapsulationKey(kemPqHandle),
    rawGroupElement(groupHandle, config),
  ], config.encapsulationKeyLength);
}

/**
 * Imports both components of a Hybrid KEM public key.
 * @param {Uint8Array} kemPq
 * @param {Uint8Array} group
 * @param {object} config
 * @returns {{ kemPqHandle: KeyObjectHandle, groupHandle: KeyObjectHandle }}
 */
function importPublicKeyHandles(kemPq, group, config) {
  try {
    return {
      __proto__: null,
      kemPqHandle: importKemPqEncapsulationHandle(kemPq, config),
      groupHandle: importGroupElementHandle(group, config),
    };
  } catch (err) {
    throw dataFailure(err);
  }
}

/**
 * Imports both components of a Hybrid KEM private key.
 * @param {Uint8Array} seedPq
 * @param {Uint8Array} groupSeed
 * @param {object} config
 * @returns {{ kemPqHandle: KeyObjectHandle, groupHandle: KeyObjectHandle }}
 */
function importPrivateKeyHandles(seedPq, groupSeed, config) {
  try {
    return {
      __proto__: null,
      kemPqHandle: importKemPqDecapsulationHandle(seedPq, config),
      groupHandle: importGroupPrivateHandle(groupSeed, config),
    };
  } catch (err) {
    throw operationFailure(err);
  }
}

/**
 * Creates a Hybrid KEM public CryptoKey from imported component handles.
 * @param {KeyObjectHandle} kemPqHandle
 * @param {KeyObjectHandle} groupHandle
 * @param {object} config
 * @param {boolean} extractable
 * @param {Set<string> | string[]} keyUsages
 * @returns {InternalCryptoKey}
 */
function createPublicKeyFromComponents(
  kemPqHandle,
  groupHandle,
  config,
  extractable,
  keyUsages) {
  const usagesSet = new SafeSet(keyUsages);
  return new InternalCryptoKey(
    kemPqHandle,
    { name: config.name },
    getUsagesMask(usagesSet),
    extractable,
    groupHandle);
}

/**
 * Creates a Hybrid KEM private CryptoKey from imported component handles and seed.
 * @param {KeyObjectHandle} kemPqHandle
 * @param {KeyObjectHandle} groupHandle
 * @param {Uint8Array} seed
 * @param {object} config
 * @param {boolean} extractable
 * @param {Set<string> | string[]} keyUsages
 * @returns {InternalCryptoKey}
 */
function createPrivateKeyFromComponents(
  kemPqHandle,
  groupHandle,
  seed,
  config,
  extractable,
  keyUsages) {
  const usagesSet = new SafeSet(keyUsages);
  return new InternalCryptoKey(
    kemPqHandle,
    { name: config.name },
    getUsagesMask(usagesSet),
    extractable,
    groupHandle,
    seed);
}

/**
 * Creates a Hybrid KEM public CryptoKey from concatenated raw-public bytes.
 * @param {Uint8Array} rawEncapsulationKey
 * @param {object} config
 * @param {boolean} extractable
 * @param {Set<string> | string[]} keyUsages
 * @returns {InternalCryptoKey}
 */
function createPublicKeyFromRaw(
  rawEncapsulationKey,
  config,
  extractable,
  keyUsages) {
  const { kemPq, group } = splitEncapsulationKey(rawEncapsulationKey, config);
  const { kemPqHandle, groupHandle } =
    importPublicKeyHandles(kemPq, group, config);

  return createPublicKeyFromComponents(
    kemPqHandle,
    groupHandle,
    config,
    extractable,
    keyUsages);
}

/**
 * Expands the 32-byte Hybrid KEM seed into PQ KEM seed and group seed material.
 * @param {Uint8Array} seed
 * @param {object} config
 * @returns {{ seedPq: Uint8Array, groupSeed: Uint8Array }}
 */
function expandSeed(seed, config) {
  validateLength(seed, kSeedLength);

  // DeriveKeyPair(seed) expands seed into seed_PQ and seed_T.
  // https://www.ietf.org/archive/id/draft-irtf-cfrg-concrete-hybrid-kems-04.html#section-4.1
  const expanded = copyBytes(hash('shake256', seed, {
    outputEncoding: 'buffer',
    outputLength: kKemPqSeedLength + config.groupSeedLength,
  }));

  const { head, tail } = splitAt(expanded, kKemPqSeedLength);
  return {
    __proto__: null,
    seedPq: copyBytes(head),
    groupSeed: randomScalar(tail, config),
  };
}

/**
 * Derives the Hybrid KEM private key and, when requested, the matching public key.
 * @param {Uint8Array} seed
 * @param {object} config
 * @param {boolean} extractable
 * @param {Set<string> | string[]} decapsulationKeyUsages
 * @param {Set<string> | string[]} [encapsulationKeyUsages]
 * @returns {{ privateKey: InternalCryptoKey, publicKey?: InternalCryptoKey }}
 */
function deriveKeyPair(
  seed,
  config,
  extractable,
  decapsulationKeyUsages,
  encapsulationKeyUsages) {
  const { seedPq, groupSeed } = expandSeed(seed, config);
  const { kemPqHandle, groupHandle } =
    importPrivateKeyHandles(seedPq, groupSeed, config);

  const privateKey = createPrivateKeyFromComponents(
    kemPqHandle,
    groupHandle,
    seed,
    config,
    extractable,
    decapsulationKeyUsages);

  if (encapsulationKeyUsages === undefined)
    return { __proto__: null, privateKey };

  const publicKey = createPublicKeyFromRaw(
    rawEncapsulationKeyFromHandles(
      kemPqHandle,
      groupHandle,
      config),
    config,
    true,
    encapsulationKeyUsages);
  return { __proto__: null, privateKey, publicKey };
}

/**
 * Extracts both component handles stored in a Hybrid KEM CryptoKey.
 * @param {CryptoKey} key
 * @returns {{ kemPqHandle: KeyObjectHandle, groupHandle: KeyObjectHandle }}
 */
function getHybridKeyHandles(key) {
  const kemPqHandle = getCryptoKeyHandle(key);
  const groupHandle = getCryptoKeySecondaryHandle(key);
  if (groupHandle === undefined) {
    throw operationFailure();
  }
  return { __proto__: null, kemPqHandle, groupHandle };
}

/**
 * Extracts and copies the stored 32-byte Hybrid KEM seed from a private key.
 * @param {CryptoKey} key
 * @returns {Uint8Array}
 */
function getHybridSeed(key) {
  const seed = getCryptoKeySeedData(key);
  if (seed === undefined) {
    throw operationFailure();
  }
  return copyBytes(seed);
}

/**
 * Returns the algorithm config and component handles for a Hybrid KEM CryptoKey.
 * @param {CryptoKey} key
 * @returns {object}
 */
function getHybridKeyContext(key) {
  const config = kAlgorithms[getCryptoKeyAlgorithm(key).name];
  const { kemPqHandle, groupHandle } = getHybridKeyHandles(key);
  return { __proto__: null, config, kemPqHandle, groupHandle };
}

/**
 * Validates the CryptoKey type and returns its Hybrid KEM key context.
 * @param {CryptoKey} key
 * @param {'public' | 'private'} type
 * @param {string} message
 * @returns {object}
 */
function requireHybridKeyContext(key, type, message) {
  if (getCryptoKeyType(key) !== type)
    throw lazyDOMException(message, 'InvalidAccessError');
  return getHybridKeyContext(key);
}

/**
 * Runs ECDH/X25519 over the traditional group component.
 * @param {KeyObjectHandle} publicHandle
 * @param {KeyObjectHandle} privateHandle
 * @returns {Promise<Uint8Array>}
 */
function deriveGroupBits(publicHandle, privateHandle) {
  const bits = jobPromise(() => new DHBitsJob(
    kCryptoJobWebCrypto,
    publicHandle,
    undefined,
    undefined,
    undefined,
    undefined,
    privateHandle,
    undefined,
    undefined,
    undefined,
    undefined));
  return jobPromiseThen(
    bits,
    (bits) => copyBytes(bits),
    (err) => { throw operationFailure(err); });
}

/**
 * Applies the C2PRI combiner to the PQ and traditional shared secrets.
 * @param {Uint8Array} sharedSecretPq
 * @param {Uint8Array} sharedSecretT
 * @param {Uint8Array} ciphertextT
 * @param {Uint8Array} encapsulationKey
 * @param {object} config
 * @returns {Uint8Array}
 */
function combineSharedSecret(
  sharedSecretPq,
  sharedSecretT,
  ciphertextT,
  encapsulationKey,
  config) {
  // C2PRICombiner(ss_PQ, ss_T, ct_T, ek_T, Label).
  // https://www.ietf.org/archive/id/draft-irtf-cfrg-hybrid-kems-12.html#section-5.1.3
  const encapsulationKeyT = getByteView(
    encapsulationKey,
    config.kemPqEncapsulationKeyLength);
  const inputLength =
    TypedArrayPrototypeGetByteLength(sharedSecretPq) +
    TypedArrayPrototypeGetByteLength(sharedSecretT) +
    TypedArrayPrototypeGetByteLength(ciphertextT) +
    TypedArrayPrototypeGetByteLength(encapsulationKeyT) +
    TypedArrayPrototypeGetByteLength(config.label);

  const input = concatBytes([
    sharedSecretPq,
    sharedSecretT,
    ciphertextT,
    encapsulationKeyT,
    config.label,
  ], inputLength);

  return copyBytes(hash('sha3-256', input, {
    outputEncoding: 'buffer',
  }));
}

/**
 * Splits requested Hybrid KEM key usages into private and public key usages.
 * @param {string} name
 * @param {string[]} keyUsages
 * @returns {{ privateUsages: Set<string>, publicUsages: Set<string> }}
 */
function getGenerateKeyUsages(name, keyUsages) {
  const usageSet = validateKeyUsages(keyUsages, kUsages.keygen, name);
  const usages = getKeyPairUsages(usageSet, kUsages);
  validateUsagesNotEmpty(usages.private);

  return {
    __proto__: null,
    privateUsages: usages.private,
    publicUsages: usages.public,
  };
}

/**
 * Imports a Hybrid KEM JWK, validating public/private consistency when `priv`
 * is present.
 * @param {object} input
 * @param {string} name
 * @param {object} config
 * @param {boolean} extractable
 * @param {Set<string>} usagesSet
 * @returns {InternalCryptoKey}
 */
function importJwkKey(input, name, config, extractable, usagesSet) {
  const isPublic = input.priv === undefined;
  verifyAcceptableKeyUse(
    name,
    usagesSet,
    isPublic ? kUsages.public : kUsages.private);
  validateJwk(input, 'AKP', extractable, usagesSet, 'enc');
  if (input.alg !== name) {
    throw lazyDOMException(
      'JWK "alg" Parameter and algorithm name mismatch',
      'DataError');
  }

  const rawEncapsulationKey = decodeJwkBase64Url(input.pub);
  validateLength(rawEncapsulationKey, config.encapsulationKeyLength);
  if (isPublic) {
    return createPublicKeyFromRaw(
      rawEncapsulationKey,
      config,
      extractable,
      usagesSet);
  }

  const { privateKey } = deriveKeyPair(
    decodeJwkBase64Url(input.priv),
    config,
    extractable,
    usagesSet);
  const { kemPqHandle, groupHandle } = getHybridKeyHandles(privateKey);
  const derivedRawEncapsulationKey =
    rawEncapsulationKeyFromHandles(kemPqHandle, groupHandle, config);
  if (!bytesEqual(derivedRawEncapsulationKey, rawEncapsulationKey))
    throw lazyDOMException('Invalid keyData', 'DataError');
  return privateKey;
}

/**
 * Exports a Hybrid KEM key as an AKP JWK.
 * @param {CryptoKey} key
 * @param {Uint8Array} rawEncapsulationKey
 * @param {object} config
 * @returns {object}
 */
function exportJwkKey(key, rawEncapsulationKey, config) {
  const jwk = {
    kty: 'AKP',
    alg: config.name,
    pub: base64urlEncode(rawEncapsulationKey),
    key_ops: getUsagesFromMask(getCryptoKeyUsagesMask(key)),
    ext: getCryptoKeyExtractable(key),
  };
  if (getCryptoKeyType(key) === 'private')
    setOwnProperty(jwk, 'priv', base64urlEncode(getHybridSeed(key)));
  return jwk;
}

/**
 * Implements generateKey for Hybrid KEM algorithms.
 * @param {object} algorithm
 * @param {boolean} extractable
 * @param {string[]} keyUsages
 * @returns {{ publicKey: InternalCryptoKey, privateKey: InternalCryptoKey }}
 */
function kemHybridGenerateKey(algorithm, extractable, keyUsages) {
  const { name } = algorithm;
  const config = kAlgorithms[name];
  const { privateUsages, publicUsages } =
    getGenerateKeyUsages(name, keyUsages);

  const keyPair = deriveKeyPair(
    copyBytes(randomBytes(kSeedLength)),
    config,
    extractable,
    privateUsages,
    publicUsages);
  return { publicKey: keyPair.publicKey, privateKey: keyPair.privateKey };
}

/**
 * Implements importKey for Hybrid KEM algorithms.
 * @param {'raw-public' | 'raw-seed' | 'jwk'} format
 * @param {ArrayBuffer | ArrayBufferView | object} input
 * @param {object} algorithm
 * @param {boolean} extractable
 * @param {string[]} keyUsages
 * @returns {InternalCryptoKey | undefined}
 */
function kemHybridImportKey(
  format,
  input,
  algorithm,
  extractable,
  keyUsages) {

  const { name } = algorithm;
  const config = kAlgorithms[name];
  const usagesSet = new SafeSet(keyUsages);

  switch (format) {
    case 'raw-public': {
      verifyAcceptableKeyUse(name, usagesSet, kUsages.public);
      return createPublicKeyFromRaw(
        copyBytes(input),
        config,
        extractable,
        usagesSet);
    }
    case 'raw-seed': {
      verifyAcceptableKeyUse(name, usagesSet, kUsages.private);
      return deriveKeyPair(
        copyBytes(input),
        config,
        extractable,
        usagesSet).privateKey;
    }
    case 'jwk':
      return importJwkKey(input, name, config, extractable, usagesSet);
    default:
      return undefined;
  }
}

/**
 * Implements exportKey for Hybrid KEM algorithms.
 * @param {CryptoKey} key
 * @param {'raw-public' | 'raw-seed' | 'jwk'} format
 * @returns {ArrayBuffer | object | undefined}
 */
function kemHybridExportKey(key, format) {
  const { config, kemPqHandle, groupHandle } = getHybridKeyContext(key);
  const rawEncapsulationKey =
    rawEncapsulationKeyFromHandles(kemPqHandle, groupHandle, config);
  switch (format) {
    case 'raw-public':
      return toArrayBuffer(rawEncapsulationKey);
    case 'raw-seed':
      if (getCryptoKeyType(key) === 'private') {
        return toArrayBuffer(getHybridSeed(key));
      }
      return undefined;
    case 'jwk':
      return exportJwkKey(key, rawEncapsulationKey, config);
    default:
      return undefined;
  }
}

/**
 * Implements getPublicKey for Hybrid KEM private keys.
 * @param {CryptoKey} privateKey
 * @param {string[]} keyUsages
 * @returns {InternalCryptoKey}
 */
function kemHybridGetPublicKey(privateKey, keyUsages) {
  const { config, kemPqHandle, groupHandle } =
    getHybridKeyContext(privateKey);
  const usageSet = new SafeSet(keyUsages);
  verifyAcceptableKeyUse(config.name, usageSet, kUsages.public);
  return createPublicKeyFromRaw(
    rawEncapsulationKeyFromHandles(kemPqHandle, groupHandle, config),
    config,
    true,
    usageSet);
}

/**
 * Generates the ephemeral traditional group private key for encapsulation.
 * @param {object} config
 * @returns {KeyObjectHandle}
 */
function generateEphemeralGroupScalar(config) {
  const seed = randomScalar(
    copyBytes(randomBytes(config.groupSeedLength)),
    config);
  return importGroupPrivateHandle(seed, config);
}

/**
 * Continues a WebCrypto job promise and routes synchronous continuation
 * failures to the provided reject callback.
 * @param {Promise} promise
 * @param {Function} reject
 * @param {Function} onFulfilled
 */
function continueJob(promise, reject, onFulfilled) {
  jobPromiseThen(promise, (value) => {
    try {
      onFulfilled(value);
    } catch (err) {
      reject(err);
    }
  }, reject);
}

/**
 * Continues a WebCrypto job promise and resolves with WebCrypto result
 * shielding for object results.
 * @param {Promise} promise
 * @param {Function} resolve
 * @param {Function} reject
 * @param {Function} onFulfilled
 */
function resolveJob(promise, resolve, reject, onFulfilled) {
  continueJob(promise, reject, (value) => {
    resolveWebCryptoResult(resolve, onFulfilled(value));
  });
}

/**
 * Prepares the traditional group side of encapsulation and starts its derive job.
 * @param {KeyObjectHandle} kemPqHandle
 * @param {KeyObjectHandle} groupHandle
 * @param {object} config
 * @returns {object}
 */
function prepareEncapsulationGroup(kemPqHandle, groupHandle, config) {
  const ephemeralGroupHandle = generateEphemeralGroupScalar(config);
  const ciphertextT = rawGroupElement(ephemeralGroupHandle, config);
  const sharedSecretT = deriveGroupBits(
    groupHandle,
    ephemeralGroupHandle);
  return {
    __proto__: null,
    ciphertextT,
    sharedSecretT,
    rawEncapsulationKey:
      rawEncapsulationKeyFromHandles(kemPqHandle, groupHandle, config),
  };
}

/**
 * Combines the PQ and traditional encapsulation outputs into WebCrypto's
 * encapsulation result object.
 * @param {object} encapsPq
 * @param {Uint8Array} sharedSecretT
 * @param {object} group
 * @param {object} config
 * @returns {{ sharedKey: ArrayBuffer, ciphertext: ArrayBuffer }}
 */
function hybridEncapsulationResult(encapsPq, sharedSecretT, group, config) {
  const sharedKey = combineSharedSecret(
    copyBytes(encapsPq.sharedKey),
    sharedSecretT,
    group.ciphertextT,
    group.rawEncapsulationKey,
    config);
  const ciphertext = concatBytes([
    copyBytes(encapsPq.ciphertext),
    group.ciphertextT,
  ], config.ciphertextLength);

  return {
    sharedKey: toArrayBuffer(sharedKey),
    ciphertext: toArrayBuffer(ciphertext),
  };
}

/**
 * Imports the traditional group ciphertext component as a public key handle.
 * @param {Uint8Array} ciphertextT
 * @param {object} config
 * @returns {KeyObjectHandle}
 */
function importCiphertextGroupHandle(ciphertextT, config) {
  try {
    return importGroupElementHandle(ciphertextT, config);
  } catch (err) {
    throw operationFailure(err);
  }
}

/**
 * Implements encapsulateBits for Hybrid KEM algorithms.
 * @param {CryptoKey} encapsulationKey
 * @returns {Promise<{ sharedKey: ArrayBuffer, ciphertext: ArrayBuffer }>}
 */
function kemHybridEncaps(encapsulationKey) {
  const { config, kemPqHandle, groupHandle } = requireHybridKeyContext(
    encapsulationKey,
    'public',
    'Key must be a public key');
  const encapsPq = jobPromise(() => new KEMEncapsulateJob(
    kCryptoJobWebCrypto,
    kemPqHandle,
    undefined,
    undefined,
    undefined,
    undefined));
  const {
    promise,
    resolve,
    reject,
  } = PromiseWithResolvers();

  continueJob(encapsPq, reject, (encapsPq) => {
    const group = prepareEncapsulationGroup(
      kemPqHandle,
      groupHandle,
      config);
    resolveJob(group.sharedSecretT, resolve, reject, (sharedSecretT) =>
      hybridEncapsulationResult(encapsPq, sharedSecretT, group, config));
  });

  return promise;
}

/**
 * Implements decapsulateBits for Hybrid KEM algorithms.
 * @param {CryptoKey} decapsulationKey
 * @param {ArrayBuffer | ArrayBufferView} ciphertext
 * @returns {Promise<ArrayBuffer>}
 */
function kemHybridDecaps(decapsulationKey, ciphertext) {
  const { config, kemPqHandle, groupHandle } = requireHybridKeyContext(
    decapsulationKey,
    'private',
    'Key must be a private key');
  const { kemPq: ciphertextPq, group: ciphertextT } =
    splitCiphertext(ciphertext, config);
  const groupPublicHandle =
    importCiphertextGroupHandle(ciphertextT, config);

  const sharedSecretPq = jobPromise(() => new KEMDecapsulateJob(
    kCryptoJobWebCrypto,
    kemPqHandle,
    undefined,
    undefined,
    undefined,
    undefined,
    ciphertextPq));
  const {
    promise,
    resolve,
    reject,
  } = PromiseWithResolvers();

  continueJob(sharedSecretPq, reject, (sharedSecretPq) => {
    const sharedSecretT = deriveGroupBits(
      groupPublicHandle,
      groupHandle);
    resolveJob(sharedSecretT, resolve, reject, (sharedSecretT) =>
      toArrayBuffer(combineSharedSecret(
        copyBytes(sharedSecretPq),
        sharedSecretT,
        ciphertextT,
        rawEncapsulationKeyFromHandles(kemPqHandle, groupHandle, config),
        config)));
  });

  return promise;
}

module.exports = {
  kemHybridDecaps,
  kemHybridEncaps,
  kemHybridExportKey,
  kemHybridGenerateKey,
  kemHybridGetPublicKey,
  kemHybridImportKey,
};

sources.internal/crypto/keygen:
'use strict';

const {
  FunctionPrototypeCall,
  ObjectDefineProperty,
  SafeArrayIterator,
} = primordials;

const {
  DhKeyPairGenJob,
  DsaKeyPairGenJob,
  EcKeyPairGenJob,
  NamedKeyPairGenJob,
  RsaKeyPairGenJob,
  SecretKeyGenJob,
  kCryptoJobAsync,
  kCryptoJobSync,
  kKeyVariantRSA_PSS,
  kKeyVariantRSA_SSA_PKCS1_v1_5,
  OPENSSL_EC_NAMED_CURVE,
  OPENSSL_EC_EXPLICIT_CURVE,
} = internalBinding('crypto');

const {
  PublicKeyObject,
  PrivateKeyObject,
  SecretKeyObject,
  parsePublicKeyEncoding,
  parsePrivateKeyEncoding,
} = require('internal/crypto/keys');

const {
  customPromisifyArgs,
  kEmptyObject,
} = require('internal/util');

const {
  validateFunction,
  validateBuffer,
  validateString,
  validateInteger,
  validateObject,
  validateOneOf,
  validateInt32,
  validateUint32,
} = require('internal/validators');

const {
  codes: {
    ERR_INCOMPATIBLE_OPTION_PAIR,
    ERR_INVALID_ARG_VALUE,
    ERR_MISSING_OPTION,
  },
} = require('internal/errors');

const { isArrayBufferView } = require('internal/util/types');

function isJwk(obj) {
  return obj != null && obj.kty !== undefined;
}

function wrapKey(key, ctor) {
  if (typeof key === 'string' ||
      isArrayBufferView(key) ||
      isJwk(key))
    return key;
  return new ctor(key);
}

function generateKeyPair(type, options, callback) {
  if (typeof options === 'function') {
    callback = options;
    options = undefined;
  }
  validateFunction(callback, 'callback');

  const job = createJob(kCryptoJobAsync, type, options);

  job.ondone = (error, result) => {
    if (error) return FunctionPrototypeCall(callback, job, error);
    // If no encoding was chosen, return key objects instead.
    let { 0: pubkey, 1: privkey } = result;
    pubkey = wrapKey(pubkey, PublicKeyObject);
    privkey = wrapKey(privkey, PrivateKeyObject);
    FunctionPrototypeCall(callback, job, null, pubkey, privkey);
  };

  job.run();
}

ObjectDefineProperty(generateKeyPair, customPromisifyArgs, {
  __proto__: null,
  value: ['publicKey', 'privateKey'],
  enumerable: false,
});

function generateKeyPairSync(type, options) {
  return handleError(createJob(kCryptoJobSync, type, options).run());
}

function handleError(ret) {
  if (ret == null)
    return; // async

  const { 0: err, 1: keys } = ret;
  if (err !== undefined)
    throw err;

  const { 0: publicKey, 1: privateKey } = keys;

  // If no encoding was chosen, return key objects instead.
  return {
    publicKey: wrapKey(publicKey, PublicKeyObject),
    privateKey: wrapKey(privateKey, PrivateKeyObject),
  };
}

function parseKeyEncoding(keyType, options = kEmptyObject) {
  const { publicKeyEncoding, privateKeyEncoding } = options;

  let publicFormat, publicType;
  if (publicKeyEncoding == null) {
    publicFormat = publicType = undefined;
  } else if (typeof publicKeyEncoding === 'object') {
    ({
      format: publicFormat,
      type: publicType,
    } = parsePublicKeyEncoding(publicKeyEncoding, keyType,
                               'options.publicKeyEncoding'));
  } else {
    throw new ERR_INVALID_ARG_VALUE('options.publicKeyEncoding',
                                    publicKeyEncoding);
  }

  let privateFormat, privateType, cipher, passphrase;
  if (privateKeyEncoding == null) {
    privateFormat = privateType = undefined;
  } else if (typeof privateKeyEncoding === 'object') {
    ({
      format: privateFormat,
      type: privateType,
      cipher,
      passphrase,
    } = parsePrivateKeyEncoding(privateKeyEncoding, keyType,
                                'options.privateKeyEncoding'));
  } else {
    throw new ERR_INVALID_ARG_VALUE('options.privateKeyEncoding',
                                    privateKeyEncoding);
  }

  return [
    publicFormat,
    publicType,
    privateFormat,
    privateType,
    cipher,
    passphrase,
  ];
}

function createJob(mode, type, options) {
  validateString(type, 'type');

  if (options !== undefined)
    validateObject(options, 'options');

  const encoding = new SafeArrayIterator(parseKeyEncoding(type, options));

  switch (type) {
    case 'rsa':
    case 'rsa-pss':
    {
      validateObject(options, 'options');
      let { modulusLength } = options;
      validateUint32(modulusLength, 'options.modulusLength');
      // Coerce -0 to +0.
      modulusLength += 0;

      let { publicExponent } = options;
      if (publicExponent == null) {
        publicExponent = 0x10001;
      } else {
        validateUint32(publicExponent, 'options.publicExponent');
        // Coerce -0 to +0.
        publicExponent += 0;
      }

      if (type === 'rsa') {
        return new RsaKeyPairGenJob(
          mode,
          kKeyVariantRSA_SSA_PKCS1_v1_5,  // Used also for RSA-OAEP
          modulusLength,
          publicExponent,
          ...encoding);
      }

      const { hashAlgorithm, mgf1HashAlgorithm } = options;
      let { saltLength } = options;

      if (saltLength !== undefined) {
        validateInt32(saltLength, 'options.saltLength', 0);
        // Coerce -0 to +0.
        saltLength += 0;
      }
      if (hashAlgorithm !== undefined)
        validateString(hashAlgorithm, 'options.hashAlgorithm');
      if (mgf1HashAlgorithm !== undefined)
        validateString(mgf1HashAlgorithm, 'options.mgf1HashAlgorithm');
      if (options.hash !== undefined) {
        // This API previously accepted a `hash` option that was deprecated
        // and removed. However, in order to make the change more visible, we
        // opted to throw an error if hash is specified rather than removing it
        // entirely.
        throw new ERR_INVALID_ARG_VALUE(
          'options.hash',
          options.hash,
          'is no longer supported',
        );
      }
      if (options.mgf1Hash !== undefined) {
        // This API previously accepted a `mgf1Hash` option that was deprecated
        // and removed. However, in order to make the change more visible, we
        // opted to throw an error if mgf1Hash is specified rather than removing
        // it entirely.
        throw new ERR_INVALID_ARG_VALUE(
          'options.mgf1Hash',
          options.mgf1Hash,
          'is no longer supported',
        );
      }

      return new RsaKeyPairGenJob(
        mode,
        kKeyVariantRSA_PSS,
        modulusLength,
        publicExponent,
        hashAlgorithm,
        mgf1HashAlgorithm,
        saltLength,
        ...encoding);
    }
    case 'dsa':
    {
      validateObject(options, 'options');
      let { modulusLength } = options;
      validateUint32(modulusLength, 'options.modulusLength');
      // Coerce -0 to +0.
      modulusLength += 0;

      let { divisorLength } = options;
      if (divisorLength == null) {
        divisorLength = -1;
      } else {
        validateInt32(divisorLength, 'options.divisorLength', 0);
        // Coerce -0 to +0.
        divisorLength += 0;
      }

      return new DsaKeyPairGenJob(
        mode,
        modulusLength,
        divisorLength,
        ...encoding);
    }
    case 'ec':
    {
      validateObject(options, 'options');
      const { namedCurve } = options;
      validateString(namedCurve, 'options.namedCurve');
      let { paramEncoding } = options;
      if (paramEncoding == null || paramEncoding === 'named')
        paramEncoding = OPENSSL_EC_NAMED_CURVE;
      else if (paramEncoding === 'explicit')
        paramEncoding = OPENSSL_EC_EXPLICIT_CURVE;
      else
        throw new ERR_INVALID_ARG_VALUE('options.paramEncoding', paramEncoding);

      return new EcKeyPairGenJob(
        mode,
        namedCurve,
        paramEncoding,
        ...encoding);
    }
    case 'dh':
    {
      validateObject(options, 'options');
      const { group, prime } = options;
      let { primeLength, generator } = options;
      if (group != null) {
        if (prime != null)
          throw new ERR_INCOMPATIBLE_OPTION_PAIR('group', 'prime');
        if (primeLength != null)
          throw new ERR_INCOMPATIBLE_OPTION_PAIR('group', 'primeLength');
        if (generator != null)
          throw new ERR_INCOMPATIBLE_OPTION_PAIR('group', 'generator');

        validateString(group, 'options.group');

        return new DhKeyPairGenJob(mode, group, ...encoding);
      }

      if (prime != null) {
        if (primeLength != null)
          throw new ERR_INCOMPATIBLE_OPTION_PAIR('prime', 'primeLength');

        validateBuffer(prime, 'options.prime');
      } else if (primeLength != null) {
        validateInt32(primeLength, 'options.primeLength', 0);
        // Coerce -0 to +0.
        primeLength += 0;
      } else {
        throw new ERR_MISSING_OPTION(
          'At least one of the group, prime, or primeLength options');
      }

      if (generator != null) {
        validateInt32(generator, 'options.generator', 0);
        // Coerce -0 to +0.
        generator += 0;
      }
      return new DhKeyPairGenJob(
        mode,
        prime != null ? prime : primeLength,
        generator == null ? 2 : generator,
        ...encoding);
    }
    default:
      return new NamedKeyPairGenJob(mode, type, ...encoding);
  }
}

// Symmetric Key Generation

function generateKeyJob(mode, keyType, options) {
  validateString(keyType, 'type');
  validateObject(options, 'options');
  const { length } = options;
  switch (keyType) {
    case 'hmac':
      validateInteger(length, 'options.length', 8, 2 ** 31 - 1);
      break;
    case 'aes':
      validateOneOf(length, 'options.length', [128, 192, 256]);
      break;
    default:
      throw new ERR_INVALID_ARG_VALUE(
        'type',
        keyType,
        'must be a supported key type');
  }

  return new SecretKeyGenJob(mode, length);
}

function handleGenerateKeyError(ret) {
  if (ret === undefined)
    return; // async

  const { 0: err, 1: key } = ret;
  if (err !== undefined)
    throw err;

  return wrapKey(key, SecretKeyObject);
}

function generateKey(type, options, callback) {
  if (typeof options === 'function') {
    callback = options;
    options = undefined;
  }

  validateFunction(callback, 'callback');

  const job = generateKeyJob(kCryptoJobAsync, type, options);

  job.ondone = (error, key) => {
    if (error) return FunctionPrototypeCall(callback, job, error);
    FunctionPrototypeCall(callback, job, null, wrapKey(key, SecretKeyObject));
  };

  handleGenerateKeyError(job.run());
}

function generateKeySync(type, options) {
  return handleGenerateKeyError(
    generateKeyJob(kCryptoJobSync, type, options).run());
}

module.exports = {
  generateKeyPair,
  generateKeyPairSync,
  generateKey,
  generateKeySync,
};

sources.internal/crypto/keys:
'use strict';

const {
  ArrayPrototypeMap,
  ObjectDefineProperties,
  ObjectPrototypeHasOwnProperty,
  ObjectSetPrototypeOf,
  StringPrototypeIncludes,
  StringPrototypeStartsWith,
  SymbolToStringTag,
  TypedArrayPrototypeIncludes,
  Uint8Array,
} = primordials;

const {
  KeyObjectHandle,
  createNativeKeyObjectClass,
  // eslint-disable-next-line no-restricted-syntax -- intended here
  getKeyObjectSlots: nativeGetKeyObjectSlots,
  isKeyObject: isNativeKeyObject,
  createCryptoKeyClass,
  // eslint-disable-next-line no-restricted-syntax -- intended here
  getCryptoKeySlots: nativeGetCryptoKeySlots,
  isCryptoKey: isNativeCryptoKey,
  kKeyTypeSecret,
  kKeyTypePublic,
  kKeyTypePrivate,
  kKeyFormatPEM,
  kKeyFormatDER,
  kKeyFormatJWK,
  kKeyFormatRawPublic,
  kKeyFormatRawPrivate,
  kKeyFormatRawSeed,
  kKeyFormatStore,
  kKeyEncodingPKCS1,
  kKeyEncodingPKCS8,
  kKeyEncodingSPKI,
  kKeyEncodingSEC1,
  parsePKCS12: _parsePKCS12,
} = internalBinding('crypto');

const {
  crypto: {
    POINT_CONVERSION_COMPRESSED,
    POINT_CONVERSION_UNCOMPRESSED,
  },
} = internalBinding('constants');

const {
  validateObject,
  validateOneOf,
  validateString,
} = require('internal/validators');

const {
  codes: {
    ERR_CRYPTO_INCOMPATIBLE_KEY_OPTIONS,
    ERR_CRYPTO_INVALID_KEY_OBJECT_TYPE,
    ERR_ILLEGAL_CONSTRUCTOR,
    ERR_INVALID_ARG_TYPE,
    ERR_INVALID_ARG_VALUE,
    ERR_INVALID_THIS,
  },
} = require('internal/errors');

const {
  getArrayBufferOrView,
  getBufferSourceBytes,
  bigIntArrayToUnsignedBigInt,
  normalizeAlgorithm,
  hasAnyNotIn,
  getUsagesMask,
  getUsagesFromMask,
  hasUsage,
  toUsagesSet,
} = require('internal/crypto/util');

const {
  isAnyArrayBuffer,
  isArrayBufferView,
} = require('internal/util/types');

const {
  fileURLToPath,
  getURLHref,
  isURLInstance,
} = require('internal/url');

const {
  customInspectSymbol: kInspect,
  getDeprecationWarningEmitter,
  kEnumerableProperty,
  kEmptyObject,
  lazyDOMException,
} = require('internal/util');

const { inspect } = require('internal/util/inspect');
const { Buffer } = require('buffer');

const emitDEP0203 = getDeprecationWarningEmitter(
  'DEP0203',
  'Passing a CryptoKey to node:crypto functions is deprecated.',
);

const maybeEmitDEP0204 = getDeprecationWarningEmitter(
  'DEP0204',
  'Passing a non-extractable CryptoKey to KeyObject.from() is deprecated.',
  undefined,
  false,
  (key) => !getCryptoKeyExtractable(key),
);

// Key input contexts.
const kConsumePublic = 0;
const kConsumePrivate = 1;
const kCreatePublic = 2;
const kCreatePrivate = 3;

const encodingNames = [];
for (const m of [[kKeyEncodingPKCS1, 'pkcs1'], [kKeyEncodingPKCS8, 'pkcs8'],
                 [kKeyEncodingSPKI, 'spki'], [kKeyEncodingSEC1, 'sec1']])
  encodingNames[m[0]] = m[1];

// KeyObject state lives on the native NativeKeyObject base class. JS caches
// the constructor-known type enum in a private field, then replaces it with
// the native type and KeyObjectHandle tuple when the handle is first needed.
// No forgeable own Symbols are exposed on public KeyObject instances.
let getKeyObjectSlots; // Populated by the createNativeKeyObjectClass callback.
let isKeyObject;
let getKeyObjectTypeValue;

const kKeyObjectSlotType = 0;
const kKeyObjectSlotHandle = 1;
// The native slot tuple stops at kKeyObjectSlotHandle. The remaining entries
// are JS-side lazy cache slots derived from the KeyObjectHandle on first use.
const kKeyObjectSlotSymmetricKeySize = 2;
const kKeyObjectSlotAsymmetricKeyType = 3;
const kKeyObjectSlotAsymmetricKeyDetails = 4;

function normalizeKeyDetails(details = kEmptyObject) {
  if (details.publicExponent !== undefined) {
    return {
      __proto__: null,
      ...details,
      publicExponent:
        bigIntArrayToUnsignedBigInt(new Uint8Array(details.publicExponent)),
    };
  }
  return details;
}

// Creating the KeyObject class is a little complicated due to inheritance
// and the fact that KeyObjects should be transferable between threads,
// which requires the KeyObject base class to be implemented in C++.
// The creation requires a callback to make sure that the NativeKeyObject
// base class cannot exist without the other KeyObject implementations.
const {
  0: KeyObject,
  1: SecretKeyObject,
  2: PublicKeyObject,
  3: PrivateKeyObject,
} = createNativeKeyObjectClass((NativeKeyObject) => {
  let webidl;

  // Publicly visible KeyObject class.
  class KeyObject extends NativeKeyObject {
    #slots;

    constructor(type, handle) {
      let keyType;
      switch (type) {
        case 'secret': keyType = kKeyTypeSecret; break;
        case 'public': keyType = kKeyTypePublic; break;
        case 'private': keyType = kKeyTypePrivate; break;
        default: throw new ERR_INVALID_ARG_VALUE('type', type);
      }
      if (typeof handle !== 'object' || !(handle instanceof KeyObjectHandle))
        throw new ERR_INVALID_ARG_TYPE('handle', 'object', handle);

      super(handle);
      this.#slots = keyType;
    }

    get type() {
      return getKeyObjectType(this);
    }

    toCryptoKey(algorithm, extractable, keyUsages) {
      webidl ??= require('internal/crypto/webidl');
      algorithm = normalizeAlgorithm(webidl.converters.AlgorithmIdentifier(algorithm), 'importKey');
      extractable = webidl.converters.boolean(extractable);
      keyUsages = webidl.converters['sequence<KeyUsage>'](keyUsages);

      const type = getKeyObjectType(this);
      const handle = getKeyObjectHandle(this);
      switch (type) {
        case 'secret':
          return toCryptoKeySecret(
            handle,
            algorithm,
            extractable,
            keyUsages);
        case 'public':
          // Fall through
        case 'private':
          return toCryptoKey(
            handle,
            algorithm,
            extractable,
            keyUsages);
      }
    }

    static from(key) {
      if (!isCryptoKey(key))
        throw new ERR_INVALID_ARG_TYPE('key', 'CryptoKey', key);
      maybeEmitDEP0204(key);
      if (getCryptoKeySecondaryHandle(key) !== undefined) {
        throw new ERR_INVALID_ARG_VALUE(
          'key',
          key,
          'cannot be represented by a single KeyObject');
      }
      const handle = getCryptoKeyHandle(key);
      switch (getCryptoKeyType(key)) {
        /* eslint-disable no-use-before-define */
        case 'secret': return new SecretKeyObject(handle);
        case 'public': return new PublicKeyObject(handle);
        case 'private': return new PrivateKeyObject(handle);
        /* eslint-enable no-use-before-define */
      }
    }

    equals(otherKeyObject) {
      if (!isKeyObject(otherKeyObject)) {
        throw new ERR_INVALID_ARG_TYPE(
          'otherKeyObject', 'KeyObject', otherKeyObject);
      }

      const slots = getKeyObjectSlots(this);
      const otherSlots = getKeyObjectSlots(otherKeyObject);
      return slots[kKeyObjectSlotType] === otherSlots[kKeyObjectSlotType] &&
        slots[kKeyObjectSlotHandle].equals(
          otherSlots[kKeyObjectSlotHandle]);
    }

    static {
      isKeyObject = (key) => {
        if (key == null || typeof key !== 'object') return false;
        return #slots in key || isNativeKeyObject(key);
      };
      getKeyObjectTypeValue = (key) => {
        if (!key || typeof key !== 'object')
          throw new ERR_INVALID_THIS('KeyObject');
        if (#slots in key) {
          const cached = key.#slots;
          if (typeof cached === 'number') return cached;
          if (cached !== undefined) return cached[kKeyObjectSlotType];
        }
        return getKeyObjectSlots(key)[kKeyObjectSlotType];
      };

      getKeyObjectSlots = (key) => {
        if (!key || typeof key !== 'object')
          throw new ERR_INVALID_THIS('KeyObject');
        if (#slots in key) {
          const cached = key.#slots;
          if (cached !== undefined && typeof cached !== 'number') return cached;
        }
        const slots = nativeGetKeyObjectSlots(key);
        key.#slots = slots;
        return slots;
      };
    }
  }

  ObjectDefineProperties(KeyObject.prototype, {
    [SymbolToStringTag]: {
      __proto__: null,
      configurable: true,
      value: 'KeyObject',
    },
  });

  class SecretKeyObject extends KeyObject {
    constructor(handle) {
      super('secret', handle);
    }

    get symmetricKeySize() {
      return getKeyObjectSymmetricKeySize(this);
    }

    export(options) {
      const handle = getKeyObjectHandle(this);
      if (options !== undefined) {
        validateObject(options, 'options');
        validateOneOf(
          options.format, 'options.format', [undefined, 'buffer', 'jwk']);
        if (options.format === 'jwk') {
          return handle.exportJwk({}, false);
        }
      }
      return handle.export();
    }
  }

  class AsymmetricKeyObject extends KeyObject {
    get asymmetricKeyType() {
      return getKeyObjectAsymmetricKeyType(this);
    }

    get asymmetricKeyDetails() {
      return { ...getKeyObjectAsymmetricKeyDetails(this) };
    }
  }

  class PublicKeyObject extends AsymmetricKeyObject {
    constructor(handle) {
      super('public', handle);
    }

    export(options) {
      switch (options?.format) {
        case 'jwk':
          return getKeyObjectHandle(this).exportJwk({}, false);
        case 'raw-public': {
          const handle = getKeyObjectHandle(this);
          const asymmetricKeyType = getKeyObjectAsymmetricKeyType(this);
          if (asymmetricKeyType === 'ec') {
            const { type = 'uncompressed' } = options;
            validateOneOf(type, 'options.type', ['compressed', 'uncompressed']);
            const form = type === 'compressed' ?
              POINT_CONVERSION_COMPRESSED : POINT_CONVERSION_UNCOMPRESSED;
            return handle.exportECPublicRaw(form);
          }
          return handle.rawPublicKey();
        }
        default: {
          const asymmetricKeyType = getKeyObjectAsymmetricKeyType(this);
          const handle = getKeyObjectHandle(this);
          const {
            format,
            type,
          } = parsePublicKeyEncoding(options, asymmetricKeyType);
          return handle.export(format, type);
        }
      }
    }
  }

  class PrivateKeyObject extends AsymmetricKeyObject {
    constructor(handle) {
      super('private', handle);
    }

    export(options) {
      if (options?.passphrase !== undefined &&
          options.format !== 'pem' && options.format !== 'der') {
        throw new ERR_CRYPTO_INCOMPATIBLE_KEY_OPTIONS(
          options.format, 'does not support encryption');
      }
      switch (options?.format) {
        case 'jwk':
          return getKeyObjectHandle(this).exportJwk({}, false);
        case 'raw-private': {
          const handle = getKeyObjectHandle(this);
          const asymmetricKeyType = getKeyObjectAsymmetricKeyType(this);
          if (asymmetricKeyType === 'ec') {
            return handle.exportECPrivateRaw();
          }
          return handle.rawPrivateKey();
        }
        case 'raw-seed':
          return getKeyObjectHandle(this).rawSeed();
        default: {
          const asymmetricKeyType = getKeyObjectAsymmetricKeyType(this);
          const handle = getKeyObjectHandle(this);
          const {
            format,
            type,
            cipher,
            passphrase,
          } = parsePrivateKeyEncoding(options, asymmetricKeyType);
          return handle.export(format, type, cipher, passphrase);
        }
      }
    }
  }

  return [KeyObject, SecretKeyObject, PublicKeyObject, PrivateKeyObject];
});

function parseKeyFormat(formatStr, defaultFormat, objName) {
  if (formatStr === undefined && defaultFormat !== undefined)
    return defaultFormat;
  else if (formatStr === 'pem')
    return kKeyFormatPEM;
  else if (formatStr === 'der')
    return kKeyFormatDER;
  else if (formatStr === 'jwk')
    return kKeyFormatJWK;
  else if (formatStr === 'raw-public')
    return kKeyFormatRawPublic;
  else if (formatStr === 'raw-private')
    return kKeyFormatRawPrivate;
  else if (formatStr === 'raw-seed')
    return kKeyFormatRawSeed;
  throw new ERR_INVALID_ARG_VALUE(option('format', objName), formatStr);
}

function parseKeyType(typeStr, required, keyType, isPublic, objName) {
  if (typeStr === undefined && !required) {
    return undefined;
  } else if (typeStr === 'pkcs1') {
    if (keyType !== undefined && keyType !== 'rsa') {
      throw new ERR_CRYPTO_INCOMPATIBLE_KEY_OPTIONS(
        typeStr, 'can only be used for RSA keys');
    }
    return kKeyEncodingPKCS1;
  } else if (typeStr === 'spki' && isPublic !== false) {
    return kKeyEncodingSPKI;
  } else if (typeStr === 'pkcs8' && isPublic !== true) {
    return kKeyEncodingPKCS8;
  } else if (typeStr === 'sec1' && isPublic !== true) {
    if (keyType !== undefined && keyType !== 'ec') {
      throw new ERR_CRYPTO_INCOMPATIBLE_KEY_OPTIONS(
        typeStr, 'can only be used for EC keys');
    }
    return kKeyEncodingSEC1;
  }

  throw new ERR_INVALID_ARG_VALUE(option('type', objName), typeStr);
}

function option(name, prefix) {
  return prefix === undefined ?
    `options.${name}` : `${prefix}.${name}`;
}

function parseKeyFormatAndType(enc, keyType, isPublic, objName) {
  const { format: formatStr, type: typeStr } = enc;

  const isInput = keyType === undefined;
  const format = parseKeyFormat(formatStr,
                                isInput ? kKeyFormatPEM : undefined,
                                objName);

  if (format === kKeyFormatRawPublic) {
    if (isPublic === false) {
      throw new ERR_INVALID_ARG_VALUE(option('format', objName), 'raw-public');
    }
    let type;
    if (typeStr === undefined || typeStr === 'uncompressed') {
      type = POINT_CONVERSION_UNCOMPRESSED;
    } else if (typeStr === 'compressed') {
      type = POINT_CONVERSION_COMPRESSED;
    } else {
      throw new ERR_INVALID_ARG_VALUE(option('type', objName), typeStr);
    }
    return { format, type };
  }

  if (format === kKeyFormatRawPrivate || format === kKeyFormatRawSeed) {
    if (isPublic === true) {
      throw new ERR_INVALID_ARG_VALUE(
        option('format', objName),
        format === kKeyFormatRawPrivate ? 'raw-private' : 'raw-seed');
    }
    if (typeStr !== undefined) {
      throw new ERR_INVALID_ARG_VALUE(option('type', objName), typeStr);
    }
    return { format };
  }

  const isRequired = (!isInput ||
                      format === kKeyFormatDER) &&
                      format !== kKeyFormatJWK;
  const type = parseKeyType(typeStr,
                            isRequired,
                            keyType,
                            isPublic,
                            objName);
  return { format, type };
}

function isStringOrBuffer(val) {
  return typeof val === 'string' ||
         isArrayBufferView(val) ||
         isAnyArrayBuffer(val);
}

function encodeKeyString(value, encoding) {
  return Buffer.from(value, encoding === 'buffer' ? 'utf8' : encoding);
}

function parseKeyEncoding(enc, keyType, isPublic, objName) {
  validateObject(enc, 'options');

  const isInput = keyType === undefined;

  const {
    format,
    type,
  } = parseKeyFormatAndType(enc, keyType, isPublic, objName);

  let cipher, passphrase, encoding;
  if (isPublic !== true) {
    ({ cipher, passphrase, encoding } = enc);

    if (format === kKeyFormatRawPrivate || format === kKeyFormatRawSeed) {
      if (cipher != null || passphrase !== undefined) {
        throw new ERR_CRYPTO_INCOMPATIBLE_KEY_OPTIONS(
          'raw format', 'does not support encryption');
      }
      return { format, type };
    }

    if (!isInput) {
      if (cipher != null) {
        if (typeof cipher !== 'string')
          throw new ERR_INVALID_ARG_VALUE(option('cipher', objName), cipher);
        if (format === kKeyFormatDER &&
            (type === kKeyEncodingPKCS1 ||
             type === kKeyEncodingSEC1)) {
          throw new ERR_CRYPTO_INCOMPATIBLE_KEY_OPTIONS(
            encodingNames[type], 'does not support encryption');
        }
      } else if (passphrase !== undefined) {
        throw new ERR_INVALID_ARG_VALUE(
          option('cipher', objName), cipher,
          'is required when a passphrase is specified');
      }
    }

    if ((isInput && passphrase !== undefined &&
         !isStringOrBuffer(passphrase)) ||
        (!isInput && cipher != null && !isStringOrBuffer(passphrase))) {
      throw new ERR_INVALID_ARG_VALUE(option('passphrase', objName),
                                      passphrase);
    }
  }

  if (typeof passphrase === 'string')
    passphrase = encodeKeyString(passphrase, encoding);

  return { format, type, cipher, passphrase };
}

// Parses the public key encoding based on an object. keyType must be undefined
// when this is used to parse an input encoding and must be a valid key type if
// used to parse an output encoding.
function parsePublicKeyEncoding(enc, keyType, objName) {
  return parseKeyEncoding(enc, keyType, keyType ? true : undefined, objName);
}

// Parses the private key encoding based on an object. keyType must be undefined
// when this is used to parse an input encoding and must be a valid key type if
// used to parse an output encoding.
function parsePrivateKeyEncoding(enc, keyType, objName) {
  return parseKeyEncoding(enc, keyType, false, objName);
}

function validateAsymmetricKeyType(type, ctx, key) {
  if (ctx === kCreatePrivate) {
    throw new ERR_INVALID_ARG_TYPE(
      'key',
      getKeyTypes({ allowKeyObject: false, allowURL: true }),
      key,
    );
  }

  if (type !== kKeyTypePrivate) {
    if (ctx === kConsumePrivate || ctx === kCreatePublic)
      throw new ERR_CRYPTO_INVALID_KEY_OBJECT_TYPE(keyObjectTypeToString(type), 'private');
    if (type !== kKeyTypePublic) {
      throw new ERR_CRYPTO_INVALID_KEY_OBJECT_TYPE(keyObjectTypeToString(type),
                                                   'private or public');
    }
  }
}

const kKeyTypesBufferOnly = [
  'ArrayBuffer',
  'Buffer',
  'TypedArray',
  'DataView',
];

function getKeyTypes({ allowKeyObject, allowURL = false }) {
  return [
    ...kKeyTypesBufferOnly,
    'string',
    ...(allowKeyObject ? ['KeyObject', 'CryptoKey'] : []),
    ...(allowURL ? ['URL'] : []),
  ];
}

function prepareStorePrivateKey(url, name, passphrase, encoding, properties) {
  // Read the canonical serialization from private URL state. Public accessors
  // can be overridden by subclasses or through prototype mutation.
  let uri = getURLHref(url);
  if (StringPrototypeStartsWith(uri, 'file:'))
    uri = fileURLToPath(uri);

  validateString(uri, name);
  // The URI is handed to OpenSSL as a NUL-terminated C string. Reject embedded
  // NUL bytes, which `fileURLToPath()` happily decodes from `%00`, rather than
  // letting the URI be silently truncated.
  if (StringPrototypeIncludes(uri, '\u0000')) {
    throw new ERR_INVALID_ARG_VALUE(
      name, url, 'must be a URL without null bytes');
  }

  if (passphrase !== undefined) {
    if (!isStringOrBuffer(passphrase)) {
      throw new ERR_INVALID_ARG_VALUE(option('passphrase', name), passphrase);
    }
    if (typeof passphrase === 'string') {
      passphrase = encodeKeyString(passphrase, encoding);
    }
  }

  if (properties !== undefined) {
    validateString(properties, option('properties', name));
    // Reaches OpenSSL as a NUL-terminated C string, same as the URI above.
    if (StringPrototypeIncludes(properties, '\u0000')) {
      throw new ERR_INVALID_ARG_VALUE(
        option('properties', name),
        properties,
        'must be a string without null bytes');
    }
  }

  return {
    data: {
      uri,
      properties: properties ?? null,
    },
    format: kKeyFormatStore,
    passphrase: passphrase ?? null,
  };
}

function prepareAsymmetricKey(key, ctx, name = 'key') {
  if (typeof key === 'string') {
    return { format: kKeyFormatPEM, data: encodeKeyString(key) };
  }
  if (isArrayBufferView(key)) {
    return { format: kKeyFormatPEM, data: key };
  }
  const isPrivateKeyInput = ctx === kConsumePrivate || ctx === kCreatePrivate;

  if (isKeyObject(key)) {
    // Best case: A key object, as simple as that.
    const slots = getKeyObjectSlots(key);
    validateAsymmetricKeyType(slots[kKeyObjectSlotType], ctx, key);
    return { data: slots[kKeyObjectSlotHandle] };
  }
  if (isCryptoKey(key)) {
    emitDEP0203();
    const slots = getSlots(key);
    validateAsymmetricKeyType(slots[kSlotType], ctx, key);
    return { data: slots[kSlotHandle] };
  }
  if (isPrivateKeyInput && isURLInstance(key)) {
    // A private key referenced by a URI for an OpenSSL STORE loader.
    return prepareStorePrivateKey(key, name);
  }
  if (isAnyArrayBuffer(key)) {
    return { format: kKeyFormatPEM, data: key };
  }
  if (typeof key === 'object') {
    return prepareAsymmetricKeyOptions(key, ctx, name, isPrivateKeyInput);
  }

  throw new ERR_INVALID_ARG_TYPE(
    name,
    getKeyTypes({
      allowKeyObject: ctx !== kCreatePrivate,
      allowURL: isPrivateKeyInput,
    }),
    key);
}

function prepareAsymmetricKeyOptions(key, ctx, name, isPrivateKeyInput) {
  const { key: data, encoding, format, properties } = key;
  let isData = typeof data === 'string' || isArrayBufferView(data);

  // The 'key' property can be a KeyObject as well to allow specifying
  // additional options such as padding along with the key.
  if (!isData && isKeyObject(data)) {
    const slots = getKeyObjectSlots(data);
    validateAsymmetricKeyType(slots[kKeyObjectSlotType], ctx, data);
    return { data: slots[kKeyObjectSlotHandle] };
  }
  if (!isData && isCryptoKey(data)) {
    emitDEP0203();
    const slots = getSlots(data);
    validateAsymmetricKeyType(slots[kSlotType], ctx, data);
    return { data: slots[kSlotHandle] };
  }
  isData ||= isAnyArrayBuffer(data);
  if (!isData && isPrivateKeyInput && isURLInstance(data)) {
    // A private key referenced by a URI for an OpenSSL STORE loader, with
    // an optional passphrase/PIN.
    return prepareStorePrivateKey(
      data,
      name,
      key.passphrase,
      encoding,
      properties);
  }
  if (format === 'jwk') {
    validateObject(data, `${name}.key`);
    return { data, format: kKeyFormatJWK };
  }
  if (format === 'raw-public' || format === 'raw-private' ||
               format === 'raw-seed') {
    if (isPrivateKeyInput && format === 'raw-public') {
      throw new ERR_INVALID_ARG_VALUE(`${name}.format`, format);
    }
    if (!isData || typeof data === 'string') {
      throw new ERR_INVALID_ARG_TYPE(
        `${name}.key`,
        ['ArrayBuffer', 'Buffer', 'TypedArray', 'DataView'],
        data);
    }
    validateString(key.asymmetricKeyType, `${name}.asymmetricKeyType`);
    if (key.asymmetricKeyType === 'ec') {
      validateString(key.namedCurve, `${name}.namedCurve`);
    }
    const rawFormat = format === 'raw-public' ? kKeyFormatRawPublic :
      format === 'raw-private' ? kKeyFormatRawPrivate : kKeyFormatRawSeed;
    return {
      data,
      format: rawFormat,
      type: key.asymmetricKeyType,
      namedCurve: key.namedCurve ?? null,
    };
  }

  // Either PEM or DER using PKCS#1 or SPKI.
  if (!isData) {
    throw new ERR_INVALID_ARG_TYPE(
      `${name}.key`,
      getKeyTypes({
        allowKeyObject: ctx !== kCreatePrivate,
        allowURL: isPrivateKeyInput,
      }),
      data);
  }

  const isPublic = isPrivateKeyInput ? false : undefined;
  const keyData = typeof data === 'string' ?
    encodeKeyString(data, encoding) : data;
  const parsed = parseKeyEncoding(key, undefined, isPublic, name);
  return {
    data: keyData,
    format: parsed.format,
    type: parsed.type,
    cipher: parsed.cipher,
    passphrase: parsed.passphrase,
  };
}

function preparePrivateKey(key, name) {
  return prepareAsymmetricKey(key, kConsumePrivate, name);
}

function preparePublicOrPrivateKey(key, name) {
  return prepareAsymmetricKey(key, kConsumePublic, name);
}

function prepareSecretKey(key, encoding, bufferOnly = false) {
  if (!bufferOnly) {
    if (isKeyObject(key)) {
      const type = getKeyObjectType(key);
      if (type !== 'secret')
        throw new ERR_CRYPTO_INVALID_KEY_OBJECT_TYPE(type, 'secret');
      return getKeyObjectHandle(key);
    }
    if (isCryptoKey(key)) {
      emitDEP0203();
      const type = getCryptoKeyType(key);
      if (type !== 'secret')
        throw new ERR_CRYPTO_INVALID_KEY_OBJECT_TYPE(type, 'secret');
      return getCryptoKeyHandle(key);
    }
  }
  if (typeof key !== 'string' &&
      !isArrayBufferView(key) &&
      !isAnyArrayBuffer(key)) {
    throw new ERR_INVALID_ARG_TYPE(
      'key',
      bufferOnly ? kKeyTypesBufferOnly : getKeyTypes({ allowKeyObject: true }),
      key);
  }
  return getArrayBufferOrView(key, 'key', encoding);
}

function createSecretKey(key, encoding) {
  key = prepareSecretKey(key, encoding, true);
  const handle = new KeyObjectHandle();
  handle.init(kKeyTypeSecret, key);
  return new SecretKeyObject(handle);
}

function createPublicKey(key) {
  const { format, type, data, passphrase, namedCurve } =
    prepareAsymmetricKey(key, kCreatePublic);
  const handle = new KeyObjectHandle();
  handle.init(kKeyTypePublic, data, format ?? null,
              type ?? null, passphrase ?? null, namedCurve ?? null);
  return new PublicKeyObject(handle);
}

/**
 * Parses a PKCS#12 (.p12 / .pfx) bundle. Returns an object holding the first
 * private key as `privateKey`, the certificate associated with it as
 * `certificate`, and every other certificate in the bundle as an array in
 * `additionalCertificates`. `privateKey` and `certificate` are null when the
 * bundle contains none.
 * @param {ArrayBuffer|Buffer|TypedArray|DataView} bundle
 * @param {object} [options]
 * @returns {object}
 */
function parsePKCS12(bundle, options = kEmptyObject) {
  if (!isArrayBufferView(bundle) && !isAnyArrayBuffer(bundle)) {
    throw new ERR_INVALID_ARG_TYPE(
      'bundle',
      ['ArrayBuffer', 'TypedArray', 'DataView', 'Buffer'],
      bundle);
  }

  validateObject(options, 'options');
  const { passphrase } = options;

  // `undefined` means no passphrase, '' a zero-length one. OpenSSL accepts
  // either PKCS#12 password encoding for both, so they behave the same.
  let passBuf;
  if (passphrase !== undefined) {
    passBuf = getArrayBufferOrView(passphrase, 'options.passphrase', 'utf8');
    // OpenSSL takes the passphrase as a NUL-terminated C string, so one
    // containing a NUL byte would be truncated there and the bundle opened
    // with only the bytes before it. A PKCS#12 password cannot represent an
    // embedded NUL anyway, so reject it outright.
    if (TypedArrayPrototypeIncludes(getBufferSourceBytes(passBuf), 0)) {
      throw new ERR_INVALID_ARG_VALUE(
        'options.passphrase', passphrase, 'must not contain null bytes');
    }
    // The binding reads the passphrase as a view; wrap a bare ArrayBuffer.
    if (isAnyArrayBuffer(passBuf)) passBuf = Buffer.from(passBuf);
  }

  // Likewise, the binding reads the bundle as a view.
  const bundleBuf = isAnyArrayBuffer(bundle) ? Buffer.from(bundle) : bundle;

  const {
    0: keyHandle,
    1: certHandle,
    2: otherHandles,
  } = _parsePKCS12(bundleBuf, passBuf);

  // Required lazily: internal/crypto/x509 depends on this module.
  const { InternalX509Certificate } = require('internal/crypto/x509');

  return {
    privateKey: keyHandle === null ? null : new PrivateKeyObject(keyHandle),
    certificate:
      certHandle === null ? null : new InternalX509Certificate(certHandle),
    additionalCertificates:
      ArrayPrototypeMap(otherHandles, (h) => new InternalX509Certificate(h)),
  };
}

/**
 * Converts a secret KeyObjectHandle to a CryptoKey by dispatching to the
 * algorithm-specific Web Crypto import path.
 * @param {KeyObjectHandle} keyData
 * @param {object} algorithm
 * @param {boolean} extractable
 * @param {string[]} keyUsages
 * @returns {CryptoKey}
 */
function toCryptoKeySecret(
  keyData,
  algorithm,
  extractable,
  keyUsages,
) {
  let result;
  switch (algorithm.name) {
    case 'HMAC':
      // Fall through
    case 'KMAC128':
      // Fall through
    case 'KMAC256':
      result = require('internal/crypto/mac')
        .macImportKey('KeyObjectHandle', keyData, algorithm, extractable, keyUsages);
      break;
    case 'AES-CTR':
      // Fall through
    case 'AES-CBC':
      // Fall through
    case 'AES-GCM':
      // Fall through
    case 'AES-KW':
      // Fall through
    case 'AES-OCB':
      result = require('internal/crypto/aes')
        .aesImportKey(algorithm, 'KeyObjectHandle', keyData, extractable, keyUsages);
      break;
    case 'ChaCha20-Poly1305':
      result = require('internal/crypto/chacha20_poly1305')
        .c20pImportKey(algorithm, 'KeyObjectHandle', keyData, extractable, keyUsages);
      break;
    case 'HKDF':
      // Fall through
    case 'PBKDF2':
      // Fall through
    case 'Argon2d':
      // Fall through
    case 'Argon2i':
      // Fall through
    case 'Argon2id':
      result = importGenericSecretKey(
        algorithm,
        'KeyObjectHandle',
        keyData,
        extractable,
        keyUsages);
      break;
    default:
      throw lazyDOMException('Unrecognized algorithm name', 'NotSupportedError');
  }

  if (getCryptoKeyUsagesMask(result) === 0) {
    throw lazyDOMException(
      `Usages cannot be empty when importing a ${getCryptoKeyType(result)} key.`,
      'SyntaxError');
  }

  return result;
}

/**
 * Converts an asymmetric KeyObjectHandle to a CryptoKey by dispatching to
 * the algorithm-specific Web Crypto import path. This preserves the same
 * algorithm and usage validation used by SubtleCrypto.importKey().
 * @param {KeyObjectHandle} keyData
 * @param {object} algorithm
 * @param {boolean} extractable
 * @param {string[]} keyUsages
 * @returns {CryptoKey}
 */
function toCryptoKey(
  keyData,
  algorithm,
  extractable,
  keyUsages,
) {
  let result;
  switch (algorithm.name) {
    case 'RSASSA-PKCS1-v1_5':
      // Fall through
    case 'RSA-PSS':
      // Fall through
    case 'RSA-OAEP':
      result = require('internal/crypto/rsa')
        .rsaImportKey('KeyObjectHandle', keyData, algorithm, extractable, keyUsages);
      break;
    case 'ECDSA':
      // Fall through
    case 'ECDH':
      result = require('internal/crypto/ec')
        .ecImportKey('KeyObjectHandle', keyData, algorithm, extractable, keyUsages);
      break;
    case 'Ed25519':
      // Fall through
    case 'Ed448':
      // Fall through
    case 'X25519':
      // Fall through
    case 'X448':
      result = require('internal/crypto/cfrg')
        .cfrgImportKey('KeyObjectHandle', keyData, algorithm, extractable, keyUsages);
      break;
    case 'ML-DSA-44':
      // Fall through
    case 'ML-DSA-65':
      // Fall through
    case 'ML-DSA-87':
      result = require('internal/crypto/ml_dsa')
        .mlDsaImportKey('KeyObjectHandle', keyData, algorithm, extractable, keyUsages);
      break;
    case 'ML-KEM-512':
      // Fall through
    case 'ML-KEM-768':
      // Fall through
    case 'ML-KEM-1024':
      result = require('internal/crypto/ml_kem')
        .mlKemImportKey('KeyObjectHandle', keyData, algorithm, extractable, keyUsages);
      break;
    default:
      throw lazyDOMException('Unrecognized algorithm name', 'NotSupportedError');
  }

  const resultType = getCryptoKeyType(result);
  if (resultType === 'private' && getCryptoKeyUsagesMask(result) === 0) {
    throw lazyDOMException(
      `Usages cannot be empty when importing a ${resultType} key.`,
      'SyntaxError');
  }

  return result;
}

/**
 * Derives a public CryptoKey from a private CryptoKey. The resulting key uses
 * the private key's algorithm, is extractable, and validates the requested
 * public usages through the shared asymmetric import path.
 * @param {CryptoKey} key
 * @param {string[]} keyUsages
 * @returns {CryptoKey}
 */
function toPublicCryptoKey(key, keyUsages) {
  const handle = new KeyObjectHandle();
  handle.init(kKeyTypePublic, getCryptoKeyHandle(key),
              null, null, null, null);
  return toCryptoKey(
    handle,
    getCryptoKeyAlgorithm(key),
    true,
    keyUsages);
}

function createPrivateKey(key) {
  const { format, type, data, passphrase, namedCurve } =
    prepareAsymmetricKey(key, kCreatePrivate);
  const handle = new KeyObjectHandle();
  handle.init(kKeyTypePrivate, data, format ?? null,
              type ?? null, passphrase ?? null, namedCurve ?? null);
  return new PrivateKeyObject(handle);
}

function keyObjectTypeToString(type) {
  switch (type) {
    case kKeyTypeSecret: return 'secret';
    case kKeyTypePublic: return 'public';
    case kKeyTypePrivate: return 'private';
    default: {
      const assert = require('internal/assert');
      assert.fail('Unreachable code');
    }
  }
}

// The helpers below return a KeyObject's native-backed slot values,
// populating the per-instance cache on first access via a single native
// call. The public getters delegate to these helpers, and internal
// consumers use them directly to avoid user-replaceable public accessors.
// Derived metadata such as key size and asymmetric key details is expanded
// lazily from the cached KeyObjectHandle. The public asymmetric key details
// getter returns a clone so the cached details object stays internal.

/**
 * Returns the KeyObject's native type slot as a string.
 * @param {KeyObject} key
 * @returns {'secret' | 'public' | 'private'}
 */
function getKeyObjectType(key) {
  return keyObjectTypeToString(getKeyObjectTypeValue(key));
}

/**
 * Returns the KeyObjectHandle wrapping the KeyObject's underlying key
 * material.
 * @param {KeyObject} key
 * @returns {KeyObjectHandle}
 */
function getKeyObjectHandle(key) {
  return getKeyObjectSlots(key)[kKeyObjectSlotHandle];
}

/**
 * Returns the KeyObject's symmetric key size, bypassing the public
 * `symmetricKeySize` getter. The value is derived lazily from the cached
 * KeyObjectHandle.
 * @param {SecretKeyObject} key
 * @returns {number}
 */
function getKeyObjectSymmetricKeySize(key) {
  const slots = getKeyObjectSlots(key);
  if (slots[kKeyObjectSlotType] !== kKeyTypeSecret)
    throw new ERR_INVALID_THIS('SecretKeyObject');

  let cached = slots[kKeyObjectSlotSymmetricKeySize];
  if (cached === undefined) {
    cached = slots[kKeyObjectSlotHandle].getSymmetricKeySize();
    slots[kKeyObjectSlotSymmetricKeySize] = cached;
  }
  return cached;
}

/**
 * Returns the KeyObject's asymmetric key type, bypassing the public
 * `asymmetricKeyType` getter. The value is derived lazily from the cached
 * KeyObjectHandle.
 * @param {PublicKeyObject|PrivateKeyObject} key
 * @returns {string}
 */
function getKeyObjectAsymmetricKeyType(key) {
  const slots = getKeyObjectSlots(key);
  if (slots[kKeyObjectSlotType] === kKeyTypeSecret)
    throw new ERR_INVALID_THIS('AsymmetricKeyObject');

  let cached = slots[kKeyObjectSlotAsymmetricKeyType];
  if (cached === undefined) {
    cached = slots[kKeyObjectSlotHandle].getAsymmetricKeyType();
    slots[kKeyObjectSlotAsymmetricKeyType] = cached;
  }
  return cached;
}

/**
 * Returns the KeyObject's cached asymmetric key details, bypassing the
 * public `asymmetricKeyDetails` getter (which returns a cloned copy).
 * The value is derived lazily from the cached KeyObjectHandle.
 * @param {PublicKeyObject|PrivateKeyObject} key
 * @returns {object}
 */
function getKeyObjectAsymmetricKeyDetails(key) {
  const slots = getKeyObjectSlots(key);
  if (slots[kKeyObjectSlotType] === kKeyTypeSecret)
    throw new ERR_INVALID_THIS('AsymmetricKeyObject');

  let cached = slots[kKeyObjectSlotAsymmetricKeyDetails];
  if (cached === undefined) {
    let asymmetricKeyType = slots[kKeyObjectSlotAsymmetricKeyType];
    if (asymmetricKeyType === undefined) {
      asymmetricKeyType = slots[kKeyObjectSlotHandle].getAsymmetricKeyType();
      slots[kKeyObjectSlotAsymmetricKeyType] = asymmetricKeyType;
    }
    switch (asymmetricKeyType) {
      case 'rsa':
      case 'rsa-pss':
      case 'dsa':
      case 'ec':
        cached = normalizeKeyDetails(
          slots[kKeyObjectSlotHandle].keyDetail({ __proto__: null }),
        );
        break;
      default:
        cached = kEmptyObject;
        break;
    }
    slots[kKeyObjectSlotAsymmetricKeyDetails] = cached;
  }
  return cached;
}

// CryptoKey is a plain JS class whose prototype's [[Prototype]] is
// Object.prototype, as Web Crypto requires. Instance storage (type enum,
// extractable, algorithm, usages mask, the primary KeyObject handle, an
// optional Hybrid KEM-only secondary KeyObject handle, and optional Hybrid
// KEM-only seed data) lives
// on a C++ class, NativeCryptoKey, created by createCryptoKeyClass.
// InternalCryptoKey is the only constructor we expose to internal
// code; it extends NativeCryptoKey to get that storage and gives each
// instance the public interface prototype:
//   instance -> CryptoKey.prototype
//            -> Object.prototype
//
// Normal construction caches all native internal slots in a private class
// field on `InternalCryptoKey`. Partially initialized transferred keys read
// them from C++ in a single `getCryptoKeySlots` call on first access. The
// cache is invisible to reflection (`Object.getOwnPropertySymbols` etc.) and
// CryptoKey's hidden class pristine. The `getCryptoKey{Type,Extractable,
// Algorithm,Usages,Handle,SecondaryHandle,SeedData}` helpers index into that
// array and convert native enums/masks back to Web Crypto strings.
// The internal algorithm object is stored as a null-prototype clone
// so it cannot observe polluted Object.prototype properties.
// The public `algorithm` getter caches a cloned dictionary and the
// public `usages` getter caches a synthesized array (as Web Crypto
// requires repeat reads to return the same object so a consumer's
// mutation is visible next time).
let getSlots; // Populated by the createCryptoKeyClass callback below.
let isCryptoKey;

const kSlotType = 0;
const kSlotExtractable = 1;
const kSlotAlgorithm = 2;
const kSlotUsagesMask = 3;
const kSlotHandle = 4;
const kSlotSecondaryHandle = 5;
const kSlotSeedData = 6;
const kSlotClonedAlgorithm = 7;
const kSlotClonedUsages = 8;
const kSlotUsages = 9;

function cloneAlgorithm(raw) {
  const cloned = { ...raw };
  if (ObjectPrototypeHasOwnProperty(cloned, 'hash') &&
      cloned.hash !== undefined) {
    cloned.hash = { ...cloned.hash };
  }
  if (ObjectPrototypeHasOwnProperty(cloned, 'publicExponent') &&
      cloned.publicExponent !== undefined) {
    cloned.publicExponent = new Uint8Array(cloned.publicExponent);
  }
  return cloned;
}

function cloneInternalAlgorithm(raw) {
  const cloned = { __proto__: null, ...raw };
  if (ObjectPrototypeHasOwnProperty(cloned, 'hash') &&
      cloned.hash !== undefined) {
    cloned.hash = { __proto__: null, ...cloned.hash };
  }
  if (ObjectPrototypeHasOwnProperty(cloned, 'publicExponent') &&
      cloned.publicExponent !== undefined) {
    cloned.publicExponent = new Uint8Array(cloned.publicExponent);
  }
  return cloned;
}

const {
  0: CryptoKey,
  1: InternalCryptoKey,
} = createCryptoKeyClass((NativeCryptoKey) => {
  class CryptoKey {
    constructor() {
      throw new ERR_ILLEGAL_CONSTRUCTOR();
    }

    [kInspect](depth, options) {
      if (depth < 0)
        return this;

      if (!isCryptoKey(this))
        throw new ERR_INVALID_THIS('CryptoKey');

      const opts = {
        ...options,
        depth: options.depth == null ? null : options.depth - 1,
      };

      return `CryptoKey ${inspect({
        type: getCryptoKeyType(this),
        extractable: getCryptoKeyExtractable(this),
        algorithm: cloneAlgorithm(getCryptoKeyAlgorithm(this)),
        usages: getUsagesFromMask(getCryptoKeyUsagesMask(this)),
      }, opts)}`;
    }

    get type() {
      if (!isCryptoKey(this))
        throw new ERR_INVALID_THIS('CryptoKey');
      return getCryptoKeyType(this);
    }

    get extractable() {
      if (!isCryptoKey(this))
        throw new ERR_INVALID_THIS('CryptoKey');
      return getCryptoKeyExtractable(this);
    }

    get algorithm() {
      if (!isCryptoKey(this))
        throw new ERR_INVALID_THIS('CryptoKey');
      const slots = getSlots(this);
      let cached = slots[kSlotClonedAlgorithm];
      if (cached === undefined) {
        cached = cloneAlgorithm(slots[kSlotAlgorithm]);
        slots[kSlotClonedAlgorithm] = cached;
      }
      return cached;
    }

    get usages() {
      if (!isCryptoKey(this))
        throw new ERR_INVALID_THIS('CryptoKey');
      const slots = getSlots(this);
      let cached = slots[kSlotClonedUsages];
      if (cached === undefined) {
        cached = getUsagesFromMask(slots[kSlotUsagesMask]);
        slots[kSlotClonedUsages] = cached;
      }
      return cached;
    }
  }

  class InternalCryptoKey extends NativeCryptoKey {
    #slots;

    constructor(
      handle,
      algorithm,
      usagesMask,
      extractable,
      secondaryHandle,
      seedData) {
      if (algorithm !== undefined)
        algorithm = cloneInternalAlgorithm(algorithm);
      if (seedData !== undefined)
        seedData = new Uint8Array(seedData);
      super(
        handle,
        algorithm,
        usagesMask,
        extractable,
        secondaryHandle,
        seedData);
      ObjectSetPrototypeOf(this, CryptoKey.prototype);
      if (algorithm !== undefined) {
        this.#slots = [
          handle.getKeyType(),
          extractable,
          algorithm,
          usagesMask,
          handle,
          secondaryHandle,
          seedData,
        ];
      }
    }

    static {
      isCryptoKey = (key) => {
        if (key == null || typeof key !== 'object') return false;
        return #slots in key || isNativeCryptoKey(key);
      };
      getSlots = (key) => {
        const cached = key.#slots;
        if (cached !== undefined) return cached;
        const slots = nativeGetCryptoKeySlots(key);
        slots[kSlotAlgorithm] = cloneInternalAlgorithm(slots[kSlotAlgorithm]);
        if (slots[kSlotSeedData] !== undefined)
          slots[kSlotSeedData] = new Uint8Array(slots[kSlotSeedData]);
        key.#slots = slots;
        return slots;
      };
    }
  }
  // Hide NativeCryptoKey from user code.
  InternalCryptoKey.prototype.constructor = CryptoKey;
  ObjectSetPrototypeOf(InternalCryptoKey.prototype, CryptoKey.prototype);

  ObjectDefineProperties(CryptoKey.prototype, {
    type: kEnumerableProperty,
    extractable: kEnumerableProperty,
    algorithm: kEnumerableProperty,
    usages: kEnumerableProperty,
    [SymbolToStringTag]: {
      __proto__: null,
      configurable: true,
      value: 'CryptoKey',
    },
  });

  return [CryptoKey, InternalCryptoKey];
});

// The helpers below return a CryptoKey's internal slot value. The public
// `type` getter converts the native enum to the Web Crypto string. The
// `usages` helper converts the native usage mask to Web Crypto strings. The
// public `algorithm` / `usages` getters cache their returned objects.

/**
 * Returns the value of a CryptoKey's `[[type]]` internal slot.
 * @param {CryptoKey} key
 * @returns {'secret' | 'public' | 'private'}
 */
function getCryptoKeyType(key) {
  switch (getSlots(key)[kSlotType]) {
    case kKeyTypeSecret: return 'secret';
    case kKeyTypePublic: return 'public';
    case kKeyTypePrivate: return 'private';
    default: {
      const assert = require('internal/assert');
      assert.fail('Unreachable code');
    }
  }
}

/**
 * Returns the value of a CryptoKey's `[[extractable]]` internal slot.
 * @param {CryptoKey} key
 * @returns {boolean}
 */
function getCryptoKeyExtractable(key) {
  return getSlots(key)[kSlotExtractable];
}

/**
 * Returns the CryptoKey's `[[algorithm]]` internal slot, bypassing the
 * public `algorithm` getter (which returns a cloned copy).
 * @param {CryptoKey} key
 * @returns {object}
 */
function getCryptoKeyAlgorithm(key) {
  return getSlots(key)[kSlotAlgorithm];
}

/**
 * Returns the CryptoKey's native `[[usages]]` mask.
 * @param {CryptoKey} key
 * @returns {number}
 */
function getCryptoKeyUsagesMask(key) {
  return getSlots(key)[kSlotUsagesMask];
}

/**
 * Returns whether a CryptoKey's `[[usages]]` contains `usage`.
 * @param {CryptoKey} key
 * @param {string} usage
 * @returns {boolean}
 */
function hasCryptoKeyUsage(key, usage) {
  return hasUsage(getCryptoKeyUsagesMask(key), usage);
}

/**
 * Returns the CryptoKey's cached canonical usages array for internal
 * consumers, expanding it from the native usage mask on first access.
 * @param {Array} slots
 * @returns {string[]}
 */
function getCryptoKeyUsagesFromSlots(slots) {
  let usages = slots[kSlotUsages];
  if (usages === undefined) {
    usages = getUsagesFromMask(slots[kSlotUsagesMask]);
    slots[kSlotUsages] = usages;
  }
  return usages;
}

/**
 * Returns the CryptoKey's `[[usages]]` internal slot, bypassing the
 * public `usages` getter (which returns a cloned array). The internal
 * array is expanded lazily from the native usage mask.
 * @param {CryptoKey} key
 * @returns {string[]}
 */
function getCryptoKeyUsages(key) {
  return getCryptoKeyUsagesFromSlots(getSlots(key));
}

/**
 * Returns the KeyObjectHandle wrapping the CryptoKey's underlying
 * key material.
 * @param {CryptoKey} key
 * @returns {KeyObjectHandle}
 */
function getCryptoKeyHandle(key) {
  return getSlots(key)[kSlotHandle];
}

/**
 * Returns the optional Hybrid KEM-only secondary KeyObjectHandle wrapping a
 * CryptoKey's other underlying key material.
 * @param {CryptoKey} key
 * @returns {KeyObjectHandle | undefined}
 */
function getCryptoKeySecondaryHandle(key) {
  return getSlots(key)[kSlotSecondaryHandle];
}

/**
 * Returns the optional Hybrid KEM-only seed data stored with a CryptoKey.
 * @param {CryptoKey} key
 * @returns {Uint8Array | undefined}
 */
function getCryptoKeySeedData(key) {
  return getSlots(key)[kSlotSeedData];
}

function importGenericSecretKey(
  algorithm,
  format,
  keyData,
  extractable,
  keyUsages,
) {
  const usagesSet = toUsagesSet(keyUsages);
  const { name } = algorithm;
  if (extractable)
    throw lazyDOMException(`${name} keys are not extractable`, 'SyntaxError');

  if (hasAnyNotIn(usagesSet, ['deriveKey', 'deriveBits'])) {
    throw lazyDOMException(
      `Unsupported key usage for a ${name} key`,
      'SyntaxError');
  }

  let handle;
  switch (format) {
    case 'KeyObjectHandle': {
      handle = keyData;
      break;
    }
    case 'raw-secret':
    case 'raw': {
      handle = new KeyObjectHandle();
      handle.init(kKeyTypeSecret, keyData);
      break;
    }
    default:
      return undefined;
  }

  return new InternalCryptoKey(
    handle,
    { name },
    getUsagesMask(usagesSet),
    false);
}

module.exports = {
  // Public API.
  createSecretKey,
  createPublicKey,
  createPrivateKey,
  parsePKCS12,
  KeyObject,
  CryptoKey,
  InternalCryptoKey,

  // These are designed for internal use only and should not be exposed.
  parsePublicKeyEncoding,
  parsePrivateKeyEncoding,
  parseKeyEncoding,
  toPublicCryptoKey,
  prepareAsymmetricKey,
  kConsumePublic,
  kConsumePrivate,
  kCreatePublic,
  kCreatePrivate,
  preparePrivateKey,
  preparePublicOrPrivateKey,
  prepareSecretKey,
  SecretKeyObject,
  PublicKeyObject,
  PrivateKeyObject,
  isKeyObject,
  getKeyObjectType,
  getKeyObjectHandle,
  getKeyObjectSymmetricKeySize,
  getKeyObjectAsymmetricKeyType,
  getKeyObjectAsymmetricKeyDetails,
  isCryptoKey,
  getCryptoKeyType,
  getCryptoKeyExtractable,
  getCryptoKeyAlgorithm,
  getCryptoKeyUsages,
  getCryptoKeyUsagesMask,
  hasCryptoKeyUsage,
