function validateKmacKeyLength(length) {
  if (length < 32 || length % 8 !== 0)
    throw lazyDOMException('Invalid key length', 'NotSupportedError');
}

/**
 * Converts a bit length to the number of bytes needed to contain it.
 * Non-byte lengths are rounded up to the next byte.
 * @param {number} length
 * @returns {number}
 */
function numBitsToBytes(length) {
  return MathFloor(length / 8) + MathFloor((7 + (length % 8)) / 8);
}

/**
 * Copies `bytes` up to the byte length needed for `length` bits, then clears
 * unused least-significant bits in the final byte.
 * @param {number} length
 * @param {ArrayBuffer|ArrayBufferView} bytes
 * @returns {Uint8Array}
 */
function truncateToBitLength(length, bytes) {
  const lengthBytes = numBitsToBytes(length);
  const isView = ArrayBufferIsView(bytes);
  const byteView = isView ?
    new Uint8Array(
      getDataViewOrTypedArrayBuffer(bytes),
      getDataViewOrTypedArrayByteOffset(bytes),
      MathMin(lengthBytes, getDataViewOrTypedArrayByteLength(bytes)),
    ) :
    new Uint8Array(bytes, 0,
                   MathMin(lengthBytes, ArrayBufferPrototypeGetByteLength(bytes)));
  const result = new Uint8Array(byteView);

  const remainder = length % 8;
  if (remainder !== 0)
    result[lengthBytes - 1] &= (0xff << (8 - remainder)) & 0xff;

  return result;
}

let webidl;

// Keep this as a regular object. The WebIDL converters read and spread these
// options on the normalizeAlgorithm hot path, and a null-prototype object
// measurably regresses benchmark/misc/webcrypto-webidl normalizeAlgorithm-*.
const kNormalizeAlgorithmOpts = {
  prefix: 'Failed to normalize algorithm',
  context: 'passed algorithm',
};

// https://w3c.github.io/webcrypto/#algorithm-normalization-normalize-an-algorithm
// adapted for Node.js from Deno's implementation
// https://github.com/denoland/deno/blob/v1.29.1/ext/crypto/00_crypto.js#L195
function normalizeAlgorithm(algorithm, op) {
  if (typeof algorithm === 'string')
    return normalizeAlgorithm({ name: algorithm }, op);

  webidl ??= require('internal/crypto/webidl');

  // 2. 3.
  const initialAlg = webidl.converters.Algorithm(algorithm,
                                                 kNormalizeAlgorithmOpts);
  const { algorithms, nameMap } = getSupportedAlgorithms();
  const registeredAlgorithms = algorithms[op];
  // 4.
  let algName = initialAlg.name;

  // 5. Case-insensitive lookup via pre-built Map (O(1) instead of O(n)).
  const canonicalName = nameMap[op]?.get(
    StringPrototypeToUpperCase(algName));
  if (canonicalName === undefined)
    throw lazyDOMException('Unrecognized algorithm name', 'NotSupportedError');

  // Registered names are ASCII. Only check characters when case folding was
  // needed, so Unicode characters such as U+017F cannot match ASCII names.
  if (algName !== canonicalName) {
    for (let i = 0; i < algName.length; i++) {
      if (StringPrototypeCharCodeAt(algName, i) > 0x7f)
        throw lazyDOMException('Unrecognized algorithm name', 'NotSupportedError');
    }
  }

  algName = canonicalName;
  const desiredType = registeredAlgorithms[algName];

  // Fast path everything below if the registered dictionary is null
  if (desiredType === null)
    return { name: algName };

  // 6.
  const normalizedAlgorithm = webidl.algorithmConverters[desiredType](
    algorithm,
    kNormalizeAlgorithmOpts,
  );
  // 7.
  normalizedAlgorithm.name = algName;

  // 9. 10. Pre-computed keys and types from simpleAlgorithmDictionaries.
  const dictMeta = simpleAlgorithmDictionaries[desiredType];
  if (dictMeta) {
    const { keys: dictKeys, types: dictTypes } = dictMeta;
    for (let i = 0; i < dictKeys.length; i++) {
      const member = dictKeys[i];
      const idlType = dictTypes[member];
      const idlValue = normalizedAlgorithm[member];
      // 3.
      if (idlType === 'BufferSource' && idlValue) {
        normalizedAlgorithm[member] = new Uint8Array(
          getBufferSourceBytes(idlValue),
        );
      } else if (idlType === 'HashAlgorithmIdentifier') {
        const hash = normalizeAlgorithm(idlValue, 'digest');
        if (!StringPrototypeStartsWith(hash.name, 'SHA')) {
          throw lazyDOMException(
            `Only SHA hashes are supported in ${desiredType}`, 'NotSupportedError');
        }
        normalizedAlgorithm[member] = hash;
      } else if (idlType === 'AlgorithmIdentifier') {
        // This extension point is not used by any supported algorithm (yet?)
        throw lazyDOMException('Not implemented.', 'NotSupportedError');
      }
    }
  }

  return normalizedAlgorithm;
}

function validateAlgorithm(algorithm, op) {
  // HMAC's get key length operation handles zero with a TypeError, while
  // HmacImportParams otherwise uses the import operation's DataError.
  if (op === 'get key length' && algorithm.name === 'HMAC')
    return;
  webidl ??= require('internal/crypto/webidl');
  const desiredType = getSupportedAlgorithms().algorithms[op]?.[algorithm.name];
  webidl.validators[desiredType]?.(algorithm);
}

function getDataViewOrTypedArrayBuffer(V) {
  return isDataView(V) ?
    DataViewPrototypeGetBuffer(V) : TypedArrayPrototypeGetBuffer(V);
}

function getDataViewOrTypedArrayByteOffset(V) {
  return isDataView(V) ?
    DataViewPrototypeGetByteOffset(V) : TypedArrayPrototypeGetByteOffset(V);
}

function getDataViewOrTypedArrayByteLength(V) {
  return isDataView(V) ?
    DataViewPrototypeGetByteLength(V) : TypedArrayPrototypeGetByteLength(V);
}

function getBufferSourceByteLength(V) {
  // ArrayBuffer and typed array lengths already become zero when detached.
  if (!ArrayBufferIsView(V))
    return ArrayBufferPrototypeGetByteLength(V);
  if (!isDataView(V))
    return TypedArrayPrototypeGetByteLength(V);
  const buffer = DataViewPrototypeGetBuffer(V);
  if (isArrayBuffer(buffer) && ArrayBufferPrototypeGetDetached(buffer))
    return 0;
  return DataViewPrototypeGetByteLength(V);
}

function getBufferSourceBytes(V) {
  if (!ArrayBufferIsView(V)) {
    const length = ArrayBufferPrototypeGetByteLength(V);
    if (length === 0 && ArrayBufferPrototypeGetDetached(V))
      return new Uint8Array(0);
    return new Uint8Array(V, 0, length);
  }

  let buffer;
  let offset;
  let length;
  if (isDataView(V)) {
    buffer = DataViewPrototypeGetBuffer(V);
    if (isArrayBuffer(buffer) && ArrayBufferPrototypeGetDetached(buffer))
      return new Uint8Array(0);
    offset = DataViewPrototypeGetByteOffset(V);
    length = DataViewPrototypeGetByteLength(V);
  } else {
    buffer = TypedArrayPrototypeGetBuffer(V);
    offset = TypedArrayPrototypeGetByteOffset(V);
    length = TypedArrayPrototypeGetByteLength(V);
    if (length === 0 && isArrayBuffer(buffer) &&
        ArrayBufferPrototypeGetDetached(buffer))
      return new Uint8Array(0);
  }
  return new Uint8Array(buffer, offset, length);
}

function getOptionalByteLength(V) {
  return V === undefined ? 0 : TypedArrayPrototypeGetByteLength(V);
}

function hasAnyNotIn(set, checks) {
  for (const s of set)
    if (!ArrayPrototypeIncludes(checks, s))
      return true;
  return false;
}

const validateByteSource = hideStackFrames((val, name) => {
  val = toBuf(val);

  if (isAnyArrayBuffer(val) || isArrayBufferView(val))
    return val;

  throw new ERR_INVALID_ARG_TYPE.HideStackFramesError(
    name,
    [
      'string',
      'ArrayBuffer',
      'TypedArray',
      'DataView',
      'Buffer',
    ],
    val);
});

/**
 * @template T
 * @typedef {{ run(): Promise<T> }} WebCryptoJob
 */

/**
 * CryptoJob constructors can synchronously throw while running their native
 * AdditionalConfig hook. WebCrypto needs those operation-specific setup
 * failures to reject with an OperationError.
 * @template T
 * @param {() => WebCryptoJob<T>} getJob
 * @returns {Promise<T>}
 */
function jobPromise(getJob) {
  try {
    return getJob().run();
  } catch (err) {
    return PromiseReject(lazyDOMException(
      'The operation failed for an operation-specific reason',
      { name: 'OperationError', cause: err }));
  }
}

/**
 * Temporarily shadow inherited then accessors on WebCrypto result objects.
 * Promise resolution reads "then" synchronously for thenable assimilation.
 * Returning an own undefined data property keeps that lookup from reaching
 * user-mutated prototypes.
 * @param {unknown} value
 * @returns {boolean}
 */
function prepareWebCryptoResult(value) {
  if ((value === null || typeof value !== 'object') &&
      typeof value !== 'function') {
    return false;
  }
  if (isPromise(value) || ObjectPrototypeHasOwnProperty(value, 'then'))
    return false;
  setOwnProperty(value, 'then', undefined);
  return true;
}

/**
 * Remove the temporary then property installed by prepareWebCryptoResult().
 * @param {{ then?: unknown }} value
 * @returns {void}
 */
function cleanupWebCryptoResult(value) {
  delete value.then;
}

/**
 * @template T
 * @typedef {(value: T | PromiseLike<T>) => void} WebCryptoResolve
 */

/**
 * Resolve a WebCrypto promise while inherited then accessors are shadowed.
 * @template T
 * @param {WebCryptoResolve<T>} resolve
 * @param {T | PromiseLike<T>} value
 * @returns {void}
 */
function resolveWebCryptoResult(resolve, value) {
  const shouldCleanupResult = prepareWebCryptoResult(value);
  try {
    resolve(value);
  } finally {
    if (shouldCleanupResult)
      cleanupWebCryptoResult(value);
  }
}

/**
 * Run a WebCrypto promise reaction and settle the outer promise.
 * @template T
 * @template TResult
 * @param {((value: T) => TResult | PromiseLike<TResult>) | undefined} handler
 * @param {WebCryptoResolve<T | TResult>} resolve
 * @param {(reason?: unknown) => void} reject
 * @param {T} value
 * @param {boolean} isRejected
 * @returns {void}
 */
function settleJobPromise(handler, resolve, reject, value, isRejected) {
  try {
    if (typeof handler === 'function') {
      resolveWebCryptoResult(resolve, handler(value));
    } else if (isRejected) {
      reject(value);
    } else {
      resolveWebCryptoResult(resolve, value);
    }
  } catch (err) {
    reject(err);
  }
}

/**
 * Promise.prototype.then gets promise.constructor to determine the result
 * promise's species. These promises are internal WebCrypto intermediates, so
 * make that lookup stay on the promise itself instead of user-mutated state.
 * @template T
 * @template [TResult1=T]
 * @template [TResult2=never]
 * @param {Promise<T>} promise
 * @param {((value: T) => TResult1 | PromiseLike<TResult1>) | null | undefined} [onFulfilled]
 * @param {((reason: unknown) => TResult2 | PromiseLike<TResult2>) | null | undefined} [onRejected]
 * @returns {Promise<TResult1 | TResult2>}
 */
function jobPromiseThen(promise, onFulfilled, onRejected) {
  const {
    promise: resultPromise,
    resolve,
    reject,
  } = PromiseWithResolvers();
  setOwnProperty(promise, 'constructor', undefined);
  PromisePrototypeThen(
    promise,
    (value) => settleJobPromise(onFulfilled, resolve, reject, value, false),
    (value) => settleJobPromise(onRejected, resolve, reject, value, true));
  return resultPromise;
}

// In WebCrypto, the publicExponent option in RSA is represented as a
// WebIDL "BigInteger"... that is, a Uint8Array that allows an arbitrary
// number of leading zero bits. Our conventional APIs for reading
// an unsigned int from a Buffer are not adequate. The implementation
// here is adapted from the chromium implementation here:
// https://github.com/chromium/chromium/blob/HEAD/third_party/blink/public/platform/web_crypto_algorithm_params.h, but ported to JavaScript
// Throws an OperationError if the value does not fit in an unsigned 32-bit integer.
function bigIntArrayToUnsignedInt(input) {
  let result = 0;
  const length = TypedArrayPrototypeGetLength(input);

  for (let n = 0; n < length; ++n) {
    const n_reversed = length - n - 1;
    if (n_reversed >= 4 && input[n]) {
      throw lazyDOMException(
        'algorithm.publicExponent must fit in an unsigned 32-bit integer',
        'OperationError');
    }
    result |= input[n] << 8 * n_reversed;
  }

  return result >>> 0;
}

function bigIntArrayToUnsignedBigInt(input) {
  let result = 0n;
  const length = TypedArrayPrototypeGetLength(input);

  for (let n = 0; n < length; ++n) {
    const n_reversed = length - n - 1;
    result |= BigInt(input[n]) << 8n * BigInt(n_reversed);
  }

  return result;
}

function getStringOption(options, key) {
  let value;
  if (options && (value = options[key]) != null)
    validateString(value, `options.${key}`);
  return value;
}

// Must be at most 31 entries.
const kCanonicalUsageOrder = [
  'encrypt', 'decrypt',
  'sign', 'verify',
  'deriveKey', 'deriveBits',
  'wrapKey', 'unwrapKey',
  'encapsulateKey', 'encapsulateBits',
  'decapsulateKey', 'decapsulateBits',
];

const kUsageMasks = {
  __proto__: null,
};
const kUsageByMask = {
  __proto__: null,
};
// Derive both lookup tables from kCanonicalUsageOrder so adding a new
// usage only requires updating the canonical list above. The numeric
// mask uses the usage's canonical index as its bit position.
for (let n = 0; n < kCanonicalUsageOrder.length; n++) {
  const usage = kCanonicalUsageOrder[n];
  const mask = 1 << n;
  kUsageMasks[usage] = mask;
  kUsageByMask[mask] = usage;
}

/**
 * Collects a key usage list into a set.
 * @param {string[]} usages
 * @returns {SafeSet<string>}
 */
function toUsagesSet(usages) {
  const usagesSet = new SafeSet();
  for (let n = 0; n < usages.length; n++) {
    usagesSet.add(usages[n]);
  }
  return usagesSet;
}

/**
 * Returns a bit mask representing the usages from `usageSet`.
 * @param {SafeSet<string>} usageSet
 * @returns {number}
 */
function getUsagesMask(usageSet) {
  // No usages is a valid state for some public keys, represented by a
  // zero mask.
  if (usageSet.size === 0) return 0;
  let mask = 0;
  for (const usage of usageSet) {
    mask |= kUsageMasks[usage];
  }
  return mask;
}

/**
 * Returns whether `mask` contains `usage`.
 * @param {number} mask
 * @param {string} usage
 * @returns {boolean}
 */
function hasUsage(mask, usage) {
  return (mask & kUsageMasks[usage]) !== 0;
}

/**
 * Returns the usages represented by `mask` in canonical order.
 * @param {number} mask
 * @returns {string[]}
 */
function getUsagesFromMask(mask) {
  // Short circuit most common cases, empty and single usage
  // No usages is a valid state for some public keys
  if (mask === 0) return [];
  // A mask with exactly one bit set maps directly to one usage
  if ((mask & (mask - 1)) === 0) {
    return [kUsageByMask[mask]];
  }
  // Multiple usages need to be expanded in canonical order.
  const result = [];
  for (let n = 0; n < kCanonicalUsageOrder.length; n++) {
    if (mask & (1 << n))
      ArrayPrototypePush(result, kCanonicalUsageOrder[n]);
  }
  return result;
}

function getBlockSize(name) {
  switch (name) {
    case 'SHA-1':
      // Fall through
    case 'SHA-256':
      return 512;
    case 'SHA-384':
      // Fall through
    case 'SHA-512':
      return 1024;
    case 'SHA3-256':
      // Fall through
    case 'SHA3-384':
      // Fall through
    case 'SHA3-512':
      // This interaction is not defined for now.
      // https://github.com/WICG/webcrypto-modern-algos/issues/23
      throw lazyDOMException('Explicit algorithm length member is required', 'NotSupportedError');
  }
}

function validateKeyOps(keyOps, usagesSet) {
  if (keyOps === undefined) return;
  validateArray(keyOps, 'keyData.key_ops');
  let keyOpsMask = 0;
  const seen = new SafeSet();
  for (let n = 0; n < keyOps.length; n++) {
    const op = keyOps[n];
    if (seen.has(op))
      throw lazyDOMException('Duplicate key operation', 'DataError');
    seen.add(op);
    const opMask = kUsageMasks[op];
    // Skipping unknown key ops
    if (opMask === undefined)
      continue;
    keyOpsMask |= opMask;

    // TODO(@jasnell): RFC7517 section 4.3 strong recommends validating
    // key usage combinations. Specifically, it says that unrelated key
    // ops SHOULD NOT be used together. We're not yet validating that here.
  }

  if (usagesSet !== undefined) {
    const usagesMask = getUsagesMask(usagesSet);
    if ((keyOpsMask & usagesMask) !== usagesMask) {
      throw lazyDOMException(
        'Key operations and usage mismatch',
        'DataError');
    }
  }
}

function secureHeapUsed() {
  const val = _secureHeapUsed();
  if (val === undefined)
    return { total: 0, used: 0, utilization: 0, min: 0 };
  const used = Number(_secureHeapUsed());
  const total = Number(getOptionValue('--secure-heap'));
  const min = Number(getOptionValue('--secure-heap-min'));
  const utilization = used / total;
  return { total, used, utilization, min };
}

module.exports = {
  getArrayBufferOrView,
  getBufferSourceByteLength,
  getBufferSourceBytes,
  getCiphers,
  getCurves,
  getDataViewOrTypedArrayBuffer,
  getHashes,
  getMacs,
  getOptionalByteLength,
  kHandle,
  setEngine,
  toBuf,

  kNamedCurveAliases,
  get kSupportedAlgorithms() {
    return getSupportedAlgorithms().algorithms;
  },
  isFips,
  normalizeAlgorithm,
  normalizeHashName,
  hasAnyNotIn,
  validateByteSource,
  validateKeyOps,
  validateAlgorithm,
  jobPromise,
  jobPromiseThen,
  cleanupWebCryptoResult,
  prepareWebCryptoResult,
  validateKmacKeyLength,
  resolveWebCryptoResult,
  validateMaxBufferLength,
  numBitsToBytes,
  truncateToBitLength,
  bigIntArrayToUnsignedBigInt,
  bigIntArrayToUnsignedInt,
  getBlockSize,
  getStringOption,
  getUsagesMask,
  getUsagesFromMask,
  toUsagesSet,
  hasUsage,
  secureHeapUsed,
  getCachedHashId,
  getHashCache,
  getCachedMacId,
  getMacCache,
  getOpenSSLSecLevel,
};

sources.internal/crypto/webcrypto:
'use strict';

const {
  ArrayBufferIsView,
  ArrayIsArray,
  FunctionPrototypeCall,
  JSONParse,
  JSONStringify,
  ObjectDefineProperties,
  ObjectKeys,
  ObjectSetPrototypeOf,
  PromiseReject,
  PromiseResolve,
  ReflectApply,
  ReflectConstruct,
  SafeArrayIterator,
  StringPrototypeRepeat,
  StringPrototypeSlice,
  StringPrototypeStartsWith,
  SymbolIterator,
  SymbolToStringTag,
  TypedArrayPrototypeGetBuffer,
} = primordials;

const {
  kWebCryptoKeyFormatRaw,
  kWebCryptoKeyFormatPKCS8,
  kWebCryptoKeyFormatSPKI,
  kWebCryptoCipherEncrypt,
  kWebCryptoCipherDecrypt,
} = internalBinding('crypto');

const {
  decodeUTF8,
  encodeUtf8String,
} = internalBinding('encoding_binding');

const {
  codes: {
    ERR_ILLEGAL_CONSTRUCTOR,
    ERR_INVALID_ARG_TYPE,
    ERR_INVALID_ARG_VALUE,
    ERR_INVALID_THIS,
  },
} = require('internal/errors');

const {
  CryptoKey,
  getCryptoKeyAlgorithm,
  getCryptoKeyExtractable,
  getCryptoKeyHandle,
  getCryptoKeyType,
  getCryptoKeyUsagesMask,
  hasCryptoKeyUsage,
  importGenericSecretKey,
  toPublicCryptoKey,
} = require('internal/crypto/keys');

const {
  asyncDigest,
} = require('internal/crypto/hash');

const {
  cleanupWebCryptoResult,
  getBlockSize,
  getUsagesFromMask,
  jobPromiseThen,
  normalizeAlgorithm,
  normalizeHashName,
  numBitsToBytes,
  prepareWebCryptoResult,
  validateAlgorithm,
  validateMaxBufferLength,
} = require('internal/crypto/util');

const {
  kEnumerableProperty,
  lazyDOMException,
  setOwnProperty,
} = require('internal/util');

const {
  getRandomValues: _getRandomValues,
  randomUUID: _randomUUID,
} = require('internal/crypto/random');

const {
  isArrayBuffer,
  isPromise,
} = require('internal/util/types');

let webidl;

// WebCrypto methods return promises, including for synchronous validation
// failures. Keep that conversion in one place so method bodies stay readable.
function callSubtleCryptoMethod(fn, receiver, args) {
  try {
    const result = ReflectApply(fn, receiver, args);
    if (isPromise(result))
      return result;
    // PromiseResolve() performs thenable assimilation for object results.
    // Shadow inherited then accessors while it resolves synchronous results.
    const shouldCleanupResult = prepareWebCryptoResult(result);
    try {
      return PromiseResolve(result);
    } finally {
      if (shouldCleanupResult)
        cleanupWebCryptoResult(result);
    }
  } catch (err) {
    return PromiseReject(err);
  }
}

const kArgumentContexts = [
  '1st argument',
  '2nd argument',
  '3rd argument',
  '4th argument',
  '5th argument',
  '6th argument',
  '7th argument',
];

function prepareSubtleMethod(receiver, method, argLength, required) {
  if (receiver !== subtle) throw new ERR_INVALID_THIS('SubtleCrypto');

  webidl ??= require('internal/crypto/webidl');
  const prefix = `Failed to execute '${method}' on 'SubtleCrypto'`;
  webidl.requiredArguments(argLength, required, { prefix });
  return prefix;
}

function convertSubtleArgument(prefix, converter, value, index) {
  // Mirrors makeOptions() in internal/webidl, including why it stays an
  // ordinary literal: the converters read every member below, and an absent
  // one would resolve through %Object.prototype%.
  return webidl.converters[converter](value, {
    prefix,
    context: kArgumentContexts[index],
    code: undefined,
    enforceRange: undefined,
    clamp: undefined,
    allowShared: undefined,
    allowResizable: undefined,
  });
}

function digest(algorithm, data) {
  return callSubtleCryptoMethod(digestImpl, this, arguments);
}

function digestImpl(algorithm, data) {
  const prefix = prepareSubtleMethod(this, 'digest', arguments.length, 2);
  let i = 0;
  algorithm = convertSubtleArgument(
    prefix, 'AlgorithmIdentifier', algorithm, i++);
  data = convertSubtleArgument(prefix, 'BufferSource', data, i++);

  const normalizedAlgorithm = normalizeAlgorithm(algorithm, 'digest');

  return FunctionPrototypeCall(asyncDigest, this, normalizedAlgorithm, data);
}

function randomUUID() {
  if (this !== crypto) throw new ERR_INVALID_THIS('Crypto');
  return _randomUUID();
}

function generateKey(
  algorithm,
  extractable,
  keyUsages) {
  return callSubtleCryptoMethod(generateKeyImpl, this, arguments);
}

function generateKeyImpl(
  algorithm,
  extractable,
  keyUsages) {
  const prefix = prepareSubtleMethod(this, 'generateKey', arguments.length, 3);
  let i = 0;
  algorithm = convertSubtleArgument(
    prefix, 'AlgorithmIdentifier', algorithm, i++);
  extractable = convertSubtleArgument(prefix, 'boolean', extractable, i++);
  const usages = convertSubtleArgument(
    prefix, 'sequence<KeyUsage>', keyUsages, i++);

  const normalizedAlgorithm = normalizeAlgorithm(algorithm, 'generateKey');
  switch (normalizedAlgorithm.name) {
    case 'RSASSA-PKCS1-v1_5':
      // Fall through
    case 'RSA-PSS':
      // Fall through
    case 'RSA-OAEP':
      return require('internal/crypto/rsa')
        .rsaKeyGenerate(normalizedAlgorithm, extractable, usages);
    case 'Ed25519':
      // Fall through
    case 'Ed448':
      // Fall through
    case 'X25519':
      // Fall through
    case 'X448':
      return require('internal/crypto/cfrg')
        .cfrgGenerateKey(normalizedAlgorithm, extractable, usages);
    case 'ECDSA':
      // Fall through
    case 'ECDH':
      return require('internal/crypto/ec')
        .ecGenerateKey(normalizedAlgorithm, extractable, usages);
    case 'HMAC':
      return require('internal/crypto/mac')
        .hmacGenerateKey(normalizedAlgorithm, extractable, usages);
    case 'AES-CTR':
      // Fall through
    case 'AES-CBC':
      // Fall through
    case 'AES-GCM':
      // Fall through
    case 'AES-OCB':
      // Fall through
    case 'AES-KW':
      return require('internal/crypto/aes')
        .aesGenerateKey(normalizedAlgorithm, extractable, usages);
    case 'ChaCha20-Poly1305':
      return require('internal/crypto/chacha20_poly1305')
        .c20pGenerateKey(normalizedAlgorithm, extractable, usages);
    case 'ML-DSA-44':
      // Fall through
    case 'ML-DSA-65':
      // Fall through
    case 'ML-DSA-87':
      return require('internal/crypto/ml_dsa')
        .mlDsaGenerateKey(normalizedAlgorithm, extractable, usages);
    case 'ML-KEM-512':
      // Fall through
    case 'ML-KEM-768':
      // Fall through
    case 'ML-KEM-1024':
      return require('internal/crypto/ml_kem')
        .mlKemGenerateKey(normalizedAlgorithm, extractable, usages);
    case 'MLKEM768-P256':
      // Fall through
    case 'MLKEM768-X25519':
      // Fall through
    case 'MLKEM1024-P384':
      return require('internal/crypto/kem_hybrids')
        .kemHybridGenerateKey(normalizedAlgorithm, extractable, usages);
    case 'KMAC128':
      // Fall through
    case 'KMAC256':
      return require('internal/crypto/mac')
        .kmacGenerateKey(normalizedAlgorithm, extractable, usages);
    /* c8 ignore start */
    default: {
      const assert = require('internal/assert');
      assert.fail('Unreachable code');
    }
    /* c8 ignore stop */
  }
}

function deriveBits(algorithm, baseKey, length = null) {
  return callSubtleCryptoMethod(deriveBitsImpl, this, arguments);
}

function deriveBitsImpl(algorithm, baseKey, length = null) {
  const prefix = prepareSubtleMethod(this, 'deriveBits', arguments.length, 2);
  let i = 0;
  algorithm = convertSubtleArgument(
    prefix, 'AlgorithmIdentifier', algorithm, i++);
  baseKey = convertSubtleArgument(prefix, 'CryptoKey', baseKey, i++);
  if (length !== null) {
    length = webidl.converters['unsigned long'](length, {
      prefix,
      context: kArgumentContexts[i++],
      enforceRange: true,
    });
  }

  const normalizedAlgorithm = normalizeAlgorithm(algorithm, 'deriveBits');
  if (!hasCryptoKeyUsage(baseKey, 'deriveBits')) {
    throw lazyDOMException(
      'baseKey does not have deriveBits usage',
      'InvalidAccessError');
  }
  if (getCryptoKeyAlgorithm(baseKey).name !== normalizedAlgorithm.name)
    throw lazyDOMException('Key algorithm mismatch', 'InvalidAccessError');
  switch (normalizedAlgorithm.name) {
    case 'X25519':
      // Fall through
    case 'X448':
      // Fall through
    case 'ECDH':
      return require('internal/crypto/diffiehellman')
        .ecdhDeriveBits(normalizedAlgorithm, baseKey, length);
    case 'HKDF':
      return require('internal/crypto/hkdf')
        .hkdfDeriveBits(normalizedAlgorithm, baseKey, length);
    case 'PBKDF2':
      return require('internal/crypto/pbkdf2')
        .pbkdf2DeriveBits(normalizedAlgorithm, baseKey, length);
    case 'Argon2d':
      // Fall through
    case 'Argon2i':
      // Fall through
    case 'Argon2id':
      return require('internal/crypto/argon2')
        .argon2DeriveBits(normalizedAlgorithm, baseKey, length);
    /* c8 ignore start */
    default: {
      const assert = require('internal/assert');
      assert.fail('Unreachable code');
    }
    /* c8 ignore stop */
  }
}

function getKeyLength(algorithm) {
  validateAlgorithm(algorithm, 'get key length');
  const { name, length, hash } = algorithm;
  switch (name) {
    case 'AES-CTR':
    case 'AES-CBC':
    case 'AES-GCM':
    case 'AES-OCB':
    case 'AES-KW':
      if (length !== 128 && length !== 192 && length !== 256)
        throw lazyDOMException('Invalid key length', 'OperationError');

      return length;
    case 'HMAC':
      if (length === 0)
        throw new ERR_INVALID_ARG_VALUE('algorithm.length', length, 'must not be zero');
      if (length === undefined) {
        return getBlockSize(hash?.name);
      }

      if (typeof length === 'number' && length !== 0) {
        return length;
      }

      throw lazyDOMException('Invalid key length', 'OperationError');
    case 'KMAC128':
    case 'KMAC256':
      if (typeof length === 'number') {
        return length;
      }

      return name === 'KMAC128' ? 128 : 256;
    case 'HKDF':
    case 'PBKDF2':
    case 'Argon2d':
    case 'Argon2i':
    case 'Argon2id':
      return null;
    case 'ChaCha20-Poly1305':
      return 256;
  }
}

function getSharedKeyLength({ name }) {
  switch (name) {
    case 'ML-KEM-512':
      // Fall through
    case 'ML-KEM-768':
      // Fall through
    case 'ML-KEM-1024':
      // Fall through
    case 'MLKEM768-P256':
      // Fall through
    case 'MLKEM768-X25519':
      // Fall through
    case 'MLKEM1024-P384':
      return 256;
    /* c8 ignore start */
    default: {
      const assert = require('internal/assert');
      assert.fail('Unreachable code');
    }
    /* c8 ignore stop */
  }
}

function canImportRawSecret(algorithm, sharedKeyLength) {
  switch (algorithm.name) {
    case 'AES-OCB':
    case 'AES-KW':
    case 'AES-GCM':
    case 'AES-CTR':
    case 'AES-CBC':
      return sharedKeyLength === 128 ||
             sharedKeyLength === 192 ||
             sharedKeyLength === 256;
    case 'ChaCha20-Poly1305':
      return sharedKeyLength === 256;
    case 'HKDF':
    case 'PBKDF2':
    case 'Argon2i':
    case 'Argon2d':
    case 'Argon2id':
      return true;
    case 'HMAC':
      if (sharedKeyLength === 0)
        return false;
      // Fall through
    case 'KMAC128':
    case 'KMAC256':
      return algorithm.length === undefined ||
             numBitsToBytes(algorithm.length) * 8 === sharedKeyLength;
    default:
      return false;
  }
}

function deriveKey(
  algorithm,
  baseKey,
  derivedKeyType,
  extractable,
  keyUsages) {
  return callSubtleCryptoMethod(deriveKeyImpl, this, arguments);
}

function deriveKeyImpl(
  algorithm,
  baseKey,
  derivedKeyType,
  extractable,
  keyUsages) {
  const prefix = prepareSubtleMethod(this, 'deriveKey', arguments.length, 5);
  let i = 0;
  algorithm = convertSubtleArgument(
    prefix, 'AlgorithmIdentifier', algorithm, i++);
  baseKey = convertSubtleArgument(prefix, 'CryptoKey', baseKey, i++);
  derivedKeyType = convertSubtleArgument(
    prefix, 'AlgorithmIdentifier', derivedKeyType, i++);
  extractable = convertSubtleArgument(prefix, 'boolean', extractable, i++);
  const usages = convertSubtleArgument(
    prefix, 'sequence<KeyUsage>', keyUsages, i++);

  const normalizedAlgorithm = normalizeAlgorithm(algorithm, 'deriveBits');
  const normalizedDerivedKeyAlgorithmImport =
    normalizeAlgorithm(derivedKeyType, 'importKey');
  const normalizedDerivedKeyAlgorithmLength =
    normalizeAlgorithm(derivedKeyType, 'get key length');
  if (!hasCryptoKeyUsage(baseKey, 'deriveKey')) {
    throw lazyDOMException(
      'baseKey does not have deriveKey usage',
      'InvalidAccessError');
  }
  if (getCryptoKeyAlgorithm(baseKey).name !== normalizedAlgorithm.name)
    throw lazyDOMException('Key algorithm mismatch', 'InvalidAccessError');

  const length = getKeyLength(normalizedDerivedKeyAlgorithmLength);
  let secret;
  switch (normalizedAlgorithm.name) {
    case 'X25519':
      // Fall through
    case 'X448':
      // Fall through
    case 'ECDH':
      secret = require('internal/crypto/diffiehellman')
        .ecdhDeriveBits(normalizedAlgorithm, baseKey, length);
      break;
    case 'HKDF':
      secret = require('internal/crypto/hkdf')
        .hkdfDeriveBits(normalizedAlgorithm, baseKey, length);
      break;
    case 'PBKDF2':
      secret = require('internal/crypto/pbkdf2')
        .pbkdf2DeriveBits(normalizedAlgorithm, baseKey, length);
      break;
    case 'Argon2d':
      // Fall through
    case 'Argon2i':
      // Fall through
    case 'Argon2id':
      secret = require('internal/crypto/argon2')
        .argon2DeriveBits(normalizedAlgorithm, baseKey, length);
      break;
    /* c8 ignore start */
    default: {
      const assert = require('internal/assert');
      assert.fail('Unreachable code');
    }
    /* c8 ignore stop */
  }

  return jobPromiseThen(secret, (secret) => FunctionPrototypeCall(
    importKeySync,
    this,
    'raw-secret',
    secret,
    normalizedDerivedKeyAlgorithmImport,
    extractable,
    usages,
  ));
}

function exportKeySpki(key) {
  let exporter;
  switch (getCryptoKeyAlgorithm(key).name) {
    case 'RSASSA-PKCS1-v1_5':
      // Fall through
    case 'RSA-PSS':
