  let i = 0;
  format = convertSubtleArgument(prefix, 'KeyFormat', format, i++);
  wrappedKey = convertSubtleArgument(prefix, 'BufferSource', wrappedKey, i++);
  unwrappingKey = convertSubtleArgument(
    prefix, 'CryptoKey', unwrappingKey, i++);
