    kWebCryptoCipherDecrypt,
    normalizedAlgorithm,
    unwrappingKey,
    wrappedKey);

  return jobPromiseThen(bytes, (bytes) => {
    let keyData = bytes;
    if (format === 'jwk') {
      keyData = parseJwk(bytes);
    }

    return FunctionPrototypeCall(
      importKeySync,
      this,
      format,
      keyData,
      normalizedKeyAlgorithm,
      extractable,
      usages,
