  }

  /** @type {bigint} */
  get retransmitCount() {
    return this.#handle[IDX_STATS_SESSION_RETRANSMIT_COUNT];
  }

  toString() {
    return JSONStringify(this.toJSON());
  }

  toJSON() {
    return {
      __proto__: null,
