        const trail = unfinishedBytesUtf8(u, u.length);
        if (trail > 0) {
          this[kChunk] = new FastBuffer(u.subarray(-trail)); // copy
          if (!prefix && trail === u.length) return ''; // No further state change
          u = u.subarray(0, -trail);
