        closed = true;
        released = true;
        handle[kLocked] = false;
        handle[kUnref]();
        if (autoClose) {
          handle[kCloseSync]();
        }
        return totalBytesWritten;
      },

      fail(reason) {
        if (closed || errored) return;
        errored = true;
        error = reason;
        closing = false;
        closed = true;
        pendingEnd?.reject(reason);
        pendingEnd = null;
        for (const pending of pendingWrites) {
          pending.reject(reason);
        }
        pendingWrites.clear();
        releaseAfterFailure();
      },

      [SymbolAsyncDispose]() {
        if (closing) {
          return pendingEnd?.promise ?? PromiseResolve();
        }
        if (!closed && !errored) {
          this.fail();
        }
        return PromiseResolve();
      },

      [SymbolDispose]() {
        this.fail();
      },
    };
  };
}

async function handleFdClose(fileOpPromise, closeFunc) {
  return PromisePrototypeThen(
    fileOpPromise,
    (result) => PromisePrototypeThen(closeFunc(), () => result),
    (opError) =>
      PromisePrototypeThen(
        closeFunc(),
        () => PromiseReject(opError),
        (closeError) => PromiseReject(aggregateTwoErrors(closeError, opError)),
      ),
  );
}

async function handleFdSync(fileOpPromise, handle) {
  return PromisePrototypeThen(
    fileOpPromise,
    (result) => PromisePrototypeThen(
      handle.sync(),
      () => result,
      (syncError) => PromiseReject(syncError),
    ),
    (opError) => PromiseReject(opError),
  );
}

async function fsCall(fn, handle, ...args) {
  assert(handle[kRefs] !== undefined,
         'handle must be an instance of FileHandle');

  if (handle.fd === -1) {
    // eslint-disable-next-line no-restricted-syntax
    const err = new Error(handle[kCloseReason] ?? 'file closed');
    err.code = 'EBADF';
    err.syscall = fn.name;
    throw err;
  }

  try {
    handle[kRef]();
    return await fn(handle, ...new SafeArrayIterator(args));
  } finally {
    handle[kUnref]();
  }
}

function checkAborted(signal) {
  if (signal?.aborted)
    throw new AbortError(undefined, { cause: signal.reason });
}

function rejectWithReason(signal, reject) {
  return () => {
    reject(new AbortError(undefined, { cause: signal.reason }));
  };
}

async function raceWithSignal(opPromise, signal) {
  if (!signal) return opPromise;
  const { promise: abortPromise, reject } = PromiseWithResolvers();
  // eslint-disable-next-line no-unused-vars
  using _ = EventEmitter.addAbortListener(signal,
                                          rejectWithReason(signal, reject));
  return await SafePromiseRace([opPromise, abortPromise]);
}

async function writeFileHandle(filehandle, data, signal, encoding) {
  checkAborted(signal);
  if (isCustomIterable(data)) {
    for await (const buf of data) {
      checkAborted(signal);
      const toWrite =
        isArrayBufferView(buf) ? buf : Buffer.from(buf, encoding || 'utf8');
      let remaining = toWrite.byteLength;
      while (remaining > 0) {
        const writeSize = MathMin(kWriteFileMaxChunkSize, remaining);
        const { bytesWritten } = await write(
          filehandle, toWrite, toWrite.byteLength - remaining, writeSize);
        remaining -= bytesWritten;
        checkAborted(signal);
      }
    }
    return;
  }
  data = new Uint8Array(data.buffer, data.byteOffset, data.byteLength);
  let remaining = data.byteLength;
  if (remaining === 0) return;
  do {
    checkAborted(signal);
    const { bytesWritten } =
      await write(filehandle, data, 0,
                  MathMin(kWriteFileMaxChunkSize, data.byteLength));
    remaining -= bytesWritten;
    data = new Uint8Array(
      data.buffer,
      data.byteOffset + bytesWritten,
      data.byteLength - bytesWritten,
    );
  } while (remaining > 0);
}

async function readFileHandleWithUserBuffer(filehandle, options, size) {
  const signal = options?.signal;
  const encoding = options?.encoding;
  const buffer = getReadFileBuffer(options, size);
  const byteLengthName = getReadFileBufferByteLengthName(options);
  let totalRead = 0;

  while (totalRead < buffer.byteLength) {
    checkAborted(signal);

    const length = size === 0 ?
      buffer.byteLength - totalRead :
      MathMin(size - totalRead, kReadFileBufferLength);

    const bytesRead = (await PromisePrototypeThen(
      binding.read(filehandle.fd, buffer, totalRead, length, -1, kUsePromises),
      undefined,
      handleErrorFromBinding,
    )) ?? 0;

    totalRead += bytesRead;

    if (bytesRead === 0 || totalRead === size) {
      const result = buffer.subarray(0, totalRead);
      return encoding ? result.toString(encoding) : result;
    }
  }

  if (size === 0) {
    checkAborted(signal);

    const extraBuffer = Buffer.allocUnsafeSlow(1);
    const bytesRead = (await PromisePrototypeThen(
      binding.read(filehandle.fd, extraBuffer, 0, 1, -1, kUsePromises),
      undefined,
      handleErrorFromBinding,
    )) ?? 0;

    if (bytesRead !== 0) {
      throw new ERR_INVALID_ARG_VALUE(
        byteLengthName,
        buffer.byteLength,
        'is too small to contain the entire file',
      );
    }
  }

  return encoding ? buffer.toString(encoding) : buffer.subarray(0, totalRead);
}

async function readFileHandle(filehandle, options, knownRegularFileSize) {
  const signal = options?.signal;
  const encoding = options?.encoding;
  const decoder = encoding && new StringDecoder(encoding);

  checkAborted(signal);

  let size = 0;
  let length = 0;
  if (knownRegularFileSize !== undefined) {
    // Handed over by readFile() together with an already open fd.
    size = knownRegularFileSize;
    length = encoding ? MathMin(size, kReadFileBufferLength) : size;
  } else {
    const statFields = await PromisePrototypeThen(
      binding.fstat(filehandle.fd, false, kUsePromises),
      undefined,
      handleErrorFromBinding,
    );

    checkAborted(signal);

    if ((statFields[1/* mode */] & S_IFMT) === S_IFREG) {
      size = statFields[8/* size */];
      length = encoding ? MathMin(size, kReadFileBufferLength) : size;
    }
  }
  if (length === 0) {
    length = kReadFileUnknownBufferLength;
  }

  if (size > kIoMaxLength)
    throw new ERR_FS_FILE_TOO_LARGE(size);

  if (options.buffer !== undefined) {
    return readFileHandleWithUserBuffer(filehandle, options, size);
  }

  let totalRead = 0;
  const noSize = size === 0;
  let buffer = Buffer.allocUnsafeSlow(length);
  let result = '';
  let offset = 0;
  let buffers;
  const chunkedRead = length > kReadFileBufferLength;

  while (true) {
    checkAborted(signal);

    if (chunkedRead) {
      length = MathMin(size - totalRead, kReadFileBufferLength);
    }

    const bytesRead = (await PromisePrototypeThen(
      binding.read(filehandle.fd, buffer, offset, length, -1, kUsePromises),
      undefined,
      handleErrorFromBinding,
    )) ?? 0;
    totalRead += bytesRead;

    if (bytesRead === 0 ||
        totalRead === size ||
        (bytesRead !== buffer.length && !chunkedRead && !noSize)) {
      const singleRead = bytesRead === totalRead;

      const bytesToCheck = chunkedRead ? totalRead : bytesRead;

      if (bytesToCheck !== buffer.length) {
        buffer = buffer.subarray(0, bytesToCheck);
      }

      if (!encoding) {
        if (noSize && !singleRead) {
          ArrayPrototypePush(buffers, buffer);
          return Buffer.concat(buffers, totalRead);
        }
        return buffer;
      }

      if (singleRead) {
        return buffer.toString(encoding);
      }
      result += decoder.end(buffer);
      return result;
    }
    const readBuffer = bytesRead !== buffer.length ?
      buffer.subarray(0, bytesRead) :
      buffer;
    if (encoding) {
      result += decoder.write(readBuffer);
    } else if (size !== 0) {
      offset = totalRead;
    } else {
      buffers ??= [];
      // Unknown file size requires chunks.
      ArrayPrototypePush(buffers, readBuffer);
      buffer = Buffer.allocUnsafeSlow(kReadFileUnknownBufferLength);
    }
  }
}

// All of the functions are defined as async in order to ensure that errors
// thrown cause promise rejections rather than being thrown synchronously.
async function access(path, mode = F_OK) {
  const h = vfsState.handlers;
  if (h !== null) {
    const promise = h.access(path, mode);
    if (promise !== undefined) { await promise; return; }
  }
  return await PromisePrototypeThen(
    binding.access(getValidatedPath(path), mode, kUsePromises),
    undefined,
    handleErrorFromBinding,
  );
}

async function cp(src, dest, options) {
