async function lchmod(path, mode) {
  const h = vfsState.handlers;
  if (h !== null) {
    const promise = h.lchmod(path, mode);
    if (promise !== undefined) { await promise; return; }
  }

  if (O_SYMLINK === undefined)
    throw new ERR_METHOD_NOT_IMPLEMENTED('lchmod()');

  const fd = await open(path, O_WRONLY | O_SYMLINK);
  return handleFdClose(fchmod(fd, mode), fd.close);
}

async function lchown(path, uid, gid) {
  const h = vfsState.handlers;
  if (h !== null) {
    const promise = h.lchown(path, uid, gid);
    if (promise !== undefined) { await promise; return; }
  }

  path = getValidatedPath(path);
  validateInteger(uid, 'uid', -1, kMaxUserId);
  validateInteger(gid, 'gid', -1, kMaxUserId);
  return await PromisePrototypeThen(
    binding.lchown(path, uid, gid, kUsePromises),
    undefined,
    handleErrorFromBinding,
  );
}

async function fchown(handle, uid, gid) {
  validateInteger(uid, 'uid', -1, kMaxUserId);
  validateInteger(gid, 'gid', -1, kMaxUserId);
  if (permission.isEnabled()) {
    throw new ERR_ACCESS_DENIED('fchown API is disabled when Permission Model is enabled.');
  }
  return await PromisePrototypeThen(
    binding.fchown(handle.fd, uid, gid, kUsePromises),
    undefined,
    handleErrorFromBinding,
  );
}

async function chown(path, uid, gid) {
  const h = vfsState.handlers;
  if (h !== null) {
    const promise = h.chown(path, uid, gid);
    if (promise !== undefined) { await promise; return; }
  }

  path = getValidatedPath(path);
  validateInteger(uid, 'uid', -1, kMaxUserId);
  validateInteger(gid, 'gid', -1, kMaxUserId);
  return await PromisePrototypeThen(
    binding.chown(path, uid, gid, kUsePromises),
    undefined,
    handleErrorFromBinding,
  );
}

async function utimes(path, atime, mtime) {
  path = getValidatedPath(path);
  atime = toUnixTimestamp(atime);
  mtime = toUnixTimestamp(mtime);

  const h = vfsState.handlers;
  if (h !== null) {
    const promise = h.utimes(path, atime, mtime);
    if (promise !== undefined) { await promise; return; }
  }

  return await PromisePrototypeThen(
    binding.utimes(path, atime, mtime, kUsePromises),
    undefined,
    handleErrorFromBinding,
  );
}

async function futimes(handle, atime, mtime) {
  if (permission.isEnabled()) {
    throw new ERR_ACCESS_DENIED('futimes API is disabled when Permission Model is enabled.');
  }
  atime = toUnixTimestamp(atime, 'atime');
  mtime = toUnixTimestamp(mtime, 'mtime');
  return await PromisePrototypeThen(
    binding.futimes(handle.fd, atime, mtime, kUsePromises),
    undefined,
    handleErrorFromBinding,
  );
}

async function lutimes(path, atime, mtime) {
  path = getValidatedPath(path);
  atime = toUnixTimestamp(atime);
  mtime = toUnixTimestamp(mtime);

  const h = vfsState.handlers;
  if (h !== null) {
    const promise = h.lutimes(path, atime, mtime);
    if (promise !== undefined) { await promise; return; }
  }

  return await PromisePrototypeThen(
    binding.lutimes(path, atime, mtime, kUsePromises),
    undefined,
    handleErrorFromBinding,
  );
}

async function realpath(path, options) {
  const h = vfsState.handlers;
  if (h !== null) {
    const promise = h.realpath(path, options);
    if (promise !== undefined) return await promise;
  }
  options = getOptions(options);
  return await PromisePrototypeThen(
    binding.realpath(getValidatedPath(path), options.encoding, kUsePromises),
    undefined,
    handleErrorFromBinding,
  );
}

async function mkdtemp(prefix, options) {
  const h = vfsState.handlers;
  if (h !== null) {
    const promise = h.mkdtemp(prefix, options);
    if (promise !== undefined) return await promise;
  }

  options = getOptions(options);

  prefix = getValidatedPath(prefix, 'prefix');
  warnOnNonPortableTemplate(prefix);

  return await PromisePrototypeThen(
    binding.mkdtemp(prefix, options.encoding, kUsePromises),
    undefined,
    handleErrorFromBinding,
  );
}

async function mkdtempDisposable(prefix, options) {
  options = getOptions(options);

  prefix = getValidatedPath(prefix, 'prefix');
  warnOnNonPortableTemplate(prefix);

  const cwd = process.cwd();
  const path = await PromisePrototypeThen(
    binding.mkdtemp(prefix, options.encoding, kUsePromises),
    undefined,
    handleErrorFromBinding,
  );
  // Stash the full path in case of process.chdir()
  const fullPath = pathModule.resolve(cwd, path);

  const remove = async () => {
    const rmrf = lazyRimRaf();
    await rmrf(fullPath, {
      maxRetries: 0,
      recursive: true,
      retryDelay: 0,
    });
  };
  return {
    __proto__: null,
    path,
    remove,
    async [SymbolAsyncDispose]() {
      await remove();
    },
  };
}

async function writeFile(path, data, options) {
  options = getOptions(options, {
    encoding: 'utf8',
    mode: 0o666,
    flag: 'w',
    flush: false,
  });
  const flush = options.flush ?? false;
  validateBoolean(flush, 'options.flush');
  parseFileMode(options.mode, 'mode', 0o666);

  const h = vfsState.handlers;
  if (h !== null) {
    checkAborted(options.signal);
    const promise = h.writeFile(path, data, options);
    if (promise !== undefined) { await promise; return; }
  }

  const flag = options.flag || 'w';

  if (!isArrayBufferView(data) && !isCustomIterable(data)) {
    validateStringAfterArrayBufferView(data, 'data');
    data = Buffer.from(data, options.encoding || 'utf8');
  }

  validateAbortSignal(options.signal);
  if (path instanceof FileHandle)
    return writeFileHandle(path, data, options.signal, options.encoding);

  checkAborted(options.signal);

  if (!flush && !isCustomIterable(data) && data.byteLength <= kWriteFileMaxChunkSize) {
    path = getValidatedPath(path);
    await writeFileInOneRoundTrip(path, stringToFlags(flag, 'options.flag'),
                                  parseFileMode(options.mode, 'mode', 0o666), data);
    checkAborted(options.signal);  // An abort during the write still wins.
    return;
  }

  const fd = await open(path, flag, options.mode);
  let writeOp = writeFileHandle(fd, data, options.signal, options.encoding);

  if (flush) {
    writeOp = handleFdSync(writeOp, fd);
  }

  return handleFdClose(writeOp, fd.close);
}

/**
 * Open + write + close as one thread pool round trip.
 * @param {string|Buffer} path Validated path
 * @param {number} flagsNumber
 * @param {number} mode
 * @param {ArrayBufferView} data
 * @returns {Promise<void>}
 */
function writeFileInOneRoundTrip(path, flagsNumber, mode, data) {
  return new Promise((resolve, reject) => {
    const job = new binding.WriteFileJob(path, flagsNumber, mode, data);
    job.ondone = (err) => {
      if (err != null) {
        ErrorCaptureStackTrace(err, writeFileInOneRoundTrip);
        reject(err);
      } else {
        resolve();
      }
    };
    const accessError = job.run(path);
    if (accessError !== undefined) {
      ErrorCaptureStackTrace(accessError, writeFileInOneRoundTrip);
      reject(accessError);
    }
  });
}

function isCustomIterable(obj) {
  return isIterable(obj) && !isArrayBufferView(obj) && typeof obj !== 'string';
}

async function appendFile(path, data, options) {
  options = getOptions(options, { encoding: 'utf8', mode: 0o666, flag: 'a' });
  parseFileMode(options.mode, 'mode', 0o666);

  const h = vfsState.handlers;
  if (h !== null) {
    checkAborted(options.signal);
    const promise = h.appendFile(path, data, options);
    if (promise !== undefined) { await promise; return; }
  }
  options = copyObject(options);
  options.flag ||= 'a';
  return writeFile(path, data, options);
}

async function readFile(path, options) {
  const h = vfsState.handlers;
  if (h !== null) {
    checkAborted(options?.signal);
    const result = h.readFile(path, options);
    if (result !== undefined) return result;
  }
  options = getOptions(options, { flag: 'r' });
  validateReadFileBufferOptions(options);
  const flag = options.flag || 'r';

  if (path instanceof FileHandle)
    return readFileHandle(path, options);

  checkAborted(options.signal);

  if (options.buffer === undefined && vfsState.handlers === null) {
    // Open + fstat + read + close in one thread pool round trip for files of
    // up to one chunk; larger files come back as an open fd + size and are
    // read by readFileHandle() as before.
    path = getValidatedPath(path);
    const { 0: buffer, 1: fd, 2: size } = await readFileInOneRoundTrip(path, stringToFlags(flag));
    if (fd === -1) {
      checkAborted(options.signal);  // An abort during the read still wins.
      return options.encoding ? buffer.toString(options.encoding) : buffer;
    }
    const filehandle = new FileHandle(new binding.FileHandle(fd));
    return handleFdClose(readFileHandle(filehandle, options, size), filehandle.close);
  }

  const fd = await open(path, flag, 0o666);
  return handleFdClose(readFileHandle(fd, options), fd.close);
}

/**
 * @param {string|Buffer} path Validated path
 * @param {number} flagsNumber
 * @returns {Promise<[Buffer|undefined, number, number|undefined]>} [buffer, -1] or [undefined, fd, size]
 */
function readFileInOneRoundTrip(path, flagsNumber) {
  return new Promise((resolve, reject) => {
    const job = new binding.ReadFileJob(path, flagsNumber, kReadFileBufferLength);
    job.ondone = (err, buffer, fd, size, closeErr) => {
      const error = err ?? closeErr;
      if (error != null) {
        ErrorCaptureStackTrace(error, readFileInOneRoundTrip);
        reject(error);
      } else {
        resolve([buffer, fd, size]);
      }
    };
    const accessError = job.run(path);
    if (accessError !== undefined) {
      ErrorCaptureStackTrace(accessError, readFileInOneRoundTrip);
      reject(accessError);
    }
  });
}

async function* _watch(filename, options = kEmptyObject) {
  const h = vfsState.handlers;
  if (h !== null) {
    const result = h.promisesWatch(filename, options);
    if (result !== undefined) {
      yield* result;
      return;
    }
  }
  validateObject(options, 'options');

  if (options.recursive != null) {
    validateBoolean(options.recursive, 'options.recursive');

    // TODO(anonrig): Remove non-native watcher when/if libuv supports recursive.
    // As of November 2022, libuv does not support recursive file watch on all platforms,
    // e.g. Linux due to the limitations of inotify.
    if (options.recursive && !isMacOS && !isWindows) {
      const watcher = new nonNativeWatcher.FSWatcher(options);
      watcher[kFSWatchStart](filename);
      yield* watcher;
      return;
    }
  }

  yield* watch(filename, options);
}

const lazyGlob = getLazy(() => require('internal/fs/glob').Glob);
async function* glob(pattern, options) {
  const Glob = lazyGlob();
  yield* new Glob(pattern, options).glob();
}

module.exports = {
  exports: {
    access,
    copyFile,
    cp,
    glob,
    open,
    opendir: promisify(opendir),
    rename,
    truncate,
    rm,
    rmdir,
    mkdir,
    readdir,
    readlink,
    symlink,
    lstat,
    stat,
    statfs,
    link,
    unlink,
    chmod,
    lchmod,
    lchown,
    chown,
    utimes,
    lutimes,
    realpath,
    mkdtemp,
    mkdtempDisposable,
    writeFile,
    appendFile,
    readFile,
    watch: _watch,
    constants,
  },

  FileHandle,
  kHandle,
  kLocked,
  kRef,
  kUnref,
};

sources.internal/fs/read/context:
'use strict';

const {
  ArrayPrototypePush,
  FunctionPrototypeCall,
  MathMin,
} = primordials;

const {
  constants: {
    kReadFileBufferLength,
    kReadFileUnknownBufferLength,
  },
  createReadFileBufferTooSmallError,
  getReadFileBuffer,
  getReadFileBufferByteLengthName,
} = require('internal/fs/utils');

const { Buffer } = require('buffer');

const { FSReqCallback, close, read } = internalBinding('fs');

const {
  AbortError,
  aggregateTwoErrors,
} = require('internal/errors');

function readFileAfterRead(err, bytesRead) {
  const context = this.context;

  if (err)
    return context.close(err);

  if (context.checkOverflow) {
    context.checkOverflow = false;

    if (bytesRead !== 0) {
      return context.close(createReadFileBufferTooSmallError(
        context.bufferByteLengthName,
        context.buffer.byteLength,
      ));
    }

    return context.close();
  }

  context.pos += bytesRead;

  if (context.userBuffer) {
    if (context.pos === context.size || bytesRead === 0) {
      context.close();
    } else {
      context.read();
    }
    return;
  }

  if (context.pos === context.size || bytesRead === 0) {
    context.close();
  } else {
    if (context.size === 0) {
      // Unknown size, just read until we don't get bytes.
      const buffer = bytesRead === kReadFileUnknownBufferLength ?
        context.buffer : context.buffer.slice(0, bytesRead);
      ArrayPrototypePush(context.buffers, buffer);
    }
    context.read();
  }
}

function readFileAfterClose(err) {
  const context = this.context;
  const callback = context.callback;
  let buffer = null;

  if (context.err || err)
    return callback(aggregateTwoErrors(err, context.err));

  try {
    if (context.userBuffer) {
      buffer = context.buffer.subarray(0, context.pos);
    } else if (context.size === 0) {
      buffer = Buffer.concat(context.buffers, context.pos);
    } else if (context.pos < context.size) {
      buffer = context.buffer.slice(0, context.pos);
    } else {
      buffer = context.buffer;
    }

    if (context.encoding)
      buffer = buffer.toString(context.encoding);
  } catch (err) {
    return callback(err);
  }

  callback(null, buffer);
}

class ReadFileContext {
  constructor(callback, options) {
    this.fd = undefined;
    this.isUserFd = undefined;
    this.size = 0;
    this.callback = callback;
    this.buffers = null;
    this.buffer = null;
    this.pos = 0;
    this.encoding = options.encoding;
    this.options = options;
    this.err = null;
    this.signal = undefined;
    this.userBuffer = false;
    this.bufferByteLengthName = null;
    this.overflowBuffer = null;
    this.checkOverflow = false;
  }

  prepare() {
    const buffer = getReadFileBuffer(this.options, this.size);

    if (buffer !== undefined) {
      this.buffer = buffer;
      this.userBuffer = true;
      this.bufferByteLengthName = getReadFileBufferByteLengthName(this.options);
      return;
    }

    if (this.size === 0) {
      this.buffers = [];
    } else {
      this.buffer = Buffer.allocUnsafeSlow(this.size);
    }
  }

  read() {
    let buffer;
    let offset;
    let length;

    if (this.signal?.aborted) {
      return this.close(
        new AbortError(undefined, { cause: this.signal.reason }));
    }

    if (this.userBuffer) {
      if (this.size === 0) {
        buffer = this.buffer;
        offset = this.pos;
        length = this.buffer.byteLength - this.pos;

        if (length === 0) {
          buffer = this.overflowBuffer ??= Buffer.allocUnsafeSlow(1);
          offset = 0;
          length = 1;
          this.checkOverflow = true;
        }
      } else {
        buffer = this.buffer;
        offset = this.pos;
        length = MathMin(kReadFileBufferLength, this.size - this.pos);
      }
    } else if (this.size === 0) {
      buffer = Buffer.allocUnsafeSlow(kReadFileUnknownBufferLength);
      offset = 0;
      length = kReadFileUnknownBufferLength;
      this.buffer = buffer;
    } else {
      buffer = this.buffer;
      offset = this.pos;
      length = MathMin(kReadFileBufferLength, this.size - this.pos);
    }

    const req = new FSReqCallback();
    req.oncomplete = readFileAfterRead;
    req.context = this;

    read(this.fd, buffer, offset, length, -1, req);
  }

  close(err) {
    if (this.isUserFd) {
      process.nextTick(function tick(context) {
        FunctionPrototypeCall(readFileAfterClose, { context }, null);
      }, this);
      return;
    }

    const req = new FSReqCallback();
    req.oncomplete = readFileAfterClose;
    req.context = this;
    this.err = err;

    close(this.fd, req);
  }
}

module.exports = ReadFileContext;

sources.internal/fs/recursive_watch:
'use strict';

const {
  Promise,
  SafeMap,
  SafeSet,
  StringPrototypeStartsWith,
  SymbolAsyncIterator,
} = primordials;

const { EventEmitter } = require('events');
const assert = require('internal/assert');
const {
  AbortError,
  codes: {
    ERR_INVALID_ARG_VALUE,
  },
} = require('internal/errors');
const { getValidatedPath } = require('internal/fs/utils');
const { createIgnoreMatcher, kFSWatchStart } = require('internal/fs/watchers');
const { kEmptyObject } = require('internal/util');
const { validateBoolean, validateAbortSignal, validateIgnoreOption } = require('internal/validators');
const {
  basename: pathBasename,
  join: pathJoin,
  relative: pathRelative,
  resolve: pathResolve,
  sep: pathSep,
} = require('path');

let internalSync;

function lazyLoadFsSync() {
  internalSync ??= require('fs');
  return internalSync;
}

let kResistStopPropagation;

const kIsAIX = process.platform === 'aix';

function isPathMissingForWatch(error, file) {
  if (error.code === 'ENOENT') {
    return true;
  }
  // AIX reports ENODEV when the path disappears before fs.watch() starts.
  // Check that it is actually gone so other ENODEV errors still propagate.
  if (!kIsAIX || error.code !== 'ENODEV') {
    return false;
  }
  try {
    return lazyLoadFsSync().statSync(file, { throwIfNoEntry: false }) === undefined;
  } catch {
    return false;
  }
}

// Inotify reports changes to a directory's entries, with their names, on the
// directory's own watch, so one watcher per directory is enough on Linux.
// kqueue and event ports only report that the directory itself changed, so
// elsewhere every file keeps a watcher of its own as well.
const kDirectoryWatchReportsEntries = process.platform === 'linux';

class FSWatcher extends EventEmitter {
  #options = null;
  #closed = false;
  // Every path below the root that has been reported (or existed at start).
  #entries = new SafeSet();
  // One fs.watch() per directory and symbolic link (and per file where the
  // directory watch does not report its entries).
  #watchers = new SafeMap();
  #symbolicLinks = new SafeSet();
  #rootPath = pathResolve();
  #ignoreMatcher = null;

  constructor(options = kEmptyObject) {
    super();

    assert(typeof options === 'object');

    const { persistent, recursive, signal, encoding, ignore } = options;
    let { throwIfNoEntry } = options;

    // TODO(anonrig): Add non-recursive support to non-native-watcher for IBMi & AIX support.
    if (recursive != null) {
      validateBoolean(recursive, 'options.recursive');
    }

    if (persistent != null) {
      validateBoolean(persistent, 'options.persistent');
    }

    if (signal != null) {
      validateAbortSignal(signal, 'options.signal');
    }

    if (throwIfNoEntry != null) {
      validateBoolean(throwIfNoEntry, 'options.throwIfNoEntry');
    } else {
      throwIfNoEntry = true;
    }

    if (encoding != null) {
      // This is required since on macOS and Windows it throws ERR_INVALID_ARG_VALUE
      if (typeof encoding !== 'string') {
        throw new ERR_INVALID_ARG_VALUE('options.encoding', encoding);
      }
    }

    validateIgnoreOption(ignore, 'options.ignore');
    this.#ignoreMatcher = createIgnoreMatcher(ignore);

    this.#options = { persistent, recursive, signal, encoding, throwIfNoEntry };
  }

  close() {
    if (this.#closed) {
      return;
    }

    this.#closed = true;

    for (const watcher of this.#watchers.values()) {
      watcher.close();
    }
    this.#watchers.clear();
    this.#entries.clear();
    this.#symbolicLinks.clear();
    this.emit('close');
  }

  #emit(eventType, file) {
    this.emit('change', eventType, pathRelative(this.#rootPath, file));
  }

  #forget(file) {
    const watcher = this.#watchers.get(file);
    if (watcher !== undefined) {
      watcher.close();
      this.#watchers.delete(file);
    }
    this.#entries.delete(file);
    this.#symbolicLinks.delete(file);

    const childPrefix = file + pathSep;
    for (const entry of this.#entries) {
      if (StringPrototypeStartsWith(entry, childPrefix)) {
        this.#entries.delete(entry);
        this.#symbolicLinks.delete(entry);
        const childWatcher = this.#watchers.get(entry);
        if (childWatcher !== undefined) {
          childWatcher.close();
          this.#watchers.delete(entry);
        }
      }
    }
  }

  // Report an entry that vanished between being listed and being watched so
  // the caller can discard its stale bookkeeping.
  #watch(file, onChange) {
    if (this.#closed) {
      return false;
    }
    if (this.#watchers.has(file)) {
      return true;
    }
    const { watch } = lazyLoadFsSync();
    let watcher;
    try {
      watcher = watch(file, { persistent: this.#options.persistent }, onChange);
    } catch (err) {
      if (isPathMissingForWatch(err, file) &&
          (file !== this.#rootPath || !this.#options.throwIfNoEntry)) {
        return false;
      }
      throw err;
    }
    this.#watchers.set(file, watcher);
    return true;
  }

  // Arms one watcher for `folder`, then registers entries that are not known
  // yet (emitting 'rename' for them unless this is the initial scan);
  // #addEntry() descends into subdirectories.
  #scanFolder(folder, initial) {
    if (!this.#watch(folder, (eventType, filename) => this.#onFolderEvent(folder, filename))) {
      this.#forget(folder);
      return;
    }

    const { readdirSync } = lazyLoadFsSync();
    let entries;
    try {
      entries = readdirSync(folder, { withFileTypes: true });
    } catch (error) {
      if (error.code === 'ENOENT' || error.code === 'ENOTDIR') {
        if (folder === this.#rootPath && initial &&
            (error.code !== 'ENOENT' || this.#options.throwIfNoEntry)) {
          throw error;
        }
        if (!initial && !this.#closed) {
          this.#emit('rename', folder);
        }
        this.#forget(folder);
      } else {
        this.emit('error', error);
      }
      return;
    }

    for (const entry of entries) {
      if (this.#closed) {
        break;
      }
      const file = pathJoin(folder, entry.name);
      if (!this.#entries.has(file) && !this.#ignoreMatcher?.(pathRelative(this.#rootPath, file))) {
        this.#addEntry(file, entry, initial);
      }
    }
  }

  // `entry` is the Dirent or the lstat() Stats of `file`.
  #addEntry(file, entry, initial) {
    this.#entries.add(file);
    if (!initial) {
      this.#emit('rename', file);
    }
    if (entry.isSymbolicLink()) {
      // The link target is watched so that changes behind the link surface
      // as a 'rename' of the link, as they always have on this code path.
      this.#symbolicLinks.add(file);
      if (!this.#watch(file, () => this.#emit('rename', file))) {
        this.#forget(file);
      }
    } else if (entry.isDirectory()) {
      this.#scanFolder(file, initial);
    } else if (!kDirectoryWatchReportsEntries) {
      if (!this.#watch(file, () => this.#onEntryEvent(file))) {
        this.#forget(file);
      }
    }
  }

  #onFolderEvent(folder, filename) {
    if (this.#closed) {
      return;
    }
    const { lstatSync, statSync } = lazyLoadFsSync();
    if (!kDirectoryWatchReportsEntries || filename == null) {
      // All that is known is that something about `folder` changed.
      if (statSync(folder, { throwIfNoEntry: false }) === undefined) {
        this.#emit('rename', folder);
        this.#forget(folder);
      } else {
        this.#scanFolder(folder, false);
      }
      return;
    }
    // Events about the watched directory itself are reported under its own
    // name; those take the "unknown entry" path and are resolved by the parent.
    const file = pathJoin(folder, filename);

    if (!this.#entries.has(file)) {
      if (this.#ignoreMatcher?.(pathRelative(this.#rootPath, file))) {
        return;
      }
      const entry = lstatSync(file, { throwIfNoEntry: false });
      if (entry !== undefined) {
        this.#addEntry(file, entry, false);
      } else if (folder === this.#rootPath && statSync(folder, { throwIfNoEntry: false }) === undefined) {
        this.#emit('rename', folder);
        this.#forget(folder);
      }
      return;
    }

    this.#onEntryEvent(file);
  }

  // Something happened to a known entry: work out what from its current state.
  #onEntryEvent(file) {
    if (this.#closed) {
      return;
    }
    const { statSync } = lazyLoadFsSync();
    const stats = statSync(file, { throwIfNoEntry: false });
    if (stats === undefined) {
      this.#emit('rename', file);
      this.#forget(file);
    } else if (this.#symbolicLinks.has(file)) {
      this.#emit('rename', file);
    } else if (stats.isDirectory()) {
      this.#scanFolder(file, false);
    } else {
      this.#emit('change', file);
    }
  }

  #watchRootFile(file) {
    const { statSync } = lazyLoadFsSync();
    this.#entries.add(file);
    if (!this.#watch(file, () => {
      if (this.#closed) {
        return;
      }
      if (statSync(file, { throwIfNoEntry: false }) === undefined) {
        this.#emit('rename', file);
        this.#forget(file);
      } else {
        this.emit('change', 'change', pathBasename(file));
      }
    })) {
      this.#forget(file);
    }
  }

  [kFSWatchStart](filename) {
    filename = pathResolve(getValidatedPath(filename));

    try {
      const file = lazyLoadFsSync().statSync(filename);

      this.#rootPath = filename;
      this.#closed = false;

      if (file.isDirectory()) {
        this.#scanFolder(filename, true);
      } else {
        this.#watchRootFile(filename);
      }
    } catch (error) {
      if (this.#options.throwIfNoEntry || error.code !== 'ENOENT') {
        error.filename = filename;
        this.close();
        throw error;
      }
    }

  }

  ref() {
    for (const watcher of this.#watchers.values()) {
      watcher.ref();
    }
  }

  unref() {
    for (const watcher of this.#watchers.values()) {
      watcher.unref();
    }
  }

  [SymbolAsyncIterator]() {
    const { signal } = this.#options;
    const promiseExecutor = signal == null ?
      (resolve) => {
        this.once('change', (eventType, filename) => {
          resolve({ __proto__: null, value: { eventType, filename } });
        });
      } : (resolve, reject) => {
        const onAbort = () => {
          this.close();
          reject(new AbortError(undefined, { cause: signal.reason }));
        };
        if (signal.aborted) return onAbort();
        kResistStopPropagation ??= require('internal/event_target').kResistStopPropagation;
        signal.addEventListener('abort', onAbort, { __proto__: null, once: true, [kResistStopPropagation]: true });
        this.once('change', (eventType, filename) => {
          signal.removeEventListener('abort', onAbort);
          resolve({ __proto__: null, value: { eventType, filename } });
        });
      };
    return {
      next: () => (this.#closed ?
        { __proto__: null, done: true } :
        new Promise(promiseExecutor)),
      return: () => {
        this.close();
        return { __proto__: null, done: true };
      },
      [SymbolAsyncIterator]() { return this; },
    };
  }
}

module.exports = {
  FSWatcher,
  kFSWatchStart,
};

