'use strict';

const { Storage } = internalBinding('webstorage');
const { DOMStorage } = require('inspector');
const path = require('path');
const { getOptionValue } = require('internal/options');

class InspectorLocalStorage extends Storage {
  setItem(key, value) {
    key = `${key}`;
    value = `${value}`;
    const oldValue = this.getItem(key);
    super.setItem(key, value);
    if (oldValue == null) {
      itemAdded(key, value, true);
    } else {
      itemUpdated(key, oldValue, value, true);
    }
  }

  removeItem(key) {
    key = `${key}`;
    super.removeItem(key);
    itemRemoved(key, true);
  }

  clear() {
    super.clear();
    itemsCleared(true);
  }
}

const InspectorSessionStorage = class extends Storage {
  setItem(key, value) {
    key = `${key}`;
    value = `${value}`;
    const oldValue = this.getItem(key);
    super.setItem(key, value);
    if (oldValue == null) {
      itemAdded(key, value, false);
    } else {
      itemUpdated(key, oldValue, value, false);
    }
  }

  removeItem(key) {
    key = `${key}`;
    super.removeItem(key);
    itemRemoved(key, false);
  }

  clear() {
    super.clear();
    itemsCleared(false);
  }
};

function itemAdded(key, value, isLocalStorage) {
  DOMStorage.domStorageItemAdded({
    key,
    newValue: value,
    storageId: {
      securityOrigin: '',
      isLocalStorage,
      storageKey: getStorageKey(),
    },
  });
}

function itemUpdated(key, oldValue, newValue, isLocalStorage) {
  DOMStorage.domStorageItemUpdated({
    key,
    oldValue,
    newValue,
    storageId: {
      securityOrigin: '',
      isLocalStorage,
      storageKey: getStorageKey(),
    },
  });
}

function itemRemoved(key, isLocalStorage) {
  DOMStorage.domStorageItemRemoved({
    key,
    storageId: {
      securityOrigin: '',
      isLocalStorage,
      storageKey: getStorageKey(),
    },
  });
}

function itemsCleared(isLocalStorage) {
  DOMStorage.domStorageItemsCleared({
    storageId: {
      securityOrigin: '',
      isLocalStorage,
      storageKey: getStorageKey(),
    },
  });
}

function getStorageKey() {
  const localStorageFile = getOptionValue('--localstorage-file');
  const resolvedAbsolutePath = path.resolve(localStorageFile);
  return 'file://' + resolvedAbsolutePath;
}

module.exports = {
  InspectorLocalStorage,
  InspectorSessionStorage,
};

sources.internal/inspector_async_hook:
'use strict';

let hook;
let config;

function lazyHookCreation() {
  const inspector = internalBinding('inspector');
  const { createHook } = require('async_hooks');
  config = internalBinding('config');

  hook = createHook({
    init(asyncId, type, triggerAsyncId, resource) {
    // It's difficult to tell which tasks will be recurring and which won't,
    // therefore we mark all tasks as recurring. Based on the discussion
    // in https://github.com/nodejs/node/pull/13870#discussion_r124515293,
    // this should be fine as long as we call asyncTaskCanceled() too.
      const recurring = true;
      inspector.asyncTaskScheduled(type, asyncId, recurring);
    },

    before(asyncId) {
      inspector.asyncTaskStarted(asyncId);
    },

    after(asyncId) {
      inspector.asyncTaskFinished(asyncId);
    },

    destroy(asyncId) {
      inspector.asyncTaskCanceled(asyncId);
    },
    trackPromises: false,
  });
}

function enable() {
  if (hook === undefined) lazyHookCreation();
  if (config.bits < 64) {
    // V8 Inspector stores task ids as (void*) pointers.
    // async_hooks store ids as 64bit numbers.
    // As a result, we cannot reliably translate async_hook ids to V8 async_task
    // ids on 32bit platforms.
    process.emitWarning(
      'Warning: Async stack traces in debugger are not available ' +
      `on ${config.bits}bit platforms. The feature is disabled.`,
      {
        code: 'INSPECTOR_ASYNC_STACK_TRACES_NOT_AVAILABLE',
      });
  } else {
    hook.enable();
  }
}

function disable() {
  if (hook === undefined) lazyHookCreation();
  hook.disable();
}

module.exports = {
  enable,
  disable,
};

