sources.internal/main/mksnapshot:
'use strict';

const {
  Error,
  ObjectDefineProperty,
  ObjectGetOwnPropertyDescriptor,
  ObjectSetPrototypeOf,
  SafeArrayIterator,
  SafeSet,
} = primordials;

const { BuiltinModule: { normalizeRequirableId } } = require('internal/bootstrap/realm');
const {
  compileSerializeMain,
  anonymousMainPath,
} = internalBinding('mksnapshot');

const { isExperimentalSeaWarningNeeded } = internalBinding('sea');

const { emitExperimentalWarning } = require('internal/util');
const { emitWarningSync } = require('internal/process/warning');

const {
  namespace: {
    addDeserializeCallback,
    isBuildingSnapshot,
  },
  addAfterUserSerializeCallback,
} = require('internal/v8/startup_snapshot');

const {
  prepareMainThreadExecution,
} = require('internal/process/pre_execution');

const path = require('path');
const { getOptionValue } = require('internal/options');

const supportedModules = new SafeSet(new SafeArrayIterator([
  // '_http_agent',
  // '_http_client',
  // '_http_common',
  // '_http_incoming',
  // '_http_outgoing',
  // '_http_server',
  // '_tls_common',
  // '_tls_wrap',
  'assert',
  'assert/strict',
  // 'async_hooks',
  'buffer',
  // 'child_process',
  // 'cluster',
  'console',
  'constants',
  'crypto',
  // 'dgram',
  'diagnostics_channel',
  'dns',
  // 'dns/promises',
  // 'domain',
  'events',
  'fs',
  'fs/promises',
  // 'http',
  // 'http2',
  // 'https',
  // 'inspector',
  // 'module',
  'net',
  'os',
  'path',
  'path/posix',
  'path/win32',
  // 'perf_hooks',
  'process',
  'punycode',
  'querystring',
  // 'readline',
  // 'repl',
  'stream',
  'stream/promises',
  'string_decoder',
  'sys',
  'timers',
  'timers/promises',
  // 'tls',
  // 'trace_events',
  // 'tty',
  'url',
  'util',
  'util/types',
  'v8',
  // 'vm',
  // 'worker_threads',
  'zlib',
]));

const warnedModules = new SafeSet();
function supportedInUserSnapshot(id) {
  return supportedModules.has(id);
}

function requireForUserSnapshot(id) {
  const normalizedId = normalizeRequirableId(id);
  if (!normalizedId) {
    // eslint-disable-next-line no-restricted-syntax
    const err = new Error(
      `Cannot find module '${id}'. `,
    );
    err.code = 'MODULE_NOT_FOUND';
    throw err;
  }
  if (isBuildingSnapshot() && !supportedInUserSnapshot(normalizedId)) {
    if (!warnedModules.has(normalizedId)) {
      // Emit the warning synchronously in case we don't get to process
      // the tick and print it before the unsupported built-in causes a
      // crash.
      emitWarningSync(
        `It's not yet fully verified whether built-in module "${id}" ` +
        'works in user snapshot builder scripts.\n' +
        'It may still work in some cases, but in other cases certain ' +
        'run-time states may be out-of-sync after snapshot deserialization.\n' +
        'To request support for the module, use the Node.js issue tracker: ' +
        'https://github.com/nodejs/node/issues');
      warnedModules.add(normalizedId);
    }
  }

  return require(normalizedId);
}


function main() {
  prepareMainThreadExecution(false, false);

  // In a context created for building snapshots, V8 does not install Error.stackTraceLimit and as
  // a result, if an error is created during the snapshot building process, error.stack would be
  // undefined. To prevent users from tripping over this, install Error.stackTraceLimit based on
  // --stack-trace-limit by ourselves (which defaults to 10).
  // See https://chromium-review.googlesource.com/c/v8/v8/+/3319481
  const initialStackTraceLimitDesc = {
    value: getOptionValue('--stack-trace-limit'),
    configurable: true,
    writable: true,
    enumerable: true,
    __proto__: null,
  };
  ObjectDefineProperty(Error, 'stackTraceLimit', initialStackTraceLimitDesc);

  let stackTraceLimitDescToRestore;
  // Error.stackTraceLimit needs to be removed during serialization, because when V8 deserializes
  // the snapshot, it expects Error.stackTraceLimit to be unset so that it can install it as a new property
  // using the value of --stack-trace-limit.
  addAfterUserSerializeCallback(() => {
    const desc = ObjectGetOwnPropertyDescriptor(Error, 'stackTraceLimit');

    // If it's modified by users, emit a warning.
    if (desc && (
      desc.value !== initialStackTraceLimitDesc.value ||
        desc.configurable !== initialStackTraceLimitDesc.configurable ||
        desc.writable !== initialStackTraceLimitDesc.writable ||
        desc.enumerable !== initialStackTraceLimitDesc.enumerable
    )) {
      process._rawDebug('Error.stackTraceLimit has been modified by the snapshot builder script.');
      // We want to use null-prototype objects to not rely on globally mutable
      // %Object.prototype%.
      if (desc.configurable) {
        stackTraceLimitDescToRestore = desc;
        ObjectSetPrototypeOf(stackTraceLimitDescToRestore, null);
        process._rawDebug('It will be preserved after snapshot deserialization and override ' +
                          '--stack-trace-limit passed into the deserialized application.\n' +
                          'To allow --stack-trace-limit override in the deserialized application, ' +
                          'delete Error.stackTraceLimit.');
      } else {
        process._rawDebug('It is not configurable and will crash the application upon deserialization.\n' +
                          'To fix the error, make Error.stackTraceLimit configurable.');
      }
    }

    delete Error.stackTraceLimit;
  });

  addDeserializeCallback(() => {
    if (stackTraceLimitDescToRestore) {
      ObjectDefineProperty(Error, 'stackTraceLimit', stackTraceLimitDescToRestore);
    }
  });

  // TODO(addaleax): Make this `embedderRunCjs` once require('module')
  // is supported in snapshots.
  function minimalRunCjs(source) {
    let filename;
    let dirname;
    if (process.argv[1] === anonymousMainPath) {
      filename = dirname = process.argv[1];
    } else {
      filename = path.resolve(process.argv[1]);
      dirname = path.dirname(filename);
    }

    const fn = compileSerializeMain(filename, source);
    return fn(requireForUserSnapshot, filename, dirname);
  }

  if (isExperimentalSeaWarningNeeded()) {
    emitExperimentalWarning('Single executable application');
  }

  return [process, requireForUserSnapshot, minimalRunCjs];
}

return main();

sources.internal/main/print_help:
'use strict';

const {
  ArrayPrototypeConcat,
  ArrayPrototypeSort,
  Boolean,
  MathFloor,
  MathMax,
  ObjectKeys,
  RegExp,
  RegExpPrototypeSymbolReplace,
  SafeMap,
  StringPrototypeLocaleCompare,
  StringPrototypeRepeat,
  StringPrototypeSlice,
  StringPrototypeTrimStart,
} = primordials;

const { types } = internalBinding('options');
const hasCrypto = Boolean(process.versions.openssl);

const {
  prepareMainThreadExecution,
  markBootstrapComplete,
} = require('internal/process/pre_execution');

const { getCLIOptionsInfo, getOptionValue } = require('internal/options');
const { styleText } = require('util');

const typeLookup = [];
for (const key of ObjectKeys(types))
  typeLookup[types[key]] = key;

function style(format, text) {
  return styleText(format, text, { stream: process.stdout });
}

// Environment variables are parsed ad-hoc throughout the code base,
// so we gather the documentation here.
const { hasIntl, hasSmallICU, hasNodeOptions } = internalBinding('config');
// eslint-disable-next-line node-core/avoid-prototype-pollution
const envVars = new SafeMap(ArrayPrototypeConcat([
  ['FORCE_COLOR', { helpText: "when set to 'true', 1, 2, 3, or an empty " +
   'string causes NO_COLOR and NODE_DISABLE_COLORS to be ignored.' }],
  ['NO_COLOR', { helpText: 'Alias for NODE_DISABLE_COLORS' }],
  ['NODE_DEBUG', { helpText: "','-separated list of core modules that " +
    'should print debug information' }],
  ['NODE_DEBUG_NATIVE', { helpText: "','-separated list of C++ core debug " +
    'categories that should print debug output' }],
  ['NODE_DISABLE_COLORS', { helpText: 'set to 1 to disable colors in ' +
    'the REPL' }],
  ['NODE_EXTRA_CA_CERTS', { helpText: 'path to additional CA certificates ' +
    'file. Only read once during process startup.' }],
  ['NODE_NO_WARNINGS', { helpText: 'set to 1 to silence process warnings' }],
  ['NODE_PATH', { helpText: `'${require('path').delimiter}'-separated list ` +
    'of directories prefixed to the module search path' }],
  ['NODE_PENDING_DEPRECATION', { helpText: 'set to 1 to emit pending ' +
    'deprecation warnings' }],
  ['NODE_PENDING_PIPE_INSTANCES', { helpText: 'set the number of pending ' +
    'pipe instance handles on Windows' }],
  ['NODE_PRESERVE_SYMLINKS', { helpText: 'set to 1 to preserve symbolic ' +
    'links when resolving and caching modules' }],
  ['NODE_REDIRECT_WARNINGS', { helpText: 'write warnings to path instead ' +
    'of stderr' }],
  ['NODE_REPL_HISTORY', { helpText: 'path to the persistent REPL ' +
    'history file' }],
  ['NODE_REPL_EXTERNAL_MODULE', { helpText: 'path to a Node.js module ' +
    'which will be loaded in place of the built-in REPL' }],
  ['NODE_SKIP_PLATFORM_CHECK', { helpText: 'set to 1 to skip ' +
    'the check for a supported platform during Node.js startup' }],
  ['NODE_TLS_REJECT_UNAUTHORIZED', { helpText: 'set to 0 to disable TLS ' +
    'certificate validation' }],
  ['NODE_V8_COVERAGE', { helpText: 'directory to output v8 coverage JSON ' +
    'to' }],
  ['TZ', { helpText: 'specify the timezone configuration' }],
  ['UV_THREADPOOL_SIZE', { helpText: 'sets the number of threads used in ' +
    'libuv\'s threadpool' }],
], hasIntl ? [
  ['NODE_ICU_DATA', { helpText: 'data path for ICU (Intl object) data' +
    hasSmallICU ? '' : ' (will extend linked-in data)' }],
] : []), (hasNodeOptions ? [
  ['NODE_OPTIONS', { helpText: 'set CLI options in the environment via a ' +
    'space-separated list' }],
] : []), hasCrypto ? [
  ['OPENSSL_CONF', { helpText: 'load OpenSSL configuration from file' }],
  ['SSL_CERT_DIR', { helpText: 'sets OpenSSL\'s directory of trusted ' +
    'certificates when used in conjunction with --use-openssl-ca' }],
  ['SSL_CERT_FILE', { helpText: 'sets OpenSSL\'s trusted certificate file ' +
    'when used in conjunction with --use-openssl-ca' }],
] : []);


function indent(text, depth) {
  return RegExpPrototypeSymbolReplace(/^/gm, text, StringPrototypeRepeat(' ', depth));
}

function fold(text, width) {
  return RegExpPrototypeSymbolReplace(
    new RegExp(`([^\n]{0,${width}})( |$)`, 'g'),
    text,
    (_, newLine, end) => newLine + (end === ' ' ? '\n' : ''),
  );
}

function getArgDescription(type) {
  switch (typeLookup[type]) {
    case 'kNoOp':
    case 'kV8Option':
    case 'kBoolean':
    case undefined:
      break;
    case 'kHostPort':
      return '[host:]port';
    case 'kInteger':
    case 'kUInteger':
    case 'kString':
    case 'kStringList':
      return '...';
    default:
      require('assert').fail(`unknown option type ${type}`);
  }
}

function format(
  { options, aliases = new SafeMap(), firstColumn, secondColumn, nameStyle = [] },
) {
  let text = '';
  let maxFirstColumnUsed = 0;

  const sortedOptions = ArrayPrototypeSort(
    [...options.entries()],
    ({ 0: name1, 1: option1 }, { 0: name2, 1: option2 }) => {
      if (option1.defaultIsTrue) {
        name1 = `--no-${StringPrototypeSlice(name1, 2)}`;
      }
      if (option2.defaultIsTrue) {
        name2 = `--no-${StringPrototypeSlice(name2, 2)}`;
      }
      return StringPrototypeLocaleCompare(name1, name2);
    },
  );

  for (const {
    0: name, 1: { helpText, type, defaultIsTrue },
  } of sortedOptions) {
    if (!helpText) continue;
    const value = getOptionValue(name);

    let displayName = name;

    if (defaultIsTrue) {
      displayName = `--no-${StringPrototypeSlice(displayName, 2)}`;
    }

    const argDescription = getArgDescription(type);
    if (argDescription)
      displayName += `=${argDescription}`;

    for (const { 0: from, 1: to } of aliases) {
      // For cases like e.g. `-e, --eval`.
      if (to[0] === name && to.length === 1) {
        displayName = `${from}, ${displayName}`;
      }

      // For cases like `--inspect-brk[=[host:]port]`.
      const targetInfo = options.get(to[0]);
      const targetArgDescription =
        targetInfo ? getArgDescription(targetInfo.type) : '...';
      if (from === `${name}=`) {
        displayName += `[=${targetArgDescription}]`;
      } else if (from === `${name} <arg>`) {
        displayName += ` [${targetArgDescription}]`;
      }
    }

    let displayHelpText = helpText;
    if (value === !defaultIsTrue) {
      // Mark boolean options we currently have enabled.
      // In particular, it indicates whether --use-openssl-ca
      // or --use-bundled-ca is the (current) default.
      displayHelpText += ' (currently set)';
    }

    text += style(nameStyle, displayName);
    maxFirstColumnUsed = MathMax(maxFirstColumnUsed, displayName.length);
    if (displayName.length >= firstColumn)
      text += '\n' + StringPrototypeRepeat(' ', firstColumn);
    else
      text += StringPrototypeRepeat(' ', firstColumn - displayName.length);

    text += StringPrototypeTrimStart(
      indent(fold(displayHelpText, secondColumn), firstColumn)) + '\n';
  }

  if (maxFirstColumnUsed < firstColumn - 4) {
    // If we have more than 4 blank gap spaces, reduce first column width.
    return format({
      options,
      aliases,
      firstColumn: maxFirstColumnUsed + 2,
      secondColumn,
      nameStyle,
    });
  }

  return text;
}

function print(stream) {
  const { options, aliases } = getCLIOptionsInfo();
  const console = require('internal/console/global');

  // Use 75 % of the available width, and at least 70 characters.
  const width = MathMax(70, (stream.columns || 0) * 0.75);
  const firstColumn = MathFloor(width * 0.4);
  const secondColumn = MathFloor(width * 0.57);

  options.set('-', { helpText: 'script read from stdin ' +
                               '(default if no file name is provided, ' +
                               'interactive mode if a tty)' });
  options.set('--', { helpText: 'indicate the end of node options' });
  let helpText = (
    style('bold',
          'Usage: node [options] [ script.js ] [arguments]\n' +
      '       node inspect [options] [ script.js | host:port ] [arguments]') +
    '\n\n' + style('bold', 'Options:') + '\n');
  helpText += (indent(format({
    options, aliases, firstColumn, secondColumn, nameStyle: ['bold', 'green'],
  }), 2));

  helpText += ('\n' + style('bold', 'Environment variables:') + '\n');

  helpText += (format({
    options: envVars, firstColumn, secondColumn, nameStyle: ['bold', 'magenta'],
  }));

  helpText += ('\nDocumentation can be found at ' +
    style(['blue', 'underline'], 'https://nodejs.org/'));

  helpText = RegExpPrototypeSymbolReplace(
    / \(currently set\)/g,
    helpText,
    style('dim', ' (currently set)'),
  );

  console.log(helpText);
}

prepareMainThreadExecution();

markBootstrapComplete();

print(process.stdout);

sources.internal/main/prof_process:
'use strict';

// This main script is used by --prof-process to process logs generated by --prof.
// The tick processor implementation is vendor-in from V8, placed in deps/v8/tools,
// and they have different resolution rules compared to normal Node.js internal builtins,
// despite being embedded into the binary as a built-in as well.

// TODO(joyeecheung): put the context locals in import.meta.
const {
  ObjectAssign,
  PromisePrototypeThen,
  globalThis,
} = primordials;

const {
  prepareMainThreadExecution,
  markBootstrapComplete,
} = require('internal/process/pre_execution');

const { importBuiltinSourceTextModule } = internalBinding('builtins');
const { triggerUncaughtException } = internalBinding('errors');

prepareMainThreadExecution();
markBootstrapComplete();

// Polyfill the context with globals needed by the tick processor.
const { globals, openFile } = require('internal/v8_prof_polyfill');
ObjectAssign(globalThis, globals);
openFile(process.argv[process.argv.length - 1]);

// Load and evaluate the V8 tick processor as a source text module.
const { promise } = importBuiltinSourceTextModule('internal/deps/v8/tools/tickprocessor-driver');
// We must catch the rejection asynchronously to print it out properly since
// the tick processor contains top level await.
PromisePrototypeThen(promise, undefined, (err) => {
  triggerUncaughtException(err, true /* fromPromise */);
});

sources.internal/main/repl:
'use strict';

// Create the REPL if `-i` or `--interactive` is passed, or if
// the main module is not specified and stdin is a TTY.

const {
  prepareMainThreadExecution,
  markBootstrapComplete,
} = require('internal/process/pre_execution');

const {
  evalScript,
} = require('internal/process/execution');

const console = require('internal/console/global');

const { getOptionValue } = require('internal/options');

const { exitCodes: { kInvalidCommandLineArgument } } = internalBinding('errors');

prepareMainThreadExecution();

markBootstrapComplete();

if (process.env.NODE_REPL_EXTERNAL_MODULE) {
  require('internal/modules/cjs/loader')
    .wrapModuleLoad(process.env.NODE_REPL_EXTERNAL_MODULE, undefined, true);
} else {
  // --input-type flag not supported in REPL
  if (getOptionValue('--input-type')) {
    // If we can't write to stderr, we'd like to make this a noop,
    // so use console.error.
    console.error('Cannot specify --input-type for REPL');
    process.exit(kInvalidCommandLineArgument);
  }

  require('internal/modules/run_main').runEntryPointWithESMLoader(() => {
    console.log(`Welcome to Node.js ${process.version}.\n` +
      'Type ".help" for more information.');

    const cliRepl = require('internal/repl');
    cliRepl.createInternalRepl(process.env, (err, repl) => {
      if (err) {
        throw err;
      }
      repl.on('exit', () => {
        if (repl.historyManager.isFlushing) {
          return repl.once('flushHistory', () => {
            process.exit();
          });
        }
        process.exit();
      });
    });

    // If user passed '-e' or '--eval' along with `-i` or `--interactive`,
    // evaluate the code in the current context.
    if (getOptionValue('[has_eval_string]')) {
      evalScript('[eval]',
                 getOptionValue('--eval'),
                 getOptionValue('--inspect-brk'),
                 getOptionValue('--print'));
    }
    // The TLAs in the REPL are still run as scripts, just transformed as async
    // IIFEs for the REPL code itself to await on.
  });
}

sources.internal/main/run_main_module:
'use strict';

const {
  RegExpPrototypeExec,
} = primordials;

const {
  prepareMainThreadExecution,
  markBootstrapComplete,
} = require('internal/process/pre_execution');
const { getOptionValue } = require('internal/options');
const { emitExperimentalWarning } = require('internal/util');

const isEntryURL = getOptionValue('--entry-url');
const mainEntry = prepareMainThreadExecution(!isEntryURL);

markBootstrapComplete();

// Necessary to reset RegExp statics before user code runs.
RegExpPrototypeExec(/^/, '');

if (isEntryURL) {
  emitExperimentalWarning('--entry-url');
}

/**
 * To support legacy monkey-patching of `Module.runMain`, we call `runMain` here to have the CommonJS loader begin the
 * execution of the main entry point, even if the ESM loader immediately takes over because the main entry is an ES
 * module or one of the other opt-in conditions (such as the use of `--import`) are met. Users can monkey-patch before
 * the main entry point is loaded by doing so via scripts loaded through `--require`. This monkey-patchability is
 * undesirable and should be removed once the module customization hooks provide equivalent functionality.
 */
require('internal/modules/cjs/loader').Module.runMain(mainEntry);

sources.internal/main/test_runner:
'use strict';

const {
  ArrayPrototypeSlice,
} = primordials;

const {
  markBootstrapComplete,
  prepareTestRunnerMainExecution,
} = require('internal/process/pre_execution');
const { isUsingInspector } = require('internal/util/inspector');
const { run } = require('internal/test_runner/runner');
const { parseCommandLine } = require('internal/test_runner/utils');
const { exitCodes: { kGenericUserError } } = internalBinding('errors');
let debug = require('internal/util/debuglog').debuglog('test_runner', (fn) => {
  debug = fn;
});

const options = parseCommandLine();
const isTestIsolationDisabled = options.isolation === 'none';
// We set initializeModules to false as we want to load user modules in the test runner run function
// if we are running with --test-isolation=none
prepareTestRunnerMainExecution(!isTestIsolationDisabled);
markBootstrapComplete();

if (isUsingInspector() && options.isolation === 'process') {
  process.emitWarning('Using the inspector with --test forces running at a concurrency of 1. ' +
  'Use the inspectPort option to run with concurrency');
  options.concurrency = 1;
  options.inspectPort = process.debugPort;
}

options.globPatterns = ArrayPrototypeSlice(process.argv, 1);

debug('test runner configuration:', options);
run(options).on('test:summary', (data) => {
  if (!data.success) {
    process.exitCode = kGenericUserError;
  }
});

sources.internal/main/watch_mode:
'use strict';
const {
  ArrayPrototypeForEach,
  ArrayPrototypeJoin,
  ArrayPrototypeMap,
  ArrayPrototypePush,
  ArrayPrototypePushApply,
  ArrayPrototypeSlice,
  StringPrototypeIncludes,
  StringPrototypeIndexOf,
  StringPrototypeReplaceAll,
  StringPrototypeSlice,
  StringPrototypeStartsWith,
} = primordials;

const {
  prepareMainThreadExecution,
  markBootstrapComplete,
} = require('internal/process/pre_execution');
const {
  triggerUncaughtException,
  exitCodes: { kNoFailure },
} = internalBinding('errors');
const { getOptionValue, parseNodeOptionsEnvVar } = require('internal/options');
const { FilesWatcher } = require('internal/watch_mode/files_watcher');
const { green, blue, red, white, clear } = require('internal/util/colors');
const { convertToValidSignal, kEmptyObject } = require('internal/util');

const { spawn } = require('child_process');
const { inspect } = require('util');
const { setTimeout, clearTimeout } = require('timers');
const { resolve } = require('path');
const { once } = require('events');

prepareMainThreadExecution(false, false);
markBootstrapComplete();

const kKillSignal = convertToValidSignal(getOptionValue('--watch-kill-signal'));
const kShouldFilterModules = getOptionValue('--watch-path').length === 0;
const kEnvFiles = getOptionValue('--env-file');
const kOptionalEnvFiles = getOptionValue('--env-file-if-exists');
const kWatchedPaths = ArrayPrototypeMap(getOptionValue('--watch-path'), (path) => resolve(path));
const kPreserveOutput = getOptionValue('--watch-preserve-output');
const kCommand = ArrayPrototypeSlice(process.argv, 1);
const kCommandStr = inspect(ArrayPrototypeJoin(kCommand, ' '));

// The C++ option parser treats `_` and `-` as equivalent in option names
// (e.g. --watch_path is --watch-path), so normalize before matching.
function normalizeOptionName(arg) {
  if (!StringPrototypeStartsWith(arg, '--')) {
    return arg;
  }
  const equalsIndex = StringPrototypeIndexOf(arg, '=');
  if (equalsIndex === -1) {
    return StringPrototypeReplaceAll(arg, '_', '-');
  }
  return StringPrototypeReplaceAll(StringPrototypeSlice(arg, 0, equalsIndex), '_', '-') +
    StringPrototypeSlice(arg, equalsIndex);
}

const argsWithoutWatchOptions = [];
for (let i = 0; i < process.execArgv.length; i++) {
  const arg = normalizeOptionName(process.execArgv[i]);
  if (StringPrototypeStartsWith(arg, '--watch=')) {
    continue;
  }
  if (arg === '--watch') {
    const nextArg = process.execArgv[i + 1];
    if (nextArg && nextArg[0] !== '-') {
      // If `--watch` doesn't include `=` and the next
      // argument is not a flag then it is interpreted as
      // the watch argument, so we need to skip that as well
      i++;
    }
    continue;
  }
  if (StringPrototypeStartsWith(arg, '--watch-path')) {
    const lengthOfWatchPathStr = 12;
    if (arg[lengthOfWatchPathStr] !== '=') {
      // if --watch-path doesn't include `=` it means
      // that the next arg is the target path, so we
      // need to skip that as well
      i++;
    }
    continue;
  }
  if (arg === '--config-file' ||
      StringPrototypeStartsWith(arg, '--config-file=') ||
      arg === '--experimental-config-file' ||
      StringPrototypeStartsWith(arg, '--experimental-config-file=')) {
    continue;
  }
  if (arg === '--experimental-default-config-file') {
    continue;
  }
  ArrayPrototypePush(argsWithoutWatchOptions, process.execArgv[i]);
}

ArrayPrototypePushApply(argsWithoutWatchOptions, kCommand);

// Strip watch-related flags from NODE_OPTIONS to prevent infinite loop
// when NODE_OPTIONS contains --watch (see issue #61740).
const kNodeOptions = process.env.NODE_OPTIONS;
let cleanNodeOptions = kNodeOptions;
if (kNodeOptions != null) {
  const keep = [];
  const parts = parseNodeOptionsEnvVar(kNodeOptions);
  for (let i = 0; i < parts.length; i++) {
    const part = parts[i];
    const name = normalizeOptionName(part);
    if (name === '--watch' ||
        name === '--watch-preserve-output' ||
        StringPrototypeStartsWith(name, '--watch=') ||
        StringPrototypeStartsWith(name, '--watch-preserve-output=') ||
        StringPrototypeStartsWith(name, '--watch-path=') ||
        StringPrototypeStartsWith(name, '--watch-kill-signal=')) {
      continue;
    }
    if (name === '--watch-path' || name === '--watch-kill-signal') {
      // Skip the flag and its separate value argument
      i++;
      continue;
    }
    // The C++ tokenizer strips quotes and escapes during parsing, so values
    // that contain spaces or double quotes (e.g. --require "./a b/f.js")
    // need to be re-quoted before rejoining into a single string, otherwise
    // the child's C++ parser would split or misparse them. Inside quotes,
    // backslashes are escape characters, so `"` and `\` must be escaped.
    // Backslashes are escaped first so the ones added for `"` aren't doubled.
    // Outside quotes, backslashes are literal, so other values are kept as-is.
    if (StringPrototypeIncludes(part, ' ') || StringPrototypeIncludes(part, '"')) {
      const escaped = StringPrototypeReplaceAll(
        StringPrototypeReplaceAll(part, '\\', '\\\\'), '"', '\\"');
      ArrayPrototypePush(keep, `"${escaped}"`);
    } else {
      ArrayPrototypePush(keep, part);
    }
  }
  cleanNodeOptions = ArrayPrototypeJoin(keep, ' ');
}

const watcher = new FilesWatcher({ debounce: 200, mode: kShouldFilterModules ? 'filter' : 'all' });
ArrayPrototypeForEach(kWatchedPaths, (p) => watcher.watchPath(p));

let graceTimer;
let child;
let childExitPromise;
let exited;
let stopping;

function start() {
  exited = false;
  stopping = false;
  const stdio = kShouldFilterModules ? ['inherit', 'inherit', 'inherit', 'ipc'] : 'inherit';
  child = spawn(process.execPath, argsWithoutWatchOptions, {
    stdio,
    env: {
      ...process.env,
      WATCH_REPORT_DEPENDENCIES: '1',
      NODE_OPTIONS: cleanNodeOptions,
    },
  });
  watcher.watchChildProcessModules(child);
  if (kEnvFiles.length > 0) {
    ArrayPrototypeForEach(kEnvFiles, (file) => watcher.filterFile(resolve(file)));
  }
  if (kOptionalEnvFiles.length > 0) {
    ArrayPrototypeForEach(kOptionalEnvFiles,
                          (file) => watcher.filterFile(resolve(file), undefined, { allowMissing: true }));
  }
  childExitPromise = once(child, 'exit').then(({ 0: code }) => {
    exited = true;
    if (stopping) {
      return code;
    }
    const waitingForChanges = 'Waiting for file changes before restarting...';
    if (code === 0) {
      process.stdout.write(`${blue}Completed running ${kCommandStr}. ${waitingForChanges}${white}\n`);
    } else {
      process.stdout.write(`${red}Failed running ${kCommandStr}. ${waitingForChanges}${white}\n`);
    }
    return code;
  });
  return child;
}

async function killAndWait(signal = kKillSignal, force = false) {
  const processToKill = child;
  const onExit = childExitPromise;
  if (!processToKill) {
    return;
  }
  if ((processToKill.killed || exited) && !force) {
    return;
  }
  stopping = true;
  if (!exited && processToKill.exitCode === null && processToKill.signalCode === null) {
    processToKill.kill(signal);
  }
  const exitCode = await onExit;
  return exitCode;
}

function reportGracefulTermination() {
  // Log if process takes more than 500ms to stop.
  let reported = false;
  clearTimeout(graceTimer);
  graceTimer = setTimeout(() => {
    reported = true;
    process.stdout.write(`${blue}Waiting for graceful termination...${white}\n`);
  }, 500).unref();
  return () => {
    clearTimeout(graceTimer);
    if (reported) {
      if (!kPreserveOutput) {
        process.stdout.write(clear);
      }
      process.stdout.write(`${green}Gracefully restarted ${kCommandStr}${white}\n`);
    }
  };
}

async function stop(child) {
  // Without this line, the child process is still able to receive IPC, but is unable to send additional messages
  watcher.destroyIPC(child);
  watcher.clearFileFilters();
  const clearGraceReport = reportGracefulTermination();
  await killAndWait();
  clearGraceReport();
}

let restarting = false;

async function restart(child, trigger) {
  if (restarting) return;
  restarting = true;
  try {
    if (!kPreserveOutput) process.stdout.write(clear);
    if (trigger) {
      process.stdout.write(`${blue}Change detected in ${inspect(trigger)}${white}\n`);
    }
    process.stdout.write(`${green}Restarting ${kCommandStr}${white}\n`);
    await stop(child);
    return start();
  } finally {
    restarting = false;
  }
}

async function init() {
  let child = start();
  const restartChild = async ({ trigger } = kEmptyObject) => {
    child = await restart(child, trigger);
  };
  watcher
    .on('changed', restartChild)
    .on('error', (error) => {
      watcher.off('changed', restartChild);
      triggerUncaughtException(error, true /* fromPromise */);
    });
}

init();

// Exiting gracefully to avoid stdout/stderr getting written after
// parent process is killed.
// this is fairly safe since user code cannot run in this process
function signalHandler(signal) {
  return async () => {
    watcher.clear();
    const exitCode = await killAndWait(signal, true);
    process.exit(exitCode ?? kNoFailure);
  };
}

process.on('SIGTERM', signalHandler('SIGTERM'));
process.on('SIGINT', signalHandler('SIGINT'));

sources.internal/main/worker_thread:
'use strict';

// In worker threads, execute the script sent through the
// message port.

const {
  ArrayPrototypeForEach,
  ArrayPrototypePushApply,
  ArrayPrototypeSplice,
  AtomicsLoad,
  ObjectDefineProperty,
  PromisePrototypeThen,
  RegExpPrototypeExec,
} = primordials;

const {
  prepareWorkerThreadExecution,
  initializeModuleLoaders,
  finishVfsMounts,
  markBootstrapComplete,
} = require('internal/process/pre_execution');

const {
  threadId,
  getEnvMessagePort,
} = internalBinding('worker');

const workerIo = require('internal/worker/io');
const {
  messageTypes: {
    // Messages that may be received by workers
    LOAD_SCRIPT,
    // Messages that may be posted from workers
    UP_AND_RUNNING,
    ERROR_MESSAGE,
    COULD_NOT_SERIALIZE_ERROR,
    // Messages that may be either received or posted
    STDIO_PAYLOAD,
    STDIO_WANTS_MORE_DATA,
  },
  kStdioWantsMoreDataCallback,
} = workerIo;

const { setupMainThreadPort } = require('internal/worker/messaging');

const {
  onGlobalUncaughtException,
  evalScript,
  evalTypeScript,
  evalModuleEntryPoint,
  parseAndEvalCommonjsTypeScript,
  parseAndEvalModuleTypeScript,
} = require('internal/process/execution');

let debug = require('internal/util/debuglog').debuglog('worker', (fn) => {
  debug = fn;
});

const assert = require('internal/assert');
const { getOptionValue } = require('internal/options');
const { exitCodes: { kGenericUserError } } = internalBinding('errors');

prepareWorkerThreadExecution();

debug(`[${threadId}] is setting up worker child environment`);

// Set up the message port and start listening
const port = getEnvMessagePort();

// If the main thread is spawned with env NODE_CHANNEL_FD, it's probably
// spawned by our child_process module. In the work threads, mark the
// related IPC properties as unavailable.
if (process.env.NODE_CHANNEL_FD) {
  const workerThreadSetup = require('internal/process/worker_thread_only');
  ObjectDefineProperty(process, 'channel', {
    __proto__: null,
    enumerable: false,
    get: workerThreadSetup.unavailable('process.channel'),
  });

  ObjectDefineProperty(process, 'connected', {
    __proto__: null,
    enumerable: false,
    get: workerThreadSetup.unavailable('process.connected'),
  });

  process.send = workerThreadSetup.unavailable('process.send()');
  process.disconnect =
    workerThreadSetup.unavailable('process.disconnect()');
}

port.on('message', (message) => {
  if (message.type === LOAD_SCRIPT) {
    port.unref();
    const {
      argv,
      cwdCounter,
      doEval,
      environmentData,
      filename,
      hasStdin,
      publicPort,
      workerData,
      webWorkerData,
      mainThreadPort,
    } = message;

    if (doEval !== 'internal') {
      if (argv !== undefined) {
        ArrayPrototypePushApply(process.argv, argv);
      }

      const publicWorker = require('worker_threads');
      publicWorker.parentPort = publicPort;
      publicWorker.workerData = workerData;
    }

    require('internal/worker').assignEnvironmentData(environmentData);
    setupMainThreadPort(mainThreadPort);

    if (webWorkerData !== undefined) {
      require('internal/webworker')
        .installDedicatedWorkerGlobalScope(webWorkerData.url, webWorkerData);
    }

    // The counter is only passed to the workers created by the main thread,
    // not to workers created by other workers.
    let cachedCwd = '';
    let lastCounter = -1;
    const originalCwd = process.cwd;

    process.cwd = function() {
      const currentCounter = AtomicsLoad(cwdCounter, 0);
      if (currentCounter === lastCounter)
        return cachedCwd;
      lastCounter = currentCounter;
      cachedCwd = originalCwd();
      return cachedCwd;
    };
    workerIo.sharedCwdCounter = cwdCounter;

    const isLoaderHookWorker = (filename === 'internal/modules/esm/worker' && doEval === 'internal');
    if (!isLoaderHookWorker) {
      // If we are in the loader hook worker, delay the module loader initializations until
      // initializeAsyncLoaderHooksOnLoaderHookWorker() which needs to run preloads
      // after the asynchronous loader hooks are registered.
      initializeModuleLoaders({ shouldSpawnLoaderHookWorker: true, shouldPreloadModules: true });
      // Re-mount the inherited --vfs-load source so its reserved path (which a
      // worker filename may point into) resolves in this thread too. With
      // --import, mounting is deferred to after that loop in run_main, matching
      // the main thread; finishVfsMounts() is idempotent so it runs once.
      if (getOptionValue('--import').length === 0) {
        finishVfsMounts();
      }
    }

    if (!hasStdin)
      process.stdin.push(null);

    debug(`[${threadId}] starts worker script ${filename} ` +
          `(eval = ${doEval}) at cwd = ${process.cwd()}`);
    port.postMessage({ type: UP_AND_RUNNING });
    switch (doEval) {
      case 'internal': {
        // Currently the only user of internal eval is the async loader hook thread.
        assert(isLoaderHookWorker, `Unexpected internal eval ${filename}`);
        const setupModuleWorker = require('internal/modules/esm/worker');
        setupModuleWorker(workerData, publicPort);
        break;
      }

      case 'classic': if (webWorkerData?.source !== undefined) {
        // The source of a web Worker script loaded from a blob: or data:
        // URL.
        runWebWorkerScript(webWorkerData.source, webWorkerData);
        break;
      } else if (getOptionValue('--input-type') !== 'module') {
        const name = '[worker eval]';
        // This is necessary for CJS module compilation.
        // TODO: pass this with something really internal.
        ObjectDefineProperty(process, '_eval', {
          __proto__: null,
          configurable: true,
          enumerable: true,
          value: filename,
        });
        ArrayPrototypeSplice(process.argv, 1, 0, name);
        const tsEnabled = getOptionValue('--strip-types');
        const inputType = getOptionValue('--input-type');

        if (inputType === 'module-typescript' && tsEnabled) {
          // This is a special case where we want to parse and eval the
          // TypeScript code as a module
          parseAndEvalModuleTypeScript(filename, false);
          break;
        }

        let evalFunction;
        if (inputType === 'commonjs') {
          evalFunction = evalScript;
        } else if (inputType === 'commonjs-typescript' && tsEnabled) {
          evalFunction = parseAndEvalCommonjsTypeScript;
        } else if (tsEnabled) {
          evalFunction = evalTypeScript;
        } else {
          // Default to commonjs.
          evalFunction = evalScript;
        }

        evalFunction(name, filename);
        break;
      }

      // eslint-disable-next-line no-fallthrough
      case 'module': {
        PromisePrototypeThen(evalModuleEntryPoint(filename), undefined, (e) => {
          workerOnGlobalUncaughtException(e, true);
        });
        break;
      }

      case 'data-url': {
        const { runEntryPointWithESMLoader } = require('internal/modules/run_main');

        RegExpPrototypeExec(/^/, ''); // Necessary to reset RegExp statics before user code runs.
        const promise = runEntryPointWithESMLoader((cascadedLoader) => {
          return cascadedLoader.import(filename, undefined, { __proto__: null }, undefined, true);
        });

        PromisePrototypeThen(promise, undefined, (e) => {
          workerOnGlobalUncaughtException(e, true);
        });
        break;
      }

      default: {
        if (webWorkerData !== undefined) {
          // A web Worker script loaded from a file: URL. Its type decides
          // how the source is run, regardless of the file extension.
          const source = require('fs').readFileSync(filename, 'utf8');
          runWebWorkerScript(source, webWorkerData);
          break;
        }
        // script filename
        // runMain here might be monkey-patched by users in --require.
        // XXX: the monkey-patchability here should probably be deprecated.
        ArrayPrototypeSplice(process.argv, 1, 0, filename);
        const CJSLoader = require('internal/modules/cjs/loader');
        CJSLoader.Module.runMain(filename);
        break;
      }
    }
  } else if (message.type === STDIO_PAYLOAD) {
    const { stream, chunks } = message;
    ArrayPrototypeForEach(chunks, ({ chunk, encoding }) => {
      process[stream].push(chunk, encoding);
    });
  } else {
    assert(
      message.type === STDIO_WANTS_MORE_DATA,
      `Unknown worker message type ${message.type}`,
    );
    const { stream } = message;
    process[stream][kStdioWantsMoreDataCallback]();
  }
});

function workerOnGlobalUncaughtException(error, fromPromise) {
  debug(`[${threadId}] gets uncaught exception`);
  let handled = false;
  let handlerThrew = false;
  try {
    handled = onGlobalUncaughtException(error, fromPromise);
  } catch (e) {
    error = e;
    handlerThrew = true;
  }
  debug(`[${threadId}] uncaught exception handled = ${handled}`);

  if (handled) {
    return true;
  }

  if (!process._exiting) {
    try {
      process._exiting = true;
      process.exitCode = kGenericUserError;
      if (!handlerThrew) {
        process.emit('exit', process.exitCode);
      }
    } catch {
      // Continue regardless of error.
    }
  }

  let serialized;
  try {
    const { serializeError } = require('internal/error_serdes');
    serialized = serializeError(error);
  } catch {
    // Continue regardless of error.
  }
  debug(`[${threadId}] uncaught exception serialized = ${!!serialized}`);
  if (serialized)
    port.postMessage({
      type: ERROR_MESSAGE,
      error: serialized,
    });
  else
    port.postMessage({ type: COULD_NOT_SERIALIZE_ERROR });

  const { clearAsyncIdStack } = require('internal/async_hooks');
  clearAsyncIdStack();

  process.exit();
}

function runWebWorkerScript(source, webWorkerData) {
  const webworker = require('internal/webworker');
  if (webWorkerData.type === 'module') {
    PromisePrototypeThen(
      webworker.runModuleScriptSource(source, webWorkerData.url),
      undefined,
      (error) => workerOnGlobalUncaughtException(error, true),
    );
  } else {
    // Unlike a worker eval, "run a classic script" evaluates the source in
    // the worker's global scope.
    webworker.runClassicScriptSource(source, webWorkerData.url);
  }
}

// Patch the global uncaught exception handler so it gets picked up by
// node::errors::TriggerUncaughtException().
process._fatalException = workerOnGlobalUncaughtException;

markBootstrapComplete();

// Necessary to reset RegExp statics before user code runs.
RegExpPrototypeExec(/^/, '');

port.start();

sources.internal/mime:
'use strict';

const {
  FunctionPrototypeCall,
  ObjectDefineProperty,
  SafeMap,
  StringPrototypeCharCodeAt,
  StringPrototypeSlice,
  StringPrototypeToLowerCase,
  Symbol,
  SymbolIterator,
  Uint8Array,
} = primordials;
const {
  ERR_ILLEGAL_CONSTRUCTOR,
  ERR_INVALID_MIME_SYNTAX,
} = require('internal/errors').codes;

// Lookup table for the code point classes used by the MIME Sniffing
// standard. Only code points <= 0xFF can be in either class.
// https://mimesniff.spec.whatwg.org/#http-token-code-point
// https://mimesniff.spec.whatwg.org/#http-quoted-string-token-code-point
const kHTTPToken = 1;
const kHTTPQuotedStringToken = 2;
const codePointClass = new Uint8Array(256);
{
  codePointClass[0x09] = kHTTPQuotedStringToken;
  for (let c = 0x20; c <= 0x7E; c++) codePointClass[c] = kHTTPQuotedStringToken;
  for (let c = 0x80; c <= 0xFF; c++) codePointClass[c] = kHTTPQuotedStringToken;
  const tokens = "!#$%&'*+-.^_`|~0123456789" +
    'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz';
  for (let i = 0; i < tokens.length; i++) {
    codePointClass[StringPrototypeCharCodeAt(tokens, i)] |= kHTTPToken;
  }
}

const kNoThrow = Symbol('kNoThrow');

// https://fetch.spec.whatwg.org/#http-whitespace
function isHTTPWhitespace(c) {
  return c === 0x20 || c === 0x09 || c === 0x0A || c === 0x0D;
}

/**
 * Returns the offset from `start` of the first code point in
 * `str[start, end)` that is not in `cls`, or -1 if they all are.
 * @param {string} str
 * @param {number} start
 * @param {number} end
 * @param {number} cls
 * @returns {number}
 */
function findInvalid(str, start, end, cls) {
  for (let i = start; i < end; i++) {
    const c = StringPrototypeCharCodeAt(str, i);
    if (c > 0xFF || (codePointClass[c] & cls) === 0) return i - start;
  }
  return -1;
}

function toASCIILower(str) {
  let hasUpper = false;
  for (let i = 0; i < str.length; i++) {
    const c = StringPrototypeCharCodeAt(str, i);
    if (c > 0x7F) {
      let result = '';
      for (let j = 0; j < str.length; j++) {
        const char = str[j];
        result += char >= 'A' && char <= 'Z' ?
          StringPrototypeToLowerCase(char) :
          char;
      }
      return result;
    }
    if (c <= 0x5A && c >= 0x41) hasUpper = true;
  }
  // Returning the input unchanged when possible avoids an allocation and
  // keeps its cached hash for Map lookups.
  return hasUpper ? StringPrototypeToLowerCase(str) : str;
}

// Results of parseTypeAndSubtype(). Kept in module state to avoid allocating
// a result object per parse; they are consumed synchronously by the caller.
let parsedType = '';
let parsedSubtype = '';
let parsedParamsStart = 0;
let parsedParamsEnd = 0;
let failedProduction = '';
let failedIndex = -1;

/**
 * Parses the type and subtype of a MIME type string and locates its
 * parameters. Returns false on failure, with failedProduction and
 * failedIndex describing the error.
 * @see https://mimesniff.spec.whatwg.org/#parse-a-mime-type
 * @param {string} str
 * @returns {boolean}
 */
function parseTypeAndSubtype(str) {
  const length = str.length;

  // Skip leading HTTP whitespace.
  let position = 0;
  while (position < length &&
         isHTTPWhitespace(StringPrototypeCharCodeAt(str, position))) {
    position++;
  }

  // Collect the type, up to '/'.
  const typeStart = position;
  let invalidTypeIndex = -1;
  let typeHasUpper = false;
  for (; position < length; position++) {
    const c = StringPrototypeCharCodeAt(str, position);
    if (c === 0x2F /* / */) break;
    if (c > 0xFF || (codePointClass[c] & kHTTPToken) === 0) {
      if (invalidTypeIndex === -1) invalidTypeIndex = position - typeStart;
    } else if (c <= 0x5A && c >= 0x41) {
      typeHasUpper = true;
    }
  }
  if (position === typeStart || invalidTypeIndex !== -1 || position >= length) {
    failedProduction = 'type';
    failedIndex = invalidTypeIndex;
    return false;
  }
  const typeEnd = position;

  // Skip '/' and collect the subtype, up to ';'. In the same pass, find the
  // first non-token code point and where the trailing HTTP whitespace starts.
  position++;
  const subtypeStart = position;
  let subtypeEnd = position;
  let firstNonToken = -1;
  let subtypeHasUpper = false;
  for (; position < length; position++) {
    const c = StringPrototypeCharCodeAt(str, position);
    if (c === 0x3B /* ; */) break;
    if (c <= 0xFF && (codePointClass[c] & kHTTPToken) !== 0) {
      if (c <= 0x5A && c >= 0x41) subtypeHasUpper = true;
    } else if (firstNonToken === -1) {
      firstNonToken = position;
    }
    if (!isHTTPWhitespace(c)) subtypeEnd = position + 1;
  }
  const subtypeRawEnd = position;
  // Whitespace is not a token code point, so a non-token code point at or
  // after subtypeEnd is part of the trailing whitespace, which is removed.
  const invalidSubtypeIndex = firstNonToken !== -1 && firstNonToken < subtypeEnd ?
    firstNonToken - subtypeStart : -1;
  if (subtypeEnd === subtypeStart || invalidSubtypeIndex !== -1) {
    failedProduction = 'subtype';
    failedIndex = invalidSubtypeIndex;
    return false;
  }

  // Parameters are everything after the ';' up to the trailing whitespace.
  let paramsEnd = length;
  while (paramsEnd > subtypeRawEnd &&
         isHTTPWhitespace(StringPrototypeCharCodeAt(str, paramsEnd - 1))) {
    paramsEnd--;
  }

  const type = StringPrototypeSlice(str, typeStart, typeEnd);
  const subtype = StringPrototypeSlice(str, subtypeStart, subtypeEnd);
  // Both are ASCII-only at this point, so toLowerCase() is ASCII lowercase.
  parsedType = typeHasUpper ? StringPrototypeToLowerCase(type) : type;
  parsedSubtype = subtypeHasUpper ? StringPrototypeToLowerCase(subtype) : subtype;
  parsedParamsStart = subtypeRawEnd + 1;
  parsedParamsEnd = paramsEnd;
  return true;
}

/**
 * Parses MIME type parameters from `str[position, end)` into `params`.
 * `position` is just past the ';' that follows the subtype, and `end`
 * excludes trailing HTTP whitespace. This is step 11 of
 * https://mimesniff.spec.whatwg.org/#parse-a-mime-type
 * @param {string} str
 * @param {number} position
 * @param {number} end
 * @param {SafeMap<string, string>} params
 */
function parseParameters(str, position, end, params) {
  while (position < end) {
    // Skip HTTP whitespace.
    while (position < end &&
           isHTTPWhitespace(StringPrototypeCharCodeAt(str, position))) {
      position++;
    }

    // Collect the parameter name, up to ';' or '='.
    const nameStart = position;
    let nameIsToken = true;
    let nameHasUpper = false;
    for (; position < end; position++) {
      const c = StringPrototypeCharCodeAt(str, position);
      if (c === 0x3B /* ; */ || c === 0x3D /* = */) break;
      if (c > 0xFF || (codePointClass[c] & kHTTPToken) === 0) {
        nameIsToken = false;
      } else if (c <= 0x5A && c >= 0x41) {
        nameHasUpper = true;
      }
    }
    const nameEnd = position;

    if (position < end) {
      // Parameters without a value are ignored.
      if (StringPrototypeCharCodeAt(str, position) === 0x3B /* ; */) {
        position++;
        continue;
      }
      // Skip '='.
      position++;
    }
    if (position >= end) break;

    let value;
    if (StringPrototypeCharCodeAt(str, position) === 0x22 /* " */) {
      // Collect an HTTP quoted string with the extract-value flag.
      // https://fetch.spec.whatwg.org/#collect-an-http-quoted-string
      position++;
      value = '';
      let chunkStart = position;
      while (true) {
        while (position < end) {
          const c = StringPrototypeCharCodeAt(str, position);
          if (c === 0x22 /* " */ || c === 0x5C /* \ */) break;
          position++;
        }
        if (position >= end) {
          value += StringPrototypeSlice(str, chunkStart, position);
          break;
        }
        const quoteOrBackslash = StringPrototypeCharCodeAt(str, position);
        value += StringPrototypeSlice(str, chunkStart, position);
        position++;
        if (quoteOrBackslash === 0x5C /* \ */) {
          if (position >= end) {
            value += '\\';
            break;
          }
          // The escaped code point starts the next chunk.
          chunkStart = position;
          position++;
        } else {
          break;
        }
      }
      // Skip anything else up to the next ';'.
      while (position < end &&
             StringPrototypeCharCodeAt(str, position) !== 0x3B /* ; */) {
        position++;
      }
      if (findInvalid(value, 0, value.length, kHTTPQuotedStringToken) !== -1) {
        position++;
        continue;
      }
    } else {
      // Collect the value up to ';', validating it and finding where its
      // trailing HTTP whitespace starts in the same pass. CR and LF are not
      // quoted-string token code points, but trailing ones are removed, so
      // the value is only invalid if a bad code point comes before valueEnd.
      const valueStart = position;
      let valueEnd = position;
      let firstInvalid = -1;
      for (; position < end; position++) {
        const c = StringPrototypeCharCodeAt(str, position);
        if (c === 0x3B /* ; */) break;
        if (firstInvalid === -1 &&
            (c > 0xFF || (codePointClass[c] & kHTTPQuotedStringToken) === 0)) {
          firstInvalid = position;
        }
        if (!isHTTPWhitespace(c)) valueEnd = position + 1;
      }
      // Parameters with an empty or invalid value are ignored.
      if (valueEnd === valueStart ||
          (firstInvalid !== -1 && firstInvalid < valueEnd)) {
        position++;
        continue;
      }
      value = StringPrototypeSlice(str, valueStart, valueEnd);
    }

    if (nameEnd !== nameStart && nameIsToken) {
      // The name is ASCII-only, so toLowerCase() is ASCII lowercase.
      const name = nameHasUpper ?
        StringPrototypeToLowerCase(StringPrototypeSlice(str, nameStart, nameEnd)) :
        StringPrototypeSlice(str, nameStart, nameEnd);
      if (!params.has(name)) params.set(name, value);
    }
    // Skip ';'.
    position++;
  }
}

function escapeQuoteOrSolidus(str) {
  let result = '';
  for (let i = 0; i < str.length; i++) {
    const char = str[i];
    result += (char === '"' || char === '\\') ? `\\${char}` : char;
  }
  return result;
}

const encode = (value) => {
  if (value.length === 0) return '""';
  if (findInvalid(value, 0, value.length, kHTTPToken) === -1) return value;
  return `"${escapeQuoteOrSolidus(value)}"`;
};

class MIMEParams {
  // Parsing is deferred until the parameters are first accessed, as most
  // users only need the type and subtype. Until then #data is null and
  // #string[#start, #end) holds the unparsed parameters.
  #data = null;
  #string = null;
  #start = 0;
  #end = 0;

  /**
   * Used to instantiate a MIMEParams object within the MIMEType class and
   * to allow it to be parsed lazily.
   * @returns {MIMEParams}
   */
  static instantiateMimeParams(str, start, end) {
    const instance = new MIMEParams();
    instance.#string = str;
    instance.#start = start;
    instance.#end = end;
    return instance;
  }

  /**
   * @param {string} name
   * @returns {void}
   */
  delete(name) {
    this.#parse().delete(toASCIILower(`${name}`));
  }

  get(name) {
    const value = this.#parse().get(toASCIILower(`${name}`));
    return value === undefined ? null : value;
  }

  has(name) {
    return this.#parse().has(toASCIILower(`${name}`));
  }

  set(name, value) {
    const data = this.#parse();
    name = toASCIILower(`${name}`);
    value = `${value}`;
    const invalidNameIndex = findInvalid(name, 0, name.length, kHTTPToken);
    if (name.length === 0 || invalidNameIndex !== -1) {
      throw new ERR_INVALID_MIME_SYNTAX(
        'parameter name',
        name,
        invalidNameIndex,
      );
    }
    const invalidValueIndex = findInvalid(value, 0, value.length,
                                          kHTTPQuotedStringToken);
    if (invalidValueIndex !== -1) {
      throw new ERR_INVALID_MIME_SYNTAX(
        'parameter value',
        value,
        invalidValueIndex,
      );
    }
    data.set(name, value);
  }

  *entries() {
    yield* this.#parse().entries();
  }

  *keys() {
    yield* this.#parse().keys();
  }

  *values() {
    yield* this.#parse().values();
  }

  toString() {
    let ret = '';
    for (const { 0: key, 1: value } of this.#parse()) {
      const encoded = encode(value);
      // Ensure they are separated
      if (ret.length) ret += ';';
      ret += `${key}=${encoded}`;
    }
    return ret;
  }

  /**
   * Parses the deferred parameter string on first use.
   * @returns {SafeMap<string, string>}
   */
  #parse() {
    let data = this.#data;
    if (data !== null) return data;
    data = this.#data = new SafeMap();
    const str = this.#string;
    if (str !== null) {
      this.#string = null;
      parseParameters(str, this.#start, this.#end, data);
    }
    return data;
  }
}
const MIMEParamsStringify = MIMEParams.prototype.toString;
