    content = lazyTypeScript().stripTypeScriptModuleTypes(content, filename, this[kURL]);
    switch (format) {
      case 'commonjs-typescript': {
        format = 'commonjs';
        break;
      }
      case 'module-typescript': {
        format = 'module';
        break;
