  const hasEndSync = hasEnd &&
                      typeof writer.endSync === 'function';
  const hasFail = typeof writer.fail === 'function';
  const hasDispose = typeof writer[SymbolDispose] === 'function';
  const hasAsyncDispose = typeof writer[SymbolAsyncDispose] === 'function';
  let writerEnded = false;
  const classicErrorReasons = new SafeWeakMap();
  // Try-sync-first pattern: attempt the synchronous method and fall back to the
  // async method if it returns false (data not accepted synchronously).
  // When the sync path succeeds, the callback is deferred via queueMicrotask
  // to preserve the async resolution contract that Writable internals expect
  // from _write/_writev/_final callbacks.

  function _write(chunk, encoding, cb) {
    const bytes = typeof chunk === 'string' ?
      Buffer.from(chunk, encoding) : chunk;
    if (hasWriteSync) {
      try {
        if (writer.writeSync(bytes)) {
          queueMicrotask(cb);
          return;
        }
        // WriteSync returned false: not accepted, fall through to async.
      } catch (err) {
        cb(toClassicError(err, classicErrorReasons));
        return;
      }
    }
    try {
      PromisePrototypeThen(
        writer.write(bytes), () => cb(),
        (err) => cb(toClassicError(err, classicErrorReasons)));
    } catch (err) {
      cb(toClassicError(err, classicErrorReasons));
    }
  }

  function _writev(entries, cb) {
    const chunks = [];
    for (let i = 0; i < entries.length; i++) {
      const { chunk, encoding } = entries[i];
      chunks[i] = typeof chunk === 'string' ?
        Buffer.from(chunk, encoding) : chunk;
    }
    if (hasWritevSync) {
      try {
        if (writer.writevSync(chunks)) {
          queueMicrotask(cb);
          return;
        }
        // WritevSync returned false: not accepted, fall through to async.
      } catch (err) {
        cb(toClassicError(err, classicErrorReasons));
        return;
      }
    }
    try {
      PromisePrototypeThen(
        writer.writev(chunks), () => cb(),
        (err) => cb(toClassicError(err, classicErrorReasons)));
    } catch (err) {
      cb(toClassicError(err, classicErrorReasons));
    }
  }

  function _final(cb) {
    if (!hasEnd) {
      writerEnded = true;
      queueMicrotask(cb);
      return;
    }
    if (hasEndSync) {
      try {
        const result = writer.endSync();
        if (result >= 0) {
          writerEnded = true;
          queueMicrotask(cb);
          return;
        }
        // Result < 0: can't end synchronously, fall through to async.
      } catch (err) {
        cb(toClassicError(err, classicErrorReasons));
        return;
      }
    }
    try {
      PromisePrototypeThen(
        writer.end(), () => {
          writerEnded = true;
          cb();
        },
        (err) => cb(toClassicError(err, classicErrorReasons)));
    } catch (err) {
      cb(toClassicError(err, classicErrorReasons));
    }
  }

  function _destroy(err, cb) {
    if (!err && writerEnded) {
      cb();
      return;
    }

    let result;
    try {
      if (hasFail) {
        if (err) {
          const wrapped = classicErrorReasons.get(err);
          classicErrorReasons.delete(err);
          writer.fail(wrapped === undefined ? err : wrapped.reason);
        } else {
          writer.fail();
        }
      } else if (hasDispose) {
        writer[SymbolDispose]();
      } else if (hasAsyncDispose) {
        result = writer[SymbolAsyncDispose]();
      }
    } catch (error) {
      cb(err || toClassicError(error, classicErrorReasons));
      return;
    }

    if (result !== undefined) {
      PromisePrototypeThen(
        PromiseResolve(result),
        () => cb(err),
        (error) => cb(err || toClassicError(error, classicErrorReasons)));
      return;
    }
    cb(err);
  }

  const writableOptions = {
    __proto__: null,
    write: _write,
    final: _final,
    destroy: _destroy,
  };

  if (hasWritev) {
    writableOptions.writev = _writev;
  }

  return new WritableCtor(writableOptions);
}


module.exports = {
  // Shared helpers used by Readable.prototype[toAsyncStreamable] in
  // readable.js to avoid duplicating the batched iterator logic.
  createBatchedAsyncIterator,
  normalizeBatch,

  // Public utilities exported from 'stream/iter'.
  fromReadable,
  fromWritable,
  toReadable,
  toReadableSync,
  toWritable,
};

sources.internal/streams/iter/consumers:
'use strict';

// New Streams API - Consumers & Utilities
//
// bytes(), text(), arrayBuffer() - collect entire stream
// dump() - consume entire stream, retaining nothing
// tap(), tapSync() - observe without modifying
// merge() - temporal combining of sources
// ondrain() - backpressure drain utility

const {
  ArrayBufferIsView,
  ArrayBufferPrototypeGetByteLength,
  ArrayBufferPrototypeSlice,
  ArrayPrototypeMap,
  ArrayPrototypePush,
  ArrayPrototypeShift,
  ArrayPrototypeSlice,
  FunctionPrototypeCall,
  Promise,
  PromisePrototypeThen,
  SafePromiseAllReturnVoid,
  SafeSet,
  Symbol,
  SymbolAsyncIterator,
  TypedArrayPrototypeGetBuffer,
  TypedArrayPrototypeGetByteLength,
  TypedArrayPrototypeGetByteOffset,
  TypedArrayPrototypeSet,
  Uint8Array,
} = primordials;

const {
  codes: {
    ERR_INVALID_ARG_VALUE,
    ERR_OUT_OF_RANGE,
  },
} = require('internal/errors');
const { TextDecoder } = require('internal/encoding');
const {
  validateFunction,
} = require('internal/validators');

const {
  markPromiseAsHandled,
} = internalBinding('util');

const {
  from,
  fromSync,
  isAsyncIterable,
  isSyncIterable,
} = require('internal/streams/iter/from');

const {
  concatBytes,
  getProtocolMethod,
  recordChunk,
  validateRecordedChunks,
  yieldAbortable,
} = require('internal/streams/iter/utils');

const {
  drainableProtocol,
  toAsyncStreamable,
  toStreamable,
} = require('internal/streams/iter/types');
const {
  converters,
} = require('internal/streams/iter/webidl');

const {
  isAnyArrayBuffer,
  isSharedArrayBuffer,
} = require('internal/util/types');

// =============================================================================
// Type Guards
// =============================================================================

function isMergeOptions(value) {
  return (
    value !== null &&
    typeof value === 'object' &&
    !ArrayBufferIsView(value) &&
    typeof value[toStreamable] !== 'function' &&
    typeof value[toAsyncStreamable] !== 'function' &&
    !isAsyncIterable(value) &&
    !isSyncIterable(value) &&
    !isAnyArrayBuffer(value)
  );
}

// =============================================================================
// Shared chunk collection helpers
// =============================================================================

/**
 * Collect chunks from a sync source into an array.
 * @param {Iterable<Uint8Array[]>} source
 * @param {number} [limit]
 * @returns {Uint8Array[]}
 */
function collectSync(source, limit) {
  // Normalize source via fromSync() - accepts strings, ArrayBuffers, protocols, etc.
  const normalized = fromSync(source);
  const chunks = [];
  const checks = [];
  let totalBytes = 0;

  for (const batch of normalized) {
    for (let i = 0; i < batch.length; i++) {
      totalBytes += recordChunk(chunks, checks, batch[i]);
      if (limit !== undefined && totalBytes > limit) {
        throw new ERR_OUT_OF_RANGE('totalBytes', `<= ${limit}`, totalBytes);
      }
    }
  }

  return validateRecordedChunks(chunks, checks);
}

/**
 * Collect chunks from an async or sync source into an array.
 * @param {AsyncIterable<Uint8Array[]>|Iterable<Uint8Array[]>} source
 * @param {AbortSignal} [signal]
 * @param {number} [limit]
 * @returns {Promise<Uint8Array[]>}
 */
async function collectAsync(source, signal, limit) {
  signal?.throwIfAborted();

  // Normalize source via from() - accepts strings, ArrayBuffers, protocols, etc.
  const normalized = from(source);
  const chunks = [];
  const checks = [];

  // Fast path: no signal and no limit
  if (!signal && limit === undefined) {
    for await (const batch of normalized) {
      for (let i = 0; i < batch.length; i++) {
        recordChunk(chunks, checks, batch[i]);
      }
    }
    return validateRecordedChunks(chunks, checks);
  }

  // Slow path: with signal or limit checks
  let totalBytes = 0;
  const iterable = signal ? yieldAbortable(normalized, signal) : normalized;

  for await (const batch of iterable) {
    signal?.throwIfAborted();
    for (let i = 0; i < batch.length; i++) {
      totalBytes += recordChunk(chunks, checks, batch[i]);
      if (limit !== undefined && totalBytes > limit) {
        throw new ERR_OUT_OF_RANGE('totalBytes', `<= ${limit}`, totalBytes);
      }
    }
  }

  return validateRecordedChunks(chunks, checks);
}

/**
 * Convert a Uint8Array to its backing ArrayBuffer, slicing if necessary.
 * @param {Uint8Array} data
 * @returns {ArrayBuffer}
 */
function toArrayBuffer(data) {
  const byteOffset = TypedArrayPrototypeGetByteOffset(data);
  const byteLength = TypedArrayPrototypeGetByteLength(data);
  const buffer = TypedArrayPrototypeGetBuffer(data);
  if (isSharedArrayBuffer(buffer)) {
    const copy = new Uint8Array(byteLength);
    TypedArrayPrototypeSet(copy, data);
    return TypedArrayPrototypeGetBuffer(copy);
  }
  if (byteOffset === 0 &&
      byteLength === ArrayBufferPrototypeGetByteLength(buffer)) {
    return buffer;
  }
  return ArrayBufferPrototypeSlice(buffer, byteOffset,
                                   byteOffset + byteLength);
}

// =============================================================================
// Sync Consumers
// =============================================================================

const kNullPrototype = { __proto__: null };

/**
 * Collect all bytes from a sync source.
 * @param {Iterable<Uint8Array[]>} source
 * @param {{ limit?: number }} [options]
 * @returns {Uint8Array}
 */
function bytesSync(source, options = kNullPrototype) {
  options = converters.ConsumeSyncOptions(options, {
    __proto__: null,
    context: 'options',
  });
  return concatBytes(collectSync(source, options.limit));
}

/**
 * Collect and decode text from a sync source.
 * @param {Iterable<Uint8Array[]>} source
 * @param {{ encoding?: string, limit?: number }} [options]
 * @returns {string}
 */
function textSync(source, options = kNullPrototype) {
  options = converters.TextConsumeSyncOptions(options, {
    __proto__: null,
    context: 'options',
  });
  try {
    new TextDecoder(options.encoding);
  } catch {
    throw new ERR_INVALID_ARG_VALUE.RangeError(
      'options.encoding', options.encoding);
  }
  const data = concatBytes(collectSync(source, options.limit));
  const decoder = new TextDecoder(options.encoding, {
    __proto__: null,
    fatal: true,
  });
  return decoder.decode(data);
}

/**
 * Collect bytes as ArrayBuffer from a sync source.
 * @param {Iterable<Uint8Array[]>} source
 * @param {{ limit?: number }} [options]
 * @returns {ArrayBuffer}
 */
function arrayBufferSync(source, options = kNullPrototype) {
  options = converters.ConsumeSyncOptions(options, {
    __proto__: null,
    context: 'options',
  });
  return toArrayBuffer(concatBytes(collectSync(source, options.limit)));
}

/**
 * Collect all chunks as an array from a sync source.
 * @param {Iterable<Uint8Array[]>} source
 * @param {{ limit?: number }} [options]
 * @returns {Uint8Array[]}
 */
function arraySync(source, options = kNullPrototype) {
  options = converters.ConsumeSyncOptions(options, {
    __proto__: null,
    context: 'options',
  });
  return collectSync(source, options.limit);
}

/**
 * Read a sync source to completion, discarding every chunk.
 * @param {Iterable<Uint8Array[]>} source
 * @param {{ limit?: number }} [options]
 * @returns {undefined}
 */
function dumpSync(source, options = kNullPrototype) {
  options = converters.ConsumeSyncOptions(options, {
    __proto__: null,
    context: 'options',
  });

  const limit = options.limit;
  const normalized = fromSync(source);
  let totalBytes = 0;

  for (const batch of normalized) {
    // With no limit, just iterate through the stream completely.
    if (limit === undefined) continue;
    // Otherwise, calculate totalBytes and track the limit.
    for (let i = 0; i < batch.length; i++) {
      totalBytes += TypedArrayPrototypeGetByteLength(batch[i]);
      if (totalBytes > limit) {
        throw new ERR_OUT_OF_RANGE('totalBytes', `<= ${limit}`, totalBytes);
      }
    }
  }
}

// =============================================================================
// Async Consumers
// =============================================================================

/**
 * Collect all bytes from an async or sync source.
 * @param {AsyncIterable<Uint8Array[]>|Iterable<Uint8Array[]>} source
 * @param {{ signal?: AbortSignal, limit?: number }} [options]
 * @returns {Promise<Uint8Array>}
 */
async function bytes(source, options = kNullPrototype) {
  options = converters.ConsumeOptions(options, {
    __proto__: null,
    context: 'options',
  });
  const chunks = await collectAsync(source, options.signal, options.limit);
  return concatBytes(chunks);
}

/**
 * Collect and decode text from an async or sync source.
 * @param {AsyncIterable<Uint8Array[]>|Iterable<Uint8Array[]>} source
 * @param {{ encoding?: string, signal?: AbortSignal, limit?: number }} [options]
 * @returns {Promise<string>}
 */
async function text(source, options = kNullPrototype) {
  options = converters.TextConsumeOptions(options, {
    __proto__: null,
    context: 'options',
  });
  try {
    new TextDecoder(options.encoding);
  } catch {
    throw new ERR_INVALID_ARG_VALUE.RangeError(
      'options.encoding', options.encoding);
  }
  const chunks = await collectAsync(source, options.signal, options.limit);
  const data = concatBytes(chunks);
  const decoder = new TextDecoder(options.encoding, {
    __proto__: null,
    fatal: true,
  });
  return decoder.decode(data);
}

/**
 * Collect bytes as ArrayBuffer from an async or sync source.
 * @param {AsyncIterable<Uint8Array[]>|Iterable<Uint8Array[]>} source
 * @param {{ signal?: AbortSignal, limit?: number }} [options]
 * @returns {Promise<ArrayBuffer>}
 */
async function arrayBuffer(source, options = kNullPrototype) {
  options = converters.ConsumeOptions(options, {
    __proto__: null,
    context: 'options',
  });
  const chunks = await collectAsync(source, options.signal, options.limit);
  return toArrayBuffer(concatBytes(chunks));
}

/**
 * Collect all chunks as an array from an async or sync source.
 * @param {AsyncIterable<Uint8Array[]>|Iterable<Uint8Array[]>} source
 * @param {{ signal?: AbortSignal, limit?: number }} [options]
 * @returns {Promise<Uint8Array[]>}
 */
async function array(source, options = kNullPrototype) {
  options = converters.ConsumeOptions(options, {
    __proto__: null,
    context: 'options',
  });
  return collectAsync(source, options.signal, options.limit);
}

/**
 * Read an async or sync source to completion, discarding every chunk.
 * @param {AsyncIterable<Uint8Array[]>|Iterable<Uint8Array[]>} source
 * @param {{ signal?: AbortSignal, limit?: number }} [options]
 * @returns {Promise<undefined>}
 */
async function dump(source, options = kNullPrototype) {
  options = converters.ConsumeOptions(options, {
    __proto__: null,
    context: 'options',
  });
  const signal = options.signal;
  const limit = options.limit;

  signal?.throwIfAborted();

  const abortableSource = signal && isAsyncIterable(source) ?
    yieldAbortable(source, signal) : source;
  const normalized = from(abortableSource);
  const iterable = signal ? yieldAbortable(normalized, signal) : normalized;

  let totalBytes = 0;

  for await (const batch of iterable) {
    signal?.throwIfAborted();
    // With no limit, just iterate through the stream completely.
    if (limit === undefined) continue;
    // Otherwise, calculate totalBytes and track the limit.
    for (let i = 0; i < batch.length; i++) {
      totalBytes += TypedArrayPrototypeGetByteLength(batch[i]);
      if (totalBytes > limit) {
        throw new ERR_OUT_OF_RANGE('totalBytes', `<= ${limit}`, totalBytes);
      }
    }
  }
}

// =============================================================================
// Tap Utilities
// =============================================================================

/**
 * Create a pass-through transform that observes chunks without modifying them.
 * @param {Function} callback
 * @returns {Function}
 */
function tap(callback) {
  validateFunction(callback, 'callback');
  return async (chunks, options) => {
    await callback(chunks, options);
    return chunks;
  };
}

/**
 * Create a sync pass-through transform that observes chunks.
 * @param {Function} callback
 * @returns {Function}
 */
function tapSync(callback) {
  validateFunction(callback, 'callback');
  return (chunks) => {
    callback(chunks);
    return chunks;
  };
}

// =============================================================================
// Drain Utility
// =============================================================================

/**
 * Wait for a drainable object's backpressure to clear.
 * @param {object} drainable
 * @returns {Promise<boolean>|null}
 */
function ondrain(drainable) {
  if (
    drainable === null ||
    drainable === undefined ||
    typeof drainable !== 'object'
  ) {
    return null;
  }

  const protocol = getProtocolMethod(drainable, drainableProtocol);
  return protocol === undefined ?
    null : FunctionPrototypeCall(protocol, drainable);
}

// =============================================================================
// Merge Utility
// =============================================================================

const kNoMergeError = Symbol('kNoMergeError');

/**
 * Merge multiple async iterables by yielding values in temporal order.
 * @param {...(AsyncIterable<Uint8Array[]>|object)} args
 * @returns {AsyncIterable<Uint8Array[]>}
 */
function merge(...args) {
  let sources;
  let options;

  if (args.length > 0 && isMergeOptions(args[args.length - 1])) {
    options = args[args.length - 1];
    sources = ArrayPrototypeSlice(args, 0, -1);
  } else {
    sources = args;
  }

  options = converters.MergeOptions(options, {
    __proto__: null,
    context: 'options',
  });

  // Normalize each source via from()
  const normalized = ArrayPrototypeMap(sources, (source) => from(source));

  return {
    __proto__: null,
    async *[SymbolAsyncIterator]() {
      const { signal } = options;

      signal?.throwIfAborted();

      if (normalized.length === 0) return;

      if (normalized.length === 1) {
        const source = signal !== undefined && isAsyncIterable(sources[0]) ?
          from(yieldAbortable(sources[0], signal)) :
          yieldAbortable(normalized[0], signal);
        for await (const batch of source) {
          yield batch;
        }
        return;
      }

      // Multiple sources - use a ready queue so that batches that settle
      // between consumer pulls are drained synchronously without an extra
      // async tick per batch. Each source has at most one pending .next()
      // at a time. Every batch from every source is preserved.
      const ready = [];
      const pendingPulls = new SafeSet();
      let activeCount = normalized.length;
      let waitResolve = null;
      let onAbort;
      let stopped = false;

      if (signal) {
        onAbort = () => {
          if (waitResolve) {
            waitResolve();
            waitResolve = null;
          }
        };
        signal.addEventListener('abort', onAbort, {
          __proto__: null,
          once: true,
        });
      }

      // Called when a source's .next() settles. Pushes the result into
      // the ready queue and wakes the consumer if it's waiting.
      const onSettled = (iterator, result) => {
        pendingPulls.delete(iterator);
        if (stopped) return;
        if (result.done) {
          activeCount--;
        } else {
          ArrayPrototypePush(ready, {
            __proto__: null,
            kind: 'value',
            iterator,
            value: result.value,
          });
        }
        if (waitResolve) {
          waitResolve();
          waitResolve = null;
        }
      };

      const onRejected = (iterator, reason) => {
        pendingPulls.delete(iterator);
        if (stopped) return;
        ArrayPrototypePush(ready, {
          __proto__: null,
          kind: 'error',
          reason,
        });
        if (waitResolve) {
          waitResolve();
          waitResolve = null;
        }
      };

      // Start one .next() per source
      const iterators = [];
      for (let i = 0; i < normalized.length; i++) {
        const iterator = normalized[i][SymbolAsyncIterator]();
        ArrayPrototypePush(iterators, iterator);
        pendingPulls.add(iterator);
        PromisePrototypeThen(
          iterator.next(),
          (r) => onSettled(iterator, r),
          (reason) => onRejected(iterator, reason),
        );
      }

      let primaryError = kNoMergeError;
      try {
        while (activeCount > 0 || ready.length > 0) {
          signal?.throwIfAborted();

          // Drain ready queue synchronously
          while (ready.length > 0) {
            const item = ArrayPrototypeShift(ready);
            if (item.kind === 'error') {
              throw item.reason;
            }
            yield item.value;
            pendingPulls.add(item.iterator);
            PromisePrototypeThen(
              item.iterator.next(),
              (r) => onSettled(item.iterator, r),
              (reason) => onRejected(item.iterator, reason),
            );
          }

          // If sources are still active, wait for the next settlement
          if (activeCount > 0) {
            await new Promise((resolve) => {
              waitResolve = resolve;
              if (signal?.aborted) {
                waitResolve = null;
                resolve();
              }
            });
          }
        }
      } catch (err) {
        primaryError = err;
      } finally {
        stopped = true;
        if (onAbort !== undefined) {
          signal.removeEventListener('abort', onAbort);
        }
        // Clean up: return all iterators. Cleanup errors are not
        // swallowed - a broken iterator.return() (e.g., failing to
        // release a resource) should be visible to the caller.
        await cleanupIterators(
          iterators,
          primaryError,
          pendingPulls,
        );
      }
    },
  };
}

async function cleanupIterators(iterators, primaryError, pendingPulls) {
  let cleanupError = kNoMergeError;
  await SafePromiseAllReturnVoid(iterators, async (iterator) => {
    if (iterator.return) {
      try {
        const result = iterator.return();
        if (pendingPulls.has(iterator)) {
          markPromiseAsHandled(result);
        } else {
          await result;
        }
      } catch (err) {
        // Keep the first cleanup error encountered.
        if (cleanupError === kNoMergeError) cleanupError = err;
      }
    }
  });
  if (cleanupError !== kNoMergeError) {
    if (primaryError !== kNoMergeError) {
      // Both a primary error and a cleanup error occurred.
      // Wrap in SuppressedError so neither is lost:
      // .error = primaryError, .suppressed = cleanupError.
      // eslint-disable-next-line no-restricted-syntax
      throw new SuppressedError(primaryError, cleanupError);
    }
    // No primary error - the cleanup error is the only error.
    throw cleanupError;
  }
  if (primaryError !== kNoMergeError) {
    throw primaryError;
  }
}

module.exports = {
  array,
  arrayBuffer,
  arrayBufferSync,
  arraySync,
  bytes,
  bytesSync,
  dump,
  dumpSync,
  merge,
  ondrain,
  tap,
  tapSync,
  text,
  textSync,
};

sources.internal/streams/iter/duplex:
'use strict';

// New Streams API - Duplex Channel
//
// Creates a pair of connected channels where data written to one
// channel's writer appears in the other channel's readable.

const {
  SafePromiseAllReturnVoid,
  SymbolAsyncDispose,
  SymbolAsyncIterator,
} = primordials;

const {
  isConsumerReturnError,
  push,
} = require('internal/streams/iter/push');
const {
  converters,
} = require('internal/streams/iter/webidl');

/**
 * Create a pair of connected duplex channels for bidirectional communication.
 * @param {{ budget?: number, backpressure?: string, signal?: AbortSignal,
 *           a?: object, b?: object }} [options]
 * @returns {[DuplexChannel, DuplexChannel]}
 */
function duplex(options = { __proto__: null }) {
  options = converters.DuplexOptions(options, {
    __proto__: null,
    context: 'options',
  });
  const { budget, backpressure, signal, a, b } = options;

  // Channel A writes to B's readable (A->B direction).
  // Signal is NOT passed to push() -- we handle abort via close() below.
  const { writer: aWriter, readable: bReadable } = push({
    budget: a?.budget ?? budget,
    backpressure: a?.backpressure ?? backpressure,
  });

  // Channel B writes to A's readable (B->A direction)
  const { writer: bWriter, readable: aReadable } = push({
    budget: b?.budget ?? budget,
    backpressure: b?.backpressure ?? backpressure,
  });

  let cleanupSignal;
  const onClose = () => cleanupSignal?.();
  const channelA = createDuplexChannel(aWriter, aReadable, onClose);
  const channelB = createDuplexChannel(bWriter, bReadable, onClose);

  // Signal handler: fail both writers with the abort reason so consumers
  // see the error. This is an error-path shutdown, not a clean close.
  if (signal) {
    const abortBoth = () => {
      const reason = signal.reason;
      aWriter.fail(reason);
      bWriter.fail(reason);
      cleanupSignal?.();
    };
    cleanupSignal = () => {
      signal.removeEventListener('abort', abortBoth);
      cleanupSignal = undefined;
    };
    if (signal.aborted) {
      abortBoth();
    } else {
      signal.addEventListener('abort', abortBoth,
                              { __proto__: null, once: true });
    }
  }

  return [channelA, channelB];
}

function createDuplexChannel(writer, readable, onClose) {
  // A push readable has one shared consumer state. Keeping an iterator from
  // creation lets close() terminate that state even if no caller has iterated.
  const closeIterator = readable[SymbolAsyncIterator]();
  let closePromise;

  return {
    __proto__: null,
    get writer() { return writer; },
    get readable() { return readable; },
    close() {
      closePromise ??= closeDuplexChannel(writer, closeIterator, onClose);
      return closePromise;
    },
    [SymbolAsyncDispose]() {
      return this.close();
    },
  };
}

async function closeDuplexChannel(writer, closeIterator, onClose) {
  try {
    const result = writer.endSync();
    const endPromise = result < 0 ? writer.end() : undefined;
    const returnPromise = closeIterator.return();

    if (endPromise !== undefined) {
      try {
        await SafePromiseAllReturnVoid([endPromise, returnPromise]);
      } catch (error) {
        if (!isConsumerReturnError(error)) throw error;
      }
    } else {
      await returnPromise;
    }
  } finally {
    onClose();
  }
}

module.exports = {
  duplex,
};

sources.internal/streams/iter/from:
'use strict';

// New Streams API - from() and fromSync()
//
// Creates normalized byte stream iterables from various input types.
// Handles recursive flattening of nested iterables and protocol conversions.

const {
  ArrayBufferIsView,
  ArrayIsArray,
  ArrayPrototypeEvery,
  ArrayPrototypePush,
  ArrayPrototypeSlice,
  DataViewPrototypeGetBuffer,
  DataViewPrototypeGetByteLength,
  DataViewPrototypeGetByteOffset,
  FunctionPrototypeCall,
  PromisePrototypeThen,
  PromiseResolve,
  PromiseWithResolvers,
  SafePromiseRace,
  Symbol,
  SymbolAsyncIterator,
  SymbolIterator,
  TypedArrayPrototypeGetBuffer,
  TypedArrayPrototypeGetByteLength,
  TypedArrayPrototypeGetByteOffset,
  Uint8Array,
} = primordials;

const { markPromiseAsHandled } = internalBinding('util');

const {
  codes: {
    ERR_INVALID_ARG_TYPE,
    ERR_INVALID_RETURN_VALUE,
  },
} = require('internal/errors');
const { lazyDOMException } = require('internal/util');

const {
  isAnyArrayBuffer,
  isPromise,
  isTypedArray,
  isUint8Array,
} = require('internal/util/types');

const {
  kValidatedSource,
  toStreamable,
  toAsyncStreamable,
} = require('internal/streams/iter/types');

const {
  getProtocolMethod,
  toUint8Array,
} = require('internal/streams/iter/utils');

// Maximum number of chunks to yield per batch from from()/fromSync().
// Bounds peak memory when arrays flow through transforms, which must
// allocate output for the entire batch at once.
const FROM_BATCH_SIZE = 128;
const kNormalizationCancelled = Symbol('kNormalizationCancelled');
// Yielded by normalizeAsyncValue() (only when `emitFlush` is true) right
// before it waits on a promise or on a nested async iterable. Callers that
// batch chunks yield whatever they have collected so far, so that chunks that
// are already available are not held back until the wait completes.
const kFlushBatch = Symbol('kFlushBatch');

function createNormalizationContext() {
  return {
    __proto__: null,
    cancelled: false,
    reason: undefined,
    resolve: null,
    suppressCleanup: false,
  };
}

function cancelNormalization(context, reason, suppressCleanup = false) {
  if (context.cancelled) return;
  context.cancelled = true;
  context.reason = reason;
  context.suppressCleanup = suppressCleanup;
  context.resolve?.(kNormalizationCancelled);
}

function throwIfNormalizationCancelled(context) {
  if (context?.cancelled) throw context.reason;
}

async function waitForNormalization(value, context) {
  if (context === undefined) return value;
  const { promise, resolve } = PromiseWithResolvers();
  if (context.cancelled) {
    resolve(kNormalizationCancelled);
  } else {
    context.resolve = resolve;
  }
  try {
    const result = await SafePromiseRace([
      PromiseResolve(value),
      promise,
    ]);
    throwIfNormalizationCancelled(context);
    return result;
  } finally {
    if (context.resolve === resolve) context.resolve = null;
  }
}

function createNormalizationIterator(createIterator) {
  const context = createNormalizationContext();
  const iterator = createIterator(context);
  return {
    __proto__: null,
    next(value) {
      return FunctionPrototypeCall(iterator.next, iterator, value);
    },
    return(value) {
      cancelNormalization(
        context, lazyDOMException('Aborted', 'AbortError'));
      return FunctionPrototypeCall(iterator.return, iterator, value);
    },
    throw(error) {
      cancelNormalization(context, error, true);
      return FunctionPrototypeCall(iterator.throw, iterator, error);
    },
    [SymbolAsyncIterator]() {
      return this;
    },
  };
}

function createNormalizationSource(createIterator) {
  return {
    __proto__: null,
    [SymbolAsyncIterator]() {
      return createNormalizationIterator(createIterator);
    },
  };
}

// =============================================================================
// Type Guards and Detection
// =============================================================================

/**
 * Check if value is a primitive chunk (string, ArrayBuffer, or ArrayBufferView).
 * @returns {boolean}
 */
function isPrimitiveChunk(value) {
  return typeof value === 'string' || isAnyArrayBuffer(value) || ArrayBufferIsView(value);
}

/**
 * Check if value is a sync iterable (has Symbol.iterator).
 * @returns {boolean}
 */
function isSyncIterable(value) {
  // We do not consider regular strings to be sync iterables in this context.
  // We don't care about boxed strings (String objects) since they are uncommon.
  return typeof value !== 'string' &&
      typeof value?.[SymbolIterator] === 'function';
}

/**
 * Check if value is an async iterable (has Symbol.asyncIterator).
 * @returns {boolean}
 */
function isAsyncIterable(value) {
  return typeof value?.[SymbolAsyncIterator] === 'function';
}

// =============================================================================
// Primitive Conversion
// =============================================================================

/**
 * Convert a primitive chunk to Uint8Array.
 * - string: UTF-8 encoded
 * - ArrayBuffer: wrapped as Uint8Array view (no copy)
 * - ArrayBufferView: converted to Uint8Array view of same memory
 * @param {string|ArrayBuffer|ArrayBufferView} chunk
 * @returns {Uint8Array}
 */
function primitiveToUint8Array(chunk) {
  if (typeof chunk === 'string') {
    return toUint8Array(chunk);
  }
  if (isAnyArrayBuffer(chunk)) {
    return new Uint8Array(chunk);
  }
  if (isUint8Array(chunk)) {
    return chunk;
  }
  // Other ArrayBufferView types (Int8Array, DataView, etc.)
  return arrayBufferViewToUint8Array(chunk);
}

function arrayBufferViewToUint8Array(chunk) {
  if (isTypedArray(chunk)) {
    return new Uint8Array(
      TypedArrayPrototypeGetBuffer(chunk),
      TypedArrayPrototypeGetByteOffset(chunk),
      TypedArrayPrototypeGetByteLength(chunk),
    );
  }
  return new Uint8Array(
    DataViewPrototypeGetBuffer(chunk),
    DataViewPrototypeGetByteOffset(chunk),
    DataViewPrototypeGetByteLength(chunk),
  );
}

// =============================================================================
// Sync Normalization (for fromSync and sync contexts)
// =============================================================================

/**
 * Normalize a sync streamable yield value to Uint8Array chunks.
 * Recursively flattens arrays, iterables, and protocol conversions.
 * @yields {Uint8Array}
 */
function* normalizeSyncValue(value) {
  // Handle primitives
  if (isPrimitiveChunk(value)) {
    yield primitiveToUint8Array(value);
    return;
  }

  // Handle ToStreamable protocol
  const streamableMethod = getProtocolMethod(value, toStreamable);
  if (streamableMethod !== undefined) {
    const result = FunctionPrototypeCall(streamableMethod, value);
    yield* normalizeSyncValue(result);
    return;
  }

  // Handle arrays (which are also iterable, but check first for efficiency)
  if (ArrayIsArray(value)) {
    for (let i = 0; i < value.length; i++) {
      yield* normalizeSyncValue(value[i]);
    }
    return;
  }

  // Handle other sync iterables
  if (isSyncIterable(value)) {
    for (const item of value) {
      yield* normalizeSyncValue(item);
    }
    return;
  }

  // Reject: no valid conversion
  throw new ERR_INVALID_ARG_TYPE(
    'value',
    ['string', 'ArrayBuffer', 'ArrayBufferView', 'Iterable', 'toStreamable'],
    value,
  );
}

/**
 * Check if value is already a Uint8Array[] batch (fast path).
 * @returns {boolean}
 */
function isUint8ArrayBatch(value) {
  if (!ArrayIsArray(value)) return false;
  const len = value.length;
  if (len === 0) return true;
  // Fast path: single-element batch (most common from transforms)
  if (len === 1) return isUint8Array(value[0]);
  // Check first and last before iterating all elements
  if (!isUint8Array(value[0]) || !isUint8Array(value[len - 1])) return false;
  if (len === 2) return true;
  for (let i = 1; i < len - 1; i++) {
    if (!isUint8Array(value[i])) return false;
  }
  return true;
}

function* yieldBoundedBatch(batch) {
  if (batch.length === 0) {
    return;
  }
  if (batch.length <= FROM_BATCH_SIZE) {
    yield batch;
    return;
  }
  for (let i = 0; i < batch.length; i += FROM_BATCH_SIZE) {
    yield ArrayPrototypeSlice(batch, i, i + FROM_BATCH_SIZE);
  }
}

/**
 * Normalize a sync streamable source, yielding batches of Uint8Array.
 * @param {Iterable} source
 * @yields {Uint8Array[]}
 */
function* normalizeSyncSource(source) {
  let batch = [];

  for (const value of source) {
    // Fast path 1: value is already a Uint8Array[] batch
    if (isUint8ArrayBatch(value)) {
      if (batch.length > 0) {
        yield batch;
        batch = [];
      }
      yield* yieldBoundedBatch(value);
      continue;
    }
    // Fast path 2: value is a single Uint8Array (very common)
    if (isUint8Array(value)) {
      ArrayPrototypePush(batch, value);
      if (batch.length === FROM_BATCH_SIZE) {
        yield batch;
        batch = [];
      }
      continue;
    }
    // Slow path: normalize the value
    if (batch.length > 0) {
      yield batch;
      batch = [];
    }
    let valueBatch = [];
    for (const chunk of normalizeSyncValue(value)) {
      ArrayPrototypePush(valueBatch, chunk);
      if (valueBatch.length === FROM_BATCH_SIZE) {
        yield valueBatch;
        valueBatch = [];
      }
    }
    if (valueBatch.length > 0) {
      yield valueBatch;
    }
  }

  if (batch.length > 0) {
    yield batch;
  }
}

function yieldNormalizationAbortable(source, context) {
  if (context === undefined) return source;
  return {
    __proto__: null,
    [SymbolAsyncIterator]() {
      const iteratorMethod = source[SymbolAsyncIterator];
      const iterator = FunctionPrototypeCall(iteratorMethod, source);
      const nextMethod = iterator.next;
      let completed = false;
      let closed = false;
      let reading = false;

      async function closeSource(suppressError) {
        if (closed) return;
        closed = true;
        completed = true;

        if (suppressError) {
          try {
            const returnMethod = iterator.return;
            if (typeof returnMethod === 'function') {
              const cleanup = PromisePrototypeThen(
                PromiseResolve(),
                () => FunctionPrototypeCall(returnMethod, iterator));
              markPromiseAsHandled(cleanup);
            }
          } catch {
            // Cancellation has precedence over source cleanup errors.
          }
          return;
        }

        const returnMethod = iterator.return;
        if (typeof returnMethod === 'function') {
          const result = await FunctionPrototypeCall(returnMethod, iterator);
          if ((typeof result !== 'object' && typeof result !== 'function') ||
              result === null) {
            throw new ERR_INVALID_RETURN_VALUE(
              'an object', 'iterator.return()', result);
          }
        }
      }

      return {
        __proto__: null,
        async next() {
          if (completed) {
            return { __proto__: null, done: true, value: undefined };
          }
          throwIfNormalizationCancelled(context);
          reading = true;

          try {
            const next = FunctionPrototypeCall(nextMethod, iterator);
            const result = await waitForNormalization(next, context);
            if ((typeof result !== 'object' && typeof result !== 'function') ||
                result === null) {
              throw new ERR_INVALID_RETURN_VALUE(
                'an object', 'iterator.next()', result);
            }
            if (result.done) {
              reading = false;
              throwIfNormalizationCancelled(context);
              completed = true;
              closed = true;
              return { __proto__: null, done: true, value: result.value };
            }
            const value = result.value;
            reading = false;
            throwIfNormalizationCancelled(context);
            return { __proto__: null, done: false, value };
          } catch (error) {
            if (context.cancelled) await closeSource(true);
            reading = false;
            throw error;
          }
        },
        async return(value) {
          await closeSource(
            context.suppressCleanup || (context.cancelled && reading));
          return { __proto__: null, done: true, value };
        },
        async throw(error) {
          await closeSource(
            context.suppressCleanup || (context.cancelled && reading));
          throw error;
        },
        [SymbolAsyncIterator]() {
          return this;
        },
      };
    },
  };
}

// =============================================================================
// Async Normalization (for from and async contexts)
// =============================================================================

/**
 * Normalize an async streamable yield value to Uint8Array chunks.
 * Recursively flattens arrays, iterables, async iterables, promises,
 * and protocol conversions.
 * @yields {Uint8Array}
 */
async function* normalizeAsyncValue(
  value, allowNestedAsyncStreamables = true, context, emitFlush = false) {
  throwIfNormalizationCancelled(context);

  // Handle promises first
  if (isPromise(value)) {
    if (emitFlush) yield kFlushBatch;
    const resolved = await waitForNormalization(value, context);
    yield* normalizeAsyncValue(
      resolved, allowNestedAsyncStreamables, context, emitFlush);
    return;
  }

  // Handle primitives
  if (isPrimitiveChunk(value)) {
    yield primitiveToUint8Array(value);
    return;
  }

  const hasDisallowedAsyncIterator =
    !allowNestedAsyncStreamables && isAsyncIterable(value);
  const asyncStreamableMethod = hasDisallowedAsyncIterator ?
    undefined : getProtocolMethod(value, toAsyncStreamable);
  if (hasDisallowedAsyncIterator ||
      (!allowNestedAsyncStreamables && asyncStreamableMethod !== undefined)) {
    throw new ERR_INVALID_ARG_TYPE(
      'value',
      ['string', 'ArrayBuffer', 'ArrayBufferView', 'Iterable', 'toStreamable'],
      value,
    );
  }

  // Handle ToAsyncStreamable protocol (check before ToStreamable)
  if (asyncStreamableMethod !== undefined) {
    const result = FunctionPrototypeCall(asyncStreamableMethod, value);
    if (isPromise(result)) {
      if (emitFlush) yield kFlushBatch;
      yield* normalizeAsyncValue(
        await waitForNormalization(result, context),
        allowNestedAsyncStreamables,
        context,
        emitFlush);
    } else {
      yield* normalizeAsyncValue(
        result, allowNestedAsyncStreamables, context, emitFlush);
    }
    return;
  }

  // Handle ToStreamable protocol
  const streamableMethod = getProtocolMethod(value, toStreamable);
  if (streamableMethod !== undefined) {
    const result = FunctionPrototypeCall(streamableMethod, value);
    yield* normalizeAsyncValue(
      result, allowNestedAsyncStreamables, context, emitFlush);
    return;
  }

  // Handle arrays (which are also iterable, but check first for efficiency)
  if (ArrayIsArray(value)) {
    for (let i = 0; i < value.length; i++) {
      yield* normalizeAsyncValue(
        value[i], allowNestedAsyncStreamables, context, emitFlush);
    }
    return;
  }

  // Handle async iterables (check before sync iterables since some objects
  // have both)
  if (isAsyncIterable(value)) {
    const iterable = yieldNormalizationAbortable(value, context);
    if (emitFlush) yield kFlushBatch;
    for await (const item of iterable) {
      yield* normalizeAsyncValue(
        item, allowNestedAsyncStreamables, context, emitFlush);
      if (emitFlush) yield kFlushBatch;
    }
    return;
  }

  // Handle sync iterables
  if (isSyncIterable(value)) {
    for (const item of value) {
      yield* normalizeAsyncValue(
        item, allowNestedAsyncStreamables, context, emitFlush);
    }
    return;
  }

  // Reject: no valid conversion
  throw new ERR_INVALID_ARG_TYPE(
    'value',
    ['string', 'ArrayBuffer', 'ArrayBufferView', 'Iterable', 'AsyncIterable',
     'toStreamable', 'toAsyncStreamable'],
    value,
  );
}

/**
 * Normalize an async streamable source, yielding batches of Uint8Array.
 * @param {AsyncIterable|Iterable} source
 * @yields {Uint8Array[]}
 */
async function* normalizeAsyncSource(source, context) {
  throwIfNormalizationCancelled(context);

  // Prefer async iteration if available
  if (isAsyncIterable(source)) {
    const iterable = yieldNormalizationAbortable(source, context);
    for await (const value of iterable) {
      // Fast path 1: value is already a Uint8Array[] batch
      if (isUint8ArrayBatch(value)) {
        yield* yieldBoundedBatch(value);
        continue;
      }
      // Fast path 2: value is a single Uint8Array (very common)
      if (isUint8Array(value)) {
        yield [value];
        continue;
      }
      // Slow path: normalize the value. Chunks are batched, but whatever has
      // been collected is yielded before waiting on async content (such as a
      // nested async iterable), so data is not held back until it ends.
      let batch = [];
      for await (const chunk of
        normalizeAsyncValue(value, true, context, true)) {
        if (chunk === kFlushBatch) {
          if (batch.length > 0) {
            yield batch;
            batch = [];
          }
          continue;
        }
        ArrayPrototypePush(batch, chunk);
        if (batch.length === FROM_BATCH_SIZE) {
          yield batch;
          batch = [];
        }
      }
      if (batch.length > 0) {
        yield batch;
      }
    }
    return;
  }

  // Fall back to sync iteration - batch sync values together with a bound.
  if (isSyncIterable(source)) {
    let batch = [];

    for (const value of source) {
      throwIfNormalizationCancelled(context);
      // Fast path 1: value is already a Uint8Array[] batch
      if (isUint8ArrayBatch(value)) {
        // Flush any accumulated batch first
        if (batch.length > 0) {
          yield batch;
          batch = [];
        }
        yield* yieldBoundedBatch(value);
        continue;
      }
      // Fast path 2: value is a single Uint8Array (very common)
      if (isUint8Array(value)) {
        ArrayPrototypePush(batch, value);
        if (batch.length === FROM_BATCH_SIZE) {
          yield batch;
          batch = [];
        }
        continue;
      }
      // Slow path: normalize the value - must flush and yield individually
      if (batch.length > 0) {
        yield batch;
        batch = [];
      }
      let asyncBatch = [];
      for await (const chunk of
        normalizeAsyncValue(value, false, context, true)) {
        if (chunk === kFlushBatch) {
          if (asyncBatch.length > 0) {
            yield asyncBatch;
            asyncBatch = [];
          }
          continue;
        }
        ArrayPrototypePush(asyncBatch, chunk);
        if (asyncBatch.length === FROM_BATCH_SIZE) {
          yield asyncBatch;
          asyncBatch = [];
        }
      }
      if (asyncBatch.length > 0) {
        yield asyncBatch;
      }
    }

    // Yield any remaining batched values
    if (batch.length > 0) {
      yield batch;
    }
    return;
  }

  throw new ERR_INVALID_ARG_TYPE(
    'source',
    ['Iterable', 'AsyncIterable'],
    source,
  );
}

async function* normalizeAsyncStreamableResult(result, context) {
  const resolved = await waitForNormalization(result, context);
  const source = resolved?.[kValidatedSource] ? resolved : from(resolved);
  yield* yieldNormalizationAbortable(source, context);
}

// =============================================================================
// Public API: from() and fromSync()
// =============================================================================

/**
 * Create a SyncByteStreamReadable from a ByteInput or SyncStreamable.
 * @param {string|ArrayBuffer|ArrayBufferView|Iterable} input
 * @returns {Iterable<Uint8Array[]>}
 */
function fromSync(input) {
  if (input == null) {
    throw new ERR_INVALID_ARG_TYPE('input', 'a non-null value', input);
  }

  // Check for primitives first (ByteInput)
  if (isPrimitiveChunk(input)) {
    const chunk = primitiveToUint8Array(input);
    return {
      __proto__: null,
      *[SymbolIterator]() {
        yield [chunk];
      },
    };
  }

  // Check toStreamable protocol (takes precedence over iteration protocols).
  // toAsyncStreamable is ignored entirely in fromSync.
  const streamableMethod = getProtocolMethod(input, toStreamable);
  if (streamableMethod !== undefined) {
    return fromSync(FunctionPrototypeCall(streamableMethod, input));
  }

  // Fast path: Uint8Array[] - yield in bounded sub-batches.
  // Yielding the entire array as one batch forces downstream transforms
  // to process all data at once, causing peak memory proportional to total
  // data volume. Sub-batching keeps peak memory bounded while preserving
  // the throughput benefit of batched processing.
  if (ArrayIsArray(input)) {
    if (input.length === 0) {
      return {
        __proto__: null,
        *[SymbolIterator]() {
          // Empty - yield nothing
        },
      };
    }
    // Check if it's an array of Uint8Array (common case)
    if (isUint8Array(input[0])) {
      const allUint8 = ArrayPrototypeEvery(input, isUint8Array);
      if (allUint8) {
        const batch = input;
        return {
          __proto__: null,
          *[SymbolIterator]() {
            if (batch.length <= FROM_BATCH_SIZE) {
              yield batch;
            } else {
              for (let i = 0; i < batch.length; i += FROM_BATCH_SIZE) {
                yield ArrayPrototypeSlice(batch, i, i + FROM_BATCH_SIZE);
              }
            }
          },
        };
      }
    }
  }

  const isIterable = isSyncIterable(input);

  // Reject explicit async-only inputs
  if (!isIterable && isAsyncIterable(input)) {
    throw new ERR_INVALID_ARG_TYPE(
      'input',
      'a synchronous input, not an async iterable',
      input,
    );
  }
  if (!isIterable &&
      typeof input === 'object' &&
      input !== null &&
      typeof input.then === 'function') {
    throw new ERR_INVALID_ARG_TYPE(
      'input',
      'a synchronous input, not a promise',
      input,
    );
  }

  // Must be a SyncStreamable
  if (!isIterable) {
    throw new ERR_INVALID_ARG_TYPE(
      'input',
      ['string', 'ArrayBuffer', 'ArrayBufferView', 'Iterable', 'toStreamable'],
      input,
    );
  }

  return {
    __proto__: null,
    *[SymbolIterator]() {
      yield* normalizeSyncSource(input);
    },
  };
}

/**
 * Create a ByteStreamReadable from a ByteInput or Streamable.
 * @param {string|ArrayBuffer|ArrayBufferView|Iterable|AsyncIterable} input
 * @returns {AsyncIterable<Uint8Array[]>}
 */
function from(input) {
  if (input == null) {
    throw new ERR_INVALID_ARG_TYPE('input', 'a non-null value', input);
  }

  // Check for primitives first (ByteInput)
  if (isPrimitiveChunk(input)) {
    const chunk = primitiveToUint8Array(input);
    return {
      __proto__: null,
      async *[SymbolAsyncIterator]() {
        yield [chunk];
      },
    };
  }

  // Check toAsyncStreamable protocol (takes precedence over toStreamable and
  // iteration protocols)
  const asyncStreamableMethod = getProtocolMethod(input, toAsyncStreamable);
  if (asyncStreamableMethod !== undefined) {
    let result = FunctionPrototypeCall(asyncStreamableMethod, input);
    if (isPromise(result)) {
      result = PromisePrototypeThen(result, undefined, undefined);
      markPromiseAsHandled(result);
    }
    // Synchronous validated source (e.g. Readable batched iterator)
    if (result?.[kValidatedSource]) {
      return result;
    }
    return createNormalizationSource(
      (context) => normalizeAsyncStreamableResult(result, context));
  }

  // Check toStreamable protocol (takes precedence over iteration protocols)
  const streamableMethod = getProtocolMethod(input, toStreamable);
  if (streamableMethod !== undefined) {
    return from(FunctionPrototypeCall(streamableMethod, input));
  }

  // Fast path: validated source already yields valid Uint8Array[] batches
  if (input[kValidatedSource]) {
    return input;
  }

  // Fast path: Uint8Array[] - yield in bounded sub-batches.
  // Yielding the entire array as one batch forces downstream transforms
  // to process all data at once, causing peak memory proportional to total
  // data volume. Sub-batching keeps peak memory bounded while preserving
  // the throughput benefit of batched processing.
  if (ArrayIsArray(input)) {
    if (input.length === 0) {
      return {
        __proto__: null,
        async *[SymbolAsyncIterator]() {
          // Empty - yield nothing
        },
      };
    }
    if (isUint8Array(input[0])) {
      const allUint8 = ArrayPrototypeEvery(input, isUint8Array);
      if (allUint8) {
        const batch = input;
        return {
          __proto__: null,
          async *[SymbolAsyncIterator]() {
            if (batch.length <= FROM_BATCH_SIZE) {
              yield batch;
            } else {
              for (let i = 0; i < batch.length; i += FROM_BATCH_SIZE) {
                yield ArrayPrototypeSlice(batch, i, i + FROM_BATCH_SIZE);
              }
            }
          },
        };
      }
    }
  }

  // Must be a Streamable (sync or async iterable)
  if (!isSyncIterable(input) && !isAsyncIterable(input)) {
    throw new ERR_INVALID_ARG_TYPE(
      'input',
      ['string', 'ArrayBuffer', 'ArrayBufferView', 'Iterable',
       'AsyncIterable', 'toStreamable', 'toAsyncStreamable'],
      input,
    );
  }

  return createNormalizationIterator(
    (context) => normalizeAsyncSource(input, context));
}

// =============================================================================
// Exports
// =============================================================================

module.exports = {
  arrayBufferViewToUint8Array,
  from,
  fromSync,
  isAsyncIterable,
  isPrimitiveChunk,
  isSyncIterable,
  isUint8ArrayBatch,
  normalizeAsyncSource,
  normalizeAsyncValue,
  normalizeSyncSource,
  normalizeSyncValue,
  primitiveToUint8Array,
};

sources.internal/streams/iter/pull:
'use strict';

// New Streams API - Pull Pipeline
//
// pull(), pullSync(), pipeTo(), pipeToSync()
// Pull-through pipelines with transforms. Data flows on-demand from source
// through transforms to consumer.

const {
  ArrayBufferIsView,
  ArrayPrototypePush,
  ArrayPrototypeSlice,
  FunctionPrototypeCall,
  PromisePrototypeThen,
  PromiseReject,
  PromiseResolve,
  SymbolAsyncIterator,
  SymbolIterator,
  Uint8Array,
} = primordials;

const {
  codes: {
    ERR_INVALID_ARG_TYPE,
    ERR_INVALID_ARG_VALUE,
    ERR_INVALID_STATE,
    ERR_OUT_OF_RANGE,
  },
} = require('internal/errors');
const { lazyDOMException } = require('internal/util');
const {
  isAnyArrayBuffer,
  isPromise,
  isUint8Array,
} = require('internal/util/types');
const {
  AbortController,
  AbortSignal,
  abortSignal,
} = require('internal/abort_controller');

const {
  arrayBufferViewToUint8Array,
  from,
  fromSync,
  isSyncIterable,
  isAsyncIterable,
  isUint8ArrayBatch,
} = require('internal/streams/iter/from');

const {
  createBatchEntry,
  isTransformObject,
  parsePullArgs,
  snapshotTransform,
  toUint8Array,
  validateBatchEntry,
  validateByteView,
  yieldAbortable,
} = require('internal/streams/iter/utils');
const {
  converters,
} = require('internal/streams/iter/webidl');

const {
  kValidatedTransform,
} = require('internal/streams/iter/types');

const { markPromiseAsHandled } = internalBinding('util');

// =============================================================================
// Type Guards and Helpers
// =============================================================================

/**
 * Check if a value is a Writer (has write method).
 * @returns {boolean}
 */
function hasMethod(value, name) {
  return typeof value?.[name] === 'function';
}

/**
 * Parse pipeTo/pipeToSync arguments: [...transforms, writer, options?]
 * @param {Array} args
 * @param {string} requiredMethod - 'write' for pipeTo, 'writeSync' for pipeToSync
 * @returns {{ transforms: Array, writer: object, options: unknown }}
 */
function parsePipeToArgs(args, requiredMethod) {
  if (args.length === 0) {
    throw new ERR_INVALID_ARG_VALUE('args', args, 'pipeTo requires a writer argument');
  }

  let options;
  let writerIndex = args.length - 1;

  // Check if last arg is options
  const last = args[args.length - 1];
  if (snapshotTransform(last) === undefined &&
      !hasMethod(last, requiredMethod)) {
    options = last;
    writerIndex = args.length - 2;
  }

  if (writerIndex < 0) {
    throw new ERR_INVALID_ARG_VALUE('args', args, 'pipeTo requires a writer argument');
  }

  const writer = args[writerIndex];
  if (!hasMethod(writer, requiredMethod)) {
    throw new ERR_INVALID_ARG_TYPE(
      'writer', `object with a ${requiredMethod} method`, writer);
  }

  const transforms = ArrayPrototypeSlice(args, 0, writerIndex);
  for (let i = 0; i < transforms.length; i++) {
    const transform = snapshotTransform(transforms[i]);
    if (transform === undefined) {
      throw new ERR_INVALID_ARG_TYPE(
        `transforms[${i}]`, ['Function', 'Object with transform()'],
        transforms[i]);
    }
    transforms[i] = transform;
  }

  return {
    __proto__: null,
    transforms,
    writer,
    options,
  };
}

// =============================================================================
// Transform Output Flattening
// =============================================================================

/**
 * Flatten transform yield to Uint8Array chunks (sync).
 * @yields {Uint8Array}
 */
function* flattenTransformYieldSync(value) {
  if (isUint8Array(value)) {
    yield value;
    return;
  }
  if (typeof value === 'string') {
    yield toUint8Array(value);
    return;
  }
  if (isAnyArrayBuffer(value)) {
    yield new Uint8Array(value);
    return;
  }
  if (ArrayBufferIsView(value)) {
    yield arrayBufferViewToUint8Array(value);
    return;
  }
  // Must be Iterable<TransformYield>
  if (isSyncIterable(value)) {
    for (const item of value) {
      yield* flattenTransformYieldSync(item);
    }
    return;
  }
  throw new ERR_INVALID_ARG_TYPE(
    'value',
    ['Uint8Array', 'string', 'ArrayBuffer', 'ArrayBufferView', 'Iterable'],
    value);
}

/**
 * Flatten transform yield to Uint8Array chunks (async).
 * @yields {Uint8Array}
 */
async function* flattenTransformYieldAsync(value) {
  if (isUint8Array(value)) {
    yield value;
    return;
  }
  if (typeof value === 'string') {
    yield toUint8Array(value);
    return;
  }
  if (isAnyArrayBuffer(value)) {
    yield new Uint8Array(value);
    return;
  }
  if (ArrayBufferIsView(value)) {
    yield arrayBufferViewToUint8Array(value);
    return;
  }
  // Check for async iterable first
  if (isAsyncIterable(value)) {
    for await (const item of value) {
      yield* flattenTransformYieldAsync(item);
    }
    return;
  }
  // Must be sync Iterable<TransformYield>, no nested async iterables
  if (isSyncIterable(value)) {
    for (const item of value) {
      yield* flattenTransformYieldSync(item);
    }
    return;
  }
  throw new ERR_INVALID_ARG_TYPE(
    'value',
    ['Uint8Array', 'string', 'ArrayBuffer', 'ArrayBufferView',
     'Iterable', 'AsyncIterable'],
    value);
}

/**
 * Process transform result (sync).
 * @yields {Uint8Array[]}
 */
function* processTransformResultSync(result) {
  if (result === null) {
    return;
  }
  // Single Uint8Array -> wrap as batch
  if (isUint8Array(result)) {
    yield [result];
    return;
  }
  // String -> UTF-8 encode and wrap as batch
  if (typeof result === 'string') {
    yield [toUint8Array(result)];
    return;
  }
  // ArrayBuffer / ArrayBufferView -> convert and wrap
  if (isAnyArrayBuffer(result)) {
    yield [new Uint8Array(result)];
    return;
  }
  if (ArrayBufferIsView(result)) {
    yield [arrayBufferViewToUint8Array(result)];
    return;
  }
  // Uint8Array[] batch
  if (isUint8ArrayBatch(result)) {
    if (result.length > 0) {
      yield result;
    }
    return;
  }
  // Iterable or Generator
  if (isSyncIterable(result)) {
    const batch = [];
    for (const item of result) {
      for (const chunk of flattenTransformYieldSync(item)) {
        ArrayPrototypePush(batch, chunk);
      }
    }
    if (batch.length > 0) {
      yield batch;
    }
    return;
  }
  throw new ERR_INVALID_ARG_TYPE(
    'result',
    ['null', 'Uint8Array', 'string', 'ArrayBuffer',
     'ArrayBufferView', 'Array', 'Iterable'],
    result);
}

/**
 * Append normalized transform result batches to an array (sync).
 * @param {Array<Uint8Array[]>} target
 * @param {*} result
 */
function appendTransformResultSync(target, result) {
  if (result === null) {
    return;
  }
  if (isUint8ArrayBatch(result)) {
    if (result.length > 0) {
      ArrayPrototypePush(target, result);
    }
    return;
  }
  if (isUint8Array(result)) {
    ArrayPrototypePush(target, [result]);
    return;
  }
  if (typeof result === 'string') {
    ArrayPrototypePush(target, [toUint8Array(result)]);
    return;
  }
  if (isAnyArrayBuffer(result)) {
    ArrayPrototypePush(target, [new Uint8Array(result)]);
    return;
  }
  if (ArrayBufferIsView(result)) {
    ArrayPrototypePush(target, [arrayBufferViewToUint8Array(result)]);
    return;
  }
  for (const batch of processTransformResultSync(result)) {
    ArrayPrototypePush(target, batch);
  }
}

/**
 * Process transform result (async).
 * @yields {Uint8Array[]}
 */
async function* processTransformResultAsync(result) {
  // Handle Promise
  if (isPromise(result)) {
    const resolved = await result;
    yield* processTransformResultAsync(resolved);
    return;
  }
  if (result === null) {
    return;
  }
  // Single Uint8Array -> wrap as batch
  if (isUint8Array(result)) {
    yield [result];
    return;
  }
  // String -> UTF-8 encode and wrap as batch
  if (typeof result === 'string') {
    yield [toUint8Array(result)];
    return;
  }
  // ArrayBuffer / ArrayBufferView -> convert and wrap
  if (isAnyArrayBuffer(result)) {
    yield [new Uint8Array(result)];
    return;
  }
  if (ArrayBufferIsView(result)) {
    yield [arrayBufferViewToUint8Array(result)];
    return;
  }
  // Uint8Array[] batch
  if (isUint8ArrayBatch(result)) {
    if (result.length > 0) {
      yield result;
    }
    return;
  }
  // Check for async iterable/generator first
  if (isAsyncIterable(result)) {
    const batch = [];
    for await (const item of result) {
      if (isUint8Array(item)) {
        ArrayPrototypePush(batch, item);
        continue;
      }
      for await (const chunk of flattenTransformYieldAsync(item)) {
        ArrayPrototypePush(batch, chunk);
      }
    }
    if (batch.length > 0) {
      yield batch;
    }
    return;
  }
  // Sync Iterable or Generator
  if (isSyncIterable(result)) {
    const batch = [];
    for (const item of result) {
      if (isUint8Array(item)) {
        ArrayPrototypePush(batch, item);
        continue;
      }
      // Note: This iteration is synchronous, since async iterables
      // may not be nested within sync iterables.
      for (const chunk of flattenTransformYieldSync(item)) {
        ArrayPrototypePush(batch, chunk);
      }
    }
    if (batch.length > 0) {
      yield batch;
    }
    return;
  }
  throw new ERR_INVALID_ARG_TYPE(
    'result',
    ['null', 'Uint8Array', 'string', 'ArrayBuffer',
     'ArrayBufferView', 'Array', 'Iterable', 'AsyncIterable', 'Promise'],
    result);
}

/**
 * Append normalized transform result batches to an array (async).
 * @param {Array<Uint8Array[]>} target
 * @param {*} result
 * @returns {Promise<void>|undefined}
 */
function appendTransformResultAsync(target, result) {
  if (result === null) {
    return;
  }
  if (isUint8ArrayBatch(result)) {
    if (result.length > 0) {
      ArrayPrototypePush(target, result);
    }
    return;
  }
  if (isUint8Array(result)) {
    ArrayPrototypePush(target, [result]);
    return;
  }
  if (typeof result === 'string') {
    ArrayPrototypePush(target, [toUint8Array(result)]);
    return;
  }
  if (isAnyArrayBuffer(result)) {
    ArrayPrototypePush(target, [new Uint8Array(result)]);
    return;
  }
  if (ArrayBufferIsView(result)) {
    ArrayPrototypePush(target, [arrayBufferViewToUint8Array(result)]);
    return;
  }
  return appendTransformResultAsyncSlow(target, result);
}

async function appendTransformResultAsyncSlow(target, result) {
  for await (const batch of processTransformResultAsync(result)) {
    ArrayPrototypePush(target, batch);
  }
}

function normalizeTransformResultFast(result) {
  if (isUint8ArrayBatch(result)) {
    return result.length === 0 ? null : result;
  }
  if (isUint8Array(result)) return [result];
  if (typeof result === 'string') return [toUint8Array(result)];
  if (isAnyArrayBuffer(result)) return [new Uint8Array(result)];
  if (ArrayBufferIsView(result)) return [arrayBufferViewToUint8Array(result)];
}

// =============================================================================
// Sync Pipeline Implementation
// =============================================================================

/**
 * Apply a single stateless sync transform to a source.
 * @yields {Uint8Array[]}
 */
/**
 * Apply a fused run of stateless sync transforms.
 * @param {Iterable<Uint8Array[]>} source
 * @param {Array<Function>} run - Array of stateless transform functions
 * @yields {Uint8Array[]}
 */
function* applyFusedStatelessSyncTransforms(source, run) {
  for (const chunks of source) {
    let current = chunks;
    for (let i = 0; i < run.length; i++) {
      const result = run[i](current);
      if (result === null) {
        current = null;
        break;
      }
      if (i === run.length - 1) {
        current = result;
        continue;
      }
      current = normalizeTransformResultFast(result);
      if (current === undefined) {
        const normalized = [];
        appendTransformResultSync(normalized, result);
        current = normalized.length === 0 ? null : normalized[0];
      }
      if (current === null) break;
    }
    if (current === null) continue;
    // Inline normalization with Uint8Array[] batch as the fast path,
    // matching the async pipeline's check order.
    if (isUint8ArrayBatch(current)) {
      if (current.length > 0) yield current;
    } else if (isUint8Array(current)) {
      yield [current];
    } else if (typeof current === 'string') {
      yield [toUint8Array(current)];
    } else if (isAnyArrayBuffer(current)) {
      yield [new Uint8Array(current)];
    } else if (ArrayBufferIsView(current)) {
      yield [arrayBufferViewToUint8Array(current)];
    } else {
      yield* processTransformResultSync(current);
    }
  }
  // Flush each transform after all upstream data, including data emitted by
  // earlier flushes, has been processed by that transform.
  let pending = [];
  for (let i = 0; i < run.length; i++) {
    const next = [];
    for (let j = 0; j < pending.length; j++) {
      appendTransformResultSync(next, run[i](pending[j]));
    }
    appendTransformResultSync(next, run[i](null));
    pending = next;
  }
  for (let i = 0; i < pending.length; i++) {
    yield pending[i];
  }
}

/**
 * Apply a single stateful sync transform to a source.
 * @yields {Uint8Array[]}
 */
function* withFlushSync(source) {
  yield* source;
  yield null;
}

function* applyStatefulSyncTransform(source, transform, receiver) {
  const output = FunctionPrototypeCall(
    transform, receiver, withFlushSync(source));
  for (const item of output) {
    if (item === null) continue;
    const batch = [];
    for (const chunk of flattenTransformYieldSync(item)) {
      ArrayPrototypePush(batch, chunk);
    }
    if (batch.length > 0) {
      yield batch;
    }
  }
}

/**
 * Create a sync pipeline from source through transforms.
 * @yields {Uint8Array[]}
 */
function* createSyncPipeline(source, transforms) {
  let current = source;

  // Apply transforms - fuse consecutive stateless transforms into a single
  // generator layer to avoid unnecessary generator ticks.
  let statelessRun = [];

  for (let i = 0; i < transforms.length; i++) {
    const transform = transforms[i];
    if (isTransformObject(transform)) {
      if (statelessRun.length > 0) {
        current = applyFusedStatelessSyncTransforms(current, statelessRun);
        statelessRun = [];
      }
      current = applyStatefulSyncTransform(
        current, transform.transform, transform.receiver);
    } else {
      ArrayPrototypePush(statelessRun, transform);
    }
  }
  if (statelessRun.length > 0) {
    current = applyFusedStatelessSyncTransforms(current, statelessRun);
  }

  yield* current;
}

// =============================================================================
// Async Pipeline Implementation
// =============================================================================

/**
 * Apply a single stateless async transform to a source.
 * @yields {Uint8Array[]}
 */
/**
 * Apply a fused run of stateless async transforms to a source.
 * All transforms in the run are applied in a tight synchronous loop per batch,
 * avoiding the overhead of N async generator ticks for N transforms.
 *
 * INVARIANT: This function accepts a signal, NOT a pre-built options object.
 * A fresh { __proto__: null, signal } options object is created for each
 * transform invocation to prevent cross-transform mutation.
 * @param {AsyncIterable<Uint8Array[]>} source
 * @param {Array<Function>} run - Array of stateless transform functions
 * @param {AbortSignal} signal - The pipeline's abort signal
 * @yields {Uint8Array[]}
 */
async function* applyFusedStatelessAsyncTransforms(source, run, signal) {
  for await (const chunks of source) {
    let current = chunks;
    for (let i = 0; i < run.length; i++) {
      let result = run[i](current, { __proto__: null, signal });
      if (isPromise(result)) result = await result;
      if (result === null) {
        current = null;
        break;
      }
      if (i === run.length - 1) {
        current = result;
        continue;
      }
      current = normalizeTransformResultFast(result);
      if (current === undefined) {
        const normalized = [];
        const pendingResult = appendTransformResultAsync(normalized, result);
        if (pendingResult !== undefined) await pendingResult;
        current = normalized.length === 0 ? null : normalized[0];
      }
      if (current === null) break;
    }
    if (current === null) continue;
    // Normalize the final output
    if (isUint8ArrayBatch(current)) {
      if (current.length > 0) yield current;
    } else if (isUint8Array(current)) {
      yield [current];
    } else if (typeof current === 'string') {
      yield [toUint8Array(current)];
    } else if (isAnyArrayBuffer(current)) {
      yield [new Uint8Array(current)];
    } else if (ArrayBufferIsView(current)) {
      yield [arrayBufferViewToUint8Array(current)];
    } else {
      yield* processTransformResultAsync(current);
    }
  }
  // Flush each transform after all upstream data, including data emitted by
  // earlier flushes, has been processed by that transform.
  let pending = [];
  for (let i = 0; i < run.length; i++) {
    const next = [];
    for (let j = 0; j < pending.length; j++) {
      const pendingResult = appendTransformResultAsync(
        next,
        run[i](pending[j], { __proto__: null, signal }));
      if (pendingResult !== undefined) {
        await pendingResult;
      }
    }
    const flushResult = appendTransformResultAsync(
      next,
      run[i](null, { __proto__: null, signal }));
    if (flushResult !== undefined) {
      await flushResult;
    }
    pending = next;
  }
  for (let i = 0; i < pending.length; i++) {
    yield pending[i];
  }
}

/**
 * Append a null flush signal after the source is exhausted.
 * @yields {Uint8Array[]}
 */
/**
 * Append a null flush signal after the source is exhausted.
 * @yields {Uint8Array[]}
 */
async function* withFlushAsync(source) {
  yield* source;
  yield null;
}

async function* applyStatefulAsyncTransform(
  source, transform, receiver, options) {
  const output = FunctionPrototypeCall(
    transform, receiver, withFlushAsync(source), options);
  for await (const item of output) {
    if (item === null) continue;
    // Fast path: item is already a Uint8Array[] batch (e.g. compression transforms)
    if (isUint8ArrayBatch(item)) {
      if (item.length > 0) {
        yield item;
      }
      continue;
    }
    // Fast path: single Uint8Array
    if (isUint8Array(item)) {
      yield [item];
      continue;
    }
    // Slow path: flatten arbitrary transform yield
    const batch = [];
    for await (const chunk of flattenTransformYieldAsync(item)) {
      ArrayPrototypePush(batch, chunk);
    }
    if (batch.length > 0) {
      yield batch;
    }
  }
}

/**
 * Fast path for validated stateful transforms (e.g. compression).
 * Skips withFlushAsync (transform handles done internally) and
 * skips isUint8ArrayBatch validation (transform guarantees valid output).
 * @yields {Uint8Array[]}
 */
async function* applyValidatedStatefulAsyncTransform(
  source, transform, receiver, options) {
  const output = FunctionPrototypeCall(
    transform, receiver, source, options);
  for await (const batch of output) {
    if (batch.length > 0) {
      yield batch;
    }
  }
  // Check abort after the transform completes - without the
  // withFlushAsync wrapper there is no extra yield to give
  // the outer pipeline a chance to see the abort.
  options.signal?.throwIfAborted();
}

/**
 * Create an async pipeline from source through transforms.
 * @yields {Uint8Array[]}
 */
async function* createAsyncPipeline(source, transforms, signal) {
  // Check for abort
  signal?.throwIfAborted();

  // Fast path: no transforms, just yield normalized source directly
  if (transforms.length === 0) {
    yield* yieldAbortable(source, signal);
    return;
  }

  const normalized = yieldAbortable(source, signal);

  // Create internal controller for transform cancellation.
  // Note: if signal was already aborted, we threw above - no need to check here.
  const controller = new AbortController();
  let abortHandler;
  if (signal) {
    abortHandler = () => {
      abortSignal(controller.signal, signal.reason);
    };
    signal.addEventListener('abort', abortHandler, { __proto__: null, once: true });
  }

  let completed = false;
  try {
    // Apply transforms - fuse consecutive stateless transforms into a single
    // generator layer to avoid unnecessary async generator ticks.
    //
    // INVARIANT: Each transform invocation MUST receive its own fresh options
    // object ({ __proto__: null, signal }). Transforms may mutate the options
    // object, so sharing a single object across invocations would allow one
    // transform to corrupt the options seen by another. The signal is shared
    // across calls (mutations to it are acceptable), but the containing options
    // object must be unique per call. This is enforced inside
    // applyFusedStatelessAsyncTransforms and applyStatefulAsyncTransform, which
    // accept the signal directly and create the options object per invocation.
    // DO NOT pass a pre-built options object.
    let current = normalized;
    const transformSignal = controller.signal;
    let statelessRun = [];

    for (let i = 0; i < transforms.length; i++) {
      const transform = transforms[i];
      if (isTransformObject(transform)) {
        // Flush any accumulated stateless run before the stateful transform
        if (statelessRun.length > 0) {
          current = applyFusedStatelessAsyncTransforms(current, statelessRun,
                                                       transformSignal);
          statelessRun = [];
        }
        const opts = { __proto__: null, signal: transformSignal };
        if (transform[kValidatedTransform]) {
          current = applyValidatedStatefulAsyncTransform(
            current, transform.transform, transform.receiver, opts);
        } else {
          current = applyStatefulAsyncTransform(
            current, transform.transform, transform.receiver, opts);
        }
      } else {
        ArrayPrototypePush(statelessRun, transform);
      }
    }
    // Flush remaining stateless run
    if (statelessRun.length > 0) {
      current = applyFusedStatelessAsyncTransforms(current, statelessRun,
                                                   transformSignal);
    }

    for await (const batch of current) {
      controller.signal.throwIfAborted();
      yield batch;
    }
    // A transform can abort while completing without producing a final batch,
    // for example when an async flush resolves to null. In that case the loop
    // body has no opportunity to observe the abort.
    controller.signal.throwIfAborted();
    completed = true;
  } catch (error) {
    if (!controller.signal.aborted) {
      abortSignal(controller.signal, error);
    }
    throw error;
  } finally {
    if (!completed && !controller.signal.aborted) {
      // Consumer stopped early or generator return() was called.
      // If a transform listener throws here, let it propagate.
      controller.abort(lazyDOMException('Aborted', 'AbortError'));
    }
    // Clean up user signal listener to prevent holding controller alive
    if (signal && abortHandler) {
      signal.removeEventListener('abort', abortHandler);
    }
  }
}

// =============================================================================
// Public API: pull() and pullSync()
// =============================================================================

/**
 * Create a sync pull-through pipeline with transforms.
 * @param {Iterable} source - The sync streamable source
 * @param {...Function} transforms - Variadic transforms
 * @returns {Iterable<Uint8Array[]>}
 */
function pullSync(source, ...transforms) {
  const normalized = fromSync(source);
  for (let i = 0; i < transforms.length; i++) {
    const transform = snapshotTransform(transforms[i]);
    if (transform === undefined) {
      throw new ERR_INVALID_ARG_TYPE(
        `transforms[${i}]`, ['Function', 'Object with transform()'],
        transforms[i]);
    }
    transforms[i] = transform;
  }
  return {
    __proto__: null,
    *[SymbolIterator]() {
      yield* createSyncPipeline(normalized, transforms);
    },
  };
}

/**
 * Create an async pull-through pipeline with transforms.
 * @param {Iterable|AsyncIterable} source - The streamable source
 * @param {...(Function|object)} args - Transforms, with optional PullOptions
 *   as last argument
 * @returns {AsyncIterable<Uint8Array[]>}
 */
function pull(source, ...args) {
  const parsed = parsePullArgs(args);
  const { transforms } = parsed;
  const options = converters.PullOptions(parsed.options, {
    __proto__: null,
    context: 'options',
  });
  const { signal } = options;
  const normalized = from(source);

  return {
    __proto__: null,
    [SymbolAsyncIterator]() {
      if (signal === undefined) {
        const controller = new AbortController();
        async function* pipeline() {
          yield* createAsyncPipeline(normalized, transforms, controller.signal);
        }
        const iterator = pipeline();
        return {
          __proto__: null,
          next(value) {
            return iterator.next(value);
          },
          return(value) {
            controller.abort(lazyDOMException('Aborted', 'AbortError'));
            return iterator.return(value);
          },
          throw(error) {
            abortSignal(controller.signal, error);
            return iterator.throw(error);
          },
          [SymbolAsyncIterator]() {
            return this;
          },
        };
      }
      return createAbortablePullIterator(normalized, transforms, signal);
    },
  };
}

// Once `signal` aborts the pipeline, the pull that observed it rejects and
// so does every later pull, with the abort reason. That includes the case of
// an already-aborted signal, where the pipeline is never started. A plain
// async generator would instead complete after throwing, so later pulls
// would report a clean end of the stream.
function createAbortablePullIterator(source, transforms, signal) {
  let aborted = signal.aborted;
  let controller;
  let iterator;
  if (!aborted) {
    controller = new AbortController();
    const iteratorSignal = AbortSignal.any([signal, controller.signal]);
    async function* pipeline() {
      yield* createAsyncPipeline(source, transforms, iteratorSignal);
    }
    iterator = pipeline();
  }

  function onRejected(error) {
    if (signal.aborted) aborted = true;
    throw error;
  }

  return {
    __proto__: null,
    next(value) {
      if (aborted) return PromiseReject(signal.reason);
      return PromisePrototypeThen(iterator.next(value), undefined, onRejected);
    },
    return(value) {
      if (aborted) {
        return PromiseResolve({ __proto__: null, done: true, value });
      }
      controller.abort(lazyDOMException('Aborted', 'AbortError'));
      return iterator.return(value);
    },
    throw(error) {
      if (aborted) return PromiseReject(error);
      abortSignal(controller.signal, error);
      return PromisePrototypeThen(iterator.throw(error), undefined,
                                  onRejected);
    },
    [SymbolAsyncIterator]() {
      return this;
    },
  };
}

// Keep ownership of a bonded consumer outside the transform pipeline so it can
// be detached even when the pipeline never starts or terminates early.
function pullWithConsumerCleanup(source, transforms, signal) {
  const sourceIterator = source[SymbolAsyncIterator]();
  const pipelineSource = {
    __proto__: null,
    [SymbolAsyncIterator]() {
      return sourceIterator;
    },
  };
  let sourceClosed = false;
  let abortHandler;

  function closeSource(method, value) {
    if (sourceClosed) return;
    sourceClosed = true;
    if (abortHandler !== undefined) {
      signal.removeEventListener('abort', abortHandler);
    }
    const close = sourceIterator[method] ?? sourceIterator.return;
    if (typeof close === 'function') {
      const result = FunctionPrototypeCall(close, sourceIterator, value);
      const cleanup = PromisePrototypeThen(
        PromiseResolve(result), undefined, undefined);
      markPromiseAsHandled(cleanup);
    }
  }

  if (signal?.aborted) {
    closeSource('throw', signal.reason);
    return {
      __proto__: null,
      // eslint-disable-next-line require-yield
      async *[SymbolAsyncIterator]() {
        throw signal.reason;
      },
    };
  }

  const pipeline = signal === undefined ?
    pull(pipelineSource, ...transforms) :
    pull(pipelineSource, ...transforms, { __proto__: null, signal });

  if (signal !== undefined) {
    abortHandler = () => closeSource('throw', signal.reason);
    signal.addEventListener('abort', abortHandler,
                            { __proto__: null, once: true });
    if (signal.aborted) abortHandler();
  }

  return {
    __proto__: null,
    [SymbolAsyncIterator]() {
      const iterator = pipeline[SymbolAsyncIterator]();
      return {
        __proto__: null,
        next(value) {
          return PromisePrototypeThen(
            iterator.next(value),
            (result) => {
              if (result.done) closeSource('return');
              return result;
            },
            (error) => {
              closeSource('throw', error);
              throw error;
            });
        },
        return(value) {
          closeSource('return', value);
          return iterator.return(value);
        },
        throw(error) {
          closeSource('throw', error);
          return iterator.throw(error);
        },
        [SymbolAsyncIterator]() {
          return this;
        },
      };
    },
  };
}

// =============================================================================
// Public API: pipeTo() and pipeToSync()
// =============================================================================

/**
 * Write a sync source through transforms to a sync writer.
 * @param {Iterable<Uint8Array[]>} source
 * @param {...(Function|object)} args - Transforms, writer, and optional options
 * @returns {number} Total bytes written
 */
function pipeToSync(source, ...args) {
  const parsed = parsePipeToArgs(args, 'writeSync');
  const { transforms, writer } = parsed;
  const options = converters.PipeToSyncOptions(parsed.options, {
    __proto__: null,
    context: 'options',
  });
  const hasWritevSync = typeof writer.writevSync === 'function';
  const endSync = writer.endSync;

  if (!options.preventClose && typeof endSync !== 'function') {
    throw new ERR_INVALID_ARG_TYPE(
      'writer.endSync', 'Function', endSync);
  }

  // Normalize source and create pipeline
  const normalized = fromSync(source);
  const pipeline = transforms.length > 0 ?
    createSyncPipeline(normalized, transforms) :
    normalized;

  let totalBytes = 0;
  let closedSync = true;

  try {
    for (const batch of pipeline) {
      const entry = createBatchEntry(batch);
      if (hasWritevSync && batch.length > 1) {
        const accepted = writer.writevSync(validateBatchEntry(entry));
        validateBatchEntry(entry);
        if (accepted === false) {
          throw new ERR_OUT_OF_RANGE(
            'write', 'within byte budget', 'budget exhausted');
        }
        totalBytes += entry.byteLength;
      } else {
        for (let i = 0; i < entry.views.length; i++) {
          const view = entry.views[i];
          const chunk = validateByteView(view);
          const accepted = writer.writeSync(chunk);
          validateByteView(view);
          if (accepted === false) {
            throw new ERR_OUT_OF_RANGE(
              'write', 'within byte budget', 'budget exhausted');
          }
          totalBytes += view.byteLength;
        }
      }
    }

    if (!options.preventClose) {
      closedSync = FunctionPrototypeCall(endSync, writer) >= 0;
    }
  } catch (error) {
    if (!options.preventFail) {
      failWriterQuietly(writer, error);
    }
    throw error;
  }

  // endSync() returning -1 only means that the writer cannot close
  // synchronously; every chunk was accepted. pipeToSync() never falls back to
  // the async end(), so report it. By default the writer is left as it is so
  // that the caller can still close it (e.g. with `await writer.end()`);
  // `failOnIncompleteClose` fails it instead, for callers that cannot.
  if (!closedSync) {
    const error = new ERR_INVALID_STATE(
      'Writer could not be closed synchronously');
    if (options.failOnIncompleteClose && !options.preventFail) {
      failWriterQuietly(writer, error);
    }
    throw error;
  }

  return totalBytes;
}

// Call writer.fail(error) on a best-effort basis. The error that made the
// pipe fail is what the caller must see; an exception from fail() itself
// must not replace it.
function failWriterQuietly(writer, error) {
  try {
    writer.fail?.(error);
  } catch {
    // Ignored, see above.
  }
}

/**
 * Write an async source through transforms to a writer.
 * @param {AsyncIterable<Uint8Array[]>|Iterable<Uint8Array[]>} source
 * @param {...(Function|object)} args - Transforms, writer, and optional options
 * @returns {Promise<number>} Total bytes written
 */
async function pipeTo(source, ...args) {
  const parsed = parsePipeToArgs(args, 'write');
  const { transforms, writer } = parsed;
  const options = converters.PipeToOptions(parsed.options, {
    __proto__: null,
    context: 'options',
  });
  const { signal } = options;

  function failWriter(error) {
    if (!options.preventFail) {
      failWriterQuietly(writer, error);
    }
  }

  try {
    signal?.throwIfAborted();
  } catch (error) {
    failWriter(error);
    throw error;
  }

  const hasWriteSync = typeof writer.writeSync === 'function';
  const normalized = from(source);

  let totalBytes = 0;
  const hasWritev = typeof writer.writev === 'function';
  const hasWritevSync = typeof writer.writevSync === 'function';
  const hasEndSync = typeof writer.endSync === 'function';

  // Async fallback for writeBatch when sync write fails partway through.
  // Continues writing from batch[startIndex] using async write().
  async function writeBatchAsyncFallback(entry, startIndex) {
    for (let i = startIndex; i < entry.views.length; i++) {
      const view = entry.views[i];
      if (hasWriteSync) {
        const chunk = validateByteView(view);
        if (writer.writeSync(chunk)) {
          validateByteView(view);
          totalBytes += view.byteLength;
          continue;
        }
        validateByteView(view);
      }
      const result = writer.write(
        validateByteView(view),
        signal ? { __proto__: null, signal } : undefined);
      if (result !== undefined) {
        await result;
      }
      validateByteView(view);
      totalBytes += view.byteLength;
    }
  }

  // Write a batch using try-fallback: sync first, async if needed.
  // Returns undefined on sync success, or a Promise when async fallback
  // is required. Callers must check: const p = writeBatch(b); if (p) await p;
  function writeBatch(batch) {
    const entry = createBatchEntry(batch);
    if (hasWritev && batch.length > 1) {
      if (!hasWritevSync ||
          !writer.writevSync(validateBatchEntry(entry))) {
        validateBatchEntry(entry);
        const opts = signal ? { __proto__: null, signal } : undefined;
        const writevResult = writer.writev(validateBatchEntry(entry), opts);
        if (writevResult === undefined) {
          validateBatchEntry(entry);
          totalBytes += entry.byteLength;
          return;
        }
        return PromisePrototypeThen(PromiseResolve(writevResult), () => {
          validateBatchEntry(entry);
          totalBytes += entry.byteLength;
        });
      }
      validateBatchEntry(entry);
      totalBytes += entry.byteLength;
      return;
    }
    for (let i = 0; i < entry.views.length; i++) {
      const view = entry.views[i];
      const chunk = validateByteView(view);
      if (!hasWriteSync || !writer.writeSync(chunk)) {
        if (hasWriteSync) validateByteView(view);
        // Sync path failed at index i - fall back to async for the rest.
        return writeBatchAsyncFallback(entry, i);
      }
      validateByteView(view);
      totalBytes += view.byteLength;
    }
  }

  try {
    if (transforms.length === 0) {
      // Fast path: no transforms - iterate normalized source directly
      if (signal) {
        for await (const batch of yieldAbortable(normalized, signal)) {
          signal.throwIfAborted();
          const p = writeBatch(batch);
          if (p) await p;
        }
      } else {
        for await (const batch of normalized) {
          const p = writeBatch(batch);
          if (p) await p;
        }
      }
    } else {
      const pipeline = createAsyncPipeline(normalized, transforms, signal);

      if (signal) {
        for await (const batch of pipeline) {
          signal.throwIfAborted();
          const p = writeBatch(batch);
          if (p) await p;
        }
      } else {
        for await (const batch of pipeline) {
          const p = writeBatch(batch);
          if (p) await p;
        }
      }
    }

    if (!options.preventClose) {
      if (!hasEndSync || writer.endSync() < 0) {
        await writer.end?.(signal ? { __proto__: null, signal } : undefined);
      }
    }
  } catch (error) {
    failWriter(error);
    throw error;
  }

  return totalBytes;
}

module.exports = {
  pipeTo,
  pipeToSync,
  pull,
  pullSync,
  pullWithConsumerCleanup,
};

