'use strict';

const {
  FunctionPrototypeCall,
  ObjectAssign,
  ObjectDefineProperty,
  ObjectSetPrototypeOf,
  ReflectApply,
  RegExp,
  Symbol,
  SymbolFor,
} = primordials;

const {
  assertCrypto,
  kEmptyObject,
} = require('internal/util');

assertCrypto();

const { setImmediate } = require('timers');
const assert = require('internal/assert');
const crypto = require('crypto');
const EE = require('events');
const net = require('net');
const tls = require('tls');
const common = require('internal/tls/common');
const { kReinitializeHandle } = require('internal/net');
const JSStreamSocket = require('internal/js_stream_socket');
const { Buffer } = require('buffer');
let debug = require('internal/util/debuglog').debuglog('tls', (fn) => {
  debug = fn;
});
const { TCP, constants: TCPConstants } = internalBinding('tcp_wrap');
const tls_wrap = internalBinding('tls_wrap');
const { Pipe, constants: PipeConstants } = internalBinding('pipe_wrap');
const { owner_symbol } = require('internal/async_hooks').symbols;
const { isArrayBufferView } = require('internal/util/types');
const { SecureContext: NativeSecureContext } = internalBinding('crypto');
const {
  ConnResetException,
  codes: {
    ERR_INVALID_ARG_TYPE,
    ERR_INVALID_ARG_VALUE,
    ERR_MULTIPLE_CALLBACK,
    ERR_SOCKET_CLOSED,
    ERR_TLS_ALPN_CALLBACK_INVALID_RESULT,
    ERR_TLS_ALPN_CALLBACK_WITH_PROTOCOLS,
    ERR_TLS_DH_PARAM_SIZE,
    ERR_TLS_HANDSHAKE_TIMEOUT,
    ERR_TLS_INVALID_CONTEXT,
    ERR_TLS_INVALID_STATE,
    ERR_TLS_RENEGOTIATION_DISABLED,
    ERR_TLS_RENEGOTIATION_UNSUPPORTED,
    ERR_TLS_REQUIRED_SERVER_NAME,
    ERR_TLS_SESSION_ATTACK,
    ERR_TLS_SNI_FROM_SERVER,
  },
} = require('internal/errors');
const { onpskexchange: kOnPskExchange } = internalBinding('symbols');
const {
  getOptionValue,
  getAllowUnauthorized,
} = require('internal/options');
const {
  validateBoolean,
  validateBuffer,
  validateFunction,
  validateInt32,
  validateNumber,
  validateObject,
  validateString,
  validateUint32,
} = require('internal/validators');
const {
  InternalX509Certificate,
} = require('internal/crypto/x509');
const traceTls = getOptionValue('--trace-tls');
const tlsKeylog = getOptionValue('--tls-keylog');
const { appendFile } = require('fs');
const kConnectOptions = Symbol('connect-options');
const kDisableRenegotiation = Symbol('disable-renegotiation');
const kErrorEmitted = Symbol('error-emitted');
const kHandshakeTimeout = Symbol('handshake-timeout');
const kRes = Symbol('res');
const kSecureContext = Symbol('secureContext');
const kSNICallback = Symbol('snicallback');
const kALPNCallback = Symbol('alpncallback');
const kEnableTrace = Symbol('enableTrace');
const kPskCallback = Symbol('pskcallback');
const kPskIdentityHint = Symbol('pskidentityhint');
const kPendingSession = Symbol('pendingSession');
const kIsVerified = Symbol('verified');

const noop = () => {};

const kTLSSessionStatePrefix = Buffer.from('\0nodejs:tls:session:1\0');

function getSessionServerIdentity(options) {
  return options?.servername ||
         options?.host ||
         options?.socket?._host ||
         'localhost';
}

function wrapSessionState(session, options) {
  if (!Buffer.isBuffer(session) || options?.isServer)
    return session;

  const servername = Buffer.from(getSessionServerIdentity(options), 'utf8');
  const servernameLength = Buffer.allocUnsafe(2);
  servernameLength.writeUInt16BE(servername.length, 0);

  return Buffer.concat([
    kTLSSessionStatePrefix,
    servernameLength,
    servername,
    session,
  ]);
}

function unwrapSessionState(session) {
  if (!Buffer.isBuffer(session) ||
      session.length < kTLSSessionStatePrefix.length + 2 ||
      Buffer.compare(
        session.subarray(0, kTLSSessionStatePrefix.length),
        kTLSSessionStatePrefix,
      ) !== 0) {
    return;
  }

  const start = kTLSSessionStatePrefix.length;
  const servernameLength = session.readUInt16BE(start);
  const servernameStart = start + 2;
  const servernameEnd = servernameStart + servernameLength;
  if (session.length < servernameEnd)
    return;

  return {
    servername: session.toString('utf8', servernameStart, servernameEnd),
    session: session.subarray(servernameEnd),
  };
}

function getSessionForReuse(session, options) {
  if (typeof session === 'string')
    session = Buffer.from(session, 'latin1');

  if (options?.isServer)
    return session;

  const wrappedSession = unwrapSessionState(session);
  if (wrappedSession !== undefined) {
    const servername = getSessionServerIdentity(options);
    if (wrappedSession.servername !== servername) {
      debug('ignore session for %s: authenticated for %s',
            servername, wrappedSession.servername);
      return;
    }

    return wrappedSession.session;
  }

  if (Buffer.isBuffer(session) && options?.rejectUnauthorized !== false) {
    debug('ignore raw session for verified client connection to %s',
          getSessionServerIdentity(options));
    return;
  }

  return session;
}

let tlsTracingWarned = false;

// Server side times how long a handshake is taking to protect against slow
// handshakes being used for DoS.
function onhandshakestart(now) {
  debug('server onhandshakestart');

  const { lastHandshakeTime } = this;
  assert(now >= lastHandshakeTime,
         `now (${now}) < lastHandshakeTime (${lastHandshakeTime})`);

  this.lastHandshakeTime = now;

  // If this is the first handshake we can skip the rest of the checks.
  if (lastHandshakeTime === 0)
    return;

  if ((now - lastHandshakeTime) >= tls.CLIENT_RENEG_WINDOW * 1000)
    this.handshakes = 1;
  else
    this.handshakes++;

  const owner = this[owner_symbol];

  assert(owner._tlsOptions.isServer);

  if (this.handshakes > tls.CLIENT_RENEG_LIMIT) {
    owner._emitTLSError(new ERR_TLS_SESSION_ATTACK());
    return;
  }

  if (owner[kDisableRenegotiation])
    owner._emitTLSError(new ERR_TLS_RENEGOTIATION_DISABLED());
}

function onhandshakedone() {
  debug('server onhandshakedone');

  const owner = this[owner_symbol];
  assert(owner._tlsOptions.isServer);

  // `newSession` callback wasn't called yet
  if (owner._newSessionPending) {
    owner._securePending = true;
    return;
  }

  owner._finishInit();
}


function loadSession(hello) {
  debug('server onclienthello',
        'sessionid.len', hello.sessionId.length,
        'ticket?', hello.tlsTicket,
  );
  const owner = this[owner_symbol];

  let once = false;
  function onSession(err, session) {
    debug('server resumeSession callback(err %j, sess? %s)', err, !!session);
    if (once)
      return owner.destroy(new ERR_MULTIPLE_CALLBACK());
    once = true;

    if (err)
      return owner.destroy(err);

    if (owner._handle === null)
      return owner.destroy(new ERR_SOCKET_CLOSED());

    owner._handle.loadSession(session);
    // Session is loaded. Let the handshake continue.
    owner._handle.clientHelloDone();
  }

  if (hello.sessionId.length <= 0 ||
      hello.tlsTicket ||
      (owner.server &&
      !(() => {
        try {
          return owner.server.emit('resumeSession', hello.sessionId, onSession);
        } catch (err) {
          onSession(err);
          return true;
        }
      })())) {
    // Sessions without identifiers can't be resumed.
    // Sessions with tickets can be resumed directly from the ticket, no server
    // session storage is necessary.
    // Without a call to a resumeSession listener, a session will never be
    // loaded, so let the handshake continue.
    owner._handle.clientHelloDone();
  }
}


function loadSNI(info) {
  const owner = this[owner_symbol];
  const servername = info.servername;
  if (!servername || !owner._SNICallback)
    return requestOCSP(owner, info);

  let once = false;
  try {
    owner._SNICallback(servername, (err, context) => {
      if (once)
        return owner.destroy(new ERR_MULTIPLE_CALLBACK());
      once = true;

      if (err)
        return owner.destroy(err);

      if (owner._handle === null)
        return owner.destroy(new ERR_SOCKET_CLOSED());

      // TODO(indutny): eventually disallow raw `SecureContext`
      if (context)
        owner._handle.sni_context = context.context || context;

      requestOCSP(owner, info);
    });
  } catch (err) {
    owner.destroy(err);
  }
}


function callALPNCallback(protocolsBuffer) {
  const handle = this;
  const socket = handle[owner_symbol];

  try {
    const servername = handle.getServername();

    // Collect all the protocols from the given buffer:
    const protocols = [];
    let offset = 0;
    while (offset < protocolsBuffer.length) {
      const protocolLen = protocolsBuffer[offset];
      offset += 1;

      const protocol = protocolsBuffer.slice(offset, offset + protocolLen);
      offset += protocolLen;

      protocols.push(protocol.toString('ascii'));
    }

    const selectedProtocol = socket[kALPNCallback]({
      servername,
      protocols,
    });

    // Undefined -> all proposed protocols rejected
    if (selectedProtocol === undefined) return undefined;

    const protocolIndex = protocols.indexOf(selectedProtocol);
    if (protocolIndex === -1) {
      throw new ERR_TLS_ALPN_CALLBACK_INVALID_RESULT(selectedProtocol, protocols);
    }
    let protocolOffset = 0;
    for (let i = 0; i < protocolIndex; i++) {
      protocolOffset += 1 + protocols[i].length;
    }

    return protocolOffset;
  } catch (err) {
    socket.destroy(err);
    return undefined;
  }
