  const owner = this[owner_symbol];
  const wrappedSession = wrapSessionState(session, owner[kConnectOptions]);
  if (owner[kIsVerified]) {
    owner.emit('session', wrappedSession);
  } else {
    owner[kPendingSession] = wrappedSession;
  }
