  owner._newSessionPending = true;

  let hasEmitted = false;
  try {
    hasEmitted = owner.server.emit('newSession', sessionId, session, done);
  } catch (err) {
    owner.server.emit('error', err);
  }
  if (!hasEmitted)
    done();
