sources.internal/v8/cpu_profiler:
'use strict';

const {
  MathFloor,
} = primordials;

const { kEmptyObject } = require('internal/util');
const {
  validateNumber,
  validateObject,
} = require('internal/validators');

const kMicrosPerMilli = 1_000;
const kMaxSamplingIntervalUs = 0x7FFFFFFF;
const kMaxSamplingIntervalMs = kMaxSamplingIntervalUs / kMicrosPerMilli;
const kMaxSamplesUnlimited = 0xFFFF_FFFF;

function normalizeCpuProfileOptions(options = kEmptyObject) {
  validateObject(options, 'options');

  // TODO(ishabi): add support for 'mode' and 'filterContext' options
  const {
    sampleInterval,
    maxBufferSize,
  } = options;

  let samplingIntervalMicros = 0;
  if (sampleInterval !== undefined) {
    validateNumber(sampleInterval,
                   'options.sampleInterval',
                   0,
                   kMaxSamplingIntervalMs);
    samplingIntervalMicros = MathFloor(sampleInterval * kMicrosPerMilli);
    if (sampleInterval > 0 && samplingIntervalMicros === 0) {
      samplingIntervalMicros = 1;
    }
  }

  const size = maxBufferSize;
  let normalizedMaxSamples = kMaxSamplesUnlimited;
  if (size !== undefined) {
    validateNumber(size,
                   'options.maxBufferSize',
                   1,
                   kMaxSamplesUnlimited);
    normalizedMaxSamples = MathFloor(size);
  }

  return {
    samplingIntervalMicros,
    maxSamples: normalizedMaxSamples,
  };
}

module.exports = {
  normalizeCpuProfileOptions,
};

sources.internal/v8/heap_profile:
'use strict';

const { kEmptyObject } = require('internal/util');
const {
  validateBoolean,
  validateInteger,
  validateInt32,
  validateObject,
} = require('internal/validators');

const {
  kSamplingNoFlags,
  kSamplingForceGC,
  kSamplingIncludeObjectsCollectedByMajorGC,
  kSamplingIncludeObjectsCollectedByMinorGC,
} = internalBinding('v8');

function normalizeHeapProfileOptions(options = kEmptyObject) {
  validateObject(options, 'options');
  const {
    sampleInterval = 512 * 1024,
    stackDepth = 16,
    forceGC = false,
    includeObjectsCollectedByMajorGC = false,
    includeObjectsCollectedByMinorGC = false,
  } = options;

  validateInteger(sampleInterval, 'options.sampleInterval', 1);
  validateInt32(stackDepth, 'options.stackDepth', 0);
  validateBoolean(forceGC, 'options.forceGC');
  validateBoolean(includeObjectsCollectedByMajorGC,
                  'options.includeObjectsCollectedByMajorGC');
  validateBoolean(includeObjectsCollectedByMinorGC,
                  'options.includeObjectsCollectedByMinorGC');

  let flags = kSamplingNoFlags;
  if (forceGC) flags |= kSamplingForceGC;
  if (includeObjectsCollectedByMajorGC) {
    flags |= kSamplingIncludeObjectsCollectedByMajorGC;
  }
  if (includeObjectsCollectedByMinorGC) {
    flags |= kSamplingIncludeObjectsCollectedByMinorGC;
  }

  return { sampleInterval, stackDepth, flags };
}

module.exports = {
  normalizeHeapProfileOptions,
};

sources.internal/v8/startup_snapshot:
'use strict';

const {
  validateFunction,
} = require('internal/validators');
const {
  codes: {
    ERR_DUPLICATE_STARTUP_SNAPSHOT_MAIN_FUNCTION,
    ERR_NOT_BUILDING_SNAPSHOT,
    ERR_NOT_SUPPORTED_IN_SNAPSHOT,
  },
} = require('internal/errors');

const {
  setSerializeCallback,
  setDeserializeCallback,
  setDeserializeMainFunction: _setDeserializeMainFunction,
  isBuildingSnapshotBuffer,
} = internalBinding('mksnapshot');

function isBuildingSnapshot() {
  return isBuildingSnapshotBuffer[0];
}

function throwIfNotBuildingSnapshot() {
  if (!isBuildingSnapshot()) {
    throw new ERR_NOT_BUILDING_SNAPSHOT();
  }
}

function throwIfBuildingSnapshot(reason) {
  if (isBuildingSnapshot()) {
    throw new ERR_NOT_SUPPORTED_IN_SNAPSHOT(reason);
  }
}

const deserializeCallbacks = [];
const beforeUserDeserializeCallbacks = [];
let deserializeCallbackIsSet = false;
function runDeserializeCallbacks() {
  for (let i = 0; i < beforeUserDeserializeCallbacks.length; i++) {
    const { 0: callback, 1: data } = beforeUserDeserializeCallbacks[i];
    callback(data);
  }
  beforeUserDeserializeCallbacks.length = 0;
  for (let i = 0; i < deserializeCallbacks.length; i++) {
    const { 0: callback, 1: data } = deserializeCallbacks[i];
    callback(data);
  }
  deserializeCallbacks.length = 0;
}

function addDeserializeCallback(callback, data) {
  addDeserializeCallbackImpl(deserializeCallbacks, callback, data);
}

function addBeforeUserDeserializeCallback(callback, data) {
  addDeserializeCallbackImpl(beforeUserDeserializeCallbacks, callback, data);
}

function addDeserializeCallbackImpl(callbacks, callback, data) {
  throwIfNotBuildingSnapshot();
  validateFunction(callback, 'callback');
  if (!deserializeCallbackIsSet) {
    // TODO(joyeecheung): when the main function handling is done in JS,
    // the deserialize callbacks can always be invoked. For now only
    // store it in C++ when it's actually used to avoid unnecessary
    // C++ -> JS costs.
    setDeserializeCallback(runDeserializeCallbacks);
    deserializeCallbackIsSet = true;
  }
  callbacks.push([callback, data]);
}

const serializeCallbacks = [];
const afterUserSerializeCallbacks = [];  // Callbacks to run after user callbacks
function runSerializeCallbacks() {
  for (let i = 0; i < serializeCallbacks.length; i++) {
    const { 0: callback, 1: data } = serializeCallbacks[i];
    callback(data);
  }
  serializeCallbacks.length = 0;
  for (let i = 0; i < afterUserSerializeCallbacks.length; i++) {
    const { 0: callback, 1: data } = afterUserSerializeCallbacks[i];
    callback(data);
  }
  afterUserSerializeCallbacks.length = 0;
}

function addSerializeCallback(callback, data) {
  throwIfNotBuildingSnapshot();
  validateFunction(callback, 'callback');
  serializeCallbacks.push([callback, data]);
}

function addAfterUserSerializeCallback(callback, data) {
  afterUserSerializeCallbacks.push([callback, data]);
}

function initializeCallbacks() {
  // Only run the serialize callbacks in snapshot building mode, otherwise
  // they throw.
  if (isBuildingSnapshot()) {
    setSerializeCallback(runSerializeCallbacks);
  }
}

let deserializeMainIsSet = false;
function setDeserializeMainFunction(callback, data) {
  throwIfNotBuildingSnapshot();
  // TODO(joyeecheung): In lib/internal/bootstrap/node.js, create a default
  // main function to run the lib/internal/main scripts and make sure that
  // the main function set in the snapshot building process takes precedence.
  validateFunction(callback, 'callback');
  if (deserializeMainIsSet) {
    throw new ERR_DUPLICATE_STARTUP_SNAPSHOT_MAIN_FUNCTION();
  }
  deserializeMainIsSet = true;

  _setDeserializeMainFunction(function deserializeMain() {
    const {
      prepareMainThreadExecution,
      markBootstrapComplete,
    } = require('internal/process/pre_execution');

    // This should be in sync with run_main_module.js until we make that
    // a built-in main function.
    // TODO(joyeecheung): make a copy of argv[0] and insert it as argv[1].
    prepareMainThreadExecution(false);
    markBootstrapComplete();
    callback(data);
  });
}

initializeCallbacks();
module.exports = {
  runDeserializeCallbacks,
  throwIfBuildingSnapshot,
  // Exposed to require('v8').startupSnapshot
  namespace: {
    addDeserializeCallback,
    addSerializeCallback,
    setDeserializeMainFunction,
    isBuildingSnapshot,
  },
  addAfterUserSerializeCallback,
  addBeforeUserDeserializeCallback,
};

