  /**
   * Reads, decompresses, and (by default) CRC-32-verifies the whole entry
   * into a single `Buffer`, enforcing the declared-size and `maxSize` limits.
   * @param {{ verify?: boolean, maxSize?: number }} [options]
   * @returns {Promise<Buffer>}
