      // (the entry's retained buffer, see #compressedBytes()) so the result is
      // caller-owned on every path.
      return data === compressed && this.#fd === null ? Buffer.from(data) : data;
    } finally {
      if (handle !== null) endHandleRead(handle);
    }
  }

